window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["已废止解释"] = {"renminjianchayuanminshisusongjianduguize-2":[{"i":1,"n":"第一条","txt":"为了保障和规范人民检察院依法履行民事检察职责，根据《中华人民共和国民事诉讼法》、《中华人民共和国人民检察院组织法》和其他有关规定，结合人民检察院工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院依法独立行使检察权，通过办理民事诉讼监督案件，维护司法公正和司法权威，维护国家利益和社会公共利益，维护公民、法人和其他组织的合法权益，保障国家法律的统一正确实施。"},{"i":3,"n":"第三条","txt":"人民检察院通过抗诉、检察建议等方式，对民事诉讼活动实行法律监督。"},{"i":4,"n":"第四条","txt":"人民检察院办理民事诉讼监督案件，应当以事实为根据，以法律为准绳，坚持公开、公平、公正和诚实信用原则，尊重和保障当事人的诉讼权利，监督和支持人民法院依法行使审判权和执行权。"},{"i":5,"n":"第五条","txt":"民事诉讼监督案件的受理、办理、管理工作分别由控告检察部门、民事检察部门、案件管理部门负责，各部门互相配合，互相制约。"},{"i":6,"n":"第六条","txt":"人民检察院办理民事诉讼监督案件，实行检察官办案责任制。"},{"i":7,"n":"第七条","txt":"最高人民检察院领导地方各级人民检察院和专门人民检察院的民事诉讼监督工作，上级人民检察院领导下级人民检察院的民事诉讼监督工作。"},{"i":8,"n":"第八条","txt":"人民检察院检察长在同级人民法院审判委员会讨论民事抗诉案件或者其他与民事诉讼监督工作有关的议题时，可以依照有关规定列席会议。"},{"i":9,"n":"第九条","txt":"人民检察院办理民事诉讼监督案件，实行回避制度。"},{"i":10,"n":"第十条","txt":"检察人员办理民事诉讼监督案件，应当依法秉公办案，自觉接受监督。"},{"i":11,"n":"第十一条","txt":"对已经发生法律效力的民事判决、裁定、调解书的监督案件，最高人民检察院、作出该生效法律文书的人民法院所在地同级人民检察院和上级人民检察院均有管辖权。"},{"i":12,"n":"第十二条","txt":"对民事审判程序中审判人员违法行为的监督案件，由审理案件的人民法院所在地同级人民检察院管辖。"},{"i":13,"n":"第十三条","txt":"对民事执行活动的监督案件，由执行法院所在地同级人民检察院管辖。"},{"i":14,"n":"第十四条","txt":"人民检察院发现受理的民事诉讼监督案件不属于本院管辖的，应当移送有管辖权的人民检察院，受移送的人民检察院应当受理。受移送的人民检察院认为不属于本院管辖的，应当报请上级人民检察院指定管辖，不得再自行移送。"},{"i":15,"n":"第十五条","txt":"有管辖权的人民检察院由于特殊原因，不能行使管辖权的，由上级人民检察院指定管辖。"},{"i":16,"n":"第十六条","txt":"上级人民检察院认为确有必要的，可以办理下级人民检察院管辖的民事诉讼监督案件。"},{"i":17,"n":"第十七条","txt":"军事检察院等专门人民检察院对民事诉讼监督案件的管辖，依照有关规定执行。"},{"i":18,"n":"第十八条","txt":"检察人员有《中华人民共和国民事诉讼法》第四十四条规定情形之一的，应当自行回避，当事人有权申请他们回避。"},{"i":19,"n":"第十九条","txt":"检察人员自行回避的，可以口头或者书面方式提出，并说明理由。口头提出申请的，应当记录在卷。"},{"i":20,"n":"第二十条","txt":"当事人申请回避，应当在人民检察院作出提出抗诉或者检察建议等决定前以口头或者书面方式提出，并说明理由。口头提出申请的，应当记录在卷。根据《中华人民共和国民事诉讼法》第四十四条第二款规定提出回避申请的，应当提供相关证据。"},{"i":21,"n":"第二十一条","txt":"检察长的回避，由检察委员会讨论决定；检察人员和其他人员的回避，由检察长决定。检察委员会讨论检察长回避问题时，由副检察长主持，检察长不得参加。"},{"i":22,"n":"第二十二条","txt":"人民检察院对当事人提出的回避申请，应当在三日内作出决定，并通知申请人。申请人对决定不服的，可以在接到决定时向原决定机关申请复议一次。人民检察院应当在三日内作出复议决定，并通知复议申请人。复议期间，被申请回避的人员不停止参与本案工作。"},{"i":23,"n":"第二十三条","txt":"民事诉讼监督案件的来源包括："},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，当事人可以向人民检察院申请监督："},{"i":25,"n":"第二十五条","txt":"当事人向人民检察院申请监督，应当提交监督申请书、身份证明、相关法律文书及证据材料。提交证据材料的，应当附证据清单。"},{"i":26,"n":"第二十六条","txt":"本规则第二十五条规定的监督申请书应当记明下列事项："},{"i":27,"n":"第二十七条","txt":"本规则第二十五条规定的身份证明包括："},{"i":28,"n":"第二十八条","txt":"本规则第二十五条规定的相关法律文书是指人民法院在该案件诉讼过程中作出的全部判决书、裁定书、决定书、调解书等法律文书。"},{"i":29,"n":"第二十九条","txt":"当事人申请监督，可以依照《中华人民共和国民事诉讼法》的规定委托代理人。"},{"i":30,"n":"第三十条","txt":"当事人申请监督符合下列条件的，人民检察院应当受理："},{"i":31,"n":"第三十一条","txt":"当事人根据《中华人民共和国民事诉讼法》第二百零九条第一款的规定向人民检察院申请监督，有下列情形之一的，人民检察院不予受理："},{"i":32,"n":"第三十二条","txt":"对人民法院作出的一审民事判决、裁定，当事人依法可以上诉但未提出上诉，而依照《中华人民共和国民事诉讼法》第二百零九条第一款第一项、第二项的规定向人民检察院申请监督的，人民检察院不予受理，但有下列情形之一的除外："},{"i":33,"n":"第三十三条","txt":"当事人认为民事审判程序中审判人员存在违法行为或者民事执行活动存在违法情形，向人民检察院申请监督，有下列情形之一的，人民检察院不予受理："},{"i":34,"n":"第三十四条","txt":"当事人根据《中华人民共和国民事诉讼法》第二百零九条第一款的规定向人民检察院申请检察建议或者抗诉，由作出生效民事判决、裁定、调解书的人民法院所在地同级人民检察院控告检察部门受理。"},{"i":35,"n":"第三十五条","txt":"人民法院裁定驳回再审申请或者逾期未对再审申请作出裁定，当事人向人民检察院申请监督的，由作出原生效民事判决、裁定、调解书的人民法院所在地同级人民检察院控告检察部门受理。"},{"i":36,"n":"第三十六条","txt":"人民检察院控告检察部门对监督申请，应当根据以下情形作出处理："},{"i":37,"n":"第三十七条","txt":"控告检察部门应当在决定受理之日起三日内制作《受理通知书》，发送申请人，并告知其权利义务。"},{"i":38,"n":"第三十八条","txt":"控告检察部门应当在决定受理之日起三日内将案件材料移送本院民事检察部门，同时将《受理通知书》抄送本院案件管理部门。"},{"i":39,"n":"第三十九条","txt":"当事人以外的公民、法人和其他组织认为人民法院民事审判程序中审判人员存在违法行为或者民事执行活动存在违法情形的，可以向同级人民检察院控告、举报。控告、举报由人民检察院控告检察部门受理。"},{"i":40,"n":"第四十条","txt":"控告检察部门可以依据《人民检察院信访工作规定》，向下级人民检察院交办涉及民事诉讼监督的信访案件。"},{"i":41,"n":"第四十一条","txt":"具有下列情形之一的民事案件，人民检察院应当依职权进行监督："},{"i":42,"n":"第四十二条","txt":"下级人民检察院提请抗诉、提请其他监督等案件，由上一级人民检察院案件管理部门受理。"},{"i":43,"n":"第四十三条","txt":"案件管理部门接收案件材料后，应当在三日内登记并将案件材料和案件登记表移送民事检察部门；案件材料不符合规定的，应当要求补齐。"},{"i":44,"n":"第四十四条","txt":"民事检察部门负责对受理后的民事诉讼监督案件进行审查。"},{"i":45,"n":"第四十五条","txt":"上级人民检察院可以将受理的民事诉讼监督案件交由有管辖权的下级人民检察院办理。交办的案件应当制作《交办通知书》，并将有关材料移送下级人民检察院。下级人民检察院应当依法办理，不得将案件再行交办，作出决定前应当报上级人民检察院审核同意。"},{"i":46,"n":"第四十六条","txt":"上级人民检察院可以将案件转有管辖权的下级人民检察院办理。转办案件应当制作《转办通知书》，并将有关材料移送下级人民检察院。"},{"i":47,"n":"第四十七条","txt":"人民检察院审查民事诉讼监督案件，应当围绕申请人的申请监督请求以及发现的其他情形，对人民法院民事诉讼活动是否合法进行审查。其他当事人也申请监督的，应当将其列为申请人，对其申请监督请求一并审查。"},{"i":48,"n":"第四十八条","txt":"申请人或者其他当事人对提出的主张，应当提供证据材料。人民检察院收到当事人提交的证据材料，应当出具收据。"},{"i":49,"n":"第四十九条","txt":"人民检察院应当告知当事人有申请回避的权利，并告知办理案件的检察人员、书记员等的姓名、法律职务。"},{"i":50,"n":"第五十条","txt":"人民检察院审查案件，应当听取当事人意见，必要时可以听证或者调查核实有关情况。"},{"i":51,"n":"第五十一条","txt":"人民检察院审查案件，可以依照有关规定调阅人民法院的诉讼卷宗。"},{"i":52,"n":"第五十二条","txt":"承办人审查终结后，应当制作审查终结报告。审查终结报告应当全面、客观、公正地叙述案件事实，依据法律提出处理建议。"},{"i":53,"n":"第五十三条","txt":"案件应当经集体讨论，参加集体讨论的人员应当对案件事实、适用法律、处理建议等发表明确意见并说明理由。集体讨论意见应当在全面、客观地归纳讨论意见的基础上形成。"},{"i":54,"n":"第五十四条","txt":"人民检察院对审查终结的案件，应当区分情况作出下列决定："},{"i":55,"n":"第五十五条","txt":"人民检察院在办理民事诉讼监督案件过程中，当事人有和解意愿的，可以建议当事人自行和解。"},{"i":56,"n":"第五十六条","txt":"人民检察院受理当事人申请对人民法院已经发生法律效力的民事判决、裁定、调解书监督的案件，应当在三个月内审查终结并作出决定。"},{"i":57,"n":"第五十七条","txt":"人民检察院审查民事诉讼监督案件，认为确有必要的，可以组织有关当事人听证。"},{"i":58,"n":"第五十八条","txt":"人民检察院组织听证，由承办该案件的检察人员主持，书记员负责记录。"},{"i":59,"n":"第五十九条","txt":"人民检察院组织听证，应当在听证三日前通知参加听证的当事人，并告知听证的时间、地点。"},{"i":60,"n":"第六十条","txt":"参加听证的当事人和其他相关人员应当按时参加听证，当事人无正当理由缺席或者未经许可中途退席的，不影响听证程序的进行。"},{"i":61,"n":"第六十一条","txt":"听证应当围绕民事诉讼监督案件中的事实认定和法律适用等问题进行。"},{"i":62,"n":"第六十二条","txt":"听证应当按照下列顺序进行："},{"i":63,"n":"第六十三条","txt":"听证应当制作笔录，经当事人校阅后，由当事人签名或者盖章。拒绝签名盖章的，应当记明情况。"},{"i":64,"n":"第六十四条","txt":"参加听证的人员应当服从听证主持人指挥。"},{"i":65,"n":"第六十五条","txt":"人民检察院因履行法律监督职责提出检察建议或者抗诉的需要，有下列情形之一的，可以向当事人或者案外人调查核实有关情况："},{"i":66,"n":"第六十六条","txt":"人民检察院可以采取以下调查核实措施："},{"i":67,"n":"第六十七条","txt":"人民检察院可以就专门性问题书面或者口头咨询有关专业人员、相关部门或者行业协会的意见。口头咨询的，应当制作笔录，由接受咨询的专业人员签名或者盖章。拒绝签名盖章的，应当记明情况。"},{"i":68,"n":"第六十八条","txt":"人民检察院对专门性问题认为需要鉴定、评估、审计的，可以委托具备资格的机构进行鉴定、评估、审计。"},{"i":69,"n":"第六十九条","txt":"人民检察院认为确有必要的，可以勘验物证或者现场。勘验人应当出示人民检察院的证件，并邀请当地基层组织或者当事人所在单位派人参加。当事人或者当事人的成年家属应当到场，拒不到场的，不影响勘验的进行。"},{"i":70,"n":"第七十条","txt":"需要调查核实的，由承办人提出，部门负责人或者检察长批准。"},{"i":71,"n":"第七十一条","txt":"人民检察院调查核实，应当由二人以上共同进行。"},{"i":72,"n":"第七十二条","txt":"人民检察院可以指令下级人民检察院或者委托外地人民检察院调查核实。"},{"i":73,"n":"第七十三条","txt":"人民检察院调查核实，有关单位和个人应当配合。拒绝或者妨碍人民检察院调查核实的，人民检察院可以向有关单位或者其上级主管部门提出检察建议，责令纠正；涉嫌犯罪的，依照规定移送有关机关处理。"},{"i":74,"n":"第七十四条","txt":"有下列情形之一的，人民检察院可以中止审查："},{"i":75,"n":"第七十五条","txt":"有下列情形之一的，人民检察院应当终结审查："},{"i":76,"n":"第七十六条","txt":"人民检察院发现人民法院已经发生法律效力的民事判决、裁定有《中华人民共和国民事诉讼法》第二百条规定情形之一的，依法向人民法院提出再审检察建议或者抗诉。"},{"i":77,"n":"第七十七条","txt":"人民检察院发现民事调解书损害国家利益、社会公共利益的，依法向人民法院提出再审检察建议或者抗诉。"},{"i":78,"n":"第七十八条","txt":"下列证据，应当认定为《中华人民共和国民事诉讼法》第二百条第一项规定的“新的证据”："},{"i":79,"n":"第七十九条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第二项规定的“认定的基本事实缺乏证据证明”："},{"i":80,"n":"第八十条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第六项规定的“适用法律确有错误”："},{"i":81,"n":"第八十一条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第七项规定的“审判组织的组成不合法”："},{"i":82,"n":"第八十二条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第九项规定的“违反法律规定，剥夺当事人辩论权利”："},{"i":83,"n":"第八十三条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的民事判决、裁定有下列情形之一的，可以向同级人民法院提出再审检察建议："},{"i":84,"n":"第八十四条","txt":"符合本规则第八十三条规定的案件有下列情形之一的，地方各级人民检察院应当提请上一级人民检察院抗诉："},{"i":85,"n":"第八十五条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的民事判决、裁定具有下列情形之一的，应当提请上一级人民检察院抗诉："},{"i":86,"n":"第八十六条","txt":"地方各级人民检察院发现民事调解书损害国家利益、社会公共利益的，可以向同级人民法院提出再审检察建议，也可以提请上一级人民检察院抗诉。"},{"i":87,"n":"第八十七条","txt":"对人民法院已经采纳再审检察建议进行再审的案件，提出再审检察建议的人民检察院一般不得再向上级人民检察院提请抗诉。"},{"i":88,"n":"第八十八条","txt":"人民检察院提出再审检察建议，应当制作《再审检察建议书》，在决定提出再审检察建议之日起十五日内将《再审检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出再审检察建议的《通知书》，发送当事人。"},{"i":89,"n":"第八十九条","txt":"人民检察院提请抗诉，应当制作《提请抗诉报告书》，在决定提请抗诉之日起十五日内将《提请抗诉报告书》连同案件卷宗报送上一级人民检察院，并制作决定提请抗诉的《通知书》，发送当事人。"},{"i":90,"n":"第九十条","txt":"人民检察院认为当事人的监督申请不符合提出再审检察建议或者提请抗诉条件的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送当事人。"},{"i":91,"n":"第九十一条","txt":"最高人民检察院对各级人民法院已经发生法律效力的民事判决、裁定、调解书，上级人民检察院对下级人民法院已经发生法律效力的民事判决、裁定、调解书，发现有《中华人民共和国民事诉讼法》第二百条、第二百零八条规定情形的，应当向同级人民法院提出抗诉。"},{"i":92,"n":"第九十二条","txt":"人民检察院提出抗诉，应当制作《抗诉书》，在决定抗诉之日起十五日内将《抗诉书》连同案件卷宗移送同级人民法院，并制作决定抗诉的《通知书》，发送当事人。"},{"i":93,"n":"第九十三条","txt":"人民检察院认为当事人的监督申请不符合抗诉条件的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送当事人。下级人民检察院提请抗诉的案件，上级人民检察院可以委托提请抗诉的人民检察院将《不支持监督申请决定书》发送当事人。"},{"i":94,"n":"第九十四条","txt":"人民检察院提出抗诉的案件，人民法院再审时，人民检察院应当派员出席法庭。"},{"i":95,"n":"第九十五条","txt":"受理抗诉的人民法院将抗诉案件交下级人民法院再审的，提出抗诉的人民检察院可以指令再审人民法院的同级人民检察院派员出庭。"},{"i":96,"n":"第九十六条","txt":"检察人员出席再审法庭的任务是："},{"i":97,"n":"第九十七条","txt":"《中华人民共和国民事诉讼法》第二百零八条第三款规定的审判程序包括："},{"i":98,"n":"第九十八条","txt":"《中华人民共和国民事诉讼法》第二百零八条第三款的规定适用于法官、人民陪审员、书记员。"},{"i":99,"n":"第九十九条","txt":"人民检察院发现同级人民法院民事审判程序中有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":100,"n":"第一百条","txt":"人民检察院依照本规则第九十九条提出检察建议的，应当制作《检察建议书》，在决定提出检察建议之日起十五日内将《检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出检察建议的《通知书》，发送申请人。"},{"i":101,"n":"第一百零一条","txt":"人民检察院认为当事人申请监督的审判程序中审判人员违法行为不存在或者不构成的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送申请人。"},{"i":102,"n":"第一百零二条","txt":"人民检察院对人民法院在民事执行活动中违反法律规定的情形实行法律监督。"},{"i":103,"n":"第一百零三条","txt":"人民检察院对民事执行活动提出检察建议的，应当经检察委员会决定，制作《检察建议书》，在决定之日起十五日内将《检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出检察建议的《通知书》，发送当事人。"},{"i":104,"n":"第一百零四条","txt":"人民检察院认为当事人申请监督的人民法院执行活动不存在违法情形的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送申请人。"},{"i":105,"n":"第一百零五条","txt":"人民检察院案件管理部门对民事诉讼监督案件实行流程监控、案后评查、统计分析、信息查询、综合考评等，对办案期限、办案程序、办案质量等进行管理、监督、预警。"},{"i":106,"n":"第一百零六条","txt":"民事检察部门在办理案件过程中有下列情形之一的，应当在作出决定之日起三日内到本院案件管理部门登记："},{"i":107,"n":"第一百零七条","txt":"案件管理部门发现本院办案部门或者办案人员在办理民事诉讼监督案件中有下列情形之一的，应当及时提出纠正意见："},{"i":108,"n":"第一百零八条","txt":"案件管理部门对以本院名义制发的民事诉讼监督法律文书实施监督管理。"},{"i":109,"n":"第一百零九条","txt":"人民检察院办理的民事诉讼监督案件，办结后需要向其他单位移送案卷材料的，统一由案件管理部门审核移送材料是否规范、齐备。案件管理部门认为材料规范、齐备，符合移送条件的，应当立即由有关部门按照相关规定移送；认为材料不符合要求的，应当及时通知办案部门补送、更正。"},{"i":110,"n":"第一百一十条","txt":"人民法院向人民检察院送达的民事判决书、裁定书或者调解书等法律文书，由案件管理部门负责接收，并即时登记移送民事检察部门。"},{"i":111,"n":"第一百一十一条","txt":"人民检察院在办理民事诉讼监督案件过程中，当事人及其诉讼代理人提出有关申请、要求或者提交有关书面材料的，由案件管理部门负责接收，需要出具相关手续的，案件管理部门应当出具。案件管理部门接收材料后应当及时移送民事检察部门。"},{"i":112,"n":"第一百一十二条","txt":"有下列情形之一的，人民检察院可以提出改进工作的检察建议："},{"i":113,"n":"第一百一十三条","txt":"民事检察部门在履行职责过程中，发现涉嫌犯罪的行为，应当及时将犯罪线索及相关材料移送本院相关职能部门。"},{"i":114,"n":"第一百一十四条","txt":"人民检察院向人民法院或者有关机关提出监督意见后，发现监督意见确有错误或者有其他情形确需撤回的，应当经检察长批准或者检察委员会决定予以撤回。"},{"i":115,"n":"第一百一十五条","txt":"人民法院对人民检察院监督行为提出建议的，人民检察院应当在一个月内将处理结果书面回复人民法院。人民法院对回复意见有异议，并通过上一级人民法院向上一级人民检察院提出的，上一级人民检察院认为人民法院建议正确，应当要求下级人民检察院及时纠正。"},{"i":116,"n":"第一百一十六条","txt":"人民法院对民事诉讼监督案件作出再审判决、裁定或者其他处理决定后，提出监督意见的人民检察院应当对处理结果进行审查，并填写《民事诉讼监督案件处理结果审查登记表》。"},{"i":117,"n":"第一百一十七条","txt":"有下列情形之一的，人民检察院应当按照有关规定跟进监督或者提请上级人民检察院监督："},{"i":118,"n":"第一百一十八条","txt":"地方各级人民检察院对适用法律确属疑难、复杂，本院难以决断的重大民事诉讼监督案件，可以向上一级人民检察院请示。"},{"i":119,"n":"第一百一十九条","txt":"制作民事诉讼监督法律文书，应当符合规定的格式。"},{"i":120,"n":"第一百二十条","txt":"人民检察院可以参照《中华人民共和国民事诉讼法》有关规定发送法律文书。"},{"i":121,"n":"第一百二十一条","txt":"人民检察院发现制作的法律文书存在笔误的，应当作出《补正决定书》予以补正。"},{"i":122,"n":"第一百二十二条","txt":"人民检察院办理民事诉讼监督案件，应当按照规定建立民事诉讼监督案卷。"},{"i":123,"n":"第一百二十三条","txt":"人民检察院办理民事诉讼监督案件，不收取案件受理费。申请复印、鉴定、审计、勘验等产生的费用由申请人直接支付给有关机构或者单位，人民检察院不得代收代付。"},{"i":124,"n":"第一百二十四条","txt":"本规则自发布之日起施行。本院之前公布的其他规定与本规则内容不一致的，以本规则为准。"}],"renminjianchayuantiqigongyisusongshidiangongzuoshicfdea0":[{"i":1,"n":"第一条","txt":"人民检察院履行职责中发现污染环境、食品药品安全领域侵害众多消费者合法权益等损害社会公共利益的行为，在没有适格主体或者适格主体不提起诉讼的情况下，可以向人民法院提起民事公益诉讼。"},{"i":2,"n":"第二条","txt":"人民检察院提起民事公益诉讼的案件，一般由侵权行为地、损害结果地或者被告住所地的市（分、州）人民检察院管辖。"},{"i":3,"n":"第三条","txt":"人民检察院提起民事公益诉讼案件的办理，由民事行政检察部门负责。"},{"i":4,"n":"第四条","txt":"人民检察院各业务部门在履行职责中，发现可能属于民事公益诉讼案件范围的案件线索，应当将有关材料移送民事行政检察部门。"},{"i":5,"n":"第五条","txt":"经审查认为污染环境、食品药品安全领域侵害众多消费者合法权益等行为可能损害社会公共利益的，应当报请检察长批准决定立案，并到案件管理部门登记。"},{"i":6,"n":"第六条","txt":"人民检察院可以采取以下方式调查核实污染环境、侵害众多消费者合法权益等违法行为、损害后果涉及的相关证据及有关情况："},{"i":7,"n":"第七条","txt":"民事行政检察部门在办理民事公益诉讼案件过程中，发现国家工作人员涉嫌贪污贿赂、渎职侵权等职务犯罪线索的，应当及时移送职务犯罪侦查部门；发现其他刑事犯罪线索的，应当及时移送侦查监督部门。"},{"i":8,"n":"第八条","txt":"人民检察院提起民事公益诉讼案件审查终结，承办人应当制作审查终结报告。审查终结报告应当全面、客观、公正地叙述案件事实，依据法律规定提出处理建议。"},{"i":9,"n":"第九条","txt":"办理民事公益诉讼案件应当经集体讨论。参加集体讨论的人员应当对案件事实、适用法律、处理建议等发表明确的意见并说明理由。集体讨论意见应当在全面、客观地归纳讨论意见的基础上形成。"},{"i":10,"n":"第十条","txt":"人民检察院对审查终结的民事公益诉讼案件，应当区分情况作出下列决定："},{"i":11,"n":"第十一条","txt":"人民检察院办理民事公益诉讼案件，拟作出第十条第一项、第二项决定的，应当自决定立案之日起三个月内办理终结；拟作出第十条第三项决定的，应当自决定立案之日起六个月内办理终结。有特殊情况需要延长的，报经检察长批准。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，人民检察院应当终结审查："},{"i":13,"n":"第十三条","txt":"人民检察院在提起民事公益诉讼之前，应当履行以下诉前程序："},{"i":14,"n":"第十四条","txt":"经过诉前程序，法律规定的机关和有关组织没有提起民事公益诉讼，或者没有适格主体提起诉讼，社会公共利益仍处于受侵害状态的，人民检察院可以提起民事公益诉讼。"},{"i":15,"n":"第十五条","txt":"人民检察院以公益诉讼人身份提起民事公益诉讼。民事公益诉讼的被告是实施损害社会公共利益行为的公民、法人或者其他组织。"},{"i":16,"n":"第十六条","txt":"人民检察院可以向人民法院提出要求被告停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失、赔礼道歉等诉讼请求。"},{"i":17,"n":"第十七条","txt":"人民检察院提起民事公益诉讼应当提交下列材料："},{"i":18,"n":"第十八条","txt":"人民检察院提起民事公益诉讼，被告没有反诉权。"},{"i":19,"n":"第十九条","txt":"人民检察院提起民事公益诉讼，对提出的诉讼请求所依据的事实或者反驳对方意见所依据的事实，以及履行诉前程序的事实，应当提供证据加以证明，法律另有规定的除外。"},{"i":20,"n":"第二十条","txt":"对于可能因被告一方的行为或者其他原因，使判决难以执行或者造成与社会公共利益相关的其他损害情形，人民检察院可以向人民法院建议对被告财产进行保全、责令其作出一定行为或者禁止其作出一定行为。"},{"i":21,"n":"第二十一条","txt":"人民法院开庭审理人民检察院提起的民事公益诉讼案件，人民检察院应当派员出席法庭。"},{"i":22,"n":"第二十二条","txt":"检察人员出席法庭的任务是："},{"i":23,"n":"第二十三条","txt":"民事公益诉讼案件，人民检察院可以与被告和解，人民法院可以调解。和解协议、调解协议不得损害社会公共利益。"},{"i":24,"n":"第二十四条","txt":"在民事公益诉讼审理过程中，人民检察院诉讼请求全部实现的，可以撤回起诉。"},{"i":25,"n":"第二十五条","txt":"地方各级人民检察院认为同级人民法院未生效的第一审判决、裁定确有错误，应当向上一级人民法院提出抗诉。"},{"i":26,"n":"第二十六条","txt":"地方各级人民检察院对同级人民法院未生效的第一审判决、裁定的抗诉，应当通过原审人民法院提出抗诉书，并且将抗诉书抄送上一级人民检察院。"},{"i":27,"n":"第二十七条","txt":"对人民检察院提出抗诉的二审案件或者人民法院决定开庭审理的上诉案件，同级人民检察院应当派员出席第二审法庭。"},{"i":28,"n":"第二十八条","txt":"人民检察院履行职责中发现生态环境和资源保护、国有资产保护、国有土地使用权出让等领域负有监督管理职责的行政机关违法行使职权或者不作为，造成国家和社会公共利益受到侵害，公民、法人和其他社会组织由于没有直接利害关系，没有也无法提起诉讼的，可以向人民法院提起行政公益诉讼。"},{"i":29,"n":"第二十九条","txt":"人民检察院提起行政公益诉讼的案件，一般由违法行使职权或者不作为的行政机关所在地的基层人民检察院管辖。"},{"i":30,"n":"第三十条","txt":"人民检察院提起行政公益诉讼案件的办理，由民事行政检察部门负责。"},{"i":31,"n":"第三十一条","txt":"人民检察院各业务部门在履行职责中，发现可能属于行政公益诉讼案件范围的案件线索，应当将有关材料移送民事行政检察部门。"},{"i":32,"n":"第三十二条","txt":"经审查认为生态环境和资源保护、国有资产保护、国有土地使用权出让等领域负有监督管理职责的行政机关违法行使职权或者不作为可能损害国家和社会公共利益的，应报请检察长批准决定立案，并到案件管理部门登记。"},{"i":33,"n":"第三十三条","txt":"人民检察院可以采取以下方式调查核实有关行政机关违法行使职权或者不作为的相关证据及有关情况："},{"i":34,"n":"第三十四条","txt":"民事行政检察部门在办理行政公益诉讼案件过程中，发现国家工作人员涉嫌贪污贿赂、渎职侵权等职务犯罪线索的，应当及时移送职务犯罪侦查部门；发现其他刑事犯罪线索的，应当及时移送侦查监督部门。"},{"i":35,"n":"第三十五条","txt":"人民检察院提起行政公益诉讼案件审查终结，承办人应当制作审查终结报告。审查终结报告应当全面、客观、公正地叙述案件事实，依据法律规定提出处理建议。"},{"i":36,"n":"第三十六条","txt":"办理行政公益诉讼案件应当经集体讨论。参加集体讨论的人员应当对案件事实、适用法律、处理建议等发表明确的意见并说明理由。集体讨论意见应当在全面、客观地归纳讨论意见的基础上形成。"},{"i":37,"n":"第三十七条","txt":"人民检察院对审查终结的行政公益诉讼案件，应当区分情况作出下列决定："},{"i":38,"n":"第三十八条","txt":"人民检察院办理行政公益诉讼案件，拟作出第三十七条第一项、第二项决定的，应当自决定立案之日起三个月内办理终结；拟作出第三十七条第三项决定的，应当自决定立案之日起六个月内办理终结。有特殊情况需要延长的，报经检察长批准。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，人民检察院应当终结审查："},{"i":40,"n":"第四十条","txt":"在提起行政公益诉讼之前，人民检察院应当先行向相关行政机关提出检察建议，督促其纠正违法行为或者依法履行职责。行政机关应当在收到检察建议书后一个月内依法办理，并将办理情况及时书面回复人民检察院。"},{"i":41,"n":"第四十一条","txt":"经过诉前程序，行政机关拒不纠正违法行为或者不履行法定职责，国家和社会公共利益仍处于受侵害状态的，人民检察院可以提起行政公益诉讼。"},{"i":42,"n":"第四十二条","txt":"人民检察院以公益诉讼人身份提起行政公益诉讼。行政公益诉讼的被告是生态环境和资源保护、国有资产保护、国有土地使用权出让等领域违法行使职权或者不作为的行政机关，以及法律、法规、规章授权的组织。"},{"i":43,"n":"第四十三条","txt":"人民检察院可以向人民法院提出撤销或者部分撤销违法行政行为、在一定期限内履行法定职责、确认行政行为违法或者无效等诉讼请求。"},{"i":44,"n":"第四十四条","txt":"人民检察院提起行政公益诉讼应当提交下列材料："},{"i":45,"n":"第四十五条","txt":"人民检察院提起行政公益诉讼，对下列事项承担举证责任："},{"i":46,"n":"第四十六条","txt":"人民法院开庭审理人民检察院提起的行政公益诉讼案件，人民检察院应当派员出席法庭。"},{"i":47,"n":"第四十七条","txt":"检察人员出席法庭的任务是："},{"i":48,"n":"第四十八条","txt":"行政公益诉讼案件不适用调解。"},{"i":49,"n":"第四十九条","txt":"在行政公益诉讼审理过程中，被告纠正违法行为或者依法履行职责而使人民检察院的诉讼请求全部实现的，人民检察院可以变更诉讼请求，请求判决确认行政行为违法，或者撤回起诉。"},{"i":50,"n":"第五十条","txt":"地方各级人民检察院认为同级人民法院未生效的第一审判决、裁定确有错误，应当向上一级人民法院提出抗诉。"},{"i":51,"n":"第五十一条","txt":"地方各级人民检察院对同级人民法院未生效的第一审判决、裁定的抗诉，应当通过原审人民法院提出抗诉书，并且将抗诉书抄送上一级人民检察院。"},{"i":52,"n":"第五十二条","txt":"对人民检察院提出抗诉的二审案件或者人民法院决定开庭审理的上诉案件，同级人民检察院应当派员出席第二审法庭。"},{"i":53,"n":"第五十三条","txt":"地方各级人民检察院拟决定向人民法院提起公益诉讼的，应当层报最高人民检察院审查批准。"},{"i":54,"n":"第五十四条","txt":"省级人民检察院向最高人民检察院报送审批的材料包括："},{"i":55,"n":"第五十五条","txt":"提起公益诉讼，人民检察院免缴诉讼费。"},{"i":56,"n":"第五十六条","txt":"本办法未规定的，分别适用民事诉讼法、行政诉讼法以及相关司法解释的规定。"},{"i":57,"n":"第五十七条","txt":"本办法仅适用于北京、内蒙古、吉林、江苏、安徽、福建、山东、湖北、广东、贵州、云南、陕西、甘肃等省、自治区、直辖市。"},{"i":58,"n":"第五十八条","txt":"本办法自发布之日起施行。本院之前发布的司法解释和规范性文件，与本办法规定不一致的，适用本办法。"}],"renminjianchayuanxingshisusongguize-2":[{"i":1,"n":"第一条","txt":"为保证人民检察院在刑事诉讼中严格依照法定程序办案，正确履行职权，实现惩罚犯罪与保障人权的统一，根据《中华人民共和国刑事诉讼法》、《中华人民共和国人民检察院组织法》和有关法律规定，结合人民检察院工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院在刑事诉讼中的任务，是立案侦查直接受理的案件、批准或者决定逮捕、审查起诉和提起公诉、对刑事诉讼实行法律监督，保证准确、及时地查明犯罪事实，正确应用法律，惩罚犯罪分子，保障无罪的人不受刑事追究，保障国家刑事法律的统一正确实施，维护社会主义法制，尊重和保障人权，保护公民的人身权利、财产权利、民主权利和其他权利，保障社会主义建设事业的顺利进行。"},{"i":3,"n":"第三条","txt":"人民检察院办理刑事案件，应当严格遵守《中华人民共和国刑事诉讼法》规定的各项基本原则和程序以及其他法律的有关规定。"},{"i":4,"n":"第四条","txt":"人民检察院办理刑事案件，由检察人员承办，办案部门负责人审核，检察长或者检察委员会决定。"},{"i":5,"n":"第五条","txt":"人民检察院按照法律规定设置内部机构，在刑事诉讼中实行案件受理、立案侦查、侦查监督、公诉、控告、申诉、监所检察等业务分工，各司其职，互相制约，保证办案质量。"},{"i":6,"n":"第六条","txt":"在刑事诉讼中，最高人民检察院领导地方各级人民检察院和专门人民检察院的工作，上级人民检察院领导下级人民检察院的工作。检察长统一领导检察院的工作。"},{"i":7,"n":"第七条","txt":"在刑事诉讼中，上级人民检察院对下级人民检察院作出的决定，有权予以撤销或者变更；发现下级人民检察院办理的案件有错误的，有权指令下级人民检察院予以纠正。"},{"i":8,"n":"第八条","txt":"人民检察院立案侦查贪污贿赂犯罪、国家工作人员的渎职犯罪、国家机关工作人员利用职权实施的非法拘禁、刑讯逼供、报复陷害、非法搜查的侵犯公民人身权利的犯罪以及侵犯公民民主权利的犯罪案件。"},{"i":9,"n":"第九条","txt":"国家机关工作人员利用职权实施的其他重大犯罪案件，需要由人民检察院直接受理的时候，经省级以上人民检察院决定，可以由人民检察院立案侦查。"},{"i":10,"n":"第十条","txt":"对本规则第九条规定的案件，基层人民检察院或者分、州、市人民检察院需要直接立案侦查的，应当层报省级人民检察院决定。分、州、市人民检察院对于基层人民检察院层报省级人民检察院的案件，应当进行审查，提出是否需要立案侦查的意见，报请省级人民检察院决定。"},{"i":11,"n":"第十一条","txt":"对于根据本规则第九条规定立案侦查的案件，应当根据案件性质，由人民检察院负责侦查的部门进行侦查。"},{"i":12,"n":"第十二条","txt":"人民检察院侦查直接受理的刑事案件涉及公安机关管辖的刑事案件，应当将属于公安机关管辖的刑事案件移送公安机关。在上述情况中，如果涉嫌主罪属于公安机关管辖，由公安机关为主侦查，人民检察院予以配合；如果涉嫌主罪属于人民检察院管辖，由人民检察院为主侦查，公安机关予以配合。"},{"i":13,"n":"第十三条","txt":"人民检察院对直接受理的案件实行分级立案侦查的制度。"},{"i":14,"n":"第十四条","txt":"上级人民检察院在必要的时候，可以直接立案侦查或者组织、指挥、参与侦查下级人民检察院管辖的案件，也可以将本院管辖的案件指定下级人民检察院立案侦查；下级人民检察院认为案情重大、复杂，需要由上级人民检察院立案侦查的案件，可以请求移送上级人民检察院立案侦查。"},{"i":15,"n":"第十五条","txt":"国家工作人员职务犯罪案件，由犯罪嫌疑人工作单位所在地的人民检察院管辖；如果由其他人民检察院管辖更为适宜的，可以由其他人民检察院管辖。"},{"i":16,"n":"第十六条","txt":"对管辖不明确的案件，可以由有关人民检察院协商确定管辖。对管辖有争议的或者情况特殊的案件，由共同的上级人民检察院指定管辖。"},{"i":17,"n":"第十七条","txt":"几个人民检察院都有权管辖的案件，由最初受理的人民检察院管辖。必要时，可以由主要犯罪地的人民检察院管辖。"},{"i":18,"n":"第十八条","txt":"上级人民检察院可以指定下级人民检察院立案侦查管辖不明或者需要改变管辖的案件。"},{"i":19,"n":"第十九条","txt":"军事检察院、铁路运输检察院等专门人民检察院的管辖以及军队、武装警察与地方互涉刑事案件的管辖，按照有关规定执行。"},{"i":20,"n":"第二十条","txt":"检察人员在受理举报和办理案件过程中，发现有刑事诉讼法第二十八条或者第二十九条规定的情形之一的，应当自行提出回避；没有自行提出回避的，人民检察院应当按照本规则第二十四条的规定决定其回避，当事人及其法定代理人有权要求其回避。"},{"i":21,"n":"第二十一条","txt":"检察人员自行回避的，可以口头或者书面提出，并说明理由。口头提出申请的，应当记录在案。"},{"i":22,"n":"第二十二条","txt":"人民检察院应当告知当事人及其法定代理人有依法申请回避的权利，并告知办理相关案件检察人员、书记员等的姓名、职务等有关情况。"},{"i":23,"n":"第二十三条","txt":"当事人及其法定代理人的回避要求，应当书面或者口头向人民检察院提出，并说明理由；根据刑事诉讼法第二十九条的规定提出回避申请的，应当提供有关证明材料。人民检察院经过审查或者调查，符合回避条件的，应当作出回避决定；不符合回避条件的，应当驳回申请。"},{"i":24,"n":"第二十四条","txt":"检察长的回避，由检察委员会讨论决定。检察委员会讨论检察长回避问题时，由副检察长主持，检察长不得参加。其他检察人员的回避，由检察长决定。"},{"i":25,"n":"第二十五条","txt":"当事人及其法定代理人要求公安机关负责人回避，应当向公安机关同级的人民检察院提出，由检察长提交检察委员会讨论决定。"},{"i":26,"n":"第二十六条","txt":"应当回避的人员，本人没有自行回避，当事人及其法定代理人也没有申请其回避的，检察长或者检察委员会应当决定其回避。"},{"i":27,"n":"第二十七条","txt":"人民检察院作出驳回申请回避的决定后，应当告知当事人及其法定代理人如不服本决定，有权在收到驳回申请回避的决定书后五日以内向原决定机关申请复议一次。"},{"i":28,"n":"第二十八条","txt":"当事人及其法定代理人对驳回申请回避的决定不服申请复议的，决定机关应当在三日以内作出复议决定并书面通知申请人。"},{"i":29,"n":"第二十九条","txt":"人民检察院直接受理案件的侦查人员或者进行补充侦查的人员在回避决定作出以前或者复议期间，不得停止对案件的侦查。"},{"i":30,"n":"第三十条","txt":"参加过本案侦查的侦查人员，不得承办本案的审查逮捕、起诉和诉讼监督工作。"},{"i":31,"n":"第三十一条","txt":"因符合刑事诉讼法第二十八条或者第二十九条规定的情形之一而回避的检察人员，在回避决定作出以前所取得的证据和进行的诉讼行为是否有效，由检察委员会或者检察长根据案件具体情况决定。"},{"i":32,"n":"第三十二条","txt":"本章所称检察人员，包括人民检察院检察长、副检察长、检察委员会委员、检察员和助理检察员。"},{"i":33,"n":"第三十三条","txt":"本规则关于回避的规定，适用于书记员、司法警察和人民检察院聘请或者指派的翻译人员、鉴定人。"},{"i":34,"n":"第三十四条","txt":"人民检察院在办案过程中，应当依法保障犯罪嫌疑人行使辩护权利。"},{"i":35,"n":"第三十五条","txt":"辩护人、诉讼代理人向人民检察院提出有关申请、要求或者提交有关书面材料的，案件管理部门应当接收并及时移送相关办案部门或者与相关办案部门协调、联系，具体业务由办案部门负责办理，本规则另有规定的除外。"},{"i":36,"n":"第三十六条","txt":"人民检察院侦查部门在第一次开始讯问犯罪嫌疑人或者对其采取强制措施的时候，应当告知犯罪嫌疑人有权委托辩护人，并告知其如果经济困难或者其他原因没有聘请辩护人的，可以申请法律援助。对于属于刑事诉讼法第三十四条规定情形的，应当告知犯罪嫌疑人有权获得法律援助。"},{"i":37,"n":"第三十七条","txt":"人民检察院办理直接受理立案侦查案件、审查逮捕案件和审查起诉案件，在押或者被指定居所监视居住的犯罪嫌疑人提出委托辩护人要求的，侦查部门、侦查监督部门和公诉部门应当及时向其监护人、近亲属或者其指定的人员转达其要求，并记录在案。"},{"i":38,"n":"第三十八条","txt":"在侦查期间，犯罪嫌疑人只能委托律师作为辩护人。在审查起诉期间，犯罪嫌疑人可以委托律师作为辩护人，也可以委托人民团体或者所在单位推荐的人以及监护人、亲友作为辩护人。但下列人员不得被委托担任辩护人："},{"i":39,"n":"第三十九条","txt":"审判人员、检察人员从人民法院、人民检察院离任后二年以内，不得以律师身份担任辩护人。"},{"i":40,"n":"第四十条","txt":"一名犯罪嫌疑人可以委托一至二人作为辩护人。"},{"i":41,"n":"第四十一条","txt":"人民检察院办理直接受理立案侦查案件和审查起诉案件，发现犯罪嫌疑人是盲、聋、哑人或者是尚未完全丧失辨认或者控制自己行为能力的精神病人，或者可能被判处无期徒刑、死刑，没有委托辩护人的，应当及时书面通知法律援助机构指派律师为其提供辩护。"},{"i":42,"n":"第四十二条","txt":"人民检察院收到在押或者被指定居所监视居住的犯罪嫌疑人提出的法律援助申请，应当在三日以内将其申请材料转交法律援助机构，并通知犯罪嫌疑人的监护人、近亲属或者其委托的其他人员协助提供有关证件、证明等相关材料。"},{"i":43,"n":"第四十三条","txt":"犯罪嫌疑人拒绝法律援助机构指派的律师作为辩护人的，人民检察院应当查明拒绝的原因，有正当理由的，予以准许，但犯罪嫌疑人需另行委托辩护人；犯罪嫌疑人未另行委托辩护人的，应当书面通知法律援助机构另行指派律师为其提供辩护。"},{"i":44,"n":"第四十四条","txt":"辩护人接受委托后告知人民检察院或者法律援助机构指派律师后通知人民检察院的，人民检察院案件管理部门应当及时登记辩护人的相关信息，并将有关情况和材料及时通知、移交相关办案部门。"},{"i":45,"n":"第四十五条","txt":"对于特别重大贿赂犯罪案件，犯罪嫌疑人被羁押或者监视居住的，人民检察院侦查部门应当在将犯罪嫌疑人送交看守所或者送交公安机关执行时书面通知看守所或者公安机关，在侦查期间辩护律师会见犯罪嫌疑人的，应当经人民检察院许可。"},{"i":46,"n":"第四十六条","txt":"对于特别重大贿赂犯罪案件，辩护律师在侦查期间提出会见在押或者被监视居住的犯罪嫌疑人的，人民检察院侦查部门应当提出是否许可的意见，在三日以内报检察长决定并答复辩护律师。"},{"i":47,"n":"第四十七条","txt":"自案件移送审查起诉之日起，人民检察院应当允许辩护律师查阅、摘抄、复制本案的案卷材料。"},{"i":48,"n":"第四十八条","txt":"自案件移送审查起诉之日起，律师以外的辩护人向人民检察院申请查阅、摘抄、复制本案的案卷材料或者申请同在押、被监视居住的犯罪嫌疑人会见和通信的，人民检察院公诉部门应当对申请人是否具备辩护人资格进行审查并提出是否许可的意见，在三日以内报检察长决定并书面通知申请人。"},{"i":49,"n":"第四十九条","txt":"辩护律师或者经过许可的其他辩护人到人民检察院查阅、摘抄、复制本案的案卷材料，由案件管理部门及时安排，由公诉部门提供案卷材料。因公诉部门工作等原因无法及时安排的，应当向辩护人说明，并安排辩护人自即日起三个工作日以内阅卷，公诉部门应当予以配合。"},{"i":50,"n":"第五十条","txt":"案件移送审查逮捕或者审查起诉后，辩护人认为在侦查期间公安机关收集的证明犯罪嫌疑人无罪或者罪轻的证据材料未提交，申请人民检察院向公安机关调取的，人民检察院案件管理部门应当及时将申请材料送侦查监督部门或者公诉部门办理。经审查，认为辩护人申请调取的证据已收集并且与案件事实有联系的，应当予以调取；认为辩护人申请调取的证据未收集或者与案件事实没有联系的，应当决定不予调取并向辩护人说明理由。公安机关移送相关证据材料的，人民检察院应当在三日以内告知辩护人。"},{"i":51,"n":"第五十一条","txt":"在人民检察院侦查、审查逮捕、审查起诉过程中，辩护人收集到有关犯罪嫌疑人不在犯罪现场、未达到刑事责任年龄、属于依法不负刑事责任的精神病人的证据，告知人民检察院的，人民检察院相关办案部门应当及时进行审查。"},{"i":52,"n":"第五十二条","txt":"案件移送审查起诉后，辩护律师依据刑事诉讼法第四十一条第一款的规定申请人民检察院收集、调取证据的，人民检察院案件管理部门应当及时将申请材料移送公诉部门办理。"},{"i":53,"n":"第五十三条","txt":"辩护律师向被害人或者其近亲属、被害人提供的证人收集与本案有关的材料，向人民检察院提出申请的，参照本规则第五十二条第一款的规定办理，人民检察院应当在七日以内作出是否许可的决定，通知辩护律师。人民检察院没有许可的，应当书面说明理由。"},{"i":54,"n":"第五十四条","txt":"在人民检察院侦查、审查逮捕、审查起诉过程中，辩护人提出要求听取其意见的，案件管理部门应当及时联系侦查部门、侦查监督部门或者公诉部门对听取意见作出安排。辩护人提出书面意见的，案件管理部门应当及时移送侦查部门、侦查监督部门或者公诉部门。"},{"i":55,"n":"第五十五条","txt":"人民检察院自收到移送审查起诉的案件材料之日起三日以内，应当告知被害人及其法定代理人或者其近亲属、附带民事诉讼的当事人及其法定代理人有权委托诉讼代理人。"},{"i":56,"n":"第五十六条","txt":"经人民检察院许可，诉讼代理人查阅、摘抄、复制本案的案卷材料的，参照本规则第四十七条至第四十九条的规定办理。"},{"i":57,"n":"第五十七条","txt":"辩护人、诉讼代理人认为公安机关、人民检察院、人民法院及其工作人员具有下列阻碍其依法行使诉讼权利的行为之一的，可以向同级或者上一级人民检察院申诉或者控告，控告检察部门应当接受并依法办理，相关办案部门应当予以配合："},{"i":58,"n":"第五十八条","txt":"辩护人、诉讼代理人认为其依法行使诉讼权利受到阻碍向人民检察院申诉或者控告的，人民检察院应当在受理后十日以内进行审查，情况属实的，经检察长决定，通知有关机关或者本院有关部门、下级人民检察院予以纠正，并将处理情况书面答复提出申诉或者控告的辩护人、诉讼代理人。"},{"i":59,"n":"第五十九条","txt":"辩护律师告知人民检察院其委托人或者其他人员准备实施、正在实施危害国家安全、公共安全以及严重危及他人人身安全犯罪的，人民检察院应当接受并立即移送有关机关依法处理。"},{"i":60,"n":"第六十条","txt":"人民检察院发现辩护人有帮助犯罪嫌疑人、被告人隐匿、毁灭、伪造证据或者串供，或者威胁、引诱证人作伪证以及其他干扰司法机关诉讼活动的行为，可能涉嫌犯罪的，经检察长批准，应当按照下列规定办理："},{"i":61,"n":"第六十一条","txt":"人民检察院在立案侦查、审查逮捕、审查起诉等办案活动中认定案件事实，应当以证据为根据。"},{"i":62,"n":"第六十二条","txt":"证据的审查认定，应当结合案件的具体情况，从证据与待证事实的关联程度、各证据之间的联系、是否依照法定程序收集等方面进行综合审查判断。"},{"i":63,"n":"第六十三条","txt":"人民检察院侦查终结或者提起公诉的案件，证据应当确实、充分。证据确实、充分，应当符合以下条件："},{"i":64,"n":"第六十四条","txt":"行政机关在行政执法和查办案件过程中收集的物证、书证、视听资料、电子数据等证据材料，应当以该机关的名义移送，经人民检察院审查符合法定要求的，可以作为证据使用。"},{"i":65,"n":"第六十五条","txt":"对采用刑讯逼供等非法方法收集的犯罪嫌疑人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当依法排除，不得作为报请逮捕、批准或者决定逮捕、移送审查起诉以及提起公诉的依据。"},{"i":66,"n":"第六十六条","txt":"收集物证、书证不符合法定程序，可能严重影响司法公正的，人民检察院应当及时要求侦查机关补正或者作出书面解释；不能补正或者无法作出合理解释的，对该证据应当予以排除。"},{"i":67,"n":"第六十七条","txt":"人民检察院经审查发现存在刑事诉讼法第五十四条规定的非法取证行为，依法对该证据予以排除后，其他证据不能证明犯罪嫌疑人实施犯罪行为的，应当不批准或者决定逮捕，已经移送审查起诉的，可以将案件退回侦查机关补充侦查或者作出不起诉决定。"},{"i":68,"n":"第六十八条","txt":"在侦查、审查起诉和审判阶段，人民检察院发现侦查人员以非法方法收集证据的，应当报经检察长批准，及时进行调查核实。"},{"i":69,"n":"第六十九条","txt":"对于非法证据的调查核实，在侦查阶段由侦查监督部门负责；在审查起诉、审判阶段由公诉部门负责。必要时，渎职侵权检察部门可以派员参加。"},{"i":70,"n":"第七十条","txt":"人民检察院可以采取以下方式对非法取证行为进行调查核实："},{"i":71,"n":"第七十一条","txt":"人民检察院调查完毕后，应当制作调查报告，根据查明的情况提出处理意见，报请检察长决定后依法处理。"},{"i":72,"n":"第七十二条","txt":"人民检察院认为存在以非法方法收集证据情形的，可以书面要求侦查机关对证据收集的合法性进行说明。说明应当加盖单位公章，并由侦查人员签名。"},{"i":73,"n":"第七十三条","txt":"对于公安机关立案侦查的案件，存在下列情形之一的，人民检察院在审查逮捕、审查起诉和审判阶段，可以调取公安机关讯问犯罪嫌疑人的录音、录像，对证据收集的合法性以及犯罪嫌疑人、被告人供述的真实性进行审查："},{"i":74,"n":"第七十四条","txt":"对于提起公诉的案件，被告人及其辩护人提出审前供述系非法取得，并提供相关线索或者材料的，人民检察院可以将讯问录音、录像连同案卷材料一并移送人民法院。"},{"i":75,"n":"第七十五条","txt":"在法庭审理过程中，被告人或者辩护人对讯问活动合法性提出异议，公诉人可以要求被告人及其辩护人提供相关线索或者材料。必要时，公诉人可以提请法庭当庭播放相关时段的讯问录音、录像，对有关异议或者事实进行质证。"},{"i":76,"n":"第七十六条","txt":"对于危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、毒品犯罪等案件，人民检察院在办理案件过程中，证人、鉴定人、被害人因在诉讼中作证，本人或者其近亲属人身安全面临危险，向人民检察院请求保护的，人民检察院应当受理并及时进行审查，对于确实存在人身安全危险的，应当立即采取必要的保护措施。人民检察院发现存在上述情形的，可以主动采取保护措施。"},{"i":77,"n":"第七十七条","txt":"证人在人民检察院侦查、审查起诉阶段因履行作证义务而支出的交通、住宿、就餐等费用，人民检察院应当给予补助。"},{"i":78,"n":"第七十八条","txt":"人民检察院根据案件情况，对犯罪嫌疑人可以拘传。"},{"i":79,"n":"第七十九条","txt":"拘传时，应当向被拘传的犯罪嫌疑人出示拘传证。对抗拒拘传的，可以使用械具，强制到案。"},{"i":80,"n":"第八十条","txt":"拘传持续的时间从犯罪嫌疑人到案时开始计算。犯罪嫌疑人到案后，应当责令其在拘传证上填写到案时间，并在拘传证上签名、捺指印或者盖章，然后立即讯问。讯问结束后，应当责令犯罪嫌疑人在拘传证上填写讯问结束时间。犯罪嫌疑人拒绝填写的，检察人员应当在拘传证上注明。"},{"i":81,"n":"第八十一条","txt":"人民检察院拘传犯罪嫌疑人，应当在犯罪嫌疑人所在市、县内的地点进行。"},{"i":82,"n":"第八十二条","txt":"需要对被拘传的犯罪嫌疑人变更强制措施的，应当经检察长或者检察委员会决定，在拘传期限内办理变更手续。"},{"i":83,"n":"第八十三条","txt":"人民检察院对于有下列情形之一的犯罪嫌疑人，可以取保候审："},{"i":84,"n":"第八十四条","txt":"人民检察院对于严重危害社会治安的犯罪嫌疑人，以及其他犯罪性质恶劣、情节严重的犯罪嫌疑人不得取保候审。"},{"i":85,"n":"第八十五条","txt":"被羁押或者监视居住的犯罪嫌疑人及其法定代理人、近亲属或者辩护人申请取保候审，经审查具有本规则第八十三条规定情形之一的，经检察长决定，可以对犯罪嫌疑人取保候审。"},{"i":86,"n":"第八十六条","txt":"被羁押或者监视居住的犯罪嫌疑人及其法定代理人、近亲属或者辩护人向人民检察院申请取保候审，人民检察院应当在三日以内作出是否同意的答复。经审查符合本规则第八十三条规定情形之一的，对被羁押的犯罪嫌疑人依法办理取保候审手续；经审查不符合取保候审条件的，应当告知申请人，并说明不同意取保候审的理由。"},{"i":87,"n":"第八十七条","txt":"人民检察院决定对犯罪嫌疑人取保候审，应当责令犯罪嫌疑人提出保证人或者交纳保证金。"},{"i":88,"n":"第八十八条","txt":"采取保证人担保方式的，保证人应当符合刑事诉讼法第六十七条规定的条件，并经人民检察院审查同意。"},{"i":89,"n":"第八十九条","txt":"人民检察院应当告知保证人履行以下义务："},{"i":90,"n":"第九十条","txt":"采取保证金担保方式的，人民检察院可以根据犯罪嫌疑人的社会危险性，案件的性质、情节、危害后果，可能判处刑罚的轻重，犯罪嫌疑人的经济状况等，责令犯罪嫌疑人交纳一千元以上的保证金，对于未成年犯罪嫌疑人可以责令交纳五百元以上的保证金。"},{"i":91,"n":"第九十一条","txt":"对犯罪嫌疑人取保候审，应当由办案人员提出意见，部门负责人审核，检察长决定。"},{"i":92,"n":"第九十二条","txt":"人民检察院决定对犯罪嫌疑人取保候审的，应当制作取保候审决定书，载明取保候审的期间、担保方式、被取保候审人应当履行的义务和应当遵守的规定。"},{"i":93,"n":"第九十三条","txt":"人民检察院应当向取保候审的犯罪嫌疑人宣读取保候审决定书，由犯罪嫌疑人签名、捺指印或者盖章，并责令犯罪嫌疑人遵守刑事诉讼法第六十九条的规定，告知其违反规定应负的法律责任；以保证金方式担保的，应当同时告知犯罪嫌疑人一次性将保证金存入公安机关指定银行的专门账户。"},{"i":94,"n":"第九十四条","txt":"向犯罪嫌疑人宣布取保候审决定后，人民检察院应当将执行取保候审通知书送达公安机关执行，并告知公安机关在执行期间拟批准犯罪嫌疑人离开所居住的市、县的，应当征得人民检察院同意。以保证人方式担保的，应当将取保候审保证书同时送达公安机关。"},{"i":95,"n":"第九十五条","txt":"采取保证人保证方式的，如果保证人在取保候审期间不愿继续担保或者丧失担保条件的，人民检察院应当在收到保证人不愿继续担保的申请或者发现其丧失担保条件后的三日以内，责令犯罪嫌疑人重新提出保证人或者交纳保证金，并将变更情况通知公安机关。"},{"i":96,"n":"第九十六条","txt":"采取保证金担保方式的，被取保候审人拒绝交纳保证金或者交纳保证金不足决定数额时，人民检察院应当作出变更取保候审措施、变更保证方式或者变更保证金数额的决定，并将变更情况通知公安机关。"},{"i":97,"n":"第九十七条","txt":"公安机关在执行取保候审期间向人民检察院征询是否同意批准犯罪嫌疑人离开所居住的市、县时，人民检察院应当根据案件的具体情况及时作出决定，并通知公安机关。"},{"i":98,"n":"第九十八条","txt":"人民检察院发现保证人没有履行刑事诉讼法第六十八条规定的义务，应当通知公安机关，要求公安机关对保证人作出罚款决定。构成犯罪的，依法追究保证人的刑事责任。"},{"i":99,"n":"第九十九条","txt":"人民检察院发现犯罪嫌疑人违反刑事诉讼法第六十九条的规定，已交纳保证金的，应当书面通知公安机关没收部分或者全部保证金，并且根据案件的具体情况，责令犯罪嫌疑人具结悔过，重新交纳保证金、提出保证人或者决定监视居住、予以逮捕。"},{"i":100,"n":"第一百条","txt":"犯罪嫌疑人有下列违反取保候审规定的行为，人民检察院应当对犯罪嫌疑人予以逮捕："},{"i":101,"n":"第一百零一条","txt":"人民检察院决定对犯罪嫌疑人取保候审，最长不得超过十二个月。"},{"i":102,"n":"第一百零二条","txt":"公安机关决定对犯罪嫌疑人取保候审，案件移送人民检察院审查起诉后，对于需要继续取保候审的，人民检察院应当依法重新作出取保候审决定，并对犯罪嫌疑人办理取保候审手续。取保候审的期限应当重新计算并告知犯罪嫌疑人。对继续采取保证金方式取保候审的，被取保候审人没有违反刑事诉讼法第六十九条规定的，不变更保证金数额，不再重新收取保证金。"},{"i":103,"n":"第一百零三条","txt":"在取保候审期间，不得中断对案件的侦查、审查起诉。"},{"i":104,"n":"第一百零四条","txt":"取保候审期限届满或者发现不应当追究犯罪嫌疑人的刑事责任的，应当及时解除或者撤销取保候审。"},{"i":105,"n":"第一百零五条","txt":"解除或者撤销取保候审，应当由办案人员提出意见，部门负责人审核，检察长决定。"},{"i":106,"n":"第一百零六条","txt":"解除或者撤销取保候审的决定，应当及时通知执行机关，并将解除或者撤销取保候审的决定书送达犯罪嫌疑人；有保证人的，应当通知保证人解除保证义务。"},{"i":107,"n":"第一百零七条","txt":"犯罪嫌疑人在取保候审期间没有违反刑事诉讼法第六十九条的规定，或者发现不应当追究犯罪嫌疑人刑事责任的，变更、解除或者撤销取保候审时，应当告知犯罪嫌疑人可以凭变更、解除或者撤销取保候审的通知或者有关法律文书到银行领取退还的保证金。"},{"i":108,"n":"第一百零八条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为取保候审期限届满，向人民检察院提出解除取保候审要求的，人民检察院应当在三日以内审查决定。经审查认为法定期限届满的，经检察长批准后，解除取保候审；经审查未超过法定期限的，书面答复申请人。"},{"i":109,"n":"第一百零九条","txt":"人民检察院对于符合逮捕条件，有下列情形之一的犯罪嫌疑人，可以监视居住："},{"i":110,"n":"第一百一十条","txt":"监视居住应当在犯罪嫌疑人的住处执行。对于犯罪嫌疑人无固定住处或者涉嫌特别重大贿赂犯罪在住处执行可能有碍侦查的，可以在指定的居所执行。"},{"i":111,"n":"第一百一十一条","txt":"对犯罪嫌疑人采取监视居住，应当由办案人员提出意见，部门负责人审核，检察长决定。"},{"i":112,"n":"第一百一十二条","txt":"对于特别重大贿赂犯罪案件决定指定居所监视居住的，人民检察院侦查部门应当自决定指定居所监视居住之日起每二个月对指定居所监视居住的必要性进行审查，没有必要继续指定居所监视居住或者案件已经办结的，应当解除指定居所监视居住或者变更强制措施。"},{"i":113,"n":"第一百一十三条","txt":"人民检察院应当向监视居住的犯罪嫌疑人宣读监视居住决定书，由犯罪嫌疑人签名、捺指印或者盖章，并责令犯罪嫌疑人遵守刑事诉讼法第七十五条的规定，告知其违反规定应负的法律责任。"},{"i":114,"n":"第一百一十四条","txt":"对犯罪嫌疑人决定在指定的居所执行监视居住，除无法通知的以外，人民检察院应当在执行监视居住后二十四小时以内，将指定居所监视居住的原因通知被监视居住人的家属。无法通知的，应当向检察长报告，并将原因写明附卷。无法通知的情形消除后，应当立即通知其家属。"},{"i":115,"n":"第一百一十五条","txt":"人民检察院核实犯罪嫌疑人住处或者为其指定居所后，应当制作监视居住执行通知书，将有关法律文书和案由、犯罪嫌疑人基本情况材料，送交监视居住地的公安机关执行，必要时人民检察院可以协助公安机关执行。"},{"i":116,"n":"第一百一十六条","txt":"公安机关在执行监视居住期间向人民检察院征询是否同意批准犯罪嫌疑人离开执行监视居住的处所、会见他人或者通信时，人民检察院应当根据案件的具体情况决定是否同意。"},{"i":117,"n":"第一百一十七条","txt":"人民检察院可以根据案件的具体情况，商请公安机关对被监视居住的犯罪嫌疑人采取电子监控、不定期检查等监视方法，对其遵守监视居住规定的情况进行监督。"},{"i":118,"n":"第一百一十八条","txt":"人民检察院应当依法对指定居所监视居住的决定是否合法实行监督。"},{"i":119,"n":"第一百一十九条","txt":"被指定居所监视居住人及其法定代理人、近亲属或者辩护人认为侦查机关、人民法院的指定居所监视居住决定存在违法情形，提出控告或者举报的，人民检察院应当受理，并报送或者移送本规则第一百一十八条规定的承担监督职责的部门办理。"},{"i":120,"n":"第一百二十条","txt":"人民检察院监所检察部门依法对指定居所监视居住的执行活动是否合法实行监督。发现下列违法情形的，应当及时提出纠正意见："},{"i":121,"n":"第一百二十一条","txt":"犯罪嫌疑人有下列违反监视居住规定的行为，人民检察院应当对犯罪嫌疑人予以逮捕："},{"i":122,"n":"第一百二十二条","txt":"人民检察院决定对犯罪嫌疑人监视居住，最长不得超过六个月。"},{"i":123,"n":"第一百二十三条","txt":"公安机关决定对犯罪嫌疑人监视居住，案件移送人民检察院审查起诉后，对于需要继续监视居住的，人民检察院应当依法重新作出监视居住决定，并对犯罪嫌疑人办理监视居住手续。监视居住的期限应当重新计算并告知犯罪嫌疑人。"},{"i":124,"n":"第一百二十四条","txt":"在监视居住期间，不得中断对案件的侦查、审查起诉。"},{"i":125,"n":"第一百二十五条","txt":"监视居住期限届满或者发现不应当追究犯罪嫌疑人刑事责任的，应当解除或者撤销监视居住。"},{"i":126,"n":"第一百二十六条","txt":"解除或者撤销监视居住，应当由办案人员提出意见，部门负责人审核，检察长决定。"},{"i":127,"n":"第一百二十七条","txt":"解除或者撤销监视居住的决定应当通知执行机关，并将解除或者撤销监视居住的决定书送达犯罪嫌疑人。"},{"i":128,"n":"第一百二十八条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为监视居住法定期限届满，向人民检察院提出解除监视居住要求的，人民检察院应当在三日以内审查决定。经审查认为法定期限届满的，经检察长批准后，解除监视居住；经审查未超过法定期限的，书面答复申请人。"},{"i":129,"n":"第一百二十九条","txt":"人民检察院对于有下列情形之一的犯罪嫌疑人，可以决定拘留："},{"i":130,"n":"第一百三十条","txt":"人民检察院拘留犯罪嫌疑人的时候，必须出示拘留证。"},{"i":131,"n":"第一百三十一条","txt":"人民检察院作出拘留决定后，应当将有关法律文书和案由、犯罪嫌疑人基本情况的材料送交同级公安机关执行。必要时人民检察院可以协助公安机关执行。"},{"i":132,"n":"第一百三十二条","txt":"担任县级以上人民代表大会代表的犯罪嫌疑人因现行犯被拘留的，人民检察院应当立即向该代表所属的人民代表大会主席团或者常务委员会报告；因为其他情形需要拘留的，人民检察院应当报请该代表所属的人民代表大会主席团或者常务委员会许可。"},{"i":133,"n":"第一百三十三条","txt":"对犯罪嫌疑人拘留后，除无法通知的以外，人民检察院应当在二十四小时以内，通知被拘留人的家属。"},{"i":134,"n":"第一百三十四条","txt":"对被拘留的犯罪嫌疑人，应当在拘留后的二十四小时以内进行讯问。"},{"i":135,"n":"第一百三十五条","txt":"对被拘留的犯罪嫌疑人，发现不应当拘留的，应当立即释放；依法可以取保候审或者监视居住的，按照本规则的有关规定办理取保候审或者监视居住手续。"},{"i":136,"n":"第一百三十六条","txt":"人民检察院拘留犯罪嫌疑人的羁押期限为十四日，特殊情况下可以延长一日至三日。"},{"i":137,"n":"第一百三十七条","txt":"公民将正在实行犯罪或者在犯罪后即被发觉的、通缉在案的、越狱逃跑的、正在被追捕的犯罪嫌疑人或者犯罪人扭送到人民检察院的，人民检察院应当予以接受，并且根据具体情况决定是否采取相应的紧急措施。对于不属于自己管辖的，应当移送主管机关处理。"},{"i":138,"n":"第一百三十八条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为人民检察院对拘留的犯罪嫌疑人法定羁押期限届满，向人民检察院提出释放犯罪嫌疑人或者变更拘留措施要求的，人民检察院侦查部门应当在三日以内审查完毕。"},{"i":139,"n":"第一百三十九条","txt":"人民检察院对有证据证明有犯罪事实，可能判处徒刑以上刑罚的犯罪嫌疑人，采取取保候审尚不足以防止发生下列社会危险性的，应当予以逮捕："},{"i":140,"n":"第一百四十条","txt":"对有证据证明有犯罪事实，可能判处十年有期徒刑以上刑罚的犯罪嫌疑人，应当批准或者决定逮捕。"},{"i":141,"n":"第一百四十一条","txt":"人民检察院经审查认为被取保候审、监视居住的犯罪嫌疑人违反取保候审、监视居住规定的，依照本规则第一百条、第一百二十一条的规定办理。"},{"i":142,"n":"第一百四十二条","txt":"对实施多个犯罪行为或者共同犯罪案件的犯罪嫌疑人，符合本规则第一百三十九条的规定，具有下列情形之一的，应当批准或者决定逮捕："},{"i":143,"n":"第一百四十三条","txt":"对具有下列情形之一的犯罪嫌疑人，人民检察院应当作出不批准逮捕的决定或者不予逮捕："},{"i":144,"n":"第一百四十四条","txt":"犯罪嫌疑人涉嫌的罪行较轻，且没有其他重大犯罪嫌疑，具有以下情形之一的，可以作出不批准逮捕的决定或者不予逮捕："},{"i":145,"n":"第一百四十五条","txt":"对符合刑事诉讼法第七十二条第一款规定的犯罪嫌疑人，人民检察院经审查认为不需要逮捕的，可以在作出不批准逮捕或者不予逮捕决定的同时，向侦查机关提出监视居住的建议。"},{"i":146,"n":"第一百四十六条","txt":"人民检察院对担任本级人民代表大会代表的犯罪嫌疑人批准或者决定逮捕，应当报请本级人民代表大会主席团或者常务委员会许可。报请许可手续的办理由侦查机关负责。"},{"i":147,"n":"第一百四十七条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为人民检察院采取强制措施法定期限届满，要求解除强制措施的，由人民检察院侦查部门或者公诉部门审查后报请检察长决定。人民检察院应当在收到申请后三日以内作出决定。"},{"i":148,"n":"第一百四十八条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人向人民检察院提出变更强制措施申请的，由人民检察院侦查部门或者公诉部门审查后报请检察长决定。人民检察院应当在收到申请后三日内作出决定。"},{"i":149,"n":"第一百四十九条","txt":"取保候审变更为监视居住，或者取保候审、监视居住变更为拘留、逮捕的，在变更的同时原强制措施自动解除，不再办理解除法律手续。"},{"i":150,"n":"第一百五十条","txt":"人民检察院已经对犯罪嫌疑人取保候审、监视居住，案件起诉至人民法院后，人民法院决定取保候审、监视居住或者变更强制措施的，原强制措施自动解除，不再办理解除法律手续。"},{"i":151,"n":"第一百五十一条","txt":"人民检察院提出抗诉的再审案件，需要对被告人采取强制措施的，适用本章及本规则第十章的规定。"},{"i":152,"n":"第一百五十二条","txt":"对于侦查机关、下级人民检察院移送的审查逮捕、审查起诉、延长侦查羁押期限、申请强制医疗、申请没收违法所得、提出或者提请抗诉、报请指定管辖等案件，由人民检察院案件管理部门统一受理。对人民检察院管辖的其他案件，需要由案件管理部门受理的，可以由案件管理部门受理。"},{"i":153,"n":"第一百五十三条","txt":"人民检察院案件管理部门受理案件时，应当接收案卷材料，并立即审查下列内容："},{"i":154,"n":"第一百五十四条","txt":"案件管理部门对接收的案卷材料审查后，认为具备受理条件的，应当及时进行登记，并立即将案卷材料和案件受理登记表移送相关办案部门办理。"},{"i":155,"n":"第一百五十五条","txt":"侦查机关送达的执行情况回执和人民法院送达的判决书、裁定书等法律文书，由案件管理部门负责接收。案件管理部门应当即时登记，并及时移送相关办案部门。"},{"i":156,"n":"第一百五十六条","txt":"人民检察院办理直接立案侦查的案件，移送审查逮捕、审查起诉的，按照本规则第一百五十二条至第一百五十四条的规定办理。"},{"i":157,"n":"第一百五十七条","txt":"人民检察院控告检察部门或者举报中心统一受理报案、控告、举报、申诉和犯罪嫌疑人投案自首，并根据具体情况和管辖规定，在七日以内作出以下处理："},{"i":158,"n":"第一百五十八条","txt":"控告检察部门或者举报中心对于以走访形式的报案、控告、举报和犯罪嫌疑人投案自首，应当指派两名以上工作人员接待，问明情况，并制作笔录，经核对无误后，由报案人、控告人、举报人、自首人签名、捺指印，必要时可以录音、录像；对报案人、控告人、举报人、自首人提供的有关证据材料、物品等应当登记，制作接受证据（物品）清单，并由报案人、控告人、举报人、自首人签名，必要时予以拍照，并妥善保管。"},{"i":159,"n":"第一百五十九条","txt":"接受控告、举报的检察人员，应当告知控告人、举报人如实控告、举报和捏造、歪曲事实应当承担的法律责任。"},{"i":160,"n":"第一百六十条","txt":"办案部门应当在规定期限内办理案件，并向控告检察部门或者举报中心书面回复办理结果。回复办理结果应当包括控告、申诉或举报事项、办理过程、认定的事实和证据、处理情况和法律依据以及执法办案风险评估情况等。"},{"i":161,"n":"第一百六十一条","txt":"人民检察院举报中心负责统一管理举报线索。本院其他部门或者人员对所接受的犯罪案件线索，应当在七日以内移送举报中心。"},{"i":162,"n":"第一百六十二条","txt":"控告检察部门或者举报中心对于不愿公开姓名和举报行为的举报人，应当为其保密。"},{"i":163,"n":"第一百六十三条","txt":"人民检察院对于直接受理的要案线索实行分级备案的管理制度。县、处级干部的要案线索一律报省级人民检察院举报中心备案，其中涉嫌犯罪数额特别巨大或者犯罪后果特别严重的，层报最高人民检察院举报中心备案；厅、局级以上干部的要案线索一律报最高人民检察院举报中心备案。"},{"i":164,"n":"第一百六十四条","txt":"要案线索的备案，应当逐案填写要案线索备案表。备案应当在受理后七日以内办理；情况紧急的，应当在备案之前及时报告。"},{"i":165,"n":"第一百六十五条","txt":"侦查部门收到举报中心移送的举报线索，应当在三个月以内将处理情况回复举报中心；下级人民检察院接到上级人民检察院移送的举报材料后，应当在三个月以内将处理情况回复上级人民检察院举报中心。情况复杂逾期不能办结的，报检察长批准，可以适当延长办理期限。"},{"i":166,"n":"第一百六十六条","txt":"举报中心应当对作出不立案决定的举报线索进行审查，认为不立案决定错误的，应当提出意见报检察长决定。如果符合立案条件的，应当立案侦查。"},{"i":167,"n":"第一百六十七条","txt":"举报中心对性质不明难以归口、检察长批交的举报线索应当进行初核。对群众多次举报未查处的举报线索，可以要求侦查部门说明理由，认为理由不充分的，报检察长决定。"},{"i":168,"n":"第一百六十八条","txt":"侦查部门对举报中心移交的举报线索进行审查后，认为有犯罪事实需要初查的，应当报检察长或者检察委员会决定。"},{"i":169,"n":"第一百六十九条","txt":"初查由侦查部门负责，在刑罚执行和监管活动中发现的应当由人民检察院直接立案侦查的案件线索，由监所检察部门负责初查。"},{"i":170,"n":"第一百七十条","txt":"各级人民检察院初查的分工，按照检察机关直接立案侦查案件分级管辖的规定确定。"},{"i":171,"n":"第一百七十一条","txt":"检察长或者检察委员会决定初查的，承办人员应当制作初查工作方案，经侦查部门负责人审核后，报检察长审批。"},{"i":172,"n":"第一百七十二条","txt":"初查一般应当秘密进行，不得擅自接触初查对象。公开进行初查或者接触初查对象，应当经检察长批准。"},{"i":173,"n":"第一百七十三条","txt":"在初查过程中，可以采取询问、查询、勘验、检查、鉴定、调取证据材料等不限制初查对象人身、财产权利的措施。不得对初查对象采取强制措施，不得查封、扣押、冻结初查对象的财产，不得采取技术侦查措施。"},{"i":174,"n":"第一百七十四条","txt":"根据初查工作需要，人民检察院可以商请有关部门配合调查。"},{"i":175,"n":"第一百七十五条","txt":"对案件进行初查的人民检察院可以委托其他人民检察院协助调查有关事项，委托协助调查应当提供初查审批表，并列明协助调查事项及有关要求。接受委托的人民检察院应当按照协助调查请求提供协助；对协助调查事项有争议的，应当提请双方共同的上级人民检察院协调解决。"},{"i":176,"n":"第一百七十六条","txt":"侦查部门对举报线索初查后，认为有犯罪事实需要追究刑事责任的，应当制作审查报告，提请批准立案侦查，报检察长决定。"},{"i":177,"n":"第一百七十七条","txt":"对上级人民检察院交办、指定管辖或者按照规定应当向上级人民检察院备案的案件线索，应当在初查终结后十日以内向上级人民检察院报告初查结论。"},{"i":178,"n":"第一百七十八条","txt":"对于实名举报，经初查决定不立案的，侦查部门应当制作不立案通知书，写明案由和案件来源、决定不立案的理由和法律依据，连同举报材料和调查材料，自作出不立案决定之日起十日以内移送本院举报中心，由举报中心答复举报人。必要时可以由举报中心与侦查部门共同答复。"},{"i":179,"n":"第一百七十九条","txt":"对于其他机关或者部门移送的案件线索，经初查决定不立案的，侦查部门应当制作不立案通知书，写明案由和案件来源、决定不立案的理由和法律依据，自作出不立案决定之日起十日以内送达移送案件线索的单位。"},{"i":180,"n":"第一百八十条","txt":"对于属于错告的，如果对被控告人、被举报人造成不良影响的，应当自作出决定之日起一个月以内向其所在单位或者有关部门通报初查结论，澄清事实。"},{"i":181,"n":"第一百八十一条","txt":"初查终结后，相关材料应当立卷归档。立案进入侦查程序的，对于作为诉讼证据以外的其他材料应当归入侦查内卷。"},{"i":182,"n":"第一百八十二条","txt":"刑事诉讼法以及本规则关于回避的规定，适用于初查。"},{"i":183,"n":"第一百八十三条","txt":"人民检察院对于直接受理的案件，经审查认为有犯罪事实需要追究刑事责任的，应当制作立案报告书，经检察长批准后予以立案。在决定立案之日起三日以内，将立案备案登记表、提请立案报告和立案决定书一并报送上一级人民检察院备案。"},{"i":184,"n":"第一百八十四条","txt":"人民检察院决定不予立案的，如果是被害人控告的，应当制作不立案通知书，写明案由和案件来源、决定不立案的原因和法律依据，由侦查部门在十五日以内送达控告人，同时告知本院控告检察部门。控告人如果不服，可以在收到不立案通知书后十日以内申请复议。"},{"i":185,"n":"第一百八十五条","txt":"人民检察院决定对人民代表大会代表立案，应当按照本规则第一百三十二条规定的程序向该代表所属的人民代表大会主席团或者常务委员会进行通报。"},{"i":186,"n":"第一百八十六条","txt":"人民检察院办理直接受理立案侦查的案件，应当全面、客观地收集、调取犯罪嫌疑人有罪或者无罪、罪轻或者罪重的证据材料，并依法进行审查、核实。"},{"i":187,"n":"第一百八十七条","txt":"人民检察院办理直接受理立案侦查的案件，必须重证据，重调查研究，不轻信口供。严禁刑讯逼供和以威胁、引诱、欺骗以及其他非法方法收集证据，不得强迫任何人证实自己有罪。"},{"i":188,"n":"第一百八十八条","txt":"人民检察院办理直接受理立案侦查的案件，应当保障犯罪嫌疑人和其他诉讼参与人依法享有的辩护权和其他各项诉讼权利。"},{"i":189,"n":"第一百八十九条","txt":"人民检察院办理直接受理立案侦查的案件，应当严格依照刑事诉讼法规定的条件和程序采取强制措施，严格遵守刑事案件办案期限的规定，依法提请批准逮捕、移送起诉、不起诉或撤销案件。"},{"i":190,"n":"第一百九十条","txt":"人民检察院办理直接受理立案侦查的案件，应当对侦查过程中知悉的国家秘密、商业秘密及个人隐私保密。"},{"i":191,"n":"第一百九十一条","txt":"人民检察院对于直接受理案件的侦查，可以适用刑事诉讼法第二编第二章规定的各项侦查措施。"},{"i":192,"n":"第一百九十二条","txt":"讯问犯罪嫌疑人，由检察人员负责进行。讯问的时候，检察人员不得少于二人。"},{"i":193,"n":"第一百九十三条","txt":"对于不需要逮捕、拘留的犯罪嫌疑人，经检察长批准，可以传唤到犯罪嫌疑人所在市、县内的指定地点或者到他的住处进行讯问。"},{"i":194,"n":"第一百九十四条","txt":"传唤犯罪嫌疑人时，其家属在场的，应当当场将传唤的原因和处所口头告知其家属，并在讯问笔录中注明。其家属不在场的，侦查人员应当及时将传唤的原因和处所通知被传唤人家属。无法通知的，应当在讯问笔录中注明。"},{"i":195,"n":"第一百九十五条","txt":"传唤持续的时间不得超过十二小时；案情特别重大、复杂，需要采取拘留、逮捕措施的，传唤持续的时间不得超过二十四小时。两次传唤间隔的时间一般不得少于十二小时，不得以连续传唤的方式变相拘禁犯罪嫌疑人。"},{"i":196,"n":"第一百九十六条","txt":"犯罪嫌疑人被送交看守所羁押后，检察人员对其进行讯问，应当填写提讯、提解证，在看守所讯问室进行。"},{"i":197,"n":"第一百九十七条","txt":"讯问犯罪嫌疑人一般按照下列顺序进行："},{"i":198,"n":"第一百九十八条","txt":"讯问聋、哑或者不通晓当地通用语言文字的人，人民检察院应当为其聘请通晓聋、哑手势或者当地通用语言文字且与本案无利害关系的人员进行翻译。翻译人员的姓名、性别、工作单位和职业应当记录在案。翻译人员应当在讯问笔录上签字。"},{"i":199,"n":"第一百九十九条","txt":"讯问犯罪嫌疑人，应当制作讯问笔录。讯问笔录应当忠实于原话，字迹清楚，详细具体，并交犯罪嫌疑人核对。犯罪嫌疑人没有阅读能力的，应当向他宣读。如果记载有遗漏或者差错，应当补充或者改正。犯罪嫌疑人认为讯问笔录没有错误的，由犯罪嫌疑人在笔录上逐页签名、盖章或者捺指印，并在末页写明“以上笔录我看过（向我宣读过），和我说的相符”，同时签名、盖章、捺指印并注明日期。如果犯罪嫌疑人拒绝签名、盖章、捺指印的，检察人员应当在笔录上注明。讯问的检察人员也应当在笔录上签名。"},{"i":200,"n":"第二百条","txt":"犯罪嫌疑人请求自行书写供述的，检察人员应当准许。必要的时候，检察人员也可以要求犯罪嫌疑人亲笔书写供述。犯罪嫌疑人应当在亲笔供述的末页签名、捺指印，并注明书写日期。检察人员收到后，应当在首页右上方写明“于某年某月某日收到”，并签名。"},{"i":201,"n":"第二百零一条","txt":"人民检察院立案侦查职务犯罪案件，在每次讯问犯罪嫌疑人的时候，应当对讯问过程实行全程录音、录像，并在讯问笔录中注明。"},{"i":202,"n":"第二百零二条","txt":"人民检察院讯问犯罪嫌疑人实行全程同步录音、录像，应当按照最高人民检察院的有关规定办理。"},{"i":203,"n":"第二百零三条","txt":"人民检察院在侦查过程中，应当及时询问证人，并且告知证人履行作证的权利和义务。"},{"i":204,"n":"第二百零四条","txt":"询问证人，应当由检察人员进行。询问的时候，检察人员不得少于二人。"},{"i":205,"n":"第二百零五条","txt":"询问证人，可以在现场进行，也可以到证人所在单位、住处或者证人提出的地点进行。必要时，也可以通知证人到人民检察院提供证言。到证人提出的地点进行询问的，应当在笔录中记明。"},{"i":206,"n":"第二百零六条","txt":"询问证人，应当问明证人的基本情况以及与当事人的关系，并且告知证人应当如实提供证据、证言和故意作伪证或者隐匿罪证应当承担的法律责任，但是不得向证人泄露案情，不得采用羁押、暴力、威胁、引诱、欺骗以及其他非法方法获取证言。"},{"i":207,"n":"第二百零七条","txt":"本规则第一百九十八条、第一百九十九条的规定，适用于询问证人。"},{"i":208,"n":"第二百零八条","txt":"询问被害人，适用询问证人的规定。"},{"i":209,"n":"第二百零九条","txt":"检察人员对于与犯罪有关的场所、物品、人身、尸体应当进行勘验或者检查。在必要的时候，可以指派检察技术人员或者聘请其他具有专门知识的人，在检察人员的主持下进行勘验、检查。"},{"i":210,"n":"第二百一十条","txt":"进行勘验、检查，应当持有检察长签发的勘查证。"},{"i":211,"n":"第二百一十一条","txt":"勘验时，人民检察院应当邀请二名与案件无关的见证人在场。"},{"i":212,"n":"第二百一十二条","txt":"人民检察院解剖死因不明的尸体，应当通知死者家属到场，并让其在解剖通知书上签名或者盖章。"},{"i":213,"n":"第二百一十三条","txt":"为了确定被害人、犯罪嫌疑人的某些特征、伤害情况或者生理状态，人民检察院可以对人身进行检查，可以提取指纹信息，采集血液、尿液等生物样本。"},{"i":214,"n":"第二百一十四条","txt":"人身检查不得采用损害被检查人生命、健康或贬低其名誉或人格的方法。"},{"i":215,"n":"第二百一十五条","txt":"勘验、检查的情况应当制作笔录，由参加勘验、检查的人员和见证人签名或者盖章。"},{"i":216,"n":"第二百一十六条","txt":"为了查明案情，在必要的时候，经检察长批准，可以进行侦查实验。"},{"i":217,"n":"第二百一十七条","txt":"侦查实验，在必要的时候可以聘请有关专业人员参加，也可以要求犯罪嫌疑人、被害人、证人参加。"},{"i":218,"n":"第二百一十八条","txt":"侦查实验，应当制作笔录，记明侦查实验的条件、经过和结果，由参加侦查实验的人员签名。必要时可以对侦查实验录音、录像。"},{"i":219,"n":"第二百一十九条","txt":"人民检察院有权要求有关单位和个人，交出能够证明犯罪嫌疑人有罪或者无罪以及犯罪情节轻重的证据。"},{"i":220,"n":"第二百二十条","txt":"为了收集犯罪证据，查获犯罪人，经检察长批准，检察人员可以对犯罪嫌疑人以及可能隐藏罪犯或者犯罪证据的人的身体、物品、住处、工作地点和其他有关的地方进行搜查。"},{"i":221,"n":"第二百二十一条","txt":"进行搜查，应当向被搜查人或者他的家属出示搜查证。"},{"i":222,"n":"第二百二十二条","txt":"人民检察院在搜查前，应当了解被搜查对象的基本情况、搜查现场及周围环境，确定搜查的范围和重点，明确搜查人员的分工和责任。"},{"i":223,"n":"第二百二十三条","txt":"搜查应当在检察人员的主持下进行，可以有司法警察参加。必要的时候，可以指派检察技术人员参加或者邀请当地公安机关、有关单位协助进行。"},{"i":224,"n":"第二百二十四条","txt":"在执行逮捕、拘留的时候，遇有下列紧急情况之一，不另用搜查证也可以进行搜查："},{"i":225,"n":"第二百二十五条","txt":"搜查时，应当有被搜查人或者他的家属、邻居或者其他见证人在场，并且对被搜查人或者其家属说明阻碍搜查、妨碍公务应负的法律责任。"},{"i":226,"n":"第二百二十六条","txt":"搜查时，如果遇到阻碍，可以强制进行搜查。对以暴力、威胁方法阻碍搜查的，应当予以制止，或者由司法警察将其带离现场；阻碍搜查构成犯罪的，应当依法追究刑事责任。"},{"i":227,"n":"第二百二十七条","txt":"搜查应当全面、细致、及时，并且指派专人严密注视搜查现场的动向。"},{"i":228,"n":"第二百二十八条","txt":"进行搜查的人员，应当遵守纪律，服从指挥，文明执法，不得无故损坏搜查现场的物品，不得擅自扩大搜查对象和范围。对于查获的重要书证、物证、视听资料、电子数据及其放置、存储地点应当拍照，并且用文字说明有关情况，必要的时候可以录像。"},{"i":229,"n":"第二百二十九条","txt":"搜查情况应当制作笔录，由检察人员和被搜查人或者其家属、邻居或者其他见证人签名或者盖章。被搜查人在逃，其家属拒不到场，或者拒绝签名、盖章的，应当记明笔录。"},{"i":230,"n":"第二百三十条","txt":"人民检察院到本辖区以外进行搜查，检察人员应当携带搜查证、工作证以及载有主要案情、搜查目的、要求等内容的公函，与当地人民检察院联系，当地人民检察院应当协助搜查。"},{"i":231,"n":"第二百三十一条","txt":"检察人员可以凭人民检察院的证明文件，向有关单位和个人调取能够证明犯罪嫌疑人有罪或者无罪以及犯罪情节轻重的证据材料，并且可以根据需要拍照、录像、复印和复制。"},{"i":232,"n":"第二百三十二条","txt":"人民检察院办理案件，需要向本辖区以外的有关单位和个人调取物证、书证等证据材料的，办案人员应当携带工作证、人民检察院的证明文件和有关法律文书，与当地人民检察院联系，当地人民检察院应当予以协助。"},{"i":233,"n":"第二百三十三条","txt":"调取物证应当调取原物。原物不便搬运、保存，或者依法应当返还被害人，或者因保密工作需要不能调取原物的，可以将原物封存，并拍照、录像。对原物拍照或者录像应当足以反映原物的外形、内容。"},{"i":234,"n":"第二百三十四条","txt":"在侦查活动中发现的可以证明犯罪嫌疑人有罪、无罪或者犯罪情节轻重的各种财物和文件，应当查封或者扣押；与案件无关的，不得查封或者扣押。"},{"i":235,"n":"第二百三十五条","txt":"人民检察院查封、扣押财物和文件，应当经检察长批准，由两名以上检察人员执行。"},{"i":236,"n":"第二百三十六条","txt":"对于查封、扣押的财物和文件，检察人员应当会同在场见证人和被查封、扣押物品持有人查点清楚，当场开列查封、扣押清单一式四份，注明查封、扣押物品的名称、型号、规格、数量、质量、颜色、新旧程度、包装等主要特征，由检察人员、见证人和持有人签名或者盖章，一份交给文件、资料和其他物品持有人，一份交被查封、扣押文件、资料和其他物品保管人，一份附卷，一份保存。持有人拒绝签名、盖章或者不在场的，应当在清单上记明。"},{"i":237,"n":"第二百三十七条","txt":"对于应当查封的不动产和置于该不动产上不宜移动的设施、家具和其他相关财物，以及涉案的车辆、船舶、航空器和大型机械、设备等财物，必要时可以扣押其权利证书，经拍照或者录像后原地封存，并开具查封清单一式四份，注明相关财物的详细地址和相关特征，同时注明已经拍照或者录像及其权利证书已被扣押，由检察人员、见证人和持有人签名或者盖章。持有人拒绝签名、盖章或者不在场的，应当在清单上注明。"},{"i":238,"n":"第二百三十八条","txt":"扣押犯罪嫌疑人的邮件、电报或者电子邮件，应当经检察长批准，通知邮电部门或者网络服务单位将有关的邮件、电报或者电子邮件检交扣押。"},{"i":239,"n":"第二百三十九条","txt":"查封单位的涉密电子设备、文件等物品，应当在拍照或者录像后当场密封，由检察人员、见证人、单位有关负责人签名或者盖章。启封时应当有见证人、单位有关负责人在场并签名或者盖章。"},{"i":240,"n":"第二百四十条","txt":"对于查封、扣押在人民检察院的物品、文件、邮件、电报，应当妥善保管，不得使用、调换、损毁或者自行处理。经查明确实与案件无关的，应当在三日以内作出解除或者退还决定，并通知有关单位、当事人办理相关手续。"},{"i":241,"n":"第二百四十一条","txt":"人民检察院根据侦查犯罪的需要，可以依照规定查询、冻结犯罪嫌疑人的存款、汇款、债券、股票、基金份额等财产，并可以要求有关单位和个人配合。"},{"i":242,"n":"第二百四十二条","txt":"查询、冻结犯罪嫌疑人的存款、汇款、债券、股票、基金份额等财产，应当经检察长批准，制作查询、冻结财产通知书，通知银行或者其他金融机构、邮电部门执行。"},{"i":243,"n":"第二百四十三条","txt":"犯罪嫌疑人的存款、汇款、债券、股票、基金份额等财产已冻结的，人民检察院不得重复冻结，但是应当要求有关银行或者其他金融机构、邮电部门在解除冻结或者作出处理前通知人民检察院。"},{"i":244,"n":"第二百四十四条","txt":"扣押、冻结债券、股票、基金份额等财产，应当书面告知当事人或者其法定代理人、委托代理人有权申请出售。"},{"i":245,"n":"第二百四十五条","txt":"对于冻结的存款、汇款、债券、股票、基金份额等财产，经查明确实与案件无关的，应当在三日以内解除冻结，并通知被冻结存款、汇款、债券、股票、基金份额等财产的所有人。"},{"i":246,"n":"第二百四十六条","txt":"查询、冻结与案件有关的单位的存款、汇款、债券、股票、基金份额等财产的办法适用本规则第二百四十一条至第二百四十五条的规定。"},{"i":247,"n":"第二百四十七条","txt":"人民检察院为了查明案情，解决案件中某些专门性的问题，可以进行鉴定。"},{"i":248,"n":"第二百四十八条","txt":"鉴定由检察长批准，由人民检察院技术部门有鉴定资格的人员进行。必要的时候，也可以聘请其他有鉴定资格的人员进行，但是应当征得鉴定人所在单位的同意。"},{"i":249,"n":"第二百四十九条","txt":"人民检察院应当为鉴定人进行鉴定提供必要条件，及时向鉴定人送交有关检材和对比样本等原始材料，介绍与鉴定有关的情况，并明确提出要求鉴定解决的问题，但是不得暗示或者强迫鉴定人作出某种鉴定意见。"},{"i":250,"n":"第二百五十条","txt":"鉴定人进行鉴定后，应当出具鉴定意见、检验报告，同时附上鉴定机构和鉴定人的资质证明，并且签名或者盖章。"},{"i":251,"n":"第二百五十一条","txt":"鉴定人故意作虚假鉴定的，应当承担法律责任。"},{"i":252,"n":"第二百五十二条","txt":"对于鉴定意见，检察人员应当进行审查，必要的时候，可以提出补充鉴定或者重新鉴定的意见，报检察长批准后进行补充鉴定或者重新鉴定。检察长也可以直接决定进行补充鉴定或者重新鉴定。"},{"i":253,"n":"第二百五十三条","txt":"用作证据的鉴定意见，人民检察院办案部门应当告知犯罪嫌疑人、被害人；被害人死亡或者没有诉讼行为能力的，应当告知其法定代理人、近亲属或诉讼代理人。"},{"i":254,"n":"第二百五十四条","txt":"人民检察院决定重新鉴定的，应当另行指派或者聘请鉴定人。"},{"i":255,"n":"第二百五十五条","txt":"对犯罪嫌疑人作精神病鉴定的期间不计入羁押期限和办案期限。"},{"i":256,"n":"第二百五十六条","txt":"对于因鉴定时间较长、办案期限届满仍不能终结的案件，自期限届满之日起，应当依法释放被羁押的犯罪嫌疑人或者变更强制措施。"},{"i":257,"n":"第二百五十七条","txt":"为了查明案情，在必要的时候，检察人员可以让被害人、证人和犯罪嫌疑人对与犯罪有关的物品、文件、尸体或场所进行辨认；也可以让被害人、证人对犯罪嫌疑人进行辨认，或者让犯罪嫌疑人对其他犯罪嫌疑人进行辨认。"},{"i":258,"n":"第二百五十八条","txt":"辨认应当在检察人员的主持下进行，主持辨认的检察人员不得少于二人。在辨认前，应当向辨认人详细询问被辨认对象的具体特征，避免辨认人见到被辨认对象，并应当告知辨认人有意作虚假辨认应负的法律责任。"},{"i":259,"n":"第二百五十九条","txt":"几名辨认人对同一被辨认对象进行辨认时，应当由每名辨认人单独进行。必要的时候，可以有见证人在场。"},{"i":260,"n":"第二百六十条","txt":"辨认时，应当将辨认对象混杂在其他对象中，不得给辨认人任何暗示。"},{"i":261,"n":"第二百六十一条","txt":"辨认的情况，应当制作笔录，由检察人员、辨认人、见证人签字。对辨认对象应当拍照，必要时可以对辨认过程进行录音、录像。"},{"i":262,"n":"第二百六十二条","txt":"人民检察院主持进行辨认，可以商请公安机关参加或者协助。"},{"i":263,"n":"第二百六十三条","txt":"人民检察院在立案后，对于涉案数额在十万元以上、采取其他方法难以收集证据的重大贪污、贿赂犯罪案件以及利用职权实施的严重侵犯公民人身权利的重大犯罪案件，经过严格的批准手续，可以采取技术侦查措施，交有关机关执行。"},{"i":264,"n":"第二百六十四条","txt":"人民检察院办理直接受理立案侦查的案件，需要追捕被通缉或者批准、决定逮捕的在逃的犯罪嫌疑人、被告人的，经过批准，可以采取追捕所必需的技术侦查措施，不受本规则第二百六十三条规定的案件范围的限制。"},{"i":265,"n":"第二百六十五条","txt":"人民检察院采取技术侦查措施应当根据侦查犯罪的需要，确定采取技术侦查措施的种类和适用对象，按照有关规定报请批准。批准决定自签发之日起三个月以内有效。对于不需要继续采取技术侦查措施的，应当及时解除；对于复杂、疑难案件，期限届满仍有必要继续采取技术侦查措施的，应当在期限届满前十日以内制作呈请延长技术侦查措施期限报告书，写明延长的期限及理由，经过原批准机关批准，有效期可以延长，每次不得超过三个月。"},{"i":266,"n":"第二百六十六条","txt":"采取技术侦查措施收集的物证、书证及其他证据材料，侦查人员应当制作相应的说明材料，写明获取证据的时间、地点、数量、特征以及采取技术侦查措施的批准机关、种类等，并签名和盖章。"},{"i":267,"n":"第二百六十七条","txt":"检察人员对采取技术侦查措施过程中知悉的国家秘密、商业秘密和个人隐私，应当保密；对采取技术侦查措施获取的与案件无关的材料，应当及时销毁，并对销毁情况制作记录。"},{"i":268,"n":"第二百六十八条","txt":"人民检察院办理直接受理立案侦查的案件，应当逮捕的犯罪嫌疑人如果在逃，或者已被逮捕的犯罪嫌疑人脱逃的，经检察长批准，可以通缉。"},{"i":269,"n":"第二百六十九条","txt":"各级人民检察院需要在本辖区内通缉犯罪嫌疑人的，可以直接决定通缉；需要在本辖区外通缉犯罪嫌疑人的，由有决定权的上级人民检察院决定。"},{"i":270,"n":"第二百七十条","txt":"人民检察院应当将通缉通知书和通缉对象的照片、身份、特征、案情简况送达公安机关，由公安机关发布通缉令，追捕归案。"},{"i":271,"n":"第二百七十一条","txt":"为防止犯罪嫌疑人等涉案人员逃往境外，需要在边防口岸采取边控措施的，人民检察院应当按照有关规定制作边控对象通知书，商请公安机关办理边控手续。"},{"i":272,"n":"第二百七十二条","txt":"人民检察院应当及时了解通缉的执行情况。"},{"i":273,"n":"第二百七十三条","txt":"对于应当逮捕的犯罪嫌疑人，如果潜逃出境，可以按照有关规定层报最高人民检察院商请国际刑警组织中国国家中心局，请求有关方面协助，或者通过其他法律规定的途径进行追捕。"},{"i":274,"n":"第二百七十四条","txt":"对犯罪嫌疑人逮捕后的侦查羁押期限不得超过二个月。基层人民检察院，分、州、市人民检察院和省级人民检察院直接受理立案侦查的案件，案情复杂、期限届满不能终结的案件，可以经上一级人民检察院批准延长一个月。"},{"i":275,"n":"第二百七十五条","txt":"基层人民检察院和分、州、市人民检察院直接受理立案侦查的案件，属于交通十分不便的边远地区的重大复杂案件、重大的犯罪集团案件、流窜作案的重大复杂案件和犯罪涉及面广、取证困难的重大复杂案件，在依照本规则第二百七十四条规定的期限届满前不能侦查终结的，经省、自治区、直辖市人民检察院批准，可以延长二个月。"},{"i":276,"n":"第二百七十六条","txt":"基层人民检察院和分、州、市人民检察院直接受理立案侦查的案件，对犯罪嫌疑人可能判处十年有期徒刑以上刑罚，依照本规则第二百七十五条的规定依法延长羁押期限届满，仍不能侦查终结的，经省、自治区、直辖市人民检察院批准，可以再延长二个月。"},{"i":277,"n":"第二百七十七条","txt":"最高人民检察院直接受理立案侦查的案件，依照刑事诉讼法的规定需要延长侦查羁押期限的，直接决定延长侦查羁押期限。"},{"i":278,"n":"第二百七十八条","txt":"公安机关需要延长侦查羁押期限的，应当在侦查羁押期限届满七日前，向同级人民检察院移送延长侦查羁押期限意见书，写明案件的主要案情和延长侦查羁押期限的具体理由。"},{"i":279,"n":"第二百七十九条","txt":"人民检察院审查批准或者决定延长侦查羁押期限，由侦查监督部门办理。"},{"i":280,"n":"第二百八十条","txt":"因为特殊原因，在较长时间内不宜交付审判的特别重大复杂的案件，由最高人民检察院报请全国人民代表大会常务委员会批准延期审理。"},{"i":281,"n":"第二百八十一条","txt":"人民检察院在侦查期间发现犯罪嫌疑人另有重要罪行的，自发现之日起依照本规则第二百七十四条的规定重新计算侦查羁押期限。"},{"i":282,"n":"第二百八十二条","txt":"人民检察院重新计算侦查羁押期限，应当由侦查部门提出重新计算侦查羁押期限的意见，移送本院侦查监督部门审查。侦查监督部门审查后应当提出是否同意重新计算侦查羁押期限的意见，报检察长决定。"},{"i":283,"n":"第二百八十三条","txt":"对公安机关重新计算侦查羁押期限的备案，由侦查监督部门审查。侦查监督部门认为公安机关重新计算侦查羁押期限不当的，应当提出纠正意见，报检察长决定后，通知公安机关纠正。"},{"i":284,"n":"第二百八十四条","txt":"人民检察院直接受理立案侦查的案件，不能在法定侦查羁押期限内侦查终结的，应当依法释放犯罪嫌疑人或者变更强制措施。"},{"i":285,"n":"第二百八十五条","txt":"侦查监督部门审查延长侦查羁押期限、审查重新计算侦查羁押期限案件，可以讯问犯罪嫌疑人，听取律师意见，调取案卷及相关材料等。"},{"i":286,"n":"第二百八十六条","txt":"人民检察院经过侦查，认为犯罪事实清楚，证据确实、充分，依法应当追究刑事责任的案件，应当写出侦查终结报告，并且制作起诉意见书。"},{"i":287,"n":"第二百八十七条","txt":"提出起诉意见或者不起诉意见的，侦查部门应当将起诉意见书或者不起诉意见书，查封、扣押、冻结的犯罪嫌疑人的财物及其孳息、文件清单以及对查封、扣押、冻结的涉案款物的处理意见和其他案卷材料，一并移送本院公诉部门审查。国家或者集体财产遭受损失的，在提出提起公诉意见的同时，可以提出提起附带民事诉讼的意见。"},{"i":288,"n":"第二百八十八条","txt":"在案件侦查过程中，犯罪嫌疑人委托辩护律师的，检察人员可以听取辩护律师的意见。"},{"i":289,"n":"第二百八十九条","txt":"上级人民检察院侦查终结的案件，依照刑事诉讼法的规定应当由下级人民检察院提起公诉或者不起诉的，应当将有关决定、侦查终结报告连同案卷材料、证据移送下级人民检察院，由下级人民检察院按照上级人民检察院有关决定交侦查部门制作起诉意见书或者不起诉意见书，移送本院公诉部门审查。"},{"i":290,"n":"第二百九十条","txt":"人民检察院在侦查过程中或者侦查终结后，发现具有下列情形之一的，侦查部门应当制作拟撤销案件意见书，报请检察长或者检察委员会决定："},{"i":291,"n":"第二百九十一条","txt":"检察长或者检察委员会决定撤销案件的，侦查部门应当将撤销案件意见书连同本案全部案卷材料，在法定期限届满七日前报上一级人民检察院审查；重大、复杂案件在法定期限届满十日前报上一级人民检察院审查。"},{"i":292,"n":"第二百九十二条","txt":"上一级人民检察院审查下级人民检察院报送的拟撤销案件，应当于收到案件后七日以内批复；重大、复杂案件，应当于收到案件后十日以内批复下级人民检察院。情况紧急或者因其他特殊原因不能按时送达的，可以先行通知下级人民检察院执行。"},{"i":293,"n":"第二百九十三条","txt":"上一级人民检察院同意撤销案件的，下级人民检察院应当作出撤销案件决定，并制作撤销案件决定书。上一级人民检察院不同意撤销案件的，下级人民检察院应当执行上一级人民检察院的决定。"},{"i":294,"n":"第二百九十四条","txt":"撤销案件的决定，应当分别送达犯罪嫌疑人所在单位和犯罪嫌疑人。犯罪嫌疑人死亡的，应当送达犯罪嫌疑人原所在单位。如果犯罪嫌疑人在押，应当制作决定释放通知书，通知公安机关依法释放。"},{"i":295,"n":"第二百九十五条","txt":"人民检察院作出撤销案件决定的，侦查部门应当在三十日以内对犯罪嫌疑人的违法所得作出处理，并制作查封、扣押、冻结款物的处理报告，详细列明每一项款物的来源、去向并附有关法律文书复印件，报检察长审核后存入案卷，并在撤销案件决定书中写明对查封、扣押、冻结的涉案款物的处理结果。情况特殊的，经检察长决定，可以延长三十日。"},{"i":296,"n":"第二百九十六条","txt":"人民检察院撤销案件时，对犯罪嫌疑人的违法所得应当区分不同情形，作出相应处理："},{"i":297,"n":"第二百九十七条","txt":"人民检察院撤销案件时，对查封、扣押、冻结的犯罪嫌疑人的涉案财产需要返还犯罪嫌疑人的，应当解除查封、扣押或者书面通知有关金融机构解除冻结，返还犯罪嫌疑人或者其合法继承人。"},{"i":298,"n":"第二百九十八条","txt":"查封、扣押、冻结的款物，除依法应当返还被害人或者经查明确实与案件无关的以外，不得在诉讼程序终结之前处理。法律和有关规定另有规定的除外。"},{"i":299,"n":"第二百九十九条","txt":"处理查封、扣押、冻结的涉案款物，应当由办案部门提出意见，报请检察长决定。负责保管涉案款物的管理部门会同办案部门办理相关的处理手续。"},{"i":300,"n":"第三百条","txt":"人民检察院直接受理立案侦查的共同犯罪案件，如果同案犯罪嫌疑人在逃，但在案犯罪嫌疑人犯罪事实清楚，证据确实、充分的，对在案犯罪嫌疑人应当根据本规则第二百八十六条的规定分别移送审查起诉或者移送审查不起诉。"},{"i":301,"n":"第三百零一条","txt":"人民检察院直接受理立案侦查的案件，对犯罪嫌疑人没有采取取保候审、监视居住、拘留或者逮捕措施的，侦查部门应当在立案后二年以内提出移送审查起诉、移送审查不起诉或者撤销案件的意见；对犯罪嫌疑人采取取保候审、监视居住、拘留或者逮捕措施的，侦查部门应当在解除或者撤销强制措施后一年以内提出移送审查起诉、移送审查不起诉或者撤销案件的意见。"},{"i":302,"n":"第三百零二条","txt":"人民检察院直接受理立案侦查的案件，撤销案件以后，又发现新的事实或者证据，认为有犯罪事实需要追究刑事责任的，可以重新立案侦查。"},{"i":303,"n":"第三百零三条","txt":"人民检察院审查批准或者决定逮捕犯罪嫌疑人，由侦查监督部门办理。"},{"i":304,"n":"第三百零四条","txt":"侦查监督部门办理审查逮捕案件，应当指定办案人员进行审查。办案人员应当审阅案卷材料和证据，依法讯问犯罪嫌疑人、询问证人等诉讼参与人、听取辩护律师意见，制作审查逮捕意见书，提出批准或者决定逮捕、不批准或者不予逮捕的意见，经部门负责人审核后，报请检察长批准或者决定；重大案件应当经检察委员会讨论决定。"},{"i":305,"n":"第三百零五条","txt":"侦查监督部门办理审查逮捕案件，可以讯问犯罪嫌疑人；有下列情形之一的，应当讯问犯罪嫌疑人："},{"i":306,"n":"第三百零六条","txt":"在审查逮捕中对被拘留的犯罪嫌疑人不予讯问的，应当送达听取犯罪嫌疑人意见书，由犯罪嫌疑人填写后及时收回审查并附卷。经审查发现应当讯问犯罪嫌疑人的，应当及时讯问。"},{"i":307,"n":"第三百零七条","txt":"讯问犯罪嫌疑人时，检察人员不得少于二人。"},{"i":308,"n":"第三百零八条","txt":"侦查监督部门办理审查逮捕案件，必要时，可以询问证人、被害人、鉴定人等诉讼参与人，并制作笔录附卷。"},{"i":309,"n":"第三百零九条","txt":"在审查逮捕过程中，犯罪嫌疑人已经委托辩护律师的，侦查监督部门可以听取辩护律师的意见。辩护律师提出要求的，应当听取辩护律师的意见。对辩护律师的意见应当制作笔录附卷。"},{"i":310,"n":"第三百一十条","txt":"对于公安机关立案侦查的案件，侦查监督部门审查逮捕时发现存在本规则第七十三条第一款规定情形的，可以调取公安机关讯问犯罪嫌疑人的录音、录像并审查相关的录音、录像，对于重大、疑难、复杂的案件，必要时可以审查全部录音、录像。"},{"i":311,"n":"第三百一十一条","txt":"经审查讯问犯罪嫌疑人录音、录像，发现侦查机关讯问不规范，讯问过程存在违法行为，录音、录像内容与讯问笔录不一致等情形的，应当逐一列明并向侦查机关书面提出，要求侦查机关予以纠正、补正或者书面作出合理解释。发现讯问笔录与讯问犯罪嫌疑人录音、录像内容有重大实质性差异的，或者侦查机关不能补正或者作出合理解释的，该讯问笔录不能作为批准逮捕或者决定逮捕的依据。"},{"i":312,"n":"第三百一十二条","txt":"外国人、无国籍人涉嫌危害国家安全犯罪的案件或者涉及国与国之间政治、外交关系的案件以及在适用法律上确有疑难的案件，认为需要逮捕犯罪嫌疑人的，按照刑事诉讼法第十九条、第二十条的规定，分别由基层人民检察院或者分、州、市人民检察院审查并提出意见，层报最高人民检察院审查。最高人民检察院经审查认为需要逮捕的，经征求外交部的意见后，作出批准逮捕的批复，经审查认为不需要逮捕的，作出不批准逮捕的批复。基层人民检察院或者分、州、市人民检察院根据最高人民检察院的批复，依法作出批准或者不批准逮捕的决定。层报过程中，上级人民检察院经审查认为不需要逮捕的，应当作出不批准逮捕的批复，报送的人民检察院根据批复依法作出不批准逮捕的决定。"},{"i":313,"n":"第三百一十三条","txt":"人民检察院办理审查逮捕的危害国家安全的案件，应当报上一级人民检察院备案。"},{"i":314,"n":"第三百一十四条","txt":"对于人民检察院正在侦查或者审查起诉的案件，被逮捕的犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为羁押期限届满，向人民检察院提出释放犯罪嫌疑人或者变更逮捕措施要求的，人民检察院应当在三日以内审查决定。经审查，认为法定期限届满的，应当决定释放或者依法变更逮捕措施，并通知公安机关执行；认为未满法定期限的，书面答复申请人。"},{"i":315,"n":"第三百一十五条","txt":"被害人对人民检察院以没有犯罪事实为由作出的不批准逮捕决定不服提出申诉的，由作出不批准逮捕决定的人民检察院刑事申诉检察部门审查处理。对以其他理由作出的不批准逮捕决定不服提出申诉的，由侦查监督部门办理。"},{"i":316,"n":"第三百一十六条","txt":"对公安机关提请批准逮捕的犯罪嫌疑人，已被拘留的，人民检察院应当在收到提请批准逮捕书后的七日以内作出是否批准逮捕的决定；未被拘留的，应当在收到提请批准逮捕书后的十五日以内作出是否批准逮捕的决定，重大、复杂的案件，不得超过二十日。"},{"i":317,"n":"第三百一十七条","txt":"上级公安机关指定犯罪地或者犯罪嫌疑人居住地以外的下级公安机关立案侦查的案件，需要逮捕犯罪嫌疑人的，由侦查该案件的公安机关提请同级人民检察院审查批准逮捕，人民检察院应当依法作出批准或者不批准逮捕的决定。"},{"i":318,"n":"第三百一十八条","txt":"对公安机关提请批准逮捕的犯罪嫌疑人，人民检察院经审查认为符合本规则第一百三十九条、第一百四十条、第一百四十二条规定情形的，应当作出批准逮捕的决定，连同案卷材料送达公安机关执行，并可以对收集证据、适用法律提出意见。"},{"i":319,"n":"第三百一十九条","txt":"对公安机关提请批准逮捕的犯罪嫌疑人，具有本规则第一百四十三条至第一百四十四条规定情形，人民检察院作出不批准逮捕决定的，应当说明理由，连同案卷材料送达公安机关执行。需要补充侦查的，应当同时通知公安机关。"},{"i":320,"n":"第三百二十条","txt":"对于人民检察院批准逮捕的决定，公安机关应当立即执行，并将执行回执及时送达作出批准决定的人民检察院；如果未能执行，也应当将回执送达人民检察院，并写明未能执行的原因。对于人民检察院决定不批准逮捕的，公安机关在收到不批准逮捕决定书后，应当立即释放在押的犯罪嫌疑人或者变更强制措施，并将执行回执在收到不批准逮捕决定书后的三日以内送达作出不批准逮捕决定的人民检察院。"},{"i":321,"n":"第三百二十一条","txt":"人民检察院办理审查逮捕案件，发现应当逮捕而公安机关未提请批准逮捕的犯罪嫌疑人的，应当建议公安机关提请批准逮捕。如果公安机关仍不提请批准逮捕或者不提请批准逮捕的理由不能成立的，人民检察院也可以直接作出逮捕决定，送达公安机关执行。"},{"i":322,"n":"第三百二十二条","txt":"对已作出的批准逮捕决定发现确有错误的，人民检察院应当撤销原批准逮捕决定，送达公安机关执行。"},{"i":323,"n":"第三百二十三条","txt":"对公安机关要求复议的不批准逮捕的案件，人民检察院侦查监督部门应当另行指派办案人员复议，并在收到提请复议书和案卷材料后的七日以内作出是否变更的决定，通知公安机关。"},{"i":324,"n":"第三百二十四条","txt":"对公安机关提请上一级人民检察院复核的不批准逮捕的案件，上一级人民检察院侦查监督部门应当在收到提请复核意见书和案卷材料后的十五日以内由检察长或者检察委员会作出是否变更的决定，通知下级人民检察院和公安机关执行。如果需要改变原决定，应当通知作出不批准逮捕决定的人民检察院撤销原不批准逮捕决定，另行制作批准逮捕决定书。必要时，上级人民检察院也可以直接作出批准逮捕决定，通知下级人民检察院送达公安机关执行。"},{"i":325,"n":"第三百二十五条","txt":"人民检察院作出不批准逮捕决定，并且通知公安机关补充侦查的案件，公安机关在补充侦查后又提请复议的，人民检察院应当告知公安机关重新提请批准逮捕。公安机关坚持复议的，人民检察院不予受理。"},{"i":326,"n":"第三百二十六条","txt":"对公安机关提请批准逮捕的案件，侦查监督部门应当将批准、变更、撤销逮捕措施的情况书面通知本院监所检察部门。"},{"i":327,"n":"第三百二十七条","txt":"省级以下（不含省级）人民检察院直接受理立案侦查的案件，需要逮捕犯罪嫌疑人的，应当报请上一级人民检察院审查决定。"},{"i":328,"n":"第三百二十八条","txt":"下级人民检察院报请审查逮捕的案件，由侦查部门制作报请逮捕书，报检察长或者检察委员会审批后，连同案卷材料、讯问犯罪嫌疑人录音、录像一并报上一级人民检察院审查，报请逮捕时应当说明犯罪嫌疑人的社会危险性并附相关证据材料。"},{"i":329,"n":"第三百二十九条","txt":"犯罪嫌疑人已被拘留的，下级人民检察院侦查部门应当在拘留后七日以内报上一级人民检察院审查逮捕。上一级人民检察院应当在收到报请逮捕书后七日以内作出是否逮捕的决定，特殊情况下，决定逮捕的时间可以延长一日至三日。犯罪嫌疑人未被拘留的，上一级人民检察院应当在收到报请逮捕书后十五日以内作出是否逮捕的决定，重大、复杂的案件，不得超过二十日。"},{"i":330,"n":"第三百三十条","txt":"对于重大、疑难、复杂的案件，下级人民检察院侦查部门可以提请上一级人民检察院侦查监督部门和本院侦查监督部门派员介入侦查，参加案件讨论。上一级人民检察院侦查监督部门和下级人民检察院侦查监督部门认为必要时，可以报经检察长批准，派员介入侦查，对收集证据、适用法律提出意见，监督侦查活动是否合法。"},{"i":331,"n":"第三百三十一条","txt":"上一级人民检察院经审查，对符合本规则第三百零五条规定情形的，应当讯问犯罪嫌疑人。讯问时，按照本规则第三百零七条的规定进行。"},{"i":332,"n":"第三百三十二条","txt":"对已被拘留的犯罪嫌疑人，上一级人民检察院拟不讯问的，应当向犯罪嫌疑人送达听取犯罪嫌疑人意见书。因交通不便等原因不能及时送达的，可以委托下级人民检察院侦查监督部门代为送达。下级人民检察院应当及时回收意见书，并报上一级人民检察院。经审查发现应当讯问犯罪嫌疑人的，应当及时讯问。"},{"i":333,"n":"第三百三十三条","txt":"上一级人民检察院决定逮捕的，应当将逮捕决定书连同案卷材料一并交下级人民检察院，由下级人民检察院通知同级公安机关执行。必要时，下级人民检察院可以协助执行。"},{"i":334,"n":"第三百三十四条","txt":"上一级人民检察院决定不予逮捕的，应当将不予逮捕决定书连同案卷材料一并交下级人民检察院，同时书面说明不予逮捕的理由。犯罪嫌疑人已被拘留的，下级人民检察院应当通知公安机关立即释放，并报上一级人民检察院；案件需要继续侦查，犯罪嫌疑人符合取保候审、监视居住条件的，由下级人民检察院依法决定取保候审或者监视居住。"},{"i":335,"n":"第三百三十五条","txt":"对应当逮捕而下级人民检察院未报请逮捕的犯罪嫌疑人，上一级人民检察院应当通知下级人民检察院报请逮捕犯罪嫌疑人。下级人民检察院不同意报请逮捕犯罪嫌疑人的，应当说明理由。经审查理由不成立的，上一级人民检察院可以依法作出逮捕决定。"},{"i":336,"n":"第三百三十六条","txt":"决定逮捕后，应当立即将被逮捕人送看守所羁押。除无法通知的以外，下级人民检察院侦查部门应当把逮捕的原因和羁押的处所，在二十四小时以内通知被逮捕人的家属。对于无法通知的，在无法通知的情形消除后，应当立即通知其家属。"},{"i":337,"n":"第三百三十七条","txt":"对被逮捕的犯罪嫌疑人，下级人民检察院侦查部门应当在逮捕后二十四小时以内进行讯问。"},{"i":338,"n":"第三百三十八条","txt":"对被逮捕的犯罪嫌疑人，作出逮捕决定的人民检察院发现不应当逮捕的，应当撤销逮捕决定，并通知下级人民检察院送达同级公安机关执行，同时向下级人民检察院说明撤销逮捕的理由。"},{"i":339,"n":"第三百三十九条","txt":"下级人民检察院认为上一级人民检察院作出的不予逮捕决定有错误的，应当在收到不予逮捕决定书后五日以内报请上一级人民检察院重新审查，但是必须将已被拘留的犯罪嫌疑人立即释放或者变更为其他强制措施。"},{"i":340,"n":"第三百四十条","txt":"基层人民检察院，分、州、市人民检察院对直接受理立案侦查的案件进行审查起诉时，发现需要逮捕犯罪嫌疑人的，应当报请上一级人民检察院审查决定逮捕。"},{"i":341,"n":"第三百四十一条","txt":"需要逮捕担任各级人民代表大会代表的犯罪嫌疑人的，下级人民检察院侦查部门应当按照本规则第一百四十六条的规定报请许可，在获得许可后，向上一级人民检察院报请逮捕。"},{"i":342,"n":"第三百四十二条","txt":"最高人民检察院、省级人民检察院办理直接受理立案侦查的案件，需要逮捕犯罪嫌疑人的，由侦查部门填写逮捕犯罪嫌疑人意见书，连同案卷材料、讯问犯罪嫌疑人录音、录像一并移送本院侦查监督部门审查。犯罪嫌疑人已被拘留的，侦查部门应当在拘留后七日以内将案件移送本院侦查监督部门审查。"},{"i":343,"n":"第三百四十三条","txt":"对本院侦查部门移送审查逮捕的案件，犯罪嫌疑人已被拘留的，应当在侦查监督部门收到逮捕犯罪嫌疑人意见书后的七日以内，由检察长或者检察委员会决定是否逮捕，特殊情况下，决定逮捕的时间可以延长一日至三日；犯罪嫌疑人未被拘留的，应当在侦查监督部门收到逮捕犯罪嫌疑人意见书后的十五日以内由检察长或者检察委员会决定是否逮捕，重大、复杂的案件，不得超过二十日。"},{"i":344,"n":"第三百四十四条","txt":"对本院侦查部门移送审查逮捕的犯罪嫌疑人，经检察长或者检察委员会决定逮捕的，侦查监督部门应当将逮捕决定书连同案卷材料、讯问犯罪嫌疑人录音、录像送交侦查部门，由侦查部门通知公安机关执行，必要时人民检察院可以协助执行，并可以对收集证据、适用法律提出意见。"},{"i":345,"n":"第三百四十五条","txt":"对本院侦查部门移送审查逮捕的犯罪嫌疑人，经检察长或者检察委员会决定不予逮捕的，侦查监督部门应当将不予逮捕的决定连同案卷材料、讯问犯罪嫌疑人录音、录像移交侦查部门。犯罪嫌疑人已被拘留的，侦查部门应当通知公安机关立即释放。"},{"i":346,"n":"第三百四十六条","txt":"对应当逮捕而本院侦查部门未移送审查逮捕的犯罪嫌疑人，侦查监督部门应当向侦查部门提出移送审查逮捕犯罪嫌疑人的建议。如果建议不被采纳，侦查监督部门可以报请检察长提交检察委员会决定。"},{"i":347,"n":"第三百四十七条","txt":"最高人民检察院、省级人民检察院办理直接受理立案侦查的案件，逮捕犯罪嫌疑人后，应当立即将被逮捕人送看守所羁押。除无法通知的以外，侦查部门应当把逮捕的原因和羁押的处所，在二十四小时以内通知被逮捕人的家属。对于无法通知的，在无法通知的情形消除后，应当立即通知其家属。"},{"i":348,"n":"第三百四十八条","txt":"最高人民检察院、省级人民检察院办理直接受理立案侦查的案件，对被逮捕的犯罪嫌疑人，侦查部门应当在逮捕后二十四小时以内进行讯问。"},{"i":349,"n":"第三百四十九条","txt":"最高人民检察院、省级人民检察院办理直接受理立案侦查的案件，已经作出不予逮捕的决定，又发现需要逮捕犯罪嫌疑人的，应当重新办理逮捕手续。"},{"i":350,"n":"第三百五十条","txt":"人民检察院办理直接受理立案侦查的案件，侦查部门应当将决定、变更、撤销逮捕措施的情况书面通知本院监所检察部门。"},{"i":351,"n":"第三百五十一条","txt":"法定最高刑为无期徒刑、死刑的犯罪，已过二十年追诉期限的，不再追诉。如果认为必须追诉的，须报请最高人民检察院核准。"},{"i":352,"n":"第三百五十二条","txt":"须报请最高人民检察院核准追诉的案件，侦查机关在核准之前可以依法对犯罪嫌疑人采取强制措施。"},{"i":353,"n":"第三百五十三条","txt":"报请核准追诉的案件应当同时符合下列条件："},{"i":354,"n":"第三百五十四条","txt":"侦查机关报请核准追诉的案件，由同级人民检察院受理并层报最高人民检察院审查决定。"},{"i":355,"n":"第三百五十五条","txt":"地方各级人民检察院对侦查机关报请核准追诉的案件，应当及时进行审查并开展必要的调查，经检察委员会审议提出是否同意核准追诉的意见，在受理案件后十日以内制作报请核准追诉案件报告书，连同案件材料一并层报最高人民检察院。"},{"i":356,"n":"第三百五十六条","txt":"最高人民检察院收到省级人民检察院报送的报请核准追诉案件报告书及案件材料后，应当及时审查，必要时派人到案发地了解案件有关情况。经检察长批准或者检察委员会审议，应当在受理案件后一个月以内作出是否核准追诉的决定，特殊情况下可以延长十五日，并制作核准追诉决定书或者不予核准追诉决定书，逐级下达最初受理案件的人民检察院，送达报请核准追诉的侦查机关。"},{"i":357,"n":"第三百五十七条","txt":"对已经批准逮捕的案件，侦查羁押期限届满不能做出是否核准追诉决定的，应当对犯罪嫌疑人变更强制措施或者延长侦查羁押期限。"},{"i":358,"n":"第三百五十八条","txt":"最高人民检察院决定核准追诉的案件，最初受理案件的人民检察院应当监督侦查机关的侦查工作。"},{"i":359,"n":"第三百五十九条","txt":"人民检察院直接受理立案侦查的案件报请最高人民检察院核准追诉的，参照本节规定办理。"},{"i":360,"n":"第三百六十条","txt":"人民检察院受理移送审查起诉案件，应当指定检察员或者经检察长批准代行检察员职务的助理检察员办理，也可以由检察长办理。"},{"i":361,"n":"第三百六十一条","txt":"对于重大、疑难、复杂的案件，人民检察院认为确有必要时，可以派员适时介入侦查活动，对收集证据、适用法律提出意见，监督侦查活动是否合法。"},{"i":362,"n":"第三百六十二条","txt":"各级人民检察院提起公诉，应当与人民法院审判管辖相适应。公诉部门收到移送审查起诉的案件后，经审查认为不属于本院管辖的，应当在五日以内经由案件管理部门移送有管辖权的人民检察院。"},{"i":363,"n":"第三百六十三条","txt":"人民检察院审查移送起诉的案件，应当查明："},{"i":364,"n":"第三百六十四条","txt":"人民检察院审查案件，应当讯问犯罪嫌疑人，听取辩护人、被害人及其诉讼代理人的意见，并制作笔录附卷。"},{"i":365,"n":"第三百六十五条","txt":"直接听取辩护人、被害人及其诉讼代理人的意见有困难的，可以通知辩护人、被害人及其诉讼代理人提出书面意见，在指定期限内未提出意见的，应当记录在案。"},{"i":366,"n":"第三百六十六条","txt":"人民检察院认为需要对案件中某些专门性问题进行鉴定而侦查机关没有鉴定的，应当要求侦查机关进行鉴定；必要时也可以由人民检察院进行鉴定或者由人民检察院送交有鉴定资格的人进行。"},{"i":367,"n":"第三百六十七条","txt":"在审查起诉中，发现犯罪嫌疑人可能患有精神病的，人民检察院应当依照本规则的有关规定对犯罪嫌疑人进行鉴定。"},{"i":368,"n":"第三百六十八条","txt":"人民检察院对鉴定意见有疑问的，可以询问鉴定人并制作笔录附卷，也可以指派检察技术人员或者聘请有鉴定资格的人对案件中的某些专门性问题进行补充鉴定或者重新鉴定。"},{"i":369,"n":"第三百六十九条","txt":"人民检察院审查案件的时候，对公安机关的勘验、检查，认为需要复验、复查的，应当要求公安机关复验、复查，人民检察院可以派员参加；也可以自行复验、复查，商请公安机关派员参加，必要时也可以聘请专门技术人员参加。"},{"i":370,"n":"第三百七十条","txt":"人民检察院对物证、书证、视听资料、电子数据及勘验、检查、辨认、侦查实验等笔录存在疑问的，可以要求侦查人员提供获取、制作的有关情况。必要时也可以询问提供物证、书证、视听资料、电子数据及勘验、检查、辨认、侦查实验等笔录的人员和见证人并制作笔录附卷，对物证、书证、视听资料、电子数据进行技术鉴定。"},{"i":371,"n":"第三百七十一条","txt":"人民检察院对证人证言笔录存在疑问或者认为对证人的询问不具体或者有遗漏的，可以对证人进行询问并制作笔录附卷。"},{"i":372,"n":"第三百七十二条","txt":"讯问犯罪嫌疑人或者询问被害人、证人、鉴定人时，应当分别告知其在审查起诉阶段所享有的诉讼权利。"},{"i":373,"n":"第三百七十三条","txt":"讯问犯罪嫌疑人，询问被害人、证人、鉴定人，听取辩护人、被害人及其诉讼代理人的意见，应当由二名以上办案人员进行。"},{"i":374,"n":"第三百七十四条","txt":"对于随案移送的讯问犯罪嫌疑人录音、录像或者人民检察院调取的录音、录像，人民检察院应当审查相关的录音、录像；对于重大、疑难、复杂的案件，必要时可以审查全部录音、录像。"},{"i":375,"n":"第三百七十五条","txt":"公诉部门经审查认为需要逮捕犯罪嫌疑人的，应当按照本规则第十章的规定移送侦查监督部门办理。"},{"i":376,"n":"第三百七十六条","txt":"办案人员对案件进行审查后，应当制作案件审查报告，提出起诉或者不起诉以及是否需要提起附带民事诉讼的意见，经公诉部门负责人审核，报请检察长或者检察委员会决定。"},{"i":377,"n":"第三百七十七条","txt":"人民检察院对侦查机关移送的案件进行审查后，在法院作出生效判决之前，认为需要补充提供法庭审判所必需的证据的，可以书面要求侦查机关提供。"},{"i":378,"n":"第三百七十八条","txt":"人民检察院在审查起诉中，发现可能存在刑事诉讼法第五十四条规定的以非法方法收集证据情形的，可以要求侦查机关对证据收集的合法性作出书面说明或者提供相关证明材料。"},{"i":379,"n":"第三百七十九条","txt":"人民检察院公诉部门在审查中发现侦查人员以非法方法收集犯罪嫌疑人供述、被害人陈述、证人证言等证据材料的，应当依法排除非法证据并提出纠正意见，同时可以要求侦查机关另行指派侦查人员重新调查取证，必要时人民检察院也可以自行调查取证。"},{"i":380,"n":"第三百八十条","txt":"人民检察院认为犯罪事实不清、证据不足或者遗漏罪行、遗漏同案犯罪嫌疑人等情形需要补充侦查的，应当提出具体的书面意见，连同案卷材料一并退回公安机关补充侦查；人民检察院也可以自行侦查，必要时可以要求公安机关提供协助。"},{"i":381,"n":"第三百八十一条","txt":"人民检察院公诉部门对本院侦查部门移送审查起诉的案件审查后，认为犯罪事实不清、证据不足或者遗漏罪行、遗漏同案犯罪嫌疑人等情形需要补充侦查的，应当向侦查部门提出补充侦查的书面意见，连同案卷材料一并退回侦查部门补充侦查；必要时也可以自行侦查，可以要求侦查部门予以协助。"},{"i":382,"n":"第三百八十二条","txt":"对于退回公安机关补充侦查的案件，应当在一个月以内补充侦查完毕。"},{"i":383,"n":"第三百八十三条","txt":"人民检察院在审查起诉中决定自行侦查的，应当在审查起诉期限内侦查完毕。"},{"i":384,"n":"第三百八十四条","txt":"人民检察院对已经退回侦查机关二次补充侦查的案件，在审查起诉中又发现新的犯罪事实的，应当移送侦查机关立案侦查；对已经查清的犯罪事实，应当依法提起公诉。"},{"i":385,"n":"第三百八十五条","txt":"对于在审查起诉期间改变管辖的案件，改变后的人民检察院对于符合刑事诉讼法第一百七十一条第二款规定的案件，可以通过原受理案件的人民检察院退回原侦查的公安机关补充侦查，也可以自行侦查。改变管辖前后退回补充侦查的次数总共不得超过二次。"},{"i":386,"n":"第三百八十六条","txt":"人民检察院对于移送审查起诉的案件，应当在一个月以内作出决定；重大、复杂的案件，一个月以内不能作出决定的，经检察长批准，可以延长十五日。"},{"i":387,"n":"第三百八十七条","txt":"追缴的财物中，属于被害人的合法财产，不需要在法庭出示的，应当及时返还被害人，并由被害人在发还款物清单上签名或者盖章，注明返还的理由，并将清单、照片附卷。"},{"i":388,"n":"第三百八十八条","txt":"追缴的财物中，属于违禁品或者不宜长期保存的物品，应当依照国家有关规定处理，并将清单、照片、处理结果附卷。"},{"i":389,"n":"第三百八十九条","txt":"公诉部门办理案件，可以适用本规则规定的侦查措施和程序。"},{"i":390,"n":"第三百九十条","txt":"人民检察院对案件进行审查后，认为犯罪嫌疑人的犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，应当作出起诉决定。"},{"i":391,"n":"第三百九十一条","txt":"人民检察院在办理公安机关移送起诉的案件中，发现遗漏罪行或者依法应当移送审查起诉同案犯罪嫌疑人的，应当要求公安机关补充移送审查起诉；对于犯罪事实清楚，证据确实、充分的，人民检察院也可以直接提起公诉。"},{"i":392,"n":"第三百九十二条","txt":"人民检察院立案侦查时认为属于直接立案侦查的案件，在审查起诉阶段发现不属于人民检察院管辖，案件事实清楚、证据确实充分，符合起诉条件的，可以直接起诉；事实不清、证据不足的，应当及时移送有管辖权的机关办理。"},{"i":393,"n":"第三百九十三条","txt":"人民检察院决定起诉的，应当制作起诉书。"},{"i":394,"n":"第三百九十四条","txt":"人民检察院提起公诉的案件，应当向人民法院移送起诉书、案卷材料和证据。"},{"i":395,"n":"第三百九十五条","txt":"人民检察院对于犯罪嫌疑人、被告人或者证人等翻供、翻证的材料以及对于犯罪嫌疑人、被告人有利的其他证据材料，应当移送人民法院。"},{"i":396,"n":"第三百九十六条","txt":"人民法院向人民检察院提出书面意见要求补充移送材料，人民检察院认为有必要移送的，应当自收到通知之日起三日以内补送。"},{"i":397,"n":"第三百九十七条","txt":"对提起公诉后，在人民法院宣告判决前补充收集的证据材料，人民检察院应当及时移送人民法院。"},{"i":398,"n":"第三百九十八条","txt":"在审查起诉期间，人民检察院可以根据辩护人的申请，向公安机关调取在侦查期间收集的证明犯罪嫌疑人、被告人无罪或者罪轻的证据材料。"},{"i":399,"n":"第三百九十九条","txt":"人民检察院对提起公诉的案件，可以向人民法院提出量刑建议。除有减轻处罚或者免除处罚情节外，量刑建议应当在法定量刑幅度内提出。建议判处有期徒刑、管制、拘役的，可以具有一定的幅度，也可以提出具体确定的建议。"},{"i":400,"n":"第四百条","txt":"对提起公诉的案件提出量刑建议的，可以制作量刑建议书，与起诉书一并移送人民法院。"},{"i":401,"n":"第四百零一条","txt":"人民检察院对于公安机关移送审查起诉的案件，发现犯罪嫌疑人没有犯罪事实，或者符合刑事诉讼法第十五条规定的情形之一的，经检察长或者检察委员会决定，应当作出不起诉决定。"},{"i":402,"n":"第四百零二条","txt":"公诉部门对于本院侦查部门移送审查起诉的案件，发现具有本规则第四百零一条第一款规定情形的，应当退回本院侦查部门，建议作出撤销案件的处理。"},{"i":403,"n":"第四百零三条","txt":"人民检察院对于二次退回补充侦查的案件，仍然认为证据不足，不符合起诉条件的，经检察长或者检察委员会决定，应当作出不起诉决定。"},{"i":404,"n":"第四百零四条","txt":"具有下列情形之一，不能确定犯罪嫌疑人构成犯罪和需要追究刑事责任的，属于证据不足，不符合起诉条件："},{"i":405,"n":"第四百零五条","txt":"人民检察院根据刑事诉讼法第一百七十一条第四款规定决定不起诉的，在发现新的证据，符合起诉条件时，可以提起公诉。"},{"i":406,"n":"第四百零六条","txt":"人民检察院对于犯罪情节轻微，依照刑法规定不需要判处刑罚或者免除刑罚的，经检察长或者检察委员会决定，可以作出不起诉决定。"},{"i":407,"n":"第四百零七条","txt":"省级以下人民检察院办理直接受理立案侦查的案件，拟作不起诉决定的，应当报请上一级人民检察院批准。"},{"i":408,"n":"第四百零八条","txt":"人民检察院决定不起诉的，应当制作不起诉决定书。"},{"i":409,"n":"第四百零九条","txt":"人民检察院决定不起诉的案件，可以根据案件的不同情况，对被不起诉人予以训诫或者责令具结悔过、赔礼道歉、赔偿损失。"},{"i":410,"n":"第四百一十条","txt":"人民检察院决定不起诉的案件，对犯罪嫌疑人违法所得及其他涉案财产的处理，参照本规则第二百九十六条的规定办理。"},{"i":411,"n":"第四百一十一条","txt":"人民检察院决定不起诉的案件，需要对侦查中查封、扣押、冻结的财物解除查封、扣押、冻结的，应当书面通知作出查封、扣押、冻结决定的机关或者执行查封、扣押、冻结决定的机关解除查封、扣押、冻结。"},{"i":412,"n":"第四百一十二条","txt":"不起诉的决定，由人民检察院公开宣布。公开宣布不起诉决定的活动应当记录在案。"},{"i":413,"n":"第四百一十三条","txt":"不起诉决定书应当送达被害人或者其近亲属及其诉讼代理人、被不起诉人及其辩护人以及被不起诉人的所在单位。送达时，应当告知被害人或者其近亲属及其诉讼代理人，如果对不起诉决定不服，可以自收到不起诉决定书后七日以内向上一级人民检察院申诉，也可以不经申诉，直接向人民法院起诉；告知被不起诉人，如果对不起诉决定不服，可以自收到不起诉决定书后七日以内向人民检察院申诉。"},{"i":414,"n":"第四百一十四条","txt":"对于公安机关移送起诉的案件，人民检察院决定不起诉的，应当将不起诉决定书送达公安机关。"},{"i":415,"n":"第四百一十五条","txt":"公安机关认为不起诉决定有错误，要求复议的，人民检察院公诉部门应当另行指定检察人员进行审查并提出审查意见，经公诉部门负责人审核，报请检察长或者检察委员会决定。"},{"i":416,"n":"第四百一十六条","txt":"上一级人民检察院收到公安机关对不起诉决定提请复核的意见书后，应当交由公诉部门办理。公诉部门指定检察人员进行审查并提出审查意见，经公诉部门负责人审核，报请检察长或者检察委员会决定。"},{"i":417,"n":"第四百一十七条","txt":"被害人不服不起诉决定的，在收到不起诉决定书后七日以内申诉的，由作出不起诉决定的人民检察院的上一级人民检察院刑事申诉检察部门立案复查。"},{"i":418,"n":"第四百一十八条","txt":"被害人不服不起诉决定，在收到不起诉决定书七日后提出申诉的，由作出不起诉决定的人民检察院刑事申诉检察部门审查后决定是否立案复查。"},{"i":419,"n":"第四百一十九条","txt":"刑事申诉检察部门复查后应当提出复查意见，报请检察长作出复查决定。"},{"i":420,"n":"第四百二十条","txt":"人民检察院收到人民法院受理被害人对被不起诉人起诉的通知后，人民检察院应当终止复查，将作出不起诉决定所依据的有关案件材料移送人民法院。"},{"i":421,"n":"第四百二十一条","txt":"被不起诉人对不起诉决定不服，在收到不起诉决定书后七日以内提出申诉的，应当由作出决定的人民检察院刑事申诉检察部门立案复查。被不起诉人在收到不起诉决定书七日后提出申诉的，由刑事申诉检察部门审查后决定是否立案复查。"},{"i":422,"n":"第四百二十二条","txt":"人民检察院复查不服不起诉决定的申诉，应当在立案三个月以内作出复查决定，案情复杂的，不得超过六个月。"},{"i":423,"n":"第四百二十三条","txt":"被害人、被不起诉人对不起诉决定不服，提出申诉的，应当递交申诉书，写明申诉理由。被害人、被不起诉人没有书写能力的，也可以口头提出申诉，人民检察院应当根据其口头提出的申诉制作笔录。"},{"i":424,"n":"第四百二十四条","txt":"人民检察院发现不起诉决定确有错误，符合起诉条件的，应当撤销不起诉决定，提起公诉。"},{"i":425,"n":"第四百二十五条","txt":"最高人民检察院对地方各级人民检察院的起诉、不起诉决定，上级人民检察院对下级人民检察院的起诉、不起诉决定，发现确有错误的，应当予以撤销或者指令下级人民检察院纠正。"},{"i":426,"n":"第四百二十六条","txt":"提起公诉的案件，人民检察院应当派员以国家公诉人的身份出席第一审法庭，支持公诉。"},{"i":427,"n":"第四百二十七条","txt":"对于提起公诉后改变管辖的案件，原提起公诉的人民检察院参照本规则第三百六十二条的规定将案件移送与审判管辖相对应的人民检察院。"},{"i":428,"n":"第四百二十八条","txt":"公诉人在人民法院决定开庭审判后，应当做好如下准备工作："},{"i":429,"n":"第四百二十九条","txt":"人民检察院在开庭审理前收到人民法院或者被告人及其辩护人、被害人、证人等送交的反映证据系非法取得的书面材料的，应当进行审查。对于审查逮捕、审查起诉期间已经提出并经查证不存在非法取证行为的，应当通知人民法院、有关当事人和辩护人，并按照查证的情况做好庭审准备。对于新的材料或者线索，可以要求侦查机关对证据收集的合法性进行说明或者提供相关证明材料，必要时可以自行调查核实。"},{"i":430,"n":"第四百三十条","txt":"人民法院通知人民检察院派员参加庭前会议的，由出席法庭的公诉人参加，必要时配备书记员担任记录。"},{"i":431,"n":"第四百三十一条","txt":"在庭前会议中，公诉人可以对案件管辖、回避、出庭证人、鉴定人、有专门知识的人的名单、辩护人提供的无罪证据、非法证据排除、不公开审理、延期审理、适用简易程序、庭审方案等与审判相关的问题提出和交换意见，了解辩护人收集的证据等情况。"},{"i":432,"n":"第四百三十二条","txt":"当事人、辩护人、诉讼代理人在庭前会议中提出证据系非法取得，人民法院认为可能存在以非法方法收集证据情形的，人民检察院可以对证据收集的合法性进行证明。需要调查核实的，在开庭审理前进行。"},{"i":433,"n":"第四百三十三条","txt":"人民检察院提起公诉向人民法院移送全部案卷材料、证据后，在法庭审理过程中，公诉人需要出示、宣读、播放有关证据的，可以申请法庭出示、宣读、播放。"},{"i":434,"n":"第四百三十四条","txt":"公诉人在法庭上应当依法进行下列活动："},{"i":435,"n":"第四百三十五条","txt":"在法庭审理中，公诉人应当客观、全面、公正地向法庭出示与定罪、量刑有关的证明被告人有罪、罪重或者罪轻的证据。"},{"i":436,"n":"第四百三十六条","txt":"公诉人讯问被告人，询问证人、被害人、鉴定人，出示物证，宣读书证、未出庭证人的证言笔录等应当围绕下列事实进行："},{"i":437,"n":"第四百三十七条","txt":"在法庭审理中，下列事实不必提出证据进行证明："},{"i":438,"n":"第四百三十八条","txt":"讯问被告人、询问证人应当避免可能影响陈述或者证言客观真实的诱导性讯问、询问以及其他不当讯问、询问。"},{"i":439,"n":"第四百三十九条","txt":"被告人在庭审中的陈述与在侦查、审查起诉中的供述一致或者不一致的内容不影响定罪量刑的，可以不宣读被告人供述笔录。"},{"i":440,"n":"第四百四十条","txt":"公诉人对证人证言有异议，且该证人证言对案件定罪量刑有重大影响的，可以申请人民法院通知证人出庭作证。"},{"i":441,"n":"第四百四十一条","txt":"证人应当由人民法院通知并负责安排出庭作证。"},{"i":442,"n":"第四百四十二条","txt":"证人在法庭上提供证言，公诉人应当按照审判长确定的顺序向证人发问。公诉人可以要求证人就其所了解的与案件有关的事实进行陈述，也可以直接发问。"},{"i":443,"n":"第四百四十三条","txt":"必要时公诉人可以建议法庭采取不暴露证人、鉴定人、被害人外貌、真实声音等出庭作证措施，或者建议法庭根据刑事诉讼法第一百五十二条的规定在庭外对证据进行核实。"},{"i":444,"n":"第四百四十四条","txt":"对于鉴定意见、勘验、检查、辨认、侦查实验等笔录和其他作为证据的文书以及经法院通知未到庭的被害人的陈述笔录，公诉人应当当庭宣读。"},{"i":445,"n":"第四百四十五条","txt":"公诉人向法庭出示物证，应当对该物证所要证明的内容、获取情况作概括的说明，并向当事人、证人等问明物证的主要特征，让其辨认。"},{"i":446,"n":"第四百四十六条","txt":"在法庭审理过程中，被告人及其辩护人提出被告人庭前供述系非法取得，审判人员认为需要进行法庭调查的，公诉人可以根据讯问笔录、羁押记录、出入看守所的健康检查记录、看守管教人员的谈话记录以及侦查机关对讯问过程合法性的说明等，对庭前讯问被告人的合法性进行证明，可以要求法庭播放讯问录音、录像，必要时可以申请法庭通知侦查人员或者其他人员出庭说明情况。"},{"i":447,"n":"第四百四十七条","txt":"公诉人对证据收集的合法性进行证明后，法庭仍有疑问的，可以建议法庭休庭，由人民法院对相关证据进行调查核实。人民法院调查核实证据，通知人民检察院派员到场的，人民检察院可以派员到场。"},{"i":448,"n":"第四百四十八条","txt":"在法庭审理过程中，对证据合法性以外的其他程序事实存在争议的，公诉人应当出示、宣读有关诉讼文书、侦查或者审查起诉活动笔录。"},{"i":449,"n":"第四百四十九条","txt":"对于搜查、查封、扣押、冻结、勘验、检查、辨认、侦查实验等侦查活动中形成的笔录存在争议，需要负责侦查的人员以及搜查、查封、扣押、冻结、勘验、检查、辨认、侦查实验等活动的见证人出庭陈述有关情况的，公诉人可以建议合议庭通知其出庭。"},{"i":450,"n":"第四百五十条","txt":"在法庭审理过程中，合议庭对证据有疑问或者人民法院根据辩护人、被告人的申请，向人民检察院调取在侦查、审查起诉中收集的有关被告人无罪或者罪轻的证据材料的，人民检察院应当自收到人民法院要求调取证据材料决定书后三日以内移交。没有上述材料的，应当向人民法院说明情况。"},{"i":451,"n":"第四百五十一条","txt":"在法庭审理过程中，合议庭对证据有疑问并在休庭后进行勘验、检查、查封、扣押、鉴定和查询、冻结的，人民检察院应当依法进行监督，发现上述活动有违法情况的，应当提出纠正意见。"},{"i":452,"n":"第四百五十二条","txt":"人民法院根据申请收集、调取的证据或者合议庭休庭后自行调查取得的证据，应当经过庭审出示、质证才能决定是否作为判决的依据。未经庭审出示、质证直接采纳为判决依据的，人民检察院应当提出纠正意见；作出的判决确有错误的，应当依法提出抗诉。"},{"i":453,"n":"第四百五十三条","txt":"在法庭审理过程中，经审判长许可，公诉人可以逐一对正在调查的证据和案件情况发表意见，并同被告人、辩护人进行辩论。证据调查结束时，公诉人应当发表总结性意见。"},{"i":454,"n":"第四百五十四条","txt":"人民检察院向人民法院提出量刑建议的，公诉人应当在发表公诉意见时提出。"},{"i":455,"n":"第四百五十五条","txt":"法庭审判过程中遇有下列情形之一的，公诉人可以建议法庭延期审理："},{"i":456,"n":"第四百五十六条","txt":"法庭宣布延期审理后，人民检察院应当在补充侦查的期限内提请人民法院恢复法庭审理或者撤回起诉。"},{"i":457,"n":"第四百五十七条","txt":"在审判过程中，对于需要补充提供法庭审判所必需的证据或者补充侦查的，人民检察院应当自行收集证据和进行侦查，必要时可以要求侦查机关提供协助；也可以书面要求侦查机关补充提供证据。"},{"i":458,"n":"第四百五十八条","txt":"在人民法院宣告判决前，人民检察院发现被告人的真实身份或者犯罪事实与起诉书中叙述的身份或者指控犯罪事实不符的，或者事实、证据没有变化，但罪名、适用法律与起诉书不一致的，可以变更起诉；发现遗漏的同案犯罪嫌疑人或者罪行可以一并起诉和审理的，可以追加、补充起诉。"},{"i":459,"n":"第四百五十九条","txt":"在人民法院宣告判决前，人民检察院发现具有下列情形之一的，可以撤回起诉："},{"i":460,"n":"第四百六十条","txt":"在法庭审理过程中，人民法院建议人民检察院补充侦查、补充起诉、追加起诉或者变更起诉的，人民检察院应当审查有关理由，并作出是否补充侦查、补充起诉、追加起诉或者变更起诉的决定。人民检察院不同意的，可以要求人民法院就起诉指控的犯罪事实依法作出裁判。"},{"i":461,"n":"第四百六十一条","txt":"变更、追加、补充或者撤回起诉应当报经检察长或者检察委员会决定，并以书面方式在人民法院宣告判决前向人民法院提出。"},{"i":462,"n":"第四百六十二条","txt":"出庭的书记员应当制作出庭笔录，详细记载庭审的时间、地点、参加人员、公诉人出庭执行任务情况和法庭调查、法庭辩论的主要内容以及法庭判决结果，由公诉人和书记员签名。"},{"i":463,"n":"第四百六十三条","txt":"人民检察院应当当庭向人民法院移交取回的案卷材料和证据。在审判长宣布休庭后，公诉人应当与审判人员办理交接手续。无法当庭移交的，应当在休庭后三日以内移交。"},{"i":464,"n":"第四百六十四条","txt":"人民检察院对查封、扣押、冻结的被告人财物及其孳息，应当根据不同情况作以下处理："},{"i":465,"n":"第四百六十五条","txt":"人民检察院对于基层人民法院管辖的案件，符合下列条件的，可以建议人民法院适用简易程序审理："},{"i":466,"n":"第四百六十六条","txt":"具有下列情形之一的，人民检察院不应当建议人民法院适用简易程序："},{"i":467,"n":"第四百六十七条","txt":"基层人民检察院审查案件，认为案件事实清楚、证据充分的，应当在讯问犯罪嫌疑人时，了解其是否承认自己所犯罪行，对指控的犯罪事实有无异议，告知其适用简易程序的法律规定，确认其是否同意适用简易程序。"},{"i":468,"n":"第四百六十八条","txt":"适用简易程序审理的公诉案件，人民检察院应当派员出席法庭。"},{"i":469,"n":"第四百六十九条","txt":"公诉人出席简易程序法庭时，应当主要围绕量刑以及其他有争议的问题进行法庭调查和法庭辩论。在确认被告人庭前收到起诉书并对起诉书指控的犯罪事实没有异议后，可以简化宣读起诉书，根据案件情况决定是否讯问被告人，是否询问证人、鉴定人，是否需要出示证据。"},{"i":470,"n":"第四百七十条","txt":"适用简易程序审理的公诉案件，公诉人发现不宜适用简易程序审理的，应当建议法庭按照第一审普通程序重新审理。"},{"i":471,"n":"第四百七十一条","txt":"转为普通程序审理的案件，公诉人需要为出席法庭进行准备的，可以建议人民法院延期审理。"},{"i":472,"n":"第四百七十二条","txt":"对提出抗诉的案件或者公诉案件中人民法院决定开庭审理的上诉案件，同级人民检察院应当派员出席第二审法庭。"},{"i":473,"n":"第四百七十三条","txt":"检察人员出席第二审法庭的任务是："},{"i":474,"n":"第四百七十四条","txt":"对抗诉和上诉案件，与第二审人民法院同级的人民检察院可以调取下级人民检察院与案件有关的材料。"},{"i":475,"n":"第四百七十五条","txt":"检察人员应当客观全面地审查原审案卷材料，不受上诉或者抗诉范围的限制，审查原审判决认定案件事实、适用法律是否正确，证据是否确实、充分，量刑是否适当，审判活动是否合法，并应当审查下级人民检察院的抗诉书或者上诉人的上诉书，了解抗诉或者上诉的理由是否正确、充分，重点审查有争议的案件事实、证据和法律适用问题，有针对性地做好庭审准备工作。"},{"i":476,"n":"第四百七十六条","txt":"检察人员在审查第一审案卷材料时，应当复核主要证据，可以讯问原审被告人，必要时可以补充收集证据、重新鉴定或者补充鉴定。需要原侦查机关补充收集证据的，可以要求原侦查机关补充收集。被告人、辩护人提出被告人自首、立功等可能影响定罪量刑的材料和线索的，人民检察院可以依照管辖规定交侦查机关调查核实，也可以自行调查核实。发现遗漏罪行或者同案犯罪嫌疑人的，应当建议侦查机关侦查。"},{"i":477,"n":"第四百七十七条","txt":"人民检察院办理死刑上诉、抗诉案件，应当进行下列工作："},{"i":478,"n":"第四百七十八条","txt":"检察人员出席第二审法庭前，应当制作讯问被告人、询问被害人、证人、鉴定人和出示、宣读、播放证据计划，拟写答辩提纲，并制作出庭意见。"},{"i":479,"n":"第四百七十九条","txt":"在法庭审理中，检察人员应当针对原审判决或者裁定认定事实或适用法律、量刑等方面的问题，围绕抗诉或者上诉理由以及辩护人的辩护意见，讯问被告人，询问被害人、证人、鉴定人，出示和宣读证据，并提出意见和进行辩论。"},{"i":480,"n":"第四百八十条","txt":"需要出示、宣读、播放第一审期间已移交人民法院的证据的，出庭的检察人员可以申请法庭出示、宣读、播放。"},{"i":481,"n":"第四百八十一条","txt":"人民法院开庭审理再审案件，同级人民检察院应当派员出席法庭。"},{"i":482,"n":"第四百八十二条","txt":"人民检察院对于人民法院按照审判监督程序重新审判的案件，应当对原判决、裁定认定的事实、证据、适用法律进行全面审查，重点审查有争议的案件事实、证据和法律适用问题。"},{"i":483,"n":"第四百八十三条","txt":"人民检察院派员出席再审法庭，如果再审案件按照第一审程序审理，参照本章第一节有关规定执行；如果再审案件按照第二审程序审理，参照本章第三节有关规定执行。"},{"i":484,"n":"第四百八十四条","txt":"人民检察院应当指定熟悉未成年人身心特点的检察人员办理未成年人刑事案件。"},{"i":485,"n":"第四百八十五条","txt":"人民检察院受理案件后，应当向未成年犯罪嫌疑人及其法定代理人了解其委托辩护人的情况，并告知其有权委托辩护人。"},{"i":486,"n":"第四百八十六条","txt":"人民检察院根据情况可以对未成年犯罪嫌疑人的成长经历、犯罪原因、监护教育等情况进行调查，并制作社会调查报告，作为办案和教育的参考。"},{"i":487,"n":"第四百八十七条","txt":"人民检察院办理未成年犯罪嫌疑人审查逮捕案件，应当根据未成年犯罪嫌疑人涉嫌犯罪的事实、主观恶性、有无监护与社会帮教条件等，综合衡量其社会危险性，严格限制适用逮捕措施。"},{"i":488,"n":"第四百八十八条","txt":"对于罪行较轻，具备有效监护条件或者社会帮教措施，没有社会危险性或者社会危险性较小，不逮捕不致妨害诉讼正常进行的未成年犯罪嫌疑人，应当不批准逮捕。"},{"i":489,"n":"第四百八十九条","txt":"审查逮捕未成年犯罪嫌疑人，应当重点查清其是否已满十四、十六、十八周岁。"},{"i":490,"n":"第四百九十条","txt":"在审查逮捕、审查起诉中，人民检察院应当讯问未成年犯罪嫌疑人，听取辩护人的意见，并制作笔录附卷。"},{"i":491,"n":"第四百九十一条","txt":"讯问未成年犯罪嫌疑人一般不得使用械具。对于确有人身危险性，必须使用械具的，在现实危险消除后，应当立即停止使用。"},{"i":492,"n":"第四百九十二条","txt":"对于符合刑事诉讼法第二百七十一条第一款规定条件的未成年人刑事案件，人民检察院可以作出附条件不起诉的决定。"},{"i":493,"n":"第四百九十三条","txt":"人民检察院作出附条件不起诉的决定后，应当制作附条件不起诉决定书，并在三日以内送达公安机关、被害人或者其近亲属及其诉讼代理人、未成年犯罪嫌疑人及其法定代理人、辩护人。"},{"i":494,"n":"第四百九十四条","txt":"对附条件不起诉的决定，公安机关要求复议、提请复核或者被害人申诉的，具体程序参照本规则第四百一十五条至第四百二十条的规定办理。"},{"i":495,"n":"第四百九十五条","txt":"人民检察院作出附条件不起诉决定的，应当确定考验期。考验期为六个月以上一年以下，从人民检察院作出附条件不起诉的决定之日起计算。"},{"i":496,"n":"第四百九十六条","txt":"在附条件不起诉的考验期内，由人民检察院对被附条件不起诉的未成年犯罪嫌疑人进行监督考察。未成年犯罪嫌疑人的监护人，应当对未成年犯罪嫌疑人加强管教，配合人民检察院做好监督考察工作。"},{"i":497,"n":"第四百九十七条","txt":"被附条件不起诉的未成年犯罪嫌疑人，应当遵守下列规定："},{"i":498,"n":"第四百九十八条","txt":"人民检察院可以要求被附条件不起诉的未成年犯罪嫌疑人接受下列矫治和教育："},{"i":499,"n":"第四百九十九条","txt":"考验期届满，办案人员应当制作附条件不起诉考察意见书，提出起诉或者不起诉的意见，经部门负责人审核，报请检察长决定。"},{"i":500,"n":"第五百条","txt":"被附条件不起诉的未成年犯罪嫌疑人，在考验期内有下列情形之一的，人民检察院应当撤销附条件不起诉的决定，提起公诉："},{"i":501,"n":"第五百零一条","txt":"被附条件不起诉的未成年犯罪嫌疑人，在考验期内没有本规则第五百条规定的情形，考验期满的，人民检察院应当作出不起诉的决定。"},{"i":502,"n":"第五百零二条","txt":"人民检察院办理未成年人刑事案件过程中，应当对涉案未成年人的资料予以保密，不得公开或者传播涉案未成年人的姓名、住所、照片、图像及可能推断出该未成年人的其他资料。"},{"i":503,"n":"第五百零三条","txt":"犯罪的时候不满十八周岁，被判处五年有期徒刑以下刑罚的，人民检察院应当在收到人民法院生效判决后，对犯罪记录予以封存。"},{"i":504,"n":"第五百零四条","txt":"人民检察院应当将拟封存的未成年人犯罪记录、卷宗等相关材料装订成册，加密保存，不予公开，并建立专门的未成年人犯罪档案库，执行严格的保管制度。"},{"i":505,"n":"第五百零五条","txt":"除司法机关为办案需要或者有关单位根据国家规定进行查询的以外，人民检察院不得向任何单位和个人提供封存的犯罪记录，并不得提供未成年人有犯罪记录的证明。"},{"i":506,"n":"第五百零六条","txt":"被封存犯罪记录的未成年人，如果发现漏罪，且漏罪与封存记录之罪数罪并罚后被决定执行五年有期徒刑以上刑罚的，应当对其犯罪记录解除封存。"},{"i":507,"n":"第五百零七条","txt":"人民检察院对未成年犯罪嫌疑人作出不起诉决定后，应当对相关记录予以封存。具体程序参照本规则第五百零四条至第五百零六条的规定。"},{"i":508,"n":"第五百零八条","txt":"本节所称未成年人刑事案件，是指犯罪嫌疑人实施涉嫌犯罪行为时已满十四周岁、未满十八周岁的刑事案件。"},{"i":509,"n":"第五百零九条","txt":"办理未成年人刑事案件，除本节已有规定的以外，按照刑事诉讼法和其他有关规定进行。"},{"i":510,"n":"第五百一十条","txt":"下列公诉案件，双方当事人可以和解："},{"i":511,"n":"第五百一十一条","txt":"被害人死亡的，其法定代理人、近亲属可以与犯罪嫌疑人和解。"},{"i":512,"n":"第五百一十二条","txt":"犯罪嫌疑人系限制行为能力人的，其法定代理人可以代为和解。"},{"i":513,"n":"第五百一十三条","txt":"双方当事人可以就赔偿损失、赔礼道歉等民事责任事项进行和解，并且可以就被害人及其法定代理人或者近亲属是否要求或者同意公安机关、人民检察院、人民法院对犯罪嫌疑人依法从宽处理进行协商，但不得对案件的事实认定、证据采信、法律适用和定罪量刑等依法属于公安机关、人民检察院、人民法院职权范围的事宜进行协商。"},{"i":514,"n":"第五百一十四条","txt":"双方当事人可以自行达成和解，也可以经人民调解委员会、村民委员会、居民委员会、当事人所在单位或者同事、亲友等组织或者个人调解后达成和解。"},{"i":515,"n":"第五百一十五条","txt":"人民检察院应当对和解的自愿性、合法性进行审查，重点审查以下内容："},{"i":516,"n":"第五百一十六条","txt":"经审查认为双方自愿和解，内容合法，且符合本规则第五百一十条规定的范围和条件的，人民检察院应当主持制作和解协议书。"},{"i":517,"n":"第五百一十七条","txt":"和解协议书约定的赔偿损失内容，应当在双方签署协议后立即履行，至迟在人民检察院作出从宽处理决定前履行。确实难以一次性履行的，在被害人同意并提供有效担保的情况下，也可以分期履行。"},{"i":518,"n":"第五百一十八条","txt":"双方当事人在侦查阶段达成和解协议，公安机关向人民检察院提出从宽处理建议的，人民检察院在审查逮捕和审查起诉时应当充分考虑公安机关的建议。"},{"i":519,"n":"第五百一十九条","txt":"人民检察院对于公安机关提请批准逮捕的案件，双方当事人达成和解协议的，可以作为有无社会危险性或者社会危险性大小的因素予以考虑，经审查认为不需要逮捕的，可以作出不批准逮捕的决定；在审查起诉阶段可以依法变更强制措施。"},{"i":520,"n":"第五百二十条","txt":"人民检察院对于公安机关移送审查起诉的案件，双方当事人达成和解协议的，可以作为是否需要判处刑罚或者免除刑罚的因素予以考虑，符合法律规定的不起诉条件的，可以决定不起诉。"},{"i":521,"n":"第五百二十一条","txt":"人民检察院拟对当事人达成和解的公诉案件作出不起诉决定的，应当听取双方当事人对和解的意见，并且查明犯罪嫌疑人是否已经切实履行和解协议、不能即时履行的是否已经提供有效担保，将其作为是否决定不起诉的因素予以考虑。"},{"i":522,"n":"第五百二十二条","txt":"犯罪嫌疑人或者其亲友等以暴力、威胁、欺骗或者其他非法方法强迫、引诱被害人和解，或者在协议履行完毕之后威胁、报复被害人的，应当认定和解协议无效。已经作出不批准逮捕或者不起诉决定的，人民检察院根据案件情况可以撤销原决定，对犯罪嫌疑人批准逮捕或者提起公诉。"},{"i":523,"n":"第五百二十三条","txt":"对于贪污贿赂犯罪、恐怖活动犯罪等重大犯罪案件，犯罪嫌疑人、被告人逃匿，在通缉一年后不能到案，依照刑法规定应当追缴其违法所得及其他涉案财产的，人民检察院可以向人民法院提出没收违法所得的申请。"},{"i":524,"n":"第五百二十四条","txt":"人民检察院审查侦查机关移送的没收违法所得意见书，向人民法院提出没收违法所得的申请以及对违法所得没收程序中调查活动、审判活动的监督，由公诉部门办理。"},{"i":525,"n":"第五百二十五条","txt":"没收违法所得的申请，应当由与有管辖权的中级人民法院相对应的人民检察院提出。"},{"i":526,"n":"第五百二十六条","txt":"人民检察院向人民法院提出没收违法所得的申请，应当制作没收违法所得申请书。没收违法所得申请书的主要内容包括："},{"i":527,"n":"第五百二十七条","txt":"公安机关向人民检察院移送没收违法所得意见书，应当由有管辖权的人民检察院的同级公安机关移送。"},{"i":528,"n":"第五百二十八条","txt":"人民检察院审查公安机关移送的没收违法所得意见书，应当查明："},{"i":529,"n":"第五百二十九条","txt":"人民检察院应当在接到公安机关移送的没收违法所得意见书后三十日以内作出是否提出没收违法所得申请的决定。三十日以内不能作出决定的，经检察长批准，可以延长十五日。"},{"i":530,"n":"第五百三十条","txt":"人民检察院发现公安机关应当启动违法所得没收程序而不启动的，可以要求公安机关在七日以内书面说明不启动的理由。"},{"i":531,"n":"第五百三十一条","txt":"人民检察院发现公安机关在违法所得没收程序的调查活动中有违法情形的，应当向公安机关提出纠正意见。"},{"i":532,"n":"第五百三十二条","txt":"在审查公安机关移送的没收违法所得意见书的过程中，在逃的犯罪嫌疑人、被告人自动投案或者被抓获的，人民检察院应当终止审查，并将案卷退回公安机关处理。"},{"i":533,"n":"第五百三十三条","txt":"人民检察院直接受理立案侦查的案件，犯罪嫌疑人逃匿或者犯罪嫌疑人死亡而撤销案件，符合刑事诉讼法第二百八十条第一款规定条件的，侦查部门应当启动违法所得没收程序进行调查。"},{"i":534,"n":"第五百三十四条","txt":"在人民检察院审查起诉过程中，犯罪嫌疑人死亡，或者贪污贿赂犯罪、恐怖活动犯罪等重大犯罪案件的犯罪嫌疑人逃匿，在通缉一年后不能到案，依照刑法规定应当追缴其违法所得及其他涉案财产的，人民检察院可以直接提出没收违法所得的申请。"},{"i":535,"n":"第五百三十五条","txt":"人民法院对没收违法所得的申请进行审理，人民检察院应当承担举证责任。"},{"i":536,"n":"第五百三十六条","txt":"人民检察院发现人民法院或者审判人员审理没收违法所得案件违反法律规定的诉讼程序，应当向人民法院提出纠正意见。"},{"i":537,"n":"第五百三十七条","txt":"在审理案件过程中，在逃的犯罪嫌疑人、被告人自动投案或者被抓获，人民法院按照刑事诉讼法第二百八十三条第一款的规定终止审理的，人民检察院应当将案卷退回侦查机关处理。"},{"i":538,"n":"第五百三十八条","txt":"对于刑事诉讼法第二百八十条第一款规定以外需要没收违法所得的，按照有关规定执行。"},{"i":539,"n":"第五百三十九条","txt":"对于实施暴力行为，危害公共安全或者严重危害公民人身安全，已经达到犯罪程度，经法定程序鉴定依法不负刑事责任的精神病人，有继续危害社会可能的，人民检察院应当向人民法院提出强制医疗的申请。"},{"i":540,"n":"第五百四十条","txt":"人民检察院审查公安机关移送的强制医疗意见书，向人民法院提出强制医疗的申请以及对强制医疗决定的监督，由公诉部门办理。"},{"i":541,"n":"第五百四十一条","txt":"强制医疗的申请由被申请人实施暴力行为所在地的基层人民检察院提出；由被申请人居住地的人民检察院提出更为适宜的，可以由被申请人居住地的基层人民检察院提出。"},{"i":542,"n":"第五百四十二条","txt":"人民检察院向人民法院提出强制医疗的申请，应当制作强制医疗申请书。强制医疗申请书的主要内容包括："},{"i":543,"n":"第五百四十三条","txt":"人民检察院审查公安机关移送的强制医疗意见书，应当查明："},{"i":544,"n":"第五百四十四条","txt":"人民检察院应当在接到公安机关移送的强制医疗意见书后三十日以内作出是否提出强制医疗申请的决定。"},{"i":545,"n":"第五百四十五条","txt":"人民检察院发现公安机关应当启动强制医疗程序而不启动的，可以要求公安机关在七日以内书面说明不启动的理由。"},{"i":546,"n":"第五百四十六条","txt":"人民检察院发现公安机关对涉案精神病人进行鉴定的程序违反法律或者采取临时保护性约束措施不当的，应当提出纠正意见。"},{"i":547,"n":"第五百四十七条","txt":"人民检察院发现公安机关对涉案精神病人采取临时保护性约束措施时有体罚、虐待等违法情形的，应当提出纠正意见。"},{"i":548,"n":"第五百四十八条","txt":"在审查起诉中，犯罪嫌疑人经鉴定系依法不负刑事责任的精神病人的，人民检察院应当作出不起诉决定。认为符合刑事诉讼法第二百八十四条规定条件的，应当向人民法院提出强制医疗的申请。"},{"i":549,"n":"第五百四十九条","txt":"人民法院对强制医疗案件开庭审理的，人民检察院应当派员出席法庭。"},{"i":550,"n":"第五百五十条","txt":"人民检察院发现人民法院或者审判人员审理强制医疗案件违反法律规定的诉讼程序，应当向人民法院提出纠正意见。"},{"i":551,"n":"第五百五十一条","txt":"人民法院在审理案件过程中发现被告人符合强制医疗条件，作出被告人不负刑事责任的判决后，拟作出强制医疗决定的，人民检察院应当在庭审中发表意见。"},{"i":552,"n":"第五百五十二条","txt":"人民检察院依法对公安机关的刑事立案活动实行监督。"},{"i":553,"n":"第五百五十三条","txt":"被害人及其法定代理人、近亲属或者行政执法机关，认为公安机关对其控告或者移送的案件应当立案侦查而不立案侦查，或者当事人认为公安机关不应当立案而立案，向人民检察院提出的，人民检察院应当受理并进行审查。"},{"i":554,"n":"第五百五十四条","txt":"人民检察院控告检察部门受理对公安机关应当立案而不立案或者不应当立案而立案的控告、申诉，应当根据事实和法律进行审查，并可以要求控告人、申诉人提供有关材料，认为需要公安机关说明不立案或者立案理由的，应当及时将案件移送侦查监督部门办理。"},{"i":555,"n":"第五百五十五条","txt":"人民检察院侦查监督部门经过调查、核实有关证据材料，认为需要公安机关说明不立案理由的，经检察长批准，应当要求公安机关书面说明不立案的理由。"},{"i":556,"n":"第五百五十六条","txt":"人民检察院进行调查核实，可以询问办案人员和有关当事人，查阅、复制公安机关刑事受案、立案、破案等登记表册和立案、不立案、撤销案件、治安处罚、劳动教养等相关法律文书及案卷材料。"},{"i":557,"n":"第五百五十七条","txt":"人民检察院要求公安机关说明不立案或者立案理由，应当制作要求说明不立案理由通知书或者要求说明立案理由通知书，及时送达公安机关，并且告知公安机关在收到要求说明不立案理由通知书或者要求说明立案理由通知书后七日以内，书面说明不立案或者立案的情况、依据和理由，连同有关证据材料回复人民检察院。"},{"i":558,"n":"第五百五十八条","txt":"公安机关说明不立案或者立案的理由后，人民检察院侦查监督部门应当进行审查，认为公安机关不立案或者立案理由不能成立的，经检察长或者检察委员会讨论决定，应当通知公安机关立案或者撤销案件。"},{"i":559,"n":"第五百五十九条","txt":"人民检察院通知公安机关立案或者撤销案件，应当制作通知立案书或者通知撤销案件书，说明依据和理由，连同证据材料送达公安机关，并且告知公安机关应当在收到通知立案书后十五日以内立案，对通知撤销案件书没有异议的应当立即撤销案件，并将立案决定书或者撤销案件决定书及时送达人民检察院。"},{"i":560,"n":"第五百六十条","txt":"人民检察院通知公安机关立案或者撤销案件的，应当依法对执行情况进行监督。"},{"i":561,"n":"第五百六十一条","txt":"对于由公安机关管辖的国家机关工作人员利用职权实施的重大犯罪案件，人民检察院通知公安机关立案，公安机关不予立案的，经省级以上人民检察院决定，人民检察院可以直接立案侦查。"},{"i":562,"n":"第五百六十二条","txt":"对于公安机关认为人民检察院撤销案件通知有错误要求同级人民检察院复议的，人民检察院应当重新审查，在收到要求复议意见书和案卷材料后七日以内作出是否变更的决定，并通知公安机关。"},{"i":563,"n":"第五百六十三条","txt":"人民检察院侦查监督部门或者公诉部门发现本院侦查部门对应当立案侦查的案件不报请立案侦查或者对不应当立案侦查的案件进行立案侦查的，应当建议侦查部门报请立案侦查或者撤销案件；建议不被采纳的，应当报请检察长决定。"},{"i":564,"n":"第五百六十四条","txt":"人民检察院依法对公安机关的侦查活动是否合法实行监督。"},{"i":565,"n":"第五百六十五条","txt":"侦查活动监督主要发现和纠正以下违法行为："},{"i":566,"n":"第五百六十六条","txt":"人民检察院发现公安机关侦查活动中的违法行为，对于情节较轻的，可以由检察人员以口头方式向侦查人员或者公安机关负责人提出纠正意见，并及时向本部门负责人汇报；必要的时候，由部门负责人提出。对于情节较重的违法情形，应当报请检察长批准后，向公安机关发出纠正违法通知书。构成犯罪的，移送有关部门依法追究刑事责任。"},{"i":567,"n":"第五百六十七条","txt":"人民检察院根据需要可以派员参加公安机关对于重大案件的讨论和其他侦查活动，发现违法行为，情节较轻的可以口头纠正，情节较重的应当报请检察长批准后，向公安机关发出纠正违法通知书。"},{"i":568,"n":"第五百六十八条","txt":"对于公安机关执行人民检察院批准或者不批准逮捕决定的情况，以及释放被逮捕的犯罪嫌疑人或者变更逮捕措施的情况，人民检察院发现有违法情形的，应当通知纠正。"},{"i":569,"n":"第五百六十九条","txt":"人民检察院发现侦查机关或者侦查人员决定、执行、变更、撤销强制措施等活动中有违法情形的，应当及时提出纠正意见。"},{"i":570,"n":"第五百七十条","txt":"人民检察院发出纠正违法通知书的，应当根据公安机关的回复，监督落实情况；没有回复的，应当督促公安机关回复。"},{"i":571,"n":"第五百七十一条","txt":"人民检察院提出的纠正意见不被接受，公安机关要求复查的，应当在收到公安机关的书面意见后七日以内进行复查。经过复查，认为纠正违法意见正确的，应当及时向上一级人民检察院报告；认为纠正违法意见错误的，应当及时撤销。"},{"i":572,"n":"第五百七十二条","txt":"人民检察院侦查监督部门、公诉部门发现侦查人员在侦查活动中的违法行为情节严重，构成犯罪的，应当移送本院侦查部门审查，并报告检察长。侦查部门审查后应当提出是否立案侦查的意见，报请检察长决定。对于不属于本院管辖的，应当移送有管辖权的人民检察院或者其他机关处理。"},{"i":573,"n":"第五百七十三条","txt":"人民检察院侦查监督部门或者公诉部门对本院侦查部门侦查活动中的违法行为，应当根据情节分别处理。情节较轻的，可以直接向侦查部门提出纠正意见；情节较重或者需要追究刑事责任的，应当报请检察长决定。"},{"i":574,"n":"第五百七十四条","txt":"当事人和辩护人、诉讼代理人、利害关系人对于办理案件的机关及其工作人员有刑事诉讼法第一百一十五条规定的行为，向该机关申诉或者控告，对该机关作出的处理不服，或者该机关未在规定时间内作出答复，向人民检察院申诉的，办理案件的机关的同级人民检察院应当及时受理。"},{"i":575,"n":"第五百七十五条","txt":"对人民检察院办理案件中的违法行为的控告、申诉，以及对其他司法机关对控告、申诉的处理不服向人民检察院提出的申诉，由人民检察院控告检察部门受理。"},{"i":576,"n":"第五百七十六条","txt":"人民检察院依法对人民法院的审判活动是否合法实行监督。"},{"i":577,"n":"第五百七十七条","txt":"审判活动监督主要发现和纠正以下违法行为："},{"i":578,"n":"第五百七十八条","txt":"审判活动监督由公诉部门和刑事申诉检察部门承办，对于人民法院审理案件违反法定期限的，由监所检察部门承办。"},{"i":579,"n":"第五百七十九条","txt":"人民检察院检察长可以列席人民法院审判委员会会议，对审判委员会讨论的案件等议题发表意见，依法履行法律监督职责。"},{"i":580,"n":"第五百八十条","txt":"人民检察院在审判活动监督中，如果发现人民法院或者审判人员审理案件违反法律规定的诉讼程序，应当向人民法院提出纠正意见。"},{"i":581,"n":"第五百八十一条","txt":"人民检察院对人民法院审判活动中违法行为的监督，可以参照本规则有关人民检察院对公安机关侦查活动中违法行为监督的规定办理。"},{"i":582,"n":"第五百八十二条","txt":"人民检察院依法对人民法院的判决、裁定是否正确实行监督，对人民法院确有错误的判决、裁定，应当依法提出抗诉。"},{"i":583,"n":"第五百八十三条","txt":"对刑事判决、裁定的监督由公诉部门和刑事申诉检察部门承办。当事人及其法定代理人、近亲属认为人民法院已经发生法律效力的判决、裁定确有错误，向人民检察院申诉的，由刑事申诉检察部门依法办理。"},{"i":584,"n":"第五百八十四条","txt":"人民检察院认为同级人民法院第一审判决、裁定有下列情形之一的，应当提出抗诉："},{"i":585,"n":"第五百八十五条","txt":"人民检察院在收到人民法院第一审判决书或者裁定书后，应当及时审查，承办人员应当填写刑事判决、裁定审查表，提出处理意见，报公诉部门负责人审核。对于需要提出抗诉的案件，公诉部门应当报请检察长决定；案情重大、疑难、复杂的案件，由检察长提交检察委员会讨论决定。"},{"i":586,"n":"第五百八十六条","txt":"人民检察院对同级人民法院第一审判决的抗诉，应当在接到判决书的第二日起十日以内提出；对裁定的抗诉，应当在接到裁定书后的第二日起五日以内提出。"},{"i":587,"n":"第五百八十七条","txt":"人民检察院对同级人民法院第一审判决、裁定的抗诉，应当制作抗诉书通过原审人民法院向上一级人民法院提出，并将抗诉书副本连同案件材料报送上一级人民检察院。"},{"i":588,"n":"第五百八十八条","txt":"被害人及其法定代理人不服地方各级人民法院第一审的判决，在收到判决书后五日以内请求人民检察院提出抗诉的，人民检察院应当立即进行审查，在收到被害人及其法定代理人的请求后五日以内作出是否抗诉的决定，并且答复请求人。经审查认为应当抗诉的，适用本规则第五百八十四条至第五百八十七条的规定办理。"},{"i":589,"n":"第五百八十九条","txt":"上一级人民检察院对下级人民检察院按照第二审程序提出抗诉的案件，认为抗诉正确的，应当支持抗诉；认为抗诉不当的，应当向同级人民法院撤回抗诉，并且通知下级人民检察院。下级人民检察院如果认为上一级人民检察院撤回抗诉不当的，可以提请复议。上一级人民检察院应当复议，并将复议结果通知下级人民检察院。"},{"i":590,"n":"第五百九十条","txt":"第二审人民法院发回原审人民法院重新按照第一审程序审判的案件，如果人民检察院认为重新审判的判决、裁定确有错误的，可以按照第二审程序提出抗诉。"},{"i":591,"n":"第五百九十一条","txt":"人民检察院认为人民法院已经发生法律效力的判决、裁定确有错误，具有下列情形之一的，应当按照审判监督程序向人民法院提出抗诉："},{"i":592,"n":"第五百九十二条","txt":"对于高级人民法院判处死刑缓期二年执行的案件，省级人民检察院认为确有错误提请抗诉的，一般应当在收到生效判决、裁定后三个月以内提出，至迟不得超过六个月。"},{"i":593,"n":"第五百九十三条","txt":"当事人及其法定代理人、近亲属认为人民法院已经发生法律效力的刑事判决、裁定确有错误，向人民检察院申诉的，由作出生效判决、裁定的人民法院的同级人民检察院刑事申诉检察部门依法办理。"},{"i":594,"n":"第五百九十四条","txt":"对不服人民法院已经发生法律效力的刑事判决、裁定的申诉，经两级人民检察院办理且省级人民检察院已经复查的，如果没有新的事实和理由，人民检察院不再立案复查，但原审被告人可能被宣告无罪或者判决、裁定有其他重大错误可能的除外。"},{"i":595,"n":"第五百九十五条","txt":"人民检察院刑事申诉检察部门对已经发生法律效力的刑事判决、裁定的申诉复查后，认为需要提出抗诉的，报请检察长或者检察委员会讨论决定。"},{"i":596,"n":"第五百九十六条","txt":"人民检察院刑事申诉检察部门对不服人民法院已经发生法律效力的刑事判决、裁定的申诉案件复查终结后，应当制作刑事申诉复查通知书，并在十日以内通知申诉人。"},{"i":597,"n":"第五百九十七条","txt":"最高人民检察院发现各级人民法院已经发生法律效力的判决或者裁定，上级人民检察院发现下级人民法院已经发生法律效力的判决或者裁定确有错误时，可以直接向同级人民法院提出抗诉，或者指令作出生效判决、裁定人民法院的上一级人民检察院向同级人民法院提出抗诉。"},{"i":598,"n":"第五百九十八条","txt":"人民检察院按照审判监督程序向人民法院提出抗诉的，应当将抗诉书副本报送上一级人民检察院。"},{"i":599,"n":"第五百九十九条","txt":"对按照审判监督程序提出抗诉的案件，人民检察院认为人民法院作出的判决、裁定仍然确有错误的，如果案件是依照第一审程序审判的，同级人民检察院应当向上一级人民法院提出抗诉；如果案件是依照第二审程序审判的，上一级人民检察院应当按照审判监督程序向同级人民法院提出抗诉。"},{"i":600,"n":"第六百条","txt":"人民检察院公诉部门、刑事申诉检察部门办理按照审判监督程序抗诉案件，认为需要对被告人采取逮捕措施的，应当提出意见，参照本规则第十章的规定移送侦查监督部门办理；认为需要对被告人采取取保候审、监视居住措施的，由办案人员提出意见，部门负责人审核后，报检察长决定。"},{"i":601,"n":"第六百零一条","txt":"人民检察院对自诉案件的判决、裁定的监督，适用本节的规定。"},{"i":602,"n":"第六百零二条","txt":"最高人民检察院依法对最高人民法院的死刑复核活动实行法律监督。"},{"i":603,"n":"第六百零三条","txt":"最高人民检察院死刑复核检察部门负责承办死刑复核法律监督工作。"},{"i":604,"n":"第六百零四条","txt":"最高人民检察院发现在死刑复核期间的案件具有下列情形之一，经审查认为确有必要的，应当向最高人民法院提出意见："},{"i":605,"n":"第六百零五条","txt":"最高人民检察院对于最高人民法院通报的死刑复核案件，认为确有必要的，应当在最高人民法院裁判文书下发前提出意见。"},{"i":606,"n":"第六百零六条","txt":"省级人民检察院对于进入最高人民法院死刑复核程序的下列案件，应当制作提请监督报告并连同案件有关材料及时报送最高人民检察院："},{"i":607,"n":"第六百零七条","txt":"省级人民检察院发现死刑复核案件被告人自首、立功、达成赔偿协议取得被害方谅解等新的证据材料和有关情况，可能影响死刑适用的，应当及时向最高人民检察院报告。"},{"i":608,"n":"第六百零八条","txt":"死刑复核期间当事人及其近亲属或者受委托的律师向最高人民检察院提出的不服死刑裁判的申诉，由最高人民检察院死刑复核检察部门审查。"},{"i":609,"n":"第六百零九条","txt":"最高人民检察院死刑复核检察部门对死刑复核监督案件的审查可以采取下列方式进行："},{"i":610,"n":"第六百一十条","txt":"最高人民检察院对于受理的死刑复核监督案件，应当在一个月以内作出决定；因案件重大、疑难、复杂，需要延长审查期限的，应当报请检察长批准，适当延长办理期限。"},{"i":611,"n":"第六百一十一条","txt":"最高人民检察院死刑复核检察部门拟就死刑复核案件提出检察意见的，应当报请检察长或者检察委员会决定。"},{"i":612,"n":"第六百一十二条","txt":"最高人民检察院对于死刑复核监督案件，经审查认为确有必要向最高人民法院提出意见的，应当以死刑复核案件意见书的形式提出。死刑复核案件意见书应当提出明确的意见或者建议，并说明理由和法律依据。"},{"i":613,"n":"第六百一十三条","txt":"对于最高人民检察院提出应当核准死刑意见的案件，最高人民法院经审查仍拟不核准死刑，决定将案件提交审判委员会会议讨论并通知最高人民检察院派员列席的，最高人民检察院检察长或者受检察长委托的副检察长应当列席审判委员会会议。"},{"i":614,"n":"第六百一十四条","txt":"人民检察院依法对羁押期限和办案期限是否合法实行监督。"},{"i":615,"n":"第六百一十五条","txt":"对公安机关、人民法院办理案件的羁押期限和办案期限的监督，犯罪嫌疑人、被告人被羁押的，由人民检察院监所检察部门负责；犯罪嫌疑人、被告人未被羁押的，由人民检察院侦查监督部门或者公诉部门负责。对人民检察院办理案件的羁押期限和办案期限的监督，由本院案件管理部门负责。"},{"i":616,"n":"第六百一十六条","txt":"犯罪嫌疑人、被告人被逮捕后，人民检察院仍应当对羁押的必要性进行审查。"},{"i":617,"n":"第六百一十七条","txt":"侦查阶段的羁押必要性审查由侦查监督部门负责；审判阶段的羁押必要性审查由公诉部门负责。监所检察部门在监所检察工作中发现不需要继续羁押的，可以提出释放犯罪嫌疑人、被告人或者变更强制措施的建议。"},{"i":618,"n":"第六百一十八条","txt":"犯罪嫌疑人、被告人及其法定代理人、近亲属或者辩护人可以申请人民检察院进行羁押必要性审查，申请时应当说明不需要继续羁押的理由，有相关证据或者其他材料的，应当提供。"},{"i":619,"n":"第六百一十九条","txt":"人民检察院发现有下列情形之一的，可以向有关机关提出予以释放或者变更强制措施的书面建议："},{"i":620,"n":"第六百二十条","txt":"人民检察院可以采取以下方式进行羁押必要性审查："},{"i":621,"n":"第六百二十一条","txt":"人民检察院向有关办案机关提出对犯罪嫌疑人、被告人予以释放或者变更强制措施的建议的，应当要求有关办案机关在十日以内将处理情况通知本院。有关办案机关没有采纳人民检察院建议的，应当要求其说明理由和依据。"},{"i":622,"n":"第六百二十二条","txt":"人民检察院侦查部门、侦查监督部门、公诉部门在办理案件过程中，犯罪嫌疑人、被告人被羁押的，具有下列情形之一的，应当在作出决定或者收到决定书、裁定书后十日以内通知负有监督职责的人民检察院监所检察部门或者案件管理部门以及看守所："},{"i":623,"n":"第六百二十三条","txt":"人民检察院发现看守所的羁押期限管理活动有下列情形之一的，应当依法提出纠正意见："},{"i":624,"n":"第六百二十四条","txt":"人民检察院发现公安机关的侦查羁押期限执行情况有下列情形之一的，应当依法提出纠正意见："},{"i":625,"n":"第六百二十五条","txt":"人民检察院发现人民法院的审理期限执行情况有下列情形之一的，应当依法提出纠正意见："},{"i":626,"n":"第六百二十六条","txt":"人民检察院发现同级或者下级公安机关、人民法院超期羁押的，应当报经本院检察长批准，向该办案机关发出纠正违法通知书。"},{"i":627,"n":"第六百二十七条","txt":"人民检察院发出纠正违法通知书后，有关办案机关未回复意见或者继续超期羁押的，应当及时报告上一级人民检察院处理。"},{"i":628,"n":"第六百二十八条","txt":"对人民检察院办理的直接受理立案侦查案件或者审查逮捕、审查起诉案件，在犯罪嫌疑人侦查羁押期限、办案期限届满前，案件管理部门应当依照有关规定向本院侦查部门、侦查监督部门或者公诉部门进行期限届满提示。发现办案部门办理案件超过规定期限的，应当依照有关规定提出纠正意见。"},{"i":629,"n":"第六百二十九条","txt":"人民检察院依法对看守所收押、监管、释放犯罪嫌疑人、被告人以及对留所服刑罪犯执行刑罚等执法活动实行监督。"},{"i":630,"n":"第六百三十条","txt":"人民检察院发现看守所有下列违法情形之一的，应当提出纠正意见："},{"i":631,"n":"第六百三十一条","txt":"人民检察院发现看守所代为执行刑罚的活动有下列情形之一的，应当依法提出纠正意见："},{"i":632,"n":"第六百三十二条","txt":"对于看守所违法行为情节轻微的，检察人员可以口头提出纠正意见；发现严重违法行为，或者提出口头纠正意见后看守所在七日以内未予以纠正的，应当报经检察长批准，向看守所发出纠正违法通知书，同时将纠正违法通知书副本抄报上一级人民检察院并抄送看守所所属公安机关的上一级公安机关。"},{"i":633,"n":"第六百三十三条","txt":"人民检察院依法对执行刑事判决、裁定的活动实行监督。"},{"i":634,"n":"第六百三十四条","txt":"人民法院判决被告人无罪，免予刑事处罚，判处管制，宣告缓刑，单处罚金或者剥夺政治权利，被告人被羁押的，人民检察院应当监督被告人是否被立即释放。发现被告人没有被立即释放的，应当立即向人民法院或者看守所提出纠正意见。"},{"i":635,"n":"第六百三十五条","txt":"被判处死刑的罪犯在被执行死刑时，人民检察院应当派员临场监督。"},{"i":636,"n":"第六百三十六条","txt":"人民检察院收到同级人民法院执行死刑临场监督通知后，应当查明同级人民法院是否收到最高人民法院核准死刑的裁定或者作出的死刑判决、裁定和执行死刑的命令。"},{"i":637,"n":"第六百三十七条","txt":"临场监督执行死刑的检察人员应当依法监督执行死刑的场所、方法和执行死刑的活动是否合法。在执行死刑前，发现有下列情形之一的，应当建议人民法院立即停止执行："},{"i":638,"n":"第六百三十八条","txt":"在执行死刑过程中，人民检察院临场监督人员根据需要可以进行拍照、录像；执行死刑后，人民检察院临场监督人员应当检查罪犯是否确已死亡，并填写死刑执行临场监督笔录，签名后入卷归档。"},{"i":639,"n":"第六百三十九条","txt":"判处被告人死刑缓期二年执行的判决、裁定在执行过程中，人民检察院监督的内容主要包括："},{"i":640,"n":"第六百四十条","txt":"人民检察院发现人民法院、公安机关、看守所的交付执行活动有下列违法情形之一的，应当依法提出纠正意见："},{"i":641,"n":"第六百四十一条","txt":"人民检察院发现监狱在收押罪犯活动中有下列情形之一的，应当依法提出纠正意见："},{"i":642,"n":"第六百四十二条","txt":"人民检察院发现监狱、看守所等执行机关在管理、教育改造罪犯等活动中有违法行为的，应当依法提出纠正意见。"},{"i":643,"n":"第六百四十三条","txt":"人民检察院发现监狱、看守所、公安机关暂予监外执行的执法活动有下列情形之一的，应当依法提出纠正意见："},{"i":644,"n":"第六百四十四条","txt":"人民检察院收到监狱、看守所抄送的暂予监外执行书面意见副本后，应当逐案进行审查，发现罪犯不符合暂予监外执行法定条件或者提请暂予监外执行违反法定程序的，应当在十日以内向决定或者批准机关提出书面检察意见，同时也可以向监狱、看守所提出书面纠正意见。"},{"i":645,"n":"第六百四十五条","txt":"人民检察院接到决定或者批准机关抄送的暂予监外执行决定书后，应当进行审查。审查的内容包括："},{"i":646,"n":"第六百四十六条","txt":"人民检察院经审查认为暂予监外执行不当的，应当自接到通知之日起一个月以内，报经检察长批准，向决定或者批准暂予监外执行的机关提出书面纠正意见。下级人民检察院认为暂予监外执行不当的，应当立即层报决定或者批准暂予监外执行的机关的同级人民检察院，由其决定是否向决定或者批准暂予监外执行的机关提出书面纠正意见。"},{"i":647,"n":"第六百四十七条","txt":"人民检察院向决定或者批准暂予监外执行的机关提出不同意暂予监外执行的书面意见后，应当监督其对决定或者批准暂予监外执行的结果进行重新核查，并监督重新核查的结果是否符合法律规定。对核查不符合法律规定的，应当依法提出纠正意见，并向上一级人民检察院报告。"},{"i":648,"n":"第六百四十八条","txt":"对于暂予监外执行的罪犯，人民检察院发现罪犯不符合暂予监外执行条件、严重违反有关暂予监外执行的监督管理规定或者暂予监外执行的情形消失而罪犯刑期未满的，应当通知执行机关收监执行，或者建议决定或者批准暂予监外执行的机关作出收监执行决定。"},{"i":649,"n":"第六百四十九条","txt":"人民检察院收到执行机关抄送的减刑、假释建议书副本后，应当逐案进行审查，发现减刑、假释建议不当或者提请减刑、假释违反法定程序的，应当在十日以内向审理减刑、假释案件的人民法院提出书面检察意见，同时也可以向执行机关提出书面纠正意见。"},{"i":650,"n":"第六百五十条","txt":"人民检察院发现监狱等执行机关提请人民法院裁定减刑、假释的活动有下列情形之一的，应当依法提出纠正意见："},{"i":651,"n":"第六百五十一条","txt":"人民法院开庭审理减刑、假释案件，人民检察院应当指派检察人员出席法庭，发表意见。"},{"i":652,"n":"第六百五十二条","txt":"人民检察院收到人民法院减刑、假释的裁定书副本后，应当及时进行审查。审查的内容包括："},{"i":653,"n":"第六百五十三条","txt":"人民检察院经审查认为人民法院减刑、假释的裁定不当，应当在收到裁定书副本后二十日以内，报经检察长批准，向作出减刑、假释裁定的人民法院提出书面纠正意见。"},{"i":654,"n":"第六百五十四条","txt":"对人民法院减刑、假释裁定的纠正意见，由作出减刑、假释裁定的人民法院的同级人民检察院书面提出。"},{"i":655,"n":"第六百五十五条","txt":"人民检察院对人民法院减刑、假释的裁定提出纠正意见后，应当监督人民法院是否在收到纠正意见后一个月以内重新组成合议庭进行审理，并监督重新作出的裁定是否符合法律规定。对最终裁定不符合法律规定的，应当向同级人民法院提出纠正意见。"},{"i":656,"n":"第六百五十六条","txt":"人民检察院发现监狱、看守所对服刑期满或者依法应当予以释放的人员没有按期释放，对被裁定假释的罪犯依法应当交付罪犯居住地社区矫正机构实行社区矫正而不交付，对主刑执行完毕仍然需要执行附加剥夺政治权利的罪犯依法应当交付罪犯居住地公安机关执行而不交付，或者对服刑期未满又无合法释放根据的罪犯予以释放等违法行为的，应当依法提出纠正意见。"},{"i":657,"n":"第六百五十七条","txt":"人民检察院依法对公安机关执行剥夺政治权利的活动实行监督，发现公安机关未依法执行或者剥夺政治权利执行期满未书面通知本人及其所在单位、居住地基层组织等违法情形的，应当依法提出纠正意见。"},{"i":658,"n":"第六百五十八条","txt":"人民检察院依法对人民法院执行罚金刑、没收财产刑以及执行生效判决、裁定中没收违法所得及其他涉案财产的活动实行监督，发现人民法院有依法应当执行而不执行，执行不当，罚没的财物未及时上缴国库，或者执行活动中其他违法情形的，应当依法提出纠正意见。"},{"i":659,"n":"第六百五十九条","txt":"人民检察院依法对社区矫正执法活动进行监督，发现有下列情形之一的，应当依法向社区矫正机构提出纠正意见："},{"i":660,"n":"第六百六十条","txt":"对人民法院、公安机关、看守所、监狱、社区矫正机构等的交付执行活动、刑罚执行活动以及其他有关执行刑事判决、裁定活动中违法行为的监督，参照本规则第六百三十二条的规定办理。"},{"i":661,"n":"第六百六十一条","txt":"人民检察院对强制医疗执行活动是否合法实行监督。"},{"i":662,"n":"第六百六十二条","txt":"人民检察院对强制医疗的交付执行活动实行监督。发现交付执行机关未及时交付执行等违法情形的，应当依法提出纠正意见。"},{"i":663,"n":"第六百六十三条","txt":"人民检察院在强制医疗执行监督中发现被强制医疗的人不符合强制医疗条件或者需要依法追究刑事责任，人民法院作出的强制医疗决定可能错误的，应当在五日以内报经检察长批准，将有关材料转交作出强制医疗决定的人民法院的同级人民检察院。收到材料的人民检察院公诉部门应当在二十日以内进行审查，并将审查情况和处理意见反馈负责强制医疗执行监督的人民检察院。"},{"i":664,"n":"第六百六十四条","txt":"人民检察院发现强制医疗机构有下列情形之一的，应当依法提出纠正意见："},{"i":665,"n":"第六百六十五条","txt":"人民检察院应当受理被强制医疗的人及其近亲属、法定代理人的控告、举报和申诉，并及时审查处理。对控告人、举报人、申诉人要求回复处理结果的，人民检察院监所检察部门应当在十五日以内将调查处理情况书面反馈控告人、举报人、申诉人。"},{"i":666,"n":"第六百六十六条","txt":"人民检察院监所检察部门收到被强制医疗的人及其近亲属、法定代理人解除强制医疗决定的申请后，应当及时转交强制医疗机构审查，并监督强制医疗机构是否及时审查、审查处理活动是否合法。"},{"i":667,"n":"第六百六十七条","txt":"人民检察院对于人民法院批准解除强制医疗的决定实行监督，发现人民法院解除强制医疗的决定不当的，应当依法向人民法院提出纠正意见。"},{"i":668,"n":"第六百六十八条","txt":"人民检察院案件管理部门对检察机关办理的案件实行统一受理、流程监控、案后评查、统计分析、信息查询、综合考评等，对办案期限、办案程序、办案质量等进行管理、监督、预警。"},{"i":669,"n":"第六百六十九条","txt":"人民检察院案件管理部门发现本院办案部门或者办案人员有下列情形之一的，应当及时提出纠正意见："},{"i":670,"n":"第六百七十条","txt":"人民检察院案件管理部门对以本院名义制发的法律文书实施监督管理。"},{"i":671,"n":"第六百七十一条","txt":"人民检察院办理的案件，办结后需要向其他单位移送案卷材料的，统一由案件管理部门审核移送材料是否规范、齐备。案件管理部门认为材料规范、齐备，符合移送条件的，应当立即由有关部门按照相关规定移送；认为材料不符合要求的，应当及时通知办案部门补送、更正。"},{"i":672,"n":"第六百七十二条","txt":"公安机关等侦查机关移送审查起诉时随案移送涉案财物及其孳息的，人民检察院案件管理部门应当在受理案件时进行审查，并及时办理入库保管手续。"},{"i":673,"n":"第六百七十三条","txt":"人民检察院办案部门查封、扣押、冻结涉案财物及其孳息后，应当立即将扣押的款项存入专门账户，将扣押的物品送案件管理部门办理入库保管手续，并将查封、扣押、冻结涉案财物的清单送案件管理部门登记，至迟不得超过三日。法律和有关规定另有规定的除外。"},{"i":674,"n":"第六百七十四条","txt":"人民检察院案件管理部门负责对扣押的涉案财物进行保管，并对查封、扣押、冻结、处理涉案财物工作进行监督管理，对违反规定的行为提出纠正意见；对构成违法或者严重违纪的行为，移送纪检监察部门处理。"},{"i":675,"n":"第六百七十五条","txt":"人民检察院办案部门需要调用、移送、处理查封、扣押、冻结的涉案财物的，应当按照规定办理审批手续。案件管理部门对于审批手续齐全的，应当办理出库手续。"},{"i":676,"n":"第六百七十六条","txt":"人民检察院进行司法协助，有我国参加或者缔结的国际条约规定的，适用该条约规定，但是我国声明保留的条款除外；无相应条约规定的，按照互惠原则通过外交途径办理。"},{"i":677,"n":"第六百七十七条","txt":"人民检察院应当在相互尊重国家主权和平等互利的基础上，与有关国家的主管机关相互提供司法协助。"},{"i":678,"n":"第六百七十八条","txt":"享有外交特权和豁免权的外国人的刑事责任问题，通过外交途径解决。"},{"i":679,"n":"第六百七十九条","txt":"人民检察院司法协助的范围主要包括刑事方面的调查取证，送达刑事诉讼文书，通报刑事诉讼结果，移交物证、书证和视听资料，扣押、移交赃款、赃物以及法律和国际条约规定的其他司法协助事宜。"},{"i":680,"n":"第六百八十条","txt":"办理引渡案件，按照国家关于引渡的法律和规定执行。"},{"i":681,"n":"第六百八十一条","txt":"人民检察院对外进行司法协助，应当根据我国有关法律规定的程序向外国提供司法协助和办理司法协助事务。依照国际条约规定，在不违背我国法律规定的前提下，也可以按照请求方的要求适用请求书中所示的程序。"},{"i":682,"n":"第六百八十二条","txt":"外国有关机关请求的事项有损中华人民共和国的主权、安全或者社会公共利益以及违反中国法律的，应当不予协助；不属于人民检察院职权范围的，应当予以退回或者移送有关机关，并说明理由。"},{"i":683,"n":"第六百八十三条","txt":"最高人民检察院是检察机关办理司法协助事务的最高主管机关，依照国际条约规定是人民检察院司法协助的中方中央机关。"},{"i":684,"n":"第六百八十四条","txt":"人民检察院与有关国家相互提供司法协助，应当按照我国与有关国家缔结的司法协助条约规定的联系途径或者外交途径进行。"},{"i":685,"n":"第六百八十五条","txt":"有关司法协助条约规定最高人民检察院为司法协助的中方中央机关的，由最高人民检察院直接与有关国家对应的中央机关联系和转递司法协助文件及其他材料。"},{"i":686,"n":"第六百八十六条","txt":"其他机关需要通过最高人民检察院对外办理司法协助的，应当通过其最高主管机关与最高人民检察院联系。"},{"i":687,"n":"第六百八十七条","txt":"对尚未与我国缔结司法协助条约的国家，相互之间需要提供司法协助的，应当根据互惠原则，通过外交途径办理，也可以按照惯例进行。"},{"i":688,"n":"第六百八十八条","txt":"人民检察院需要通过国际刑事警察组织缉捕人犯、查询资料的，由有关人民检察院提出申请，层报最高人民检察院审查后与有关部门联系办理。"},{"i":689,"n":"第六百八十九条","txt":"我国边境地区人民检察院与相邻国家的司法机关相互进行司法合作，在不违背有关条约、协议和我国法律的前提下，可以按惯例或者遵照有关规定进行，但应当报最高人民检察院备案。"},{"i":690,"n":"第六百九十条","txt":"我国边境地区人民检察院与相邻国家的司法机关相互进行司法合作，可以视情况就双方之间办案过程中的具体事务作出安排，开展友好往来活动。"},{"i":691,"n":"第六百九十一条","txt":"最高人民检察院通过有关国际条约规定的联系途径或外交途径，接收外国提出的司法协助请求。"},{"i":692,"n":"第六百九十二条","txt":"外国有关机关请求人民检察院提供司法协助的请求书及所附文件，应当附有中文译本或者国际条约规定的其他文字文本。"},{"i":693,"n":"第六百九十三条","txt":"最高人民检察院收到缔约的外国一方提出的司法协助请求后，应当依据我国法律和有关司法协助条约进行审查。对符合条约规定并且所附材料齐全的，交由有关省、自治区、直辖市人民检察院办理或者指定有关人民检察院办理，或者交由其他有关最高主管机关指定有关机关办理。对不符合条约或者有关法律规定的，应当通过接收请求的途径退回请求方不予执行；对所附材料不齐全的，应当要求请求方予以补充。"},{"i":694,"n":"第六百九十四条","txt":"有关省、自治区、直辖市人民检察院收到最高人民检察院转交的司法协助请求书和所附材料后，可以直接办理，也可以指定有关的人民检察院办理。"},{"i":695,"n":"第六百九十五条","txt":"负责执行司法协助请求的人民检察院收到司法协助请求书和所附材料后，应即安排执行，并按条约规定的格式和语言文字将执行结果及有关材料报经省、自治区、直辖市人民检察院审查后，报送最高人民检察院。"},{"i":696,"n":"第六百九十六条","txt":"最高人民检察院应当对执行结果进行审查。对于符合请求要求和有关规定的，由最高人民检察院转递请求协助的缔约外国一方。"},{"i":697,"n":"第六百九十七条","txt":"缔约的外国一方通过其他中方中央机关请求检察机关提供司法协助的，由其他中方中央机关将请求书及所附文件转递最高人民检察院，按本节规定办理。"},{"i":698,"n":"第六百九十八条","txt":"地方各级人民检察院需要向缔约的外国一方请求提供司法协助，应当按有关条约的规定提出司法协助请求书、调查提纲及所附文件和相应的译文，经省级人民检察院审核后，报送最高人民检察院。"},{"i":699,"n":"第六百九十九条","txt":"最高人民检察院收到地方各级人民检察院请求缔约的外国一方提供司法协助的材料后，应当依照有关条约进行审查。对符合条约有关规定、所附材料齐全的，应当连同上述材料一并转递缔约另一方的中央机关，或者交由其他中方中央机关办理。对不符合条约规定或者材料不齐全的，应当退回提出请求的人民检察院补充或者修正。"},{"i":700,"n":"第七百条","txt":"需要派员赴国外调查取证的，承办案件的人民检察院应当查明在国外证人、犯罪嫌疑人的具体居住地点或者地址、通讯方式等基本情况，制作调查提纲，层报省级人民检察院审核后报送最高人民检察院，通过司法协助或者外交途径向被请求国发出请求书，在被请求国同意后按照有关程序办理赴国外取证事宜。"},{"i":701,"n":"第七百零一条","txt":"人民检察院提供司法协助，请求书中附有办理期限的，应当按期完成。未附办理期限的，调查取证一般应当在三个月以内完成；送达刑事诉讼文书一般应当在三十日以内完成。"},{"i":702,"n":"第七百零二条","txt":"人民检察院提供刑事司法协助，根据有关条约规定需要向请求方收取费用的，应当将费用和账单连同执行司法协助的结果一并报送最高人民检察院转递请求方。最高人民检察院收到上述费用后应当立即转交有关人民检察院。"},{"i":703,"n":"第七百零三条","txt":"人民检察院请求外国提供司法协助，根据条约规定应当支付费用的，最高人民检察院收到被请求方开具的收费账单后，应当立即转交有关人民检察院支付。"},{"i":704,"n":"第七百零四条","txt":"人民检察院办理国家安全机关、走私犯罪侦查机关、监狱移送的刑事案件以及对国家安全机关、走私犯罪侦查机关、监狱立案、侦查活动的监督，适用本规则的有关规定。"},{"i":705,"n":"第七百零五条","txt":"军事检察院等专门人民检察院办理刑事案件，适用本规则和其他有关规定。"},{"i":706,"n":"第七百零六条","txt":"人民检察院办理直接立案侦查的案件接受人民监督员的监督，具体程序依照有关规定办理。"},{"i":707,"n":"第七百零七条","txt":"本规则具有司法解释效力，由最高人民检察院负责解释。"},{"i":708,"n":"第七百零八条","txt":"本规则自2013年1月1日起施行。最高人民检察院1999年1月18日发布的《人民检察院刑事诉讼规则》同时废止；最高人民检察院以前发布的司法解释和规范性文件与本规则不一致的，以本规则为准。"}],"renminjianchayuanxingzhengsusongjianduguize-2":[{"i":1,"n":"第一条","txt":"为了保障和规范人民检察院依法履行行政诉讼监督职责，根据《中华人民共和国行政诉讼法》《中华人民共和国民事诉讼法》《中华人民共和国人民检察院组织法》和其他有关规定，结合检察工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院通过办理行政诉讼监督案件，监督人民法院依法审判和执行，促进行政机关依法行使职权，维护司法公正和司法权威，维护国家利益和社会公共利益，保护公民、法人和其他组织的合法权益，保障国家法律的统一正确实施。"},{"i":3,"n":"第三条","txt":"人民检察院通过抗诉、检察建议等方式，对行政诉讼实行法律监督。"},{"i":4,"n":"第四条","txt":"人民检察院对行政诉讼实行监督，应当以事实为根据，以法律为准绳，坚持公开、公平、公正，坚持合法性审查，监督和支持人民法院、行政机关依法行使职权。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，当事人可以向人民检察院申请监督："},{"i":6,"n":"第六条","txt":"当事人依照本规则第五条第一项、第二项规定向人民检察院申请监督，应当在人民法院作出驳回再审申请裁定之日或者再审判决、裁定发生法律效力之日起六个月内提出；对人民法院逾期未对再审申请作出裁定的，应当在再审申请审查期限届满之日起六个月内提出。"},{"i":7,"n":"第七条","txt":"当事人向人民检察院申请监督，有下列情形之一的，人民检察院不予受理："},{"i":8,"n":"第八条","txt":"当事人对已经发生法律效力的行政判决、裁定、调解书向人民检察院申请监督的，由作出生效判决、裁定、调解书的人民法院所在地同级人民检察院控告检察部门受理。"},{"i":9,"n":"第九条","txt":"有下列情形之一的行政诉讼案件，人民检察院应当依职权进行监督："},{"i":10,"n":"第十条","txt":"人民检察院行政检察部门负责对受理后的行政诉讼监督案件进行审查。"},{"i":11,"n":"第十一条","txt":"人民检察院对审查终结的案件，应当区分情况作出下列决定："},{"i":12,"n":"第十二条","txt":"人民检察院受理当事人申请监督的案件，应当在三个月内审查终结并作出决定，但调卷、鉴定、评估、审计期间不计入审查期限。有特殊情况需要延长的，由本院检察长批准。"},{"i":13,"n":"第十三条","txt":"人民检察院因履行法律监督职责提出检察建议或者抗诉的需要，有下列情形之一的，可以向当事人或者案外人调查核实有关情况："},{"i":14,"n":"第十四条","txt":"申请监督人提供的新的证据，能够证明原判决、裁定认定基本事实或者裁判结果错误的，应当认定为《中华人民共和国行政诉讼法》第九十一条第二项规定的情形，但原审被告无正当理由逾期提供证据的除外。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，应当认定为《中华人民共和国行政诉讼法》第九十一条第三项规定的“认定事实的主要证据不足”："},{"i":16,"n":"第十六条","txt":"有下列情形之一的，应当认定为《中华人民共和国行政诉讼法》第九十一条第四项规定的“适用法律、法规确有错误”："},{"i":17,"n":"第十七条","txt":"有下列情形之一的，应当认定为《中华人民共和国行政诉讼法》第九十一条第五项规定的“违反法律规定的诉讼程序，可能影响公正审判的”："},{"i":18,"n":"第十八条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的判决、裁定有下列情形之一的，可以向同级人民法院提出再审检察建议："},{"i":19,"n":"第十九条","txt":"符合本规则第十八条规定的案件有下列情形之一的，地方各级人民检察院应当提请上一级人民检察院抗诉："},{"i":20,"n":"第二十条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的判决、裁定具有下列情形之一的，应当提请上一级人民检察院抗诉："},{"i":21,"n":"第二十一条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的调解书损害国家利益、社会公共利益的，可以向同级人民法院提出再审检察建议，也可以提请上一级人民检察院抗诉。"},{"i":22,"n":"第二十二条","txt":"最高人民检察院对各级人民法院已经发生法律效力的判决、裁定、调解书，上级人民检察院对下级人民法院已经发生法律效力的判决、裁定、调解书，发现有《中华人民共和国行政诉讼法》第九十一条、第九十三条规定情形的，应当向同级人民法院提出抗诉。"},{"i":23,"n":"第二十三条","txt":"人民检察院提出再审检察建议，应当制作《再审检察建议书》，在决定之日起十五日内将《再审检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出再审检察建议的《通知书》，发送当事人。人民检察院提出再审检察建议，应当经检察委员会决定，并将《再审检察建议书》报上一级人民检察院备案。"},{"i":24,"n":"第二十四条","txt":"人民检察院提请抗诉，应当制作《提请抗诉报告书》，在决定之日起十五日内将《提请抗诉报告书》连同案件卷宗等材料报送上一级人民检察院，并制作决定提请抗诉的《通知书》，发送当事人。"},{"i":25,"n":"第二十五条","txt":"人民检察院提出抗诉，应当制作《抗诉书》，在决定之日起十五日内将《抗诉书》连同案件卷宗移送同级人民法院，并制作决定抗诉的《通知书》，发送当事人。"},{"i":26,"n":"第二十六条","txt":"人民检察院提出抗诉的案件，人民法院再审时，人民检察院应当派员出席法庭。"},{"i":27,"n":"第二十七条","txt":"人民检察院认为当事人的监督申请不符合监督条件，应当制作《不支持监督申请决定书》，在决定之日起十五日内发送当事人。"},{"i":28,"n":"第二十八条","txt":"人民检察院发现人民法院审判活动有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":29,"n":"第二十九条","txt":"人民检察院发现人民法院执行裁定、决定等有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":30,"n":"第三十条","txt":"人民检察院发现人民法院在执行活动中违反规定采取调查、查封、扣押、冻结、评估、拍卖、变卖、保管、发还财产等执行实施措施的，应当向同级人民法院提出检察建议。"},{"i":31,"n":"第三十一条","txt":"人民检察院发现人民法院有下列不履行或者怠于履行执行职责情形之一的，应当向同级人民法院提出检察建议："},{"i":32,"n":"第三十二条","txt":"人民检察院根据本规则第二十八条、第二十九条、第三十条、第三十一条提出检察建议，应当制作《检察建议书》，在决定之日起十五日内将《检察建议书》连同案件卷宗移送同级人民法院。当事人申请监督的案件，人民检察院应当制作决定提出检察建议的《通知书》，发送申请人。人民检察院对行政执行活动提出检察建议，应当经检察委员会决定。"},{"i":33,"n":"第三十三条","txt":"人民法院对人民检察院监督行为提出书面建议的，人民检察院应当在一个月内将处理结果书面回复人民法院。人民法院对回复意见有异议，并通过上一级人民法院向上一级人民检察院提出，上一级人民检察院认为建议正确的，应当要求下级人民检察院及时纠正。"},{"i":34,"n":"第三十四条","txt":"人民检察院办理行政诉讼监督案件，发现行政机关有违反法律规定、可能影响人民法院公正审理的行为，可以向行政机关提出检察建议，并将相关情况告知人民法院。"},{"i":35,"n":"第三十五条","txt":"人民检察院行政检察部门在履行职责过程中，发现违法违纪或者涉嫌犯罪线索，应当及时将相关材料移送有关职能部门。"},{"i":36,"n":"第三十六条","txt":"人民检察院办理行政诉讼监督案件，本规则没有规定的，适用《人民检察院民事诉讼监督规则（试行）》的相关规定。"},{"i":37,"n":"第三十七条","txt":"本规则自发布之日起施行。本院之前公布的其他有关行政诉讼监督的规定与本规则内容不一致的，以本规则为准。"}],"zuigaorenminfayuanduiguowuyuanzongjiaoshiwujuyisig00f0ac":[],"zuigaorenminfayuanduizaishenpangongzuozhongyouguanf6d6ee":[],"zuigaorenminfayuanguanyubaoxianjinnengfouzuoweibei51c879":[],"zuigaorenminfayuanguanyubeidaojidongcheliangzhaosh58ff3e":[],"zuigaorenminfayuanguanyubeijichengrensiwanghoumeiybe1b14":[],"zuigaorenminfayuanguanyucaiqusuqianbaoquancuoshide6e3207":[],"zuigaorenminfayuanguanyuchaoguosusongshixiaoqijian48a172":[],"zuigaorenminfayuanguanyuchengshijiedaobanshichushi9d7598":[],"zuigaorenminfayuanguanyuchujieyinhangzhanghudidangefdf75":[],"zuigaorenminfayuanguanyudangshirenchitaiwandiquyou79a444":[],"zuigaorenminfayuanguanyudangshirenduizhongcaixieyi6b6510":[],"zuigaorenminfayuanguanyudangshirenyinduibuyuzhixin89a4e7":[],"zuigaorenminfayuanguanyudanweifuzerenbeizhuijiuxind10e2f":[],"zuigaorenminfayuanguanyudiandangfangwubeishiweijuea98d7d":[],"zuigaorenminfayuanguanyudiershenfayuancaidinganzida2d94a":[],"zuigaorenminfayuanguanyudiyishenlihunpanjueshengxi50ed5c":[],"zuigaorenminfayuanguanyuduianwairendecaichannengfo926009":[],"zuigaorenminfayuanguanyuduiqiyefarenpochanhuanzhaiab95f1":[],"zuigaorenminfayuanguanyuduisiyingkechebaoxianqiman7e1249":[],"zuigaorenminfayuanguanyuduisuqiantingzhiqinfanzhuac45336":[{"i":1,"n":"第一条","txt":"根据专利法第六十一条的规定，专利权人或者利害关系人可以向人民法院提出诉前责令被申请人停止侵犯专利权行为的申请。"},{"i":2,"n":"第二条","txt":"诉前责令停止侵犯专利权行为的申请，应当向有专利侵权案件管辖权的人民法院提出。"},{"i":3,"n":"第三条","txt":"专利权人或者利害关系人向人民法院提出申请，应当递交书面申请状；申请状应当载明当事人及其基本情况、申请的具体内容、范围和理由等事项。申请的理由包括有关行为如不及时制止会使申请人合法权益受到难以弥补的损害的具体说明。"},{"i":4,"n":"第四条","txt":"申请人提出申请时，应当提交下列证据："},{"i":5,"n":"第五条","txt":"人民法院作出诉前停止侵犯专利权行为的裁定事项，应当限于专利权人或者利害关系人申请的范围。"},{"i":6,"n":"第六条","txt":"申请人提出申请时应当提供担保，申请人不提供担保的，驳回申请。"},{"i":7,"n":"第七条","txt":"在执行停止有关行为裁定过程中，被申请人可能因采取该项措施造成更大损失的，人民法院可以责令申请人追加相应的担保。申请人不追加担保的，解除有关停止措施。"},{"i":8,"n":"第八条","txt":"停止侵犯专利权行为裁定所采取的措施，不因被申请人提出反担保而解除。"},{"i":9,"n":"第九条","txt":"人民法院接受专利权人或者利害关系人提出责令停止侵犯专利权行为的申请后，经审查符合本规定第四条的，应当在48小时内作出书面裁定；裁定责令被申请人停止侵犯专利权行为的，应当立即开始执行。"},{"i":10,"n":"第十条","txt":"当事人对裁定不服的，可以在收到裁定之日起10日内申请复议一次。复议期间不停止裁定的执行。"},{"i":11,"n":"第十一条","txt":"人民法院对当事人提出的复议申请应当从以下方面进行审查："},{"i":12,"n":"第十二条","txt":"专利权人或者利害关系人在人民法院采取停止有关行为的措施后15日内不起诉的，人民法院解除裁定采取的措施。"},{"i":13,"n":"第十三条","txt":"申请人不起诉或者申请错误造成被申请人损失的，被申请人可以向有管辖权的人民法院起诉请求申请人赔偿，也可以在专利权人或者利害关系人提起的专利权侵权诉讼中提出损害赔偿的请求，人民法院可以一并处理。"},{"i":14,"n":"第十四条","txt":"停止侵犯专利权行为裁定的效力，一般应维持到终审法律文书生效时止。人民法院也可以根据案情，确定具体期限；期限届满时，根据当事人的请求仍可作出继续停止有关行为的裁定。"},{"i":15,"n":"第十五条","txt":"被申请人违反人民法院责令停止有关行为裁定的，依照民事诉讼法第一百零二条规定处理。"},{"i":16,"n":"第十六条","txt":"人民法院执行诉前停止侵犯专利权行为的措施时，可以根据当事人的申请，参照民事诉讼法第七十四条的规定，同时进行证据保全。"},{"i":17,"n":"第十七条","txt":"专利权人或者利害关系人向人民法院提起专利侵权诉讼时，同时提出先行停止侵犯专利权行为请求的，人民法院可以先行作出裁定。"},{"i":18,"n":"第十八条","txt":"诉前停止侵犯专利权行为的案件，申请人应当按照《人民法院诉讼收费办法》及其补充规定交纳费用。"}],"zuigaorenminfayuanguanyuduiyinfanghaiminshisusongb992967":[],"zuigaorenminfayuanguanyufuqilihunhourengongshoujin202d8b":[],"zuigaorenminfayuanguanyugejirenminfayuanyugangfang4edd23":[],"zuigaorenminfayuanguanyuguanchezhixingjichengfaruo85821a":[],"zuigaorenminfayuanguanyuguoyougongyeqiyeyijiqisheb9866cc":[],"zuigaorenminfayuanguanyujianshegongchengjiakuanyou7efdd6":[],"zuigaorenminfayuanguanyujiaotongshiguzhongdecaicha845c94":[],"zuigaorenminfayuanguanyujiechulaodonghetongdelaodo73ad03":[],"zuigaorenminfayuanguanyujingjihetongdemingchengyun920e3c":[],"zuigaorenminfayuanguanyujinrongjigouweixingzhengjie0082c":[],"zuigaorenminfayuanguanyujunshifayuanguanxiaminshia6e6488-2":[{"i":1,"n":"第一条","txt":"下列民事案件，由军事法院管辖："},{"i":2,"n":"第二条","txt":"下列民事案件，地方当事人向军事法院提起诉讼或者提出申请的，军事法院应当受理："},{"i":3,"n":"第三条","txt":"当事人一方是军人或者军队单位，且合同履行地或者标的物所在地在营区内的合同纠纷，当事人书面约定由军事法院管辖，不违反法律关于级别管辖、专属管辖和专门管辖规定的，可以由军事法院管辖。"},{"i":4,"n":"第四条","txt":"军事法院受理第一审民事案件，应当参照民事诉讼法关于地域管辖、级别管辖的规定确定。"},{"i":5,"n":"第五条","txt":"军事法院发现受理的民事案件属于地方人民法院管辖的，应当移送有管辖权的地方人民法院，受移送的地方人民法院应当受理。地方人民法院认为受移送的案件不属于本院管辖的，应当报请上级地方人民法院处理，不得再自行移送。"},{"i":6,"n":"第六条","txt":"军事法院与地方人民法院之间因管辖权发生争议，由争议双方协商解决；协商不成的，报请各自的上级法院协商解决；仍然协商不成的，报请最高人民法院指定管辖。"},{"i":7,"n":"第七条","txt":"军事法院受理案件后，当事人对管辖权有异议的，应当在提交答辩状期间提出。军事法院对当事人提出的异议，应当审查。异议成立的，裁定将案件移送有管辖权的军事法院或者地方人民法院；异议不成立的，裁定驳回。"},{"i":8,"n":"第八条","txt":"本规定所称军人是指中国人民解放军的现役军官、文职干部、士兵及具有军籍的学员，中国人民武装警察部队的现役警官、文职干部、士兵及具有军籍的学员。军队中的文职人员、非现役公勤人员、正式职工，由军队管理的离退休人员，参照军人确定管辖。"},{"i":9,"n":"第九条","txt":"本解释施行前本院公布的司法解释以及司法解释性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyujunshifayuanguanxiaminshia6e6488-3":[{"i":1,"n":"第一条","txt":"下列民事案件，由军事法院管辖："},{"i":2,"n":"第二条","txt":"下列民事案件，地方当事人向军事法院提起诉讼或者提出申请的，军事法院应当受理："},{"i":3,"n":"第三条","txt":"当事人一方是军人或者军队单位，且合同履行地或者标的物所在地在营区内的合同纠纷，当事人书面约定由军事法院管辖，不违反法律关于级别管辖、专属管辖和专门管辖规定的，可以由军事法院管辖。"},{"i":4,"n":"第四条","txt":"军事法院受理第一审民事案件，应当参照民事诉讼法关于地域管辖、级别管辖的规定确定。"},{"i":5,"n":"第五条","txt":"军事法院发现受理的民事案件属于地方人民法院管辖的，应当移送有管辖权的地方人民法院，受移送的地方人民法院应当受理。地方人民法院认为受移送的案件不属于本院管辖的，应当报请上级地方人民法院处理，不得再自行移送。"},{"i":6,"n":"第六条","txt":"军事法院与地方人民法院之间因管辖权发生争议，由争议双方协商解决；协商不成的，报请各自的上级法院协商解决；仍然协商不成的，报请最高人民法院指定管辖。"},{"i":7,"n":"第七条","txt":"军事法院受理案件后，当事人对管辖权有异议的，应当在提交答辩状期间提出。军事法院对当事人提出的异议，应当审查。异议成立的，裁定将案件移送有管辖权的军事法院或者地方人民法院；异议不成立的，裁定驳回。"},{"i":8,"n":"第八条","txt":"本规定所称军人是指中国人民解放军的现役军官、文职干部、士兵及具有军籍的学员，中国人民武装警察部队的现役警官、文职干部、士兵及具有军籍的学员。军队中的文职人员、非现役公勤人员、正式职工，由军队管理的离退休人员，参照军人确定管辖。"},{"i":9,"n":"第九条","txt":"本解释施行前本院公布的司法解释以及司法解释性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyukandengqinhaitarenmingyuqu0c27c5":[],"zuigaorenminfayuanguanyulanfazijisuoyouquandelinmu9d87bd":[],"zuigaorenminfayuanguanyulaodongzhongcaiweiyuanhuiyd81be6":[],"zuigaorenminfayuanguanyuminshixingzhengsusongzhong963bf6":[{"i":1,"n":"第一条","txt":"根据国家赔偿法第三十一条的规定，人民法院在民事、行政诉讼过程中，违法采取对妨害诉讼的强制措施、保全措施或者对判决、裁定及其他生效法律文书执行错误，侵犯公民、法人和其他组织合法权益造成损害的，依法应由国家承担赔偿责任。"},{"i":2,"n":"第二条","txt":"违法采取对妨害诉讼的强制措施，是指下列行为："},{"i":3,"n":"第三条","txt":"违法采取保全措施，是指人民法院依职权采取的下列行为："},{"i":4,"n":"第四条","txt":"对判决、裁定及其他生效法律文书执行错误，是指对已经发生法律效力的判决、裁定、民事制裁决定、调解、支付令、仲裁裁决、具有强制执行效力的公证债权文书以及行政处罚、处理决定等执行错误。包括下列行为："},{"i":5,"n":"第五条","txt":"人民法院及其工作人员在民事、行政诉讼或者执行过程中，以殴打或者唆使他人以殴打等暴力行为，或者违法使用武器、警械，造成公民身体伤害、死亡的，应当比照国家赔偿法第十五条第（四）项、第（五）项规定予以赔偿。"},{"i":6,"n":"第六条","txt":"人民法院及其工作人员在民事、行政诉讼或者执行过程中，具有本解释第二条至第五条规定情形，造成损害的，应当承担直接损失的赔偿责任。"},{"i":7,"n":"第七条","txt":"根据国家赔偿法第十七条、第三十一条的规定，具有下列情形之一的，国家不承担赔偿责任："},{"i":8,"n":"第八条","txt":"申请民事、行政诉讼中司法赔偿的，违法行使职权的行为应当先经依法确认。"},{"i":9,"n":"第九条","txt":"未经依法确认直接向人民法院赔偿委员会申请作出赔偿决定的，人民法院赔偿委员会不予受理。"},{"i":10,"n":"第十条","txt":"经依法确认有本解释第二条至第五条规定情形之一的，赔偿请求人可依法向侵权的人民法院提出赔偿申请，人民法院应当受理。人民法院逾期不作决定的，赔偿请求人可以向其上一级人民法院赔偿委员会申请作出赔偿决定。"},{"i":11,"n":"第十一条","txt":"民事、行政诉讼中司法赔偿的赔偿方式主要为支付赔偿金。包括：支付侵犯人身自由权、生命健康权的赔偿金；财产损坏的，赔偿修复所需费用；财产灭失的，按侵权行为发生时当地市场价格予以赔偿；财产已拍卖的，给付拍卖所得的价款；财产已变卖的，按合法评估机构的估价赔偿；造成其他损害的，赔偿直接损失。"},{"i":12,"n":"第十二条","txt":"国家赔偿法第二十八条第（七）项规定的直接损失包括下列情形："},{"i":13,"n":"第十三条","txt":"违法采取司法拘留措施的，按国家赔偿法第二十六条规定予以赔偿。"},{"i":14,"n":"第十四条","txt":"人民法院赔偿委员会在审理侦查、检察、监狱管理机关及其工作人员违法行使职权侵犯公民财产权造成损害的赔偿案件时，可参照本解释的有关规定办理。"}],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingz22bc9a":[{"i":1,"n":"第一条","txt":"内地人民法院和香港特别行政区法院在具有书面管辖协议的民商事案件中作出的须支付款项的具有执行力的终审判决，当事人可以根据本安排向内地人民法院或者香港特别行政区法院申请认可和执行。"},{"i":2,"n":"第二条","txt":"本安排所称“具有执行力的终审判决”："},{"i":3,"n":"第三条","txt":"本安排所称“书面管辖协议”，是指当事人为解决与特定法律关系有关的已经发生或者可能发生的争议，自本安排生效之日起，以书面形式明确约定内地人民法院或者香港特别行政区法院具有唯一管辖权的协议。"},{"i":4,"n":"第四条","txt":"申请认可和执行符合本安排规定的民商事判决，在内地向被申请人住所地、经常居住地或者财产所在地的中级人民法院提出，在香港特别行政区向香港特别行政区高等法院提出。"},{"i":5,"n":"第五条","txt":"被申请人住所地、经常居住地或者财产所在地在内地不同的中级人民法院辖区的，申请人应当选择向其中一个人民法院提出认可和执行的申请，不得分别向两个或者两个以上人民法院提出申请。"},{"i":6,"n":"第六条","txt":"申请人向有关法院申请认可和执行判决的，应当提交以下文件："},{"i":7,"n":"第七条","txt":"请求认可和执行申请书应当载明下列事项："},{"i":8,"n":"第八条","txt":"申请人申请认可和执行内地人民法院或者香港特别行政区法院判决的程序，依据执行地法律的规定。本安排另有规定的除外。"},{"i":9,"n":"第九条","txt":"对申请认可和执行的判决，原审判决中的债务人提供证据证明有下列情形之一的，受理申请的法院经审查核实，应当裁定不予认可和执行："},{"i":10,"n":"第十条","txt":"对于香港特别行政区法院作出的判决，判决确定的债务人已经提出上诉，或者上诉程序尚未完结的，内地人民法院审查核实后，可以中止认可和执行程序。经上诉，维持全部或者部分原判决的，恢复认可和执行程序；完全改变原判决的，终止认可和执行程序。"},{"i":11,"n":"第十一条","txt":"根据本安排而获认可的判决与执行地法院的判决效力相同。"},{"i":12,"n":"第十二条","txt":"当事人对认可和执行与否的裁定不服的，在内地可以向上一级人民法院申请复议，在香港特别行政区可以根据其法律规定提出上诉。"},{"i":13,"n":"第十三条","txt":"在法院受理当事人申请认可和执行判决期间，当事人依相同事实再行提起诉讼的，法院不予受理。"},{"i":14,"n":"第十四条","txt":"法院受理认可和执行判决的申请之前或者之后，可以按照执行地法律关于财产保全或者禁制资产转移的规定，根据申请人的申请，对被申请人的财产采取保全或强制措施。"},{"i":15,"n":"第十五条","txt":"当事人向有关法院申请执行判决，应当根据执行地有关诉讼收费的法律和规定交纳执行费或者法院费用。"},{"i":16,"n":"第十六条","txt":"内地与香港特别行政区法院相互认可和执行的标的范围，除判决确定的数额外，还包括根据该判决须支付的利息、经法院核定的律师费以及诉讼费，但不包括税收和罚款。"},{"i":17,"n":"第十七条","txt":"内地与香港特别行政区法院自本安排生效之日（含本日）起作出的判决，适用本安排。"},{"i":18,"n":"第十八条","txt":"本安排在执行过程中遇有问题或者需要修改，由最高人民法院和香港特别行政区政府协商解决。"}],"zuigaorenminfayuanguanyupochanqingsuanzuzailvxingz0b8789":[],"zuigaorenminfayuanguanyuqiyehuogerenqianguojiayinh5b732b":[],"zuigaorenminfayuanguanyuqiyekaibandeqitaqiyebeicheb5806d":[],"zuigaorenminfayuanguanyurenminfayuanfaxianyijingsha2d8e8":[],"zuigaorenminfayuanguanyurenminfayuangongkaishenpanaa6a85":[],"zuigaorenminfayuanguanyurenminfayuanshenlilihunanj2439c0":[],"zuigaorenminfayuanguanyurenminfayuanshenlilihunanjbf73fa":[],"zuigaorenminfayuanguanyurenminfayuanshenlilihunanjc13909":[],"zuigaorenminfayuanguanyurenminfayuansifatongjigongb6f04e":[],"zuigaorenminfayuanguanyurenminfayuanyingdangruhereeb3cb3":[],"zuigaorenminfayuanguanyurenminfayuanyingfoushoulicf7717a":[],"zuigaorenminfayuanguanyurenminfayuanzhixingsheding622f87":[{"i":1,"n":"第一条","txt":"对于被执行人所有的已经依法设定抵押的房屋，人民法院可以查封，并可以根据抵押权人的申请，依法拍卖、变卖或者抵债。"},{"i":2,"n":"第二条","txt":"人民法院对已经依法设定抵押的被执行人及其所扶养家属居住的房屋，在裁定拍卖、变卖或者抵债后，应当给予被执行人六个月的宽限期。在此期限内，被执行人应当主动腾空房屋，人民法院不得强制被执行人及其所扶养家属迁出该房屋。"},{"i":3,"n":"第三条","txt":"上述宽限期届满后，被执行人仍未迁出的，人民法院可以作出强制迁出裁定，并按照民事诉讼法第二百二十九条的规定执行。"},{"i":4,"n":"第四条","txt":"申请执行人提供的临时住房，其房屋品质、地段可以不同于被执行人原住房，面积参照建设部、财政部、民政部、国土资源部和国家税务总局联合发布的《城镇最低收入家庭廉租住房管理办法》所规定的人均廉租住房面积标准确定。"},{"i":5,"n":"第五条","txt":"申请执行人提供的临时住房，应当计收租金。租金标准由申请执行人和被执行人双方协商确定；协商不成的，由人民法院参照当地同类房屋租金标准确定，当地无同类房屋租金标准可以参照的，参照当地房屋租赁市场平均租金标准确定。"},{"i":6,"n":"第六条","txt":"被执行人属于低保对象且无法自行解决居住问题的，人民法院不应强制迁出。"},{"i":7,"n":"第七条","txt":"本规定自公布之日起施行。施行前本院已公布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenzhenguanchezhongcaifayi217421":[],"zuigaorenminfayuanguanyurenzhenxuexixuanchuanheguaf539b9":[],"zuigaorenminfayuanguanyuruhechulinongcunwubaoduixic970db":[{"i":1,"n":"第十八条","txt":"五保对象的个人财产，其本人可以继续使用，但是不得自行处分；其需要代管的财产，可以由农村集体经济组织代管。"},{"i":2,"n":"第十九条","txt":"五保对象死亡后，其遗产归所在的农村集体经济组织所有；有五保供养协议的，按照协议处理。"}],"zuigaorenminfayuanguanyuruhelijieguanyushiyongminsda18e6":[],"zuigaorenminfayuanguanyuruhequedingweituodaikuanxi1d97eb":[],"zuigaorenminfayuanguanyuruhequedingzhengquanhuigou4ff955":[],"zuigaorenminfayuanguanyuruheshiyongminfatongzediyic92feb":[],"zuigaorenminfayuanguanyushejidanbaojiufenanjiandeseb1a3d":[],"zuigaorenminfayuanguanyushenjishiwusuozhiyeshenjisf976c5":[],"zuigaorenminfayuanguanyushenlibuzhengdangjingzhengf05700-2":[{"i":1,"n":"第一条","txt":"在中国境内具有一定的市场知名度，为相关公众所知悉的商品，应当认定为反不正当竞争法第五条第（二）项规定的“知名商品”。人民法院认定知名商品，应当考虑该商品的销售时间、销售区域、销售额和销售对象，进行任何宣传的持续时间、程度和地域范围，作为知名商品受保护的情况等因素，进行综合判断。原告应当对其商品的市场知名度负举证责任。"},{"i":2,"n":"第二条","txt":"具有区别商品来源的显著特征的商品的名称、包装、装潢，应当认定为反不正当竞争法第五条第（二）项规定的“特有的名称、包装、装潢”。有下列情形之一的，人民法院不认定为知名商品特有的名称、包装、装潢："},{"i":3,"n":"第三条","txt":"由经营者营业场所的装饰、营业用具的式样、营业人员的服饰等构成的具有独特风格的整体营业形象，可以认定为反不正当竞争法第五条第（二）项规定的“装潢”。"},{"i":4,"n":"第四条","txt":"足以使相关公众对商品的来源产生误认，包括误认为与知名商品的经营者具有许可使用、关联企业关系等特定联系的，应当认定为反不正当竞争法第五条第（二）项规定的“造成和他人的知名商品相混淆，使购买者误认为是该知名商品”。"},{"i":5,"n":"第五条","txt":"商品的名称、包装、装潢属于商标法第十条第一款规定的不得作为商标使用的标志，当事人请求依照反不正当竞争法第五条第（二）项规定予以保护的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"企业登记主管机关依法登记注册的企业名称，以及在中国境内进行商业使用的外国（地区）企业名称，应当认定为反不正当竞争法第五条第（三）项规定的“企业名称”。具有一定的市场知名度、为相关公众所知悉的企业名称中的字号，可以认定为反不正当竞争法第五条第（三）项规定的“企业名称”。"},{"i":7,"n":"第七条","txt":"在中国境内进行商业使用，包括将知名商品特有的名称、包装、装潢或者企业名称、姓名用于商品、商品包装以及商品交易文书上，或者用于广告宣传、展览以及其他商业活动中，应当认定为反不正当竞争法第五条第（二）项、第（三）项规定的“使用”。"},{"i":8,"n":"第八条","txt":"经营者具有下列行为之一，足以造成相关公众误解的，可以认定为反不正当竞争法第九条第一款规定的引人误解的虚假宣传行为："},{"i":9,"n":"第九条","txt":"有关信息不为其所属领域的相关人员普遍知悉和容易获得，应当认定为反不正当竞争法第十条第三款规定的“不为公众所知悉”。"},{"i":10,"n":"第十条","txt":"有关信息具有现实的或者潜在的商业价值，能为权利人带来竞争优势的，应当认定为反不正当竞争法第十条第三款规定的“能为权利人带来经济利益、具有实用性”。"},{"i":11,"n":"第十一条","txt":"权利人为防止信息泄漏所采取的与其商业价值等具体情况相适应的合理保护措施，应当认定为反不正当竞争法第十条第三款规定的“保密措施”。"},{"i":12,"n":"第十二条","txt":"通过自行开发研制或者反向工程等方式获得的商业秘密，不认定为反不正当竞争法第十条第（一）、（二）项规定的侵犯商业秘密行为。"},{"i":13,"n":"第十三条","txt":"商业秘密中的客户名单，一般是指客户的名称、地址、联系方式以及交易的习惯、意向、内容等构成的区别于相关公知信息的特殊客户信息，包括汇集众多客户的客户名册，以及保持长期稳定交易关系的特定客户。"},{"i":14,"n":"第十四条","txt":"当事人指称他人侵犯其商业秘密的，应当对其拥有的商业秘密符合法定条件、对方当事人的信息与其商业秘密相同或者实质相同以及对方当事人采取不正当手段的事实负举证责任。其中，商业秘密符合法定条件的证据，包括商业秘密的载体、具体内容、商业价值和对该项商业秘密所采取的具体保密措施等。"},{"i":15,"n":"第十五条","txt":"对于侵犯商业秘密行为，商业秘密独占使用许可合同的被许可人提起诉讼的，人民法院应当依法受理。"},{"i":16,"n":"第十六条","txt":"人民法院对于侵犯商业秘密行为判决停止侵害的民事责任时，停止侵害的时间一般持续到该项商业秘密已为公众知悉时为止。"},{"i":17,"n":"第十七条","txt":"确定反不正当竞争法第十条规定的侵犯商业秘密行为的损害赔偿额，可以参照确定侵犯专利权的损害赔偿额的方法进行；确定反不正当竞争法第五条、第九条、第十四条规定的不正当竞争行为的损害赔偿额，可以参照确定侵犯注册商标专用权的损害赔偿额的方法进行。"},{"i":18,"n":"第十八条","txt":"反不正当竞争法第五条、第九条、第十条、第十四条规定的不正当竞争民事第一审案件，一般由中级人民法院管辖。"},{"i":19,"n":"第十九条","txt":"本解释自二〇〇七年二月一日起施行。"}],"zuigaorenminfayuanguanyushenlibuzhengdangjingzhengf05700":[{"i":1,"n":"第一条","txt":"在中国境内具有一定的市场知名度，为相关公众所知悉的商品，应当认定为反不正当竞争法第五条第（二）项规定的“知名商品”。人民法院认定知名商品，应当考虑该商品的销售时间、销售区域、销售额和销售对象，进行任何宣传的持续时间、程度和地域范围，作为知名商品受保护的情况等因素，进行综合判断。原告应当对其商品的市场知名度负举证责任。"},{"i":2,"n":"第二条","txt":"具有区别商品来源的显著特征的商品的名称、包装、装潢，应当认定为反不正当竞争法第五条第（二）项规定的“特有的名称、包装、装潢”。有下列情形之一的，人民法院不认定为知名商品特有的名称、包装、装潢："},{"i":3,"n":"第三条","txt":"由经营者营业场所的装饰、营业用具的式样、营业人员的服饰等构成的具有独特风格的整体营业形象，可以认定为反不正当竞争法第五条第（二）项规定的“装潢”。"},{"i":4,"n":"第四条","txt":"足以使相关公众对商品的来源产生误认，包括误认为与知名商品的经营者具有许可使用、关联企业关系等特定联系的，应当认定为反不正当竞争法第五条第（二）项规定的“造成和他人的知名商品相混淆，使购买者误认为是该知名商品”。"},{"i":5,"n":"第五条","txt":"商品的名称、包装、装潢属于商标法第十条第一款规定的不得作为商标使用的标志，当事人请求依照反不正当竞争法第五条第（二）项规定予以保护的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"企业登记主管机关依法登记注册的企业名称，以及在中国境内进行商业使用的外国（地区）企业名称，应当认定为反不正当竞争法第五条第（三）项规定的“企业名称”。具有一定的市场知名度、为相关公众所知悉的企业名称中的字号，可以认定为反不正当竞争法第五条第（三）项规定的“企业名称”。"},{"i":7,"n":"第七条","txt":"在中国境内进行商业使用，包括将知名商品特有的名称、包装、装潢或者企业名称、姓名用于商品、商品包装以及商品交易文书上，或者用于广告宣传、展览以及其他商业活动中，应当认定为反不正当竞争法第五条第（二）项、第（三）项规定的“使用”。"},{"i":8,"n":"第八条","txt":"经营者具有下列行为之一，足以造成相关公众误解的，可以认定为反不正当竞争法第九条第一款规定的引人误解的虚假宣传行为："},{"i":9,"n":"第九条","txt":"有关信息不为其所属领域的相关人员普遍知悉和容易获得，应当认定为反不正当竞争法第十条第三款规定的“不为公众所知悉”。"},{"i":10,"n":"第十条","txt":"有关信息具有现实的或者潜在的商业价值，能为权利人带来竞争优势的，应当认定为反不正当竞争法第十条第三款规定的“能为权利人带来经济利益、具有实用性”。"},{"i":11,"n":"第十一条","txt":"权利人为防止信息泄露所采取的与其商业价值等具体情况相适应的合理保护措施，应当认定为反不正当竞争法第十条第三款规定的“保密措施”。"},{"i":12,"n":"第十二条","txt":"通过自行开发研制或者反向工程等方式获得的商业秘密，不认定为反不正当竞争法第十条第（一）、（二）项规定的侵犯商业秘密行为。"},{"i":13,"n":"第十三条","txt":"商业秘密中的客户名单，一般是指客户的名称、地址、联系方式以及交易的习惯、意向、内容等构成的区别于相关公知信息的特殊客户信息，包括汇集众多客户的客户名册，以及保持长期稳定交易关系的特定客户。"},{"i":14,"n":"第十四条","txt":"当事人指称他人侵犯其商业秘密的，应当对其拥有的商业秘密符合法定条件、对方当事人的信息与其商业秘密相同或者实质相同以及对方当事人采取不正当手段的事实负举证责任。其中，商业秘密符合法定条件的证据，包括商业秘密的载体、具体内容、商业价值和对该项商业秘密所采取的具体保密措施等。"},{"i":15,"n":"第十五条","txt":"对于侵犯商业秘密行为，商业秘密独占使用许可合同的被许可人提起诉讼的，人民法院应当依法受理。"},{"i":16,"n":"第十六条","txt":"人民法院对于侵犯商业秘密行为判决停止侵害的民事责任时，停止侵害的时间一般持续到该项商业秘密已为公众知悉时为止。"},{"i":17,"n":"第十七条","txt":"确定反不正当竞争法第十条规定的侵犯商业秘密行为的损害赔偿额，可以参照确定侵犯专利权的损害赔偿额的方法进行；确定反不正当竞争法第五条、第九条、第十四条规定的不正当竞争行为的损害赔偿额，可以参照确定侵犯注册商标专用权的损害赔偿额的方法进行。"},{"i":18,"n":"第十八条","txt":"反不正当竞争法第五条、第九条、第十条、第十四条规定的不正当竞争民事第一审案件，一般由中级人民法院管辖。"},{"i":19,"n":"第十九条","txt":"本解释自2007年2月1日起施行。"}],"zuigaorenminfayuanguanyushenlichukoutuishuituoguan0075b3":[{"i":1,"n":"第一条","txt":"本规定适用于审理、执行涉及出口退税专用账户质押贷款的案件。"},{"i":2,"n":"第二条","txt":"以出口退税专用账户质押方式贷款的，应当签订书面质押贷款合同。质押贷款合同自贷款银行实际托管借款人出口退税专用账户时生效。"},{"i":3,"n":"第三条","txt":"出口退税专用账户质押贷款银行，对质押账户内的退税款享有优先受偿权。"},{"i":4,"n":"第四条","txt":"人民法院审理和执行案件时，不得对已设质的出口退税专用账户内的款项采取财产保全措施或者执行措施。"},{"i":5,"n":"第五条","txt":"借款人进入破产程序时，贷款银行对已经设质的出口退税专用账户内的款项享有优先受偿权，但应以被担保债权尚未受偿的数额为限。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，不受本《规定》第三、四、五条规定的限制，人民法院可以采取财产保全或者执行措施："},{"i":7,"n":"第七条","txt":"本规定自2004年12月7日起施行。"}],"zuigaorenminfayuanguanyushenlidiyishenzhuanlianjia07a34a":[],"zuigaorenminfayuanguanyushenlihehuoxinglianyingtih80286f":[],"zuigaorenminfayuanguanyushenlihuanjingqinquanzeren4650a5-2":[{"i":1,"n":"第一条","txt":"因污染环境、破坏生态造成他人损害，不论侵权人有无过错，侵权人应当承担侵权责任。"},{"i":2,"n":"第二条","txt":"两个以上侵权人共同实施污染环境、破坏生态行为造成损害，被侵权人根据民法典第一千一百六十八条规定请求侵权人承担连带责任的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"两个以上侵权人分别实施污染环境、破坏生态行为造成同一损害，每一个侵权人的污染环境、破坏生态行为都足以造成全部损害，被侵权人根据民法典第一千一百七十一条规定请求侵权人承担连带责任的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"两个以上侵权人污染环境、破坏生态，对侵权人承担责任的大小，人民法院应当根据污染物的种类、浓度、排放量、危害性，有无排污许可证、是否超过污染物排放标准、是否超过重点污染物排放总量控制指标，破坏生态的方式、范围、程度，以及行为对损害后果所起的作用等因素确定。"},{"i":5,"n":"第五条","txt":"被侵权人根据民法典第一千二百三十三条规定分别或者同时起诉侵权人、第三人的，人民法院应予受理。"},{"i":6,"n":"第六条","txt":"被侵权人根据民法典第七编第七章的规定请求赔偿的，应当提供证明以下事实的证据材料："},{"i":7,"n":"第七条","txt":"侵权人举证证明下列情形之一的，人民法院应当认定其污染环境、破坏生态行为与损害之间不存在因果关系："},{"i":8,"n":"第八条","txt":"对查明环境污染、生态破坏案件事实的专门性问题，可以委托具备相关资格的司法鉴定机构出具鉴定意见或者由负有环境资源保护监督管理职责的部门推荐的机构出具检验报告、检测报告、评估报告或者监测数据。"},{"i":9,"n":"第九条","txt":"当事人申请通知一至两名具有专门知识的人出庭，就鉴定意见或者污染物认定、损害结果、因果关系、修复措施等专业问题提出意见的，人民法院可以准许。当事人未申请，人民法院认为有必要的，可以进行释明。"},{"i":10,"n":"第十条","txt":"负有环境资源保护监督管理职责的部门或者其委托的机构出具的环境污染、生态破坏事件调查报告、检验报告、检测报告、评估报告或者监测数据等，经当事人质证，可以作为认定案件事实的根据。"},{"i":11,"n":"第十一条","txt":"对于突发性或者持续时间较短的环境污染、生态破坏行为，在证据可能灭失或者以后难以取得的情况下，当事人或者利害关系人根据民事诉讼法第八十一条规定申请证据保全的，人民法院应当准许。"},{"i":12,"n":"第十二条","txt":"被申请人具有环境保护法第六十三条规定情形之一，当事人或者利害关系人根据民事诉讼法第一百条或者第一百零一条规定申请保全的，人民法院可以裁定责令被申请人立即停止侵害行为或者采取防治措施。"},{"i":13,"n":"第十三条","txt":"人民法院应当根据被侵权人的诉讼请求以及具体案情，合理判定侵权人承担停止侵害、排除妨碍、消除危险、修复生态环境、赔礼道歉、赔偿损失等民事责任。"},{"i":14,"n":"第十四条","txt":"被侵权人请求修复生态环境的，人民法院可以依法裁判侵权人承担环境修复责任，并同时确定其不履行环境修复义务时应当承担的环境修复费用。"},{"i":15,"n":"第十五条","txt":"被侵权人起诉请求侵权人赔偿因污染环境、破坏生态造成的财产损失、人身损害以及为防止损害发生和扩大、清除污染、修复生态环境而采取必要措施所支出的合理费用的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"下列情形之一，应当认定为环境保护法第六十五条规定的弄虚作假："},{"i":17,"n":"第十七条","txt":"本解释适用于审理因污染环境、破坏生态造成损害的民事案件，但法律和司法解释对环境民事公益诉讼案件另有规定的除外。"},{"i":18,"n":"第十八条","txt":"本解释施行后，人民法院尚未审结的一审、二审案件适用本解释规定。本解释施行前已经作出生效裁判的案件，本解释施行后依法再审的，不适用本解释。"}],"zuigaorenminfayuanguanyushenlihuanjingqinquanzeren4650a5":[{"i":1,"n":"第一条","txt":"因污染环境造成损害，不论污染者有无过错，污染者应当承担侵权责任。污染者以排污符合国家或者地方污染物排放标准为由主张不承担责任的，人民法院不予支持。"},{"i":2,"n":"第二条","txt":"两个以上污染者共同实施污染行为造成损害，被侵权人根据侵权责任法第八条规定请求污染者承担连带责任的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"两个以上污染者分别实施污染行为造成同一损害，每一个污染者的污染行为都足以造成全部损害，被侵权人根据侵权责任法第十一条规定请求污染者承担连带责任的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"两个以上污染者污染环境，对污染者承担责任的大小，人民法院应当根据污染物的种类、排放量、危害性以及有无排污许可证、是否超过污染物排放标准、是否超过重点污染物排放总量控制指标等因素确定。"},{"i":5,"n":"第五条","txt":"被侵权人根据侵权责任法第六十八条规定分别或者同时起诉污染者、第三人的，人民法院应予受理。"},{"i":6,"n":"第六条","txt":"被侵权人根据侵权责任法第六十五条规定请求赔偿的，应当提供证明以下事实的证据材料："},{"i":7,"n":"第七条","txt":"污染者举证证明下列情形之一的，人民法院应当认定其污染行为与损害之间不存在因果关系："},{"i":8,"n":"第八条","txt":"对查明环境污染案件事实的专门性问题，可以委托具备相关资格的司法鉴定机构出具鉴定意见或者由国务院环境保护主管部门推荐的机构出具检验报告、检测报告、评估报告或者监测数据。"},{"i":9,"n":"第九条","txt":"当事人申请通知一至两名具有专门知识的人出庭，就鉴定意见或者污染物认定、损害结果、因果关系等专业问题提出意见的，人民法院可以准许。当事人未申请，人民法院认为有必要的，可以进行释明。"},{"i":10,"n":"第十条","txt":"负有环境保护监督管理职责的部门或者其委托的机构出具的环境污染事件调查报告、检验报告、检测报告、评估报告或者监测数据等，经当事人质证，可以作为认定案件事实的根据。"},{"i":11,"n":"第十一条","txt":"对于突发性或者持续时间较短的环境污染行为，在证据可能灭失或者以后难以取得的情况下，当事人或者利害关系人根据民事诉讼法第八十一条规定申请证据保全的，人民法院应当准许。"},{"i":12,"n":"第十二条","txt":"被申请人具有环境保护法第六十三条规定情形之一，当事人或者利害关系人根据民事诉讼法第一百条或者第一百零一条规定申请保全的，人民法院可以裁定责令被申请人立即停止侵害行为或者采取污染防治措施。"},{"i":13,"n":"第十三条","txt":"人民法院应当根据被侵权人的诉讼请求以及具体案情，合理判定污染者承担停止侵害、排除妨碍、消除危险、恢复原状、赔礼道歉、赔偿损失等民事责任。"},{"i":14,"n":"第十四条","txt":"被侵权人请求恢复原状的，人民法院可以依法裁判污染者承担环境修复责任，并同时确定被告不履行环境修复义务时应当承担的环境修复费用。"},{"i":15,"n":"第十五条","txt":"被侵权人起诉请求污染者赔偿因污染造成的财产损失、人身损害以及为防止污染扩大、消除污染而采取必要措施所支出的合理费用的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"下列情形之一，应当认定为环境保护法第六十五条规定的弄虚作假："},{"i":17,"n":"第十七条","txt":"被侵权人提起诉讼，请求污染者停止侵害、排除妨碍、消除危险的，不受环境保护法第六十六条规定的时效期间的限制。"},{"i":18,"n":"第十八条","txt":"本解释适用于审理因污染环境、破坏生态造成损害的民事案件，但法律和司法解释对环境民事公益诉讼案件另有规定的除外。"},{"i":19,"n":"第十九条","txt":"本解释施行后，人民法院尚未审结的一审、二审案件适用本解释规定。本解释施行前已经作出生效裁判的案件，本解释施行后依法再审的，不适用本解释。"}],"zuigaorenminfayuanguanyushenlijianshegongchengshig64bfeb":[{"i":1,"n":"第一条","txt":"招标人和中标人另行签订的建设工程施工合同约定的工程范围、建设工期、工程质量、工程价款等实质性内容，与中标合同不一致，一方当事人请求按照中标合同确定权利义务的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"当事人以发包人未取得建设工程规划许可证等规划审批手续为由，请求确认建设工程施工合同无效的，人民法院应予支持，但发包人在起诉前取得建设工程规划许可证等规划审批手续的除外。"},{"i":3,"n":"第三条","txt":"建设工程施工合同无效，一方当事人请求对方赔偿损失的，应当就对方过错、损失大小、过错与损失之间的因果关系承担举证责任。"},{"i":4,"n":"第四条","txt":"缺乏资质的单位或者个人借用有资质的建筑施工企业名义签订建设工程施工合同，发包人请求出借方与借用方对建设工程质量不合格等因出借资质造成的损失承担连带赔偿责任的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"当事人对建设工程开工日期有争议的，人民法院应当分别按照以下情形予以认定："},{"i":6,"n":"第六条","txt":"当事人约定顺延工期应当经发包人或者监理人签证等方式确认，承包人虽未取得工期顺延的确认，但能够证明在合同约定的期限内向发包人或者监理人申请过工期顺延且顺延事由符合合同约定，承包人以此为由主张工期顺延的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"发包人在承包人提起的建设工程施工合同纠纷案件中，以建设工程质量不符合合同约定或者法律规定为由，就承包人支付违约金或者赔偿修理、返工、改建的合理费用等损失提出反诉的，人民法院可以合并审理。"},{"i":8,"n":"第八条","txt":"有下列情形之一，承包人请求发包人返还工程质量保证金的，人民法院应予支持："},{"i":9,"n":"第九条","txt":"发包人将依法不属于必须招标的建设工程进行招标后，与承包人另行订立的建设工程施工合同背离中标合同的实质性内容，当事人请求以中标合同作为结算建设工程价款依据的，人民法院应予支持，但发包人与承包人因客观情况发生了在招标投标时难以预见的变化而另行订立建设工程施工合同的除外。"},{"i":10,"n":"第十条","txt":"当事人签订的建设工程施工合同与招标文件、投标文件、中标通知书载明的工程范围、建设工期、工程质量、工程价款不一致，一方当事人请求将招标文件、投标文件、中标通知书作为结算工程价款的依据的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"当事人就同一建设工程订立的数份建设工程施工合同均无效，但建设工程质量合格，一方当事人请求参照实际履行的合同结算建设工程价款的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"当事人在诉讼前已经对建设工程价款结算达成协议，诉讼中一方当事人申请对工程造价进行鉴定的，人民法院不予准许。"},{"i":13,"n":"第十三条","txt":"当事人在诉讼前共同委托有关机构、人员对建设工程造价出具咨询意见，诉讼中一方当事人不认可该咨询意见申请鉴定的，人民法院应予准许，但双方当事人明确表示受该咨询意见约束的除外。"},{"i":14,"n":"第十四条","txt":"当事人对工程造价、质量、修复费用等专门性问题有争议，人民法院认为需要鉴定的，应当向负有举证责任的当事人释明。当事人经释明未申请鉴定，虽申请鉴定但未支付鉴定费用或者拒不提供相关材料的，应当承担举证不能的法律后果。"},{"i":15,"n":"第十五条","txt":"人民法院准许当事人的鉴定申请后，应当根据当事人申请及查明案件事实的需要，确定委托鉴定的事项、范围、鉴定期限等，并组织双方当事人对争议的鉴定材料进行质证。"},{"i":16,"n":"第十六条","txt":"人民法院应当组织当事人对鉴定意见进行质证。鉴定人将当事人有争议且未经质证的材料作为鉴定依据的，人民法院应当组织当事人就该部分材料进行质证。经质证认为不能作为鉴定依据的，根据该材料作出的鉴定意见不得作为认定案件事实的依据。"},{"i":17,"n":"第十七条","txt":"与发包人订立建设工程施工合同的承包人，根据合同法第二百八十六条规定请求其承建工程的价款就工程折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"装饰装修工程的承包人，请求装饰装修工程价款就该装饰装修工程折价或者拍卖的价款优先受偿的，人民法院应予支持，但装饰装修工程的发包人不是该建筑物的所有权人的除外。"},{"i":19,"n":"第十九条","txt":"建设工程质量合格，承包人请求其承建工程的价款就工程折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":20,"n":"第二十条","txt":"未竣工的建设工程质量合格，承包人请求其承建工程的价款就其承建工程部分折价或者拍卖的价款优先受偿的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"承包人建设工程价款优先受偿的范围依照国务院有关行政主管部门关于建设工程价款范围的规定确定。"},{"i":22,"n":"第二十二条","txt":"承包人行使建设工程价款优先受偿权的期限为六个月，自发包人应当给付建设工程价款之日起算。"},{"i":23,"n":"第二十三条","txt":"发包人与承包人约定放弃或者限制建设工程价款优先受偿权，损害建筑工人利益，发包人根据该约定主张承包人不享有建设工程价款优先受偿权的，人民法院不予支持。"},{"i":24,"n":"第二十四条","txt":"实际施工人以发包人为被告主张权利的，人民法院应当追加转包人或者违法分包人为本案第三人，在查明发包人欠付转包人或者违法分包人建设工程价款的数额后，判决发包人在欠付建设工程价款范围内对实际施工人承担责任。"},{"i":25,"n":"第二十五条","txt":"实际施工人根据合同法第七十三条规定，以转包人或者违法分包人怠于向发包人行使到期债权，对其造成损害为由，提起代位权诉讼的，人民法院应予支持。"},{"i":26,"n":"第二十六条","txt":"本解释自2019年2月1日起施行。"}],"zuigaorenminfayuanguanyushenlijianshegongchengshigeeaefb":[{"i":1,"n":"第一条","txt":"建设工程施工合同具有下列情形之一的，应当根据合同法第五十二条第（五）项的规定，认定无效："},{"i":2,"n":"第二条","txt":"建设工程施工合同无效，但建设工程经竣工验收合格，承包人请求参照合同约定支付工程价款的，应予支持。"},{"i":3,"n":"第三条","txt":"建设工程施工合同无效，且建设工程经竣工验收不合格的，按照以下情形分别处理："},{"i":4,"n":"第四条","txt":"承包人非法转包、违法分包建设工程或者没有资质的实际施工人借用有资质的建筑施工企业名义与他人签订建设工程施工合同的行为无效。人民法院可以根据民法通则第一百三十四条规定，收缴当事人已经取得的非法所得。"},{"i":5,"n":"第五条","txt":"承包人超越资质等级许可的业务范围签订建设工程施工合同，在建设工程竣工前取得相应资质等级，当事人请求按照无效合同处理的，不予支持。"},{"i":6,"n":"第六条","txt":"当事人对垫资和垫资利息有约定，承包人请求按照约定返还垫资及其利息的，应予支持，但是约定的利息计算标准高于中国人民银行发布的同期同类贷款利率的部分除外。"},{"i":7,"n":"第七条","txt":"具有劳务作业法定资质的承包人与总承包人、分包人签订的劳务分包合同，当事人以转包建设工程违反法律规定为由请求确认无效的，不予支持。"},{"i":8,"n":"第八条","txt":"承包人具有下列情形之一，发包人请求解除建设工程施工合同的，应予支持："},{"i":9,"n":"第九条","txt":"发包人具有下列情形之一，致使承包人无法施工，且在催告的合理期限内仍未履行相应义务，承包人请求解除建设工程施工合同的，应予支持："},{"i":10,"n":"第十条","txt":"建设工程施工合同解除后，已经完成的建设工程质量合格的，发包人应当按照约定支付相应的工程价款；已经完成的建设工程质量不合格的，参照本解释第三条规定处理。"},{"i":11,"n":"第十一条","txt":"因承包人的过错造成建设工程质量不符合约定，承包人拒绝修理、返工或者改建，发包人请求减少支付工程价款的，应予支持。"},{"i":12,"n":"第十二条","txt":"发包人具有下列情形之一，造成建设工程质量缺陷，应当承担过错责任："},{"i":13,"n":"第十三条","txt":"建设工程未经竣工验收，发包人擅自使用后，又以使用部分质量不符合约定为由主张权利的，不予支持；但是承包人应当在建设工程的合理使用寿命内对地基基础工程和主体结构质量承担民事责任。"},{"i":14,"n":"第十四条","txt":"当事人对建设工程实际竣工日期有争议的，按照以下情形分别处理："},{"i":15,"n":"第十五条","txt":"建设工程竣工前，当事人对工程质量发生争议，工程质量经鉴定合格的，鉴定期间为顺延工期期间。"},{"i":16,"n":"第十六条","txt":"当事人对建设工程的计价标准或者计价方法有约定的，按照约定结算工程价款。"},{"i":17,"n":"第十七条","txt":"当事人对欠付工程价款利息计付标准有约定的，按照约定处理；没有约定的，按照中国人民银行发布的同期同类贷款利率计息。"},{"i":18,"n":"第十八条","txt":"利息从应付工程价款之日计付。当事人对付款时间没有约定或者约定不明的，下列时间视为应付款时间："},{"i":19,"n":"第十九条","txt":"当事人对工程量有争议的，按照施工过程中形成的签证等书面文件确认。承包人能够证明发包人同意其施工，但未能提供签证文件证明工程量发生的，可以按照当事人提供的其他证据确认实际发生的工程量。"},{"i":20,"n":"第二十条","txt":"当事人约定，发包人收到竣工结算文件后，在约定期限内不予答复，视为认可竣工结算文件的，按照约定处理。承包人请求按照竣工结算文件结算工程价款的，应予支持。"},{"i":21,"n":"第二十一条","txt":"当事人就同一建设工程另行订立的建设工程施工合同与经过备案的中标合同实质性内容不一致的，应当以备案的中标合同作为结算工程价款的根据。"},{"i":22,"n":"第二十二条","txt":"当事人约定按照固定价结算工程价款，一方当事人请求对建设工程造价进行鉴定的，不予支持。"},{"i":23,"n":"第二十三条","txt":"当事人对部分案件事实有争议的，仅对有争议的事实进行鉴定，但争议事实范围不能确定，或者双方当事人请求对全部事实鉴定的除外。"},{"i":24,"n":"第二十四条","txt":"建设工程施工合同纠纷以施工行为地为合同履行地。"},{"i":25,"n":"第二十五条","txt":"因建设工程质量发生争议的，发包人可以以总承包人、分包人和实际施工人为共同被告提起诉讼。"},{"i":26,"n":"第二十六条","txt":"实际施工人以转包人、违法分包人为被告起诉的，人民法院应当依法受理。"},{"i":27,"n":"第二十七条","txt":"因保修人未及时履行保修义务，导致建筑物毁损或者造成人身、财产损害的，保修人应当承担赔偿责任。"},{"i":28,"n":"第二十八条","txt":"本解释自2005年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlijingjihetongjiufenana99804":[],"zuigaorenminfayuanguanyushenlijubuzhixingpanjuecai01843e-2":[{"i":1,"n":"第一条","txt":"被执行人、协助执行义务人、担保人等负有执行义务的人对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，应当依照刑法第三百一十三条的规定，以拒不执行判决、裁定罪处罚。"},{"i":2,"n":"第二条","txt":"负有执行义务的人有能力执行而实施下列行为之一的，应当认定为全国人民代表大会常务委员会关于刑法第三百一十三条的解释中规定的“其他有能力执行而拒不执行，情节严重的情形”："},{"i":3,"n":"第三条","txt":"申请执行人有证据证明同时具有下列情形，人民法院认为符合刑事诉讼法第二百一十条第三项规定的，以自诉案件立案审理："},{"i":4,"n":"第四条","txt":"本解释第三条规定的自诉案件，依照刑事诉讼法第二百一十二条的规定，自诉人在宣告判决前，可以同被告人自行和解或者撤回自诉。"},{"i":5,"n":"第五条","txt":"拒不执行判决、裁定刑事案件，一般由执行法院所在地人民法院管辖。"},{"i":6,"n":"第六条","txt":"拒不执行判决、裁定的被告人在一审宣告判决前，履行全部或部分执行义务的，可以酌情从宽处罚。"},{"i":7,"n":"第七条","txt":"拒不执行支付赡养费、扶养费、抚育费、抚恤金、医疗费用、劳动报酬等判决、裁定的，可以酌情从重处罚。"},{"i":8,"n":"第八条","txt":"本解释自发布之日起施行。此前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlijubuzhixingpanjuecai01843e":[{"i":1,"n":"第一条","txt":"被执行人、协助执行义务人、担保人等负有执行义务的人对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，应当依照刑法第三百一十三条的规定，以拒不执行判决、裁定罪处罚。"},{"i":2,"n":"第二条","txt":"负有执行义务的人有能力执行而实施下列行为之一的，应当认定为全国人民代表大会常务委员会关于刑法第三百一十三条的解释中规定的“其他有能力执行而拒不执行，情节严重的情形”："},{"i":3,"n":"第三条","txt":"申请执行人有证据证明同时具有下列情形，人民法院认为符合刑事诉讼法第二百零四条第三项规定的，以自诉案件立案审理："},{"i":4,"n":"第四条","txt":"本解释第三条规定的自诉案件，依照刑事诉讼法第二百零六条的规定，自诉人在宣告判决前，可以同被告人自行和解或者撤回自诉。"},{"i":5,"n":"第五条","txt":"拒不执行判决、裁定刑事案件，一般由执行法院所在地人民法院管辖。"},{"i":6,"n":"第六条","txt":"拒不执行判决、裁定的被告人在一审宣告判决前，履行全部或部分执行义务的，可以酌情从宽处罚。"},{"i":7,"n":"第七条","txt":"拒不执行支付赡养费、扶养费、抚育费、抚恤金、医疗费用、劳动报酬等判决、裁定的，可以酌情从重处罚。"},{"i":8,"n":"第八条","txt":"本解释自发布之日起施行。此前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlikuangyequanjiufenanj8f1e5f-2":[{"i":1,"n":"第一条","txt":"人民法院审理探矿权、采矿权等矿业权纠纷案件，应当依法保护矿业权流转，维护市场秩序和交易安全，保障矿产资源合理开发利用，促进资源节约与环境保护。"},{"i":2,"n":"第二条","txt":"县级以上人民政府自然资源主管部门作为出让人与受让人签订的矿业权出让合同，除法律、行政法规另有规定的情形外，当事人请求确认自依法成立之日起生效的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"受让人请求自矿产资源勘查许可证、采矿许可证载明的有效期起始日确认其探矿权、采矿权的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"出让人未按照出让合同的约定移交勘查作业区或者矿区、颁发矿产资源勘查许可证或者采矿许可证，受让人请求解除出让合同的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"未取得矿产资源勘查许可证、采矿许可证，签订合同将矿产资源交由他人勘查开采的，人民法院应依法认定合同无效。"},{"i":6,"n":"第六条","txt":"矿业权转让合同自依法成立之日起具有法律约束力。矿业权转让申请未经自然资源主管部门批准，受让人请求转让人办理矿业权变更登记手续的，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"矿业权转让合同依法成立后，在不具有法定无效情形下，受让人请求转让人履行报批义务或者转让人请求受让人履行协助报批义务的，人民法院应予支持，但法律上或者事实上不具备履行条件的除外。"},{"i":8,"n":"第八条","txt":"矿业权转让合同依法成立后，转让人无正当理由拒不履行报批义务，受让人请求解除合同、返还已付转让款及利息，并由转让人承担违约责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"矿业权转让合同约定受让人支付全部或者部分转让款后办理报批手续，转让人在办理报批手续前请求受让人先履行付款义务的，人民法院应予支持，但受让人有确切证据证明存在转让人将同一矿业权转让给第三人、矿业权人将被兼并重组等符合民法典第五百二十七条规定情形的除外。"},{"i":10,"n":"第十条","txt":"自然资源主管部门不予批准矿业权转让申请致使矿业权转让合同被解除，受让人请求返还已付转让款及利息，采矿权人请求受让人返还获得的矿产品及收益，或者探矿权人请求受让人返还勘查资料和勘查中回收的矿产品及收益的，人民法院应予支持，但受让人可请求扣除相关的成本费用。"},{"i":11,"n":"第十一条","txt":"矿业权转让合同依法成立后、自然资源主管部门批准前，矿业权人又将矿业权转让给第三人并经自然资源主管部门批准、登记，受让人请求解除转让合同、返还已付转让款及利息，并由矿业权人承担违约责任的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"当事人请求确认矿业权租赁、承包合同自依法成立之日起生效的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"矿业权人与他人合作进行矿产资源勘查开采所签订的合同，当事人请求确认自依法成立之日起生效的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"矿业权人为担保自己或者他人债务的履行，将矿业权抵押给债权人的，抵押合同自依法成立之日起生效，但法律、行政法规规定不得抵押的除外。"},{"i":15,"n":"第十五条","txt":"当事人请求确认矿业权之抵押权自依法登记时设立的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人依据民事诉讼法第一百九十六条、第一百九十七条规定申请实现抵押权的，人民法院可以拍卖、变卖矿业权或者裁定以矿业权抵债，但矿业权竞买人、受让人应具备相应的资质条件。"},{"i":17,"n":"第十七条","txt":"矿业权抵押期间因抵押人被兼并重组或者矿床被压覆等原因导致矿业权全部或者部分灭失，抵押权人请求就抵押人因此获得的保险金、赔偿金或者补偿金等款项优先受偿或者将该款项予以提存的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"当事人约定在自然保护区、风景名胜区、重点生态功能区、生态环境敏感区和脆弱区等区域内勘查开采矿产资源，违反法律、行政法规的强制性规定或者损害环境公共利益的，人民法院应依法认定合同无效。"},{"i":19,"n":"第十九条","txt":"因越界勘查开采矿产资源引发的侵权责任纠纷，涉及自然资源主管部门批准的勘查开采范围重复或者界限不清的，人民法院应告知当事人先向自然资源主管部门申请解决。"},{"i":20,"n":"第二十条","txt":"因他人越界勘查开采矿产资源，矿业权人请求侵权人承担停止侵害、排除妨碍、返还财产、赔偿损失等侵权责任的，人民法院应予支持，但探矿权人请求侵权人返还越界开采的矿产品及收益的除外。"},{"i":21,"n":"第二十一条","txt":"勘查开采矿产资源造成环境污染，或者导致地质灾害、植被毁损等生态破坏，国家规定的机关或者法律规定的组织提起环境公益诉讼的，人民法院应依法予以受理。"},{"i":22,"n":"第二十二条","txt":"人民法院在审理案件中，发现无证勘查开采，勘查资质、地质资料造假，或者勘查开采未履行生态环境修复义务等违法情形的，可以向有关行政主管部门提出司法建议，由其依法处理；涉嫌犯罪的，依法移送侦查机关处理。"},{"i":23,"n":"第二十三条","txt":"本解释施行后，人民法院尚未审结的一审、二审案件适用本解释规定。本解释施行前已经作出生效裁判的案件，本解释施行后依法再审的，不适用本解释。"}],"zuigaorenminfayuanguanyushenlikuangyequanjiufenanj8f1e5f":[{"i":1,"n":"第一条","txt":"人民法院审理探矿权、采矿权等矿业权纠纷案件，应当依法保护矿业权流转，维护市场秩序和交易安全，保障矿产资源合理开发利用，促进资源节约与环境保护。"},{"i":2,"n":"第二条","txt":"县级以上人民政府国土资源主管部门作为出让人与受让人签订的矿业权出让合同，除法律、行政法规另有规定的情形外，当事人请求确认自依法成立之日起生效的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"受让人请求自矿产资源勘查许可证、采矿许可证载明的有效期起始日确认其探矿权、采矿权的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"出让人未按照出让合同的约定移交勘查作业区或者矿区、颁发矿产资源勘查许可证或者采矿许可证，受让人请求解除出让合同的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"未取得矿产资源勘查许可证、采矿许可证，签订合同将矿产资源交由他人勘查开采的，人民法院应依法认定合同无效。"},{"i":6,"n":"第六条","txt":"矿业权转让合同自依法成立之日起具有法律约束力。矿业权转让申请未经国土资源主管部门批准，受让人请求转让人办理矿业权变更登记手续的，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"矿业权转让合同依法成立后，在不具有法定无效情形下，受让人请求转让人履行报批义务或者转让人请求受让人履行协助报批义务的，人民法院应予支持，但法律上或者事实上不具备履行条件的除外。"},{"i":8,"n":"第八条","txt":"矿业权转让合同依法成立后，转让人无正当理由拒不履行报批义务，受让人请求解除合同、返还已付转让款及利息，并由转让人承担违约责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"矿业权转让合同约定受让人支付全部或者部分转让款后办理报批手续，转让人在办理报批手续前请求受让人先履行付款义务的，人民法院应予支持，但受让人有确切证据证明存在转让人将同一矿业权转让给第三人、矿业权人将被兼并重组等符合合同法第六十八条规定情形的除外。"},{"i":10,"n":"第十条","txt":"国土资源主管部门不予批准矿业权转让申请致使矿业权转让合同被解除，受让人请求返还已付转让款及利息，采矿权人请求受让人返还获得的矿产品及收益，或者探矿权人请求受让人返还勘查资料和勘查中回收的矿产品及收益的，人民法院应予支持，但受让人可请求扣除相关的成本费用。"},{"i":11,"n":"第十一条","txt":"矿业权转让合同依法成立后、国土资源主管部门批准前，矿业权人又将矿业权转让给第三人并经国土资源主管部门批准、登记，受让人请求解除转让合同、返还已付转让款及利息，并由矿业权人承担违约责任的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"当事人请求确认矿业权租赁、承包合同自依法成立之日起生效的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"矿业权人与他人合作进行矿产资源勘查开采所签订的合同，当事人请求确认自依法成立之日起生效的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"矿业权人为担保自己或者他人债务的履行，将矿业权抵押给债权人的，抵押合同自依法成立之日起生效，但法律、行政法规规定不得抵押的除外。"},{"i":15,"n":"第十五条","txt":"当事人请求确认矿业权之抵押权自依法登记时设立的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人依据民事诉讼法第一百九十六条、第一百九十七条规定申请实现抵押权的，人民法院可以拍卖、变卖矿业权或者裁定以矿业权抵债，但矿业权竞买人、受让人应具备相应的资质条件。"},{"i":17,"n":"第十七条","txt":"矿业权抵押期间因抵押人被兼并重组或者矿床被压覆等原因导致矿业权全部或者部分灭失，抵押权人请求就抵押人因此获得的保险金、赔偿金或者补偿金等款项优先受偿或者将该款项予以提存的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"当事人约定在自然保护区、风景名胜区、重点生态功能区、生态环境敏感区和脆弱区等区域内勘查开采矿产资源，违反法律、行政法规的强制性规定或者损害环境公共利益的，人民法院应依法认定合同无效。"},{"i":19,"n":"第十九条","txt":"因越界勘查开采矿产资源引发的侵权责任纠纷，涉及国土资源主管部门批准的勘查开采范围重复或者界限不清的，人民法院应告知当事人先向国土资源主管部门申请解决。"},{"i":20,"n":"第二十条","txt":"因他人越界勘查开采矿产资源，矿业权人请求侵权人承担停止侵害、排除妨碍、返还财产、赔偿损失等侵权责任的，人民法院应予支持，但探矿权人请求侵权人返还越界开采的矿产品及收益的除外。"},{"i":21,"n":"第二十一条","txt":"勘查开采矿产资源造成环境污染，或者导致地质灾害、植被毁损等生态破坏，法律规定的机关和有关组织提起环境公益诉讼的，人民法院应依法予以受理。"},{"i":22,"n":"第二十二条","txt":"人民法院在审理案件中，发现无证勘查开采，勘查资质、地质资料造假，或者勘查开采未履行生态环境修复义务等违法情形的，可以向有关行政主管部门提出司法建议，由其依法处理；涉嫌犯罪的，依法移送侦查机关处理。"},{"i":23,"n":"第二十三条","txt":"本解释施行后，人民法院尚未审结的一审、二审案件适用本解释规定。本解释施行前已经作出生效裁判的案件，本解释施行后依法再审的，不适用本解释。"}],"zuigaorenminfayuanguanyushenlilaodongzhengyianjian2d83ab":[{"i":1,"n":"第一条","txt":"劳动者以用人单位未为其办理社会保险手续，且社会保险经办机构不能补办导致其无法享受社会保险待遇为由，要求用人单位赔偿损失而发生争议的，人民法院应予受理。"},{"i":2,"n":"第二条","txt":"因企业自主进行改制引发的争议，人民法院应予受理。"},{"i":3,"n":"第三条","txt":"劳动者依据劳动合同法第八十五条规定，向人民法院提起诉讼，要求用人单位支付加付赔偿金的，人民法院应予受理。"},{"i":4,"n":"第四条","txt":"劳动者与未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位发生争议的，应当将用人单位或者其出资人列为当事人。"},{"i":5,"n":"第五条","txt":"未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位，以挂靠等方式借用他人营业执照经营的，应当将用人单位和营业执照出借方列为当事人。"},{"i":6,"n":"第六条","txt":"当事人不服劳动人事争议仲裁委员会作出的仲裁裁决，依法向人民法院提起诉讼，人民法院审查认为仲裁裁决遗漏了必须共同参加仲裁的当事人的，应当依法追加遗漏的人为诉讼当事人。"},{"i":7,"n":"第七条","txt":"用人单位与其招用的已经依法享受养老保险待遇或领取退休金的人员发生用工争议，向人民法院提起诉讼的，人民法院应当按劳务关系处理。"},{"i":8,"n":"第八条","txt":"企业停薪留职人员、未达到法定退休年龄的内退人员、下岗待岗人员以及企业经营性停产放长假人员，因与新的用人单位发生用工争议，依法向人民法院提起诉讼的，人民法院应当按劳动关系处理。"},{"i":9,"n":"第九条","txt":"劳动者主张加班费的，应当就加班事实的存在承担举证责任。但劳动者有证据证明用人单位掌握加班事实存在的证据，用人单位不提供的，由用人单位承担不利后果。"},{"i":10,"n":"第十条","txt":"劳动者与用人单位就解除或者终止劳动合同办理相关手续、支付工资报酬、加班费、经济补偿或者赔偿金等达成的协议，不违反法律、行政法规的强制性规定，且不存在欺诈、胁迫或者乘人之危情形的，应当认定有效。"},{"i":11,"n":"第十一条","txt":"劳动人事争议仲裁委员会作出的调解书已经发生法律效力，一方当事人反悔提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":12,"n":"第十二条","txt":"劳动人事争议仲裁委员会逾期未作出受理决定或仲裁裁决，当事人直接提起诉讼的，人民法院应予受理，但申请仲裁的案件存在下列事由的除外："},{"i":13,"n":"第十三条","txt":"劳动者依据调解仲裁法第四十七条第（一）项规定，追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，如果仲裁裁决涉及数项，每项确定的数额均不超过当地月最低工资标准十二个月金额的，应当按照终局裁决处理。"},{"i":14,"n":"第十四条","txt":"劳动人事争议仲裁委员会作出的同一仲裁裁决同时包含终局裁决事项和非终局裁决事项，当事人不服该仲裁裁决向人民法院提起诉讼的，应当按照非终局裁决处理。"},{"i":15,"n":"第十五条","txt":"劳动者依据调解仲裁法第四十八条规定向基层人民法院提起诉讼，用人单位依据调解仲裁法第四十九条规定向劳动人事争议仲裁委员会所在地的中级人民法院申请撤销仲裁裁决的，中级人民法院应不予受理；已经受理的，应当裁定驳回申请。"},{"i":16,"n":"第十六条","txt":"用人单位依照调解仲裁法第四十九条规定向中级人民法院申请撤销仲裁裁决，中级人民法院作出的驳回申请或者撤销仲裁裁决的裁定为终审裁定。"},{"i":17,"n":"第十七条","txt":"劳动者依据劳动合同法第三十条第二款和调解仲裁法第十六条规定向人民法院申请支付令，符合民事诉讼法第十七章督促程序规定的，人民法院应予受理。"},{"i":18,"n":"第十八条","txt":"劳动人事争议仲裁委员会作出终局裁决，劳动者向人民法院申请执行，用人单位向劳动人事争议仲裁委员会所在地的中级人民法院申请撤销的，人民法院应当裁定中止执行。"}],"zuigaorenminfayuanguanyushenlilaodongzhengyianjian479099":[{"i":1,"n":"第一条","txt":"劳动人事争议仲裁委员会以无管辖权为由对劳动争议案件不予受理，当事人提起诉讼的，人民法院按照以下情形分别处理："},{"i":2,"n":"第二条","txt":"仲裁裁决的类型以仲裁裁决书确定为准。"},{"i":3,"n":"第三条","txt":"中级人民法院审理用人单位申请撤销终局裁决的案件，应当组成合议庭开庭审理。经过阅卷、调查和询问当事人，对没有新的事实、证据或者理由，合议庭认为不需要开庭审理的，可以不开庭审理。"},{"i":4,"n":"第四条","txt":"当事人在人民调解委员会主持下仅就给付义务达成的调解协议，双方认为有必要的，可以共同向人民调解委员会所在地的基层人民法院申请司法确认。"},{"i":5,"n":"第五条","txt":"劳动者非因本人原因从原用人单位被安排到新用人单位工作，原用人单位未支付经济补偿，劳动者依照劳动合同法第三十八条规定与新用人单位解除劳动合同，或者新用人单位向劳动者提出解除、终止劳动合同，在计算支付经济补偿或赔偿金的工作年限时，劳动者请求把在原用人单位的工作年限合并计算为新用人单位工作年限的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"当事人在劳动合同或者保密协议中约定了竞业限制，但未约定解除或者终止劳动合同后给予劳动者经济补偿，劳动者履行了竞业限制义务，要求用人单位按照劳动者在劳动合同解除或者终止前十二个月平均工资的30%按月支付经济补偿的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"当事人在劳动合同或者保密协议中约定了竞业限制和经济补偿，当事人解除劳动合同时，除另有约定外，用人单位要求劳动者履行竞业限制义务，或者劳动者履行了竞业限制义务后要求用人单位支付经济补偿的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"当事人在劳动合同或者保密协议中约定了竞业限制和经济补偿，劳动合同解除或者终止后，因用人单位的原因导致三个月未支付经济补偿，劳动者请求解除竞业限制约定的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"在竞业限制期限内，用人单位请求解除竞业限制协议时，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"劳动者违反竞业限制约定，向用人单位支付违约金后，用人单位要求劳动者按照约定继续履行竞业限制义务的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"变更劳动合同未采用书面形式，但已经实际履行了口头变更的劳动合同超过一个月，且变更后的劳动合同内容不违反法律、行政法规、国家政策以及公序良俗，当事人以未采用书面形式为由主张劳动合同变更无效的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"建立了工会组织的用人单位解除劳动合同符合劳动合同法第三十九条、第四十条规定，但未按照劳动合同法第四十三条规定事先通知工会，劳动者以用人单位违法解除劳动合同为由请求用人单位支付赔偿金的，人民法院应予支持，但起诉前用人单位已经补正有关程序的除外。"},{"i":13,"n":"第十三条","txt":"劳动合同法施行后，因用人单位经营期限届满不再继续经营导致劳动合同不能继续履行，劳动者请求用人单位支付经济补偿的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"外国人、无国籍人未依法取得就业证件即与中国境内的用人单位签订劳动合同，以及香港特别行政区、澳门特别行政区和台湾地区居民未依法取得就业证件即与内地用人单位签订劳动合同，当事人请求确认与用人单位存在劳动关系的，人民法院不予支持。"},{"i":15,"n":"第十五条","txt":"本解释施行前本院颁布的有关司法解释与本解释抵触的，自本解释施行之日起不再适用。"}],"zuigaorenminfayuanguanyushenlilaodongzhengyianjian8e1444":[{"i":1,"n":"第一条","txt":"劳动者与用人单位之间发生的下列纠纷，属于《劳动法》第二条规定的劳动争议，当事人不服劳动争议仲裁委员会作出的裁决，依法向人民法院起诉的，人民法院应当受理："},{"i":2,"n":"第二条","txt":"劳动争议仲裁委员会以当事人申请仲裁的事项不属于劳动争议为由，作出不予受理的书面裁决、决定或者通知，当事人不服，依法向人民法院起诉的，人民法院应当分别情况予以处理："},{"i":3,"n":"第三条","txt":"劳动争议仲裁委员会根据《劳动法》第八十二条之规定，以当事人的仲裁申请超过60日期限为由，作出不予受理的书面裁决、决定或者通知，当事人不服，依法向人民法院起诉的，人民法院应当受理；对确已超过仲裁申请期限，又无不可抗力或者其他正当理由的，依法驳回其诉讼请求。"},{"i":4,"n":"第四条","txt":"劳动争议仲裁委员会以申请仲裁的主体不适格为由，作出不予受理的书面裁决、决定或者通知，当事人不服，依法向人民法院起诉的，经审查，确属主体不适格的，裁定不予受理或者驳回起诉。"},{"i":5,"n":"第五条","txt":"劳动争议仲裁委员会为纠正原仲裁裁决错误重新作出裁决，当事人不服，依法向人民法院起诉的，人民法院应当受理。"},{"i":6,"n":"第六条","txt":"人民法院受理劳动争议案件后，当事人增加诉讼请求的，如该诉讼请求与讼争的劳动争议具有不可分性，应当合并审理；如属独立的劳动争议，应当告知当事人向劳动争议仲裁委员会申请仲裁。"},{"i":7,"n":"第七条","txt":"劳动争议仲裁委员会仲裁的事项不属于人民法院受理的案件范围，当事人不服，依法向人民法院起诉的，裁定不予受理或者驳回起诉。"},{"i":8,"n":"第八条","txt":"劳动争议案件由用人单位所在地或者劳动合同履行地的基层人民法院管辖。"},{"i":9,"n":"第九条","txt":"当事人双方不服劳动争议仲裁委员会作出的同一仲裁裁决，均向同一人民法院起诉的，先起诉的一方当事人为原告，但对双方的诉讼请求，人民法院应当一并作出裁决。"},{"i":10,"n":"第十条","txt":"用人单位与其他单位合并的，合并前发生的劳动争议，由合并后的单位为当事人；用人单位分立为若干单位的，其分立前发生的劳动争议，由分立后的实际用人单位为当事人。"},{"i":11,"n":"第十一条","txt":"用人单位招用尚未解除劳动合同的劳动者，原用人单位与劳动者发生的劳动争议，可以列新的用人单位为第三人。"},{"i":12,"n":"第十二条","txt":"劳动者在用人单位与其他平等主体之间的承包经营期间，与发包方和承包方双方或者一方发生劳动争议，依法向人民法院起诉的，应当将承包方和发包方作为当事人。"},{"i":13,"n":"第十三条","txt":"因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。"},{"i":14,"n":"第十四条","txt":"劳动合同被确认为无效后，用人单位对劳动者付出的劳动，一般可参照本单位同期、同工种、同岗位的工资标准支付劳动报酬。"},{"i":15,"n":"第十五条","txt":"用人单位有下列情形之一，迫使劳动者提出解除劳动合同的，用人单位应当支付劳动者的劳动报酬和经济补偿，并可支付赔偿金："},{"i":16,"n":"第十六条","txt":"劳动合同期满后，劳动者仍在原用人单位工作，原用人单位未表示异议的，视为双方同意以原条件继续履行劳动合同。一方提出终止劳动关系的，人民法院应当支持。"},{"i":17,"n":"第十七条","txt":"劳动争议仲裁委员会作出仲裁裁决后，当事人对裁决中的部分事项不服，依法向人民法院起诉的，劳动争议仲裁裁决不发生法律效力。"},{"i":18,"n":"第十八条","txt":"劳动争议仲裁委员会对多个劳动者的劳动争议作出仲裁裁决后，部分劳动者对仲裁裁决不服，依法向人民法院起诉的，仲裁裁决对提出起诉的劳动者不发生法律效力；对未提出起诉的部分劳动者，发生法律效力，如其申请执行的，人民法院应当受理。"},{"i":19,"n":"第十九条","txt":"用人单位根据《劳动法》第四条之规定，通过民主程序制定的规章制度，不违反国家法律、行政法规及政策规定，并已向劳动者公示的，可以作为人民法院审理劳动争议案件的依据。"},{"i":20,"n":"第二十条","txt":"用人单位对劳动者作出的开除、除名、辞退等处理，或者因其他原因解除劳动合同确有错误的，人民法院可以依法判决予以撤销。"},{"i":21,"n":"第二十一条","txt":"当事人申请人民法院执行劳动争议仲裁机构作出的发生法律效力的裁决书、调解书，被申请人提出证据证明劳动争议仲裁裁决书、调解书有下列情形之一，并经审查核实的，人民法院可以根据《民事诉讼法》第二百一十七条之规定，裁定不予执行："}],"zuigaorenminfayuanguanyushenlilaodongzhengyianjiand3cf9d":[{"i":1,"n":"第一条","txt":"人民法院审理劳动争议案件，对下列情形，视为劳动法第八十二条规定的“劳动争议发生之日”："},{"i":2,"n":"第二条","txt":"拖欠工资争议，劳动者申请仲裁时劳动关系仍然存续，用人单位以劳动者申请仲裁超过六十日为由主张不再支付的，人民法院不予支持。但用人单位能够证明劳动者已经收到拒付工资的书面通知的除外。"},{"i":3,"n":"第三条","txt":"劳动者以用人单位的工资欠条为证据直接向人民法院起诉，诉讼请求不涉及劳动关系其他争议的，视为拖欠劳动报酬争议，按照普通民事纠纷受理。"},{"i":4,"n":"第四条","txt":"用人单位和劳动者因劳动关系是否已经解除或者终止，以及应否支付解除或终止劳动关系经济补偿金产生的争议，经劳动争议仲裁委员会仲裁后，当事人依法起诉的，人民法院应予受理。"},{"i":5,"n":"第五条","txt":"劳动者与用人单位解除或者终止劳动关系后，请求用人单位返还其收取的劳动合同定金、保证金、抵押金、抵押物产生的争议，或者办理劳动者的人事档案、社会保险关系等移转手续产生的争议，经劳动争议仲裁委员会仲裁后，当事人依法起诉的，人民法院应予受理。"},{"i":6,"n":"第六条","txt":"劳动者因为工伤、职业病，请求用人单位依法承担给予工伤保险待遇的争议，经劳动争议仲裁委员会仲裁后，当事人依法起诉的，人民法院应予受理。"},{"i":7,"n":"第七条","txt":"下列纠纷不属于劳动争议："},{"i":8,"n":"第八条","txt":"当事人不服劳动争议仲裁委员会作出的预先支付劳动者部分工资或者医疗费用的裁决，向人民法院起诉的，人民法院不予受理。"},{"i":9,"n":"第九条","txt":"劳动者与起有字号的个体工商户产生的劳动争议诉讼，人民法院应当以营业执照上登记的字号为当事人，但应同时注明该字号业主的自然情况。"},{"i":10,"n":"第十条","txt":"劳动者因履行劳动力派遣合同产生劳动争议而起诉，以派遣单位为被告；争议内容涉及接受单位的，以派遣单位和接受单位为共同被告。"},{"i":11,"n":"第十一条","txt":"劳动者和用人单位均不服劳动争议仲裁委员会的同一裁决，向同一人民法院起诉的，人民法院应当并案审理，双方当事人互为原告和被告。在诉讼过程中，一方当事人撤诉的，人民法院应当根据另一方当事人的诉讼请求继续审理。"},{"i":12,"n":"第十二条","txt":"当事人能够证明在申请仲裁期间内因不可抗力或者其他客观原因无法申请仲裁的，人民法院应当认定申请仲裁期间中止，从中止的原因消灭之次日起，申请仲裁期间连续计算。"},{"i":13,"n":"第十三条","txt":"当事人能够证明在申请仲裁期间内具有下列情形之一的，人民法院应当认定申请仲裁期间中断："},{"i":14,"n":"第十四条","txt":"在诉讼过程中，劳动者向人民法院申请采取财产保全措施，人民法院经审查认为申请人经济确有困难，或有证据证明用人单位存在欠薪逃匿可能的，应当减轻或者免除劳动者提供担保的义务，及时采取保全措施。"},{"i":15,"n":"第十五条","txt":"人民法院作出的财产保全裁定中，应当告知当事人在劳动仲裁机构的裁决书或者在人民法院的裁判文书生效后三个月内申请强制执行。逾期不申请的，人民法院应当裁定解除保全措施。"},{"i":16,"n":"第十六条","txt":"用人单位制定的内部规章制度与集体合同或者劳动合同约定的内容不一致，劳动者请求优先适用合同约定的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"当事人在劳动争议调解委员会主持下达成的具有劳动权利义务内容的调解协议，具有劳动合同的约束力，可以作为人民法院裁判的根据。"},{"i":18,"n":"第十八条","txt":"本解释自2006年10月1日起施行。本解释施行前本院颁布的有关司法解释与本解释规定不一致的，以本解释的规定为准。"}],"zuigaorenminfayuanguanyushenlimingyuquananjianruog1b036c":[],"zuigaorenminfayuanguanyushenlimingyuquananjianruogae310c":[],"zuigaorenminfayuanguanyushenlipianquchukoutuishuix4c99a1":[{"i":1,"n":"第一条","txt":"刑法第二百零四条规定的“假报出口”，是指以虚构已税货物出口事实为目的，具有下列情形之一的行为："},{"i":2,"n":"第二条","txt":"具有下列情形之一的，应当认定为刑法第二百零四条规定的“其他欺骗手段”："},{"i":3,"n":"第三条","txt":"骗取国家出口退税款5万元以上的，为刑法第二百零四条规定的“数额较大”；骗取国家出口退税款50万元以上的，为刑法第二百零四条规定的“数额巨大”；骗取国家出口退税款250万元以上的，为刑法第二百零四条规定的“数额特别巨大”。"},{"i":4,"n":"第四条","txt":"具有下列情形之一的，属于刑法第二百零四条规定的“其他严重情节”："},{"i":5,"n":"第五条","txt":"具有下列情形之一的，属于刑法第二百零四条规定的“其他特别严重情节”："},{"i":6,"n":"第六条","txt":"有进出口经营权的公司、企业，明知他人意欲骗取国家出口退税款，仍违反国家有关进出口经营的规定，允许他人自带客户、自带货源、自带汇票并自行报关，骗取国家出口退税款的，依照刑法第二百零四条第一款、第二百一十一条的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"实施骗取国家出口退税行为，没有实际取得出口退税款的，可以比照既遂犯从轻或者减轻处罚。"},{"i":8,"n":"第八条","txt":"国家工作人员参与实施骗取出口退税犯罪活动的，依照刑法第二百零四条第一款的规定从重处罚。"},{"i":9,"n":"第九条","txt":"实施骗取出口退税犯罪，同时构成虚开增值税专用发票罪等其他犯罪的，依照刑法处罚较重的规定定罪处罚。"}],"zuigaorenminfayuanguanyushenlipohuailindiziyuanxinc7d9b2":[{"i":1,"n":"第一条","txt":"违反土地管理法规，非法占用林地，改变被占用林地用途，在非法占用的林地上实施建窑、建坟、建房、挖沙、采石、采矿、取土、种植农作物、堆放或排泄废弃物等行为或者进行其他非林业生产、建设，造成林地的原有植被或林业种植条件严重毁坏或者严重污染，并具有下列情形之一的，属于《中华人民共和国刑法修正案（二）》规定的“数量较大，造成林地大量毁坏”，应当以非法占用农用地罪判处五年以下有期徒刑或者拘役，并处或者单处罚金："},{"i":2,"n":"第二条","txt":"国家机关工作人员徇私舞弊，违反土地管理法规，滥用职权，非法批准征用、占用林地，具有下列情形之一的，属于刑法第四百一十条规定的“情节严重”，应当以非法批准征用、占用土地罪判处三年以下有期徒刑或者拘役："},{"i":3,"n":"第三条","txt":"实施本解释第二条规定的行为，具有下列情形之一的，属于刑法第四百一十条规定的“致使国家或者集体利益遭受特别重大损失”，应当以非法批准征用、占用土地罪判处三年以上七年以下有期徒刑："},{"i":4,"n":"第四条","txt":"国家机关工作人员徇私舞弊，违反土地管理法规，非法低价出让国有林地使用权，具有下列情形之一的，属于刑法第四百一十条规定的“情节严重”，应当以非法低价出让国有土地使用权罪判处三年以下有期徒刑或者拘役："},{"i":5,"n":"第五条","txt":"实施本解释第四条规定的行为，造成国有资产流失价额达到六十万元以上的，属于刑法第四百一十条规定的“致使国家和集体利益遭受特别重大损失”，应当以非法低价出让国有土地使用权罪判处三年以上七年以下有期徒刑。"},{"i":6,"n":"第六条","txt":"单位实施破坏林地资源犯罪的，依照本解释规定的相关定罪量刑标准执行。"},{"i":7,"n":"第七条","txt":"多次实施本解释规定的行为依法应当追诉且未经处理的，应当按照累计的数量、数额处罚。"}],"zuigaorenminfayuanguanyushenlipohuaisenlinziyuanxifd64e0":[{"i":1,"n":"第一条","txt":"刑法第三百四十四条规定的“珍贵树木”，包括由省级以上林业主管部门或者其他部门确定的具有重大历史纪念意义、科学研究价值或者年代久远的古树名木，国家禁止、限制出口的珍贵树木以及列入国家重点保护野生植物名录的树木。"},{"i":2,"n":"第二条","txt":"具有下列情形之一的，属于非法采伐、毁坏珍贵树木行为“情节严重”："},{"i":3,"n":"第三条","txt":"以非法占有为目的，具有下列情形之一，数量较大的，依照刑法第三百四十五条第一款的规定，以盗伐林木罪定罪处罚："},{"i":4,"n":"第四条","txt":"盗伐林木“数量较大”，以2至5立方米或者幼树100至200株为起点；盗伐林木“数量巨大”，以20至50立方米或者幼树1000至2000株为起点；盗伐林木“数量特别巨大”，以100至200立方米或者幼树5000至1万株为起点。"},{"i":5,"n":"第五条","txt":"违反森林法的规定，具有下列情形之一，数量较大的，依照刑法第三百四十五条第二款的规定，以滥伐林木罪定罪处罚："},{"i":6,"n":"第六条","txt":"滥伐林木“数量较大”，以10至20立方米或者幼树500至1000株为起点；滥伐林木“数量巨大”，以50至100立方米或者幼树2500至5000株为起点。"},{"i":7,"n":"第七条","txt":"对于1年内多次盗伐、滥伐少量林木未经处罚的，累计其盗伐、滥伐林木的数量，构成犯罪的，依法追究刑事责任。"},{"i":8,"n":"第八条","txt":"盗伐、滥伐珍贵树木，同时触犯刑法第三百四十四条、第三百四十五条规定的，依照处罚较重的规定定罪处罚。"},{"i":9,"n":"第九条","txt":"将国家、集体、他人所有并已经伐倒的树木窃为己有，以及偷砍他人房前屋后、自留地种植的零星树木，数额较大的，依照刑法第二百六十四条的规定，以盗窃罪定罪处罚。"},{"i":10,"n":"第十条","txt":"刑法第三百四十五条规定的“非法收购明知是盗伐、滥伐的林木”中的“明知”，是指知道或者应当知道。具有下列情形之一的，可以视为应当知道，但是有证据证明确属被蒙骗的除外："},{"i":11,"n":"第十一条","txt":"具有下列情形之一的，属于在林区非法收购盗伐、滥伐的林木“情节严重”："},{"i":12,"n":"第十二条","txt":"林业主管部门的工作人员违反森林法的规定，超过批准的年采伐限额发放林木采伐许可证或者违反规定滥发林木采伐许可证，具有下列情形之一的，属于刑法第四百零七条规定的“情节严重，致使森林遭受严重破坏”，以违法发放林木采伐许可证罪定罪处罚："},{"i":13,"n":"第十三条","txt":"对于伪造、变造、买卖林木采伐许可证、木材运输证件，森林、林木、林地权属证书，占用或者征用林地审核同意书、育林基金等缴费收据以及其他国家机关批准的林业证件构成犯罪的，依照刑法第二百八十条第一款的规定，以伪造、变造、买卖国家机关公文、证件罪定罪处罚。"},{"i":14,"n":"第十四条","txt":"聚众哄抢林木5立方米以上的，属于聚众哄抢“数额较大”；聚众哄抢林木20立方米以上的，属于聚众哄抢“数额巨大”，对首要分子和积极参加的，依照刑法第二百六十八条的规定，以聚众哄抢罪定罪处罚。"},{"i":15,"n":"第十五条","txt":"非法实施采种、采脂、挖笋、掘根、剥树皮等行为，牟取经济利益数额较大的，依照刑法第二百六十四条的规定，以盗窃罪定罪处罚。同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":16,"n":"第十六条","txt":"单位犯刑法第三百四十四条、第三百四十五条规定之罪，定罪量刑标准按照本解释的规定执行。"},{"i":17,"n":"第十七条","txt":"本解释规定的林木数量以立木蓄积计算，计算方法为：原木材积除以该树种的出材率。"},{"i":18,"n":"第十八条","txt":"盗伐、滥伐以生产竹材为主要目的的竹林的定罪量刑问题，有关省、自治区、直辖市高级人民法院可以参照上述规定的精神，规定本地区的具体标准，并报最高人民法院备案。"},{"i":19,"n":"第十九条","txt":"各省、自治区、直辖市高级人民法院可以根据本地区的实际情况，在本解释第四条、第六条规定的数量幅度内，确定本地区执行的具体数量标准，并报最高人民法院备案。"}],"zuigaorenminfayuanguanyushenlipohuaiyeshengdongwuzcc095b":[{"i":1,"n":"第一条","txt":"刑法第三百四十一条第一款规定的“珍贵、濒危野生动物”，包括列入国家重点保护野生动物名录的国家一、二级保护野生动物、列入《濒危野生动植物种国际贸易公约》附录一、附录二的野生动物以及驯养繁殖的上述物种。"},{"i":2,"n":"第二条","txt":"刑法第三百四十一条第一款规定的“收购”，包括以营利、自用等为目的的购买行为；“运输”，包括采用携带、邮寄、利用他人、使用交通工具等方法进行运送的行为；“出售”，包括出卖和以营利为目的的加工利用行为。"},{"i":3,"n":"第三条","txt":"非法猎捕、杀害、收购、运输、出售珍贵、濒危野生动物具有下列情形之一的，属于“情节严重”："},{"i":4,"n":"第四条","txt":"非法猎捕、杀害、收购、运输、出售珍贵、濒危野生动物构成犯罪，具有下列情形之一的，可以认定为“情节严重”；非法猎捕、杀害、收购、运输、出售珍贵、濒危野生动物符合本解释第三条第一款的规定，并具有下列情形之一的，可以认定为“情节特别严重”："},{"i":5,"n":"第五条","txt":"非法收购、运输、出售珍贵、濒危野生动物制品具有下列情形之一的，属于“情节严重”："},{"i":6,"n":"第六条","txt":"违反狩猎法规，在禁猎区、禁猎期或者使用禁用的工具、方法狩猎，具有下列情形之一的，属于非法狩猎“情节严重”："},{"i":7,"n":"第七条","txt":"使用爆炸、投毒、设置电网等危险方法破坏野生动物资源，构成非法猎捕、杀害珍贵、濒危野生动物罪或者非法狩猎罪，同时构成刑法第一百一十四条或者第一百一十五条规定之罪的，依照处罚较重的规定定罪处罚。"},{"i":8,"n":"第八条","txt":"实施刑法第三百四十一条规定的犯罪，又以暴力、威胁方法抗拒查处，构成其他犯罪的，依照数罪并罚的规定处罚。"},{"i":9,"n":"第九条","txt":"伪造、变造、买卖国家机关颁发的野生动物允许进出口证明书、特许猎捕证、狩猎证、驯养繁殖许可证等公文、证件构成犯罪的，依照刑法第二百八十条第一款的规定以伪造、变造、买卖国家机关公文、证件罪定罪处罚。"},{"i":10,"n":"第十条","txt":"非法猎捕、杀害、收购、运输、出售《濒危野生动植物种国际贸易公约》附录一、附录二所列的非原产于我国的野生动物“情节严重”、“情节特别严重”的认定标准，参照本解释第三条、第四条以及附表所列与其同属的国家一、二级保护野生动物的认定标准执行；没有与其同属的国家一、二级保护野生动物的，参照与其同科的国家一、二级保护野生动物的认定标准执行。"},{"i":11,"n":"第十一条","txt":"珍贵、濒危野生动物制品的价值，依照国家野生动物保护主管部门的规定核定；核定价值低于实际交易价格的，以实际交易价格认定。"},{"i":12,"n":"第十二条","txt":"单位犯刑法第三百四十一条规定之罪，定罪量刑标准依照本解释的有关规定执行。"}],"zuigaorenminfayuanguanyushenliqinhaizhishichanquan2b2616":[{"i":1,"n":"第一条","txt":"原告主张被告故意侵害其依法享有的知识产权且情节严重，请求判令被告承担惩罚性赔偿责任的，人民法院应当依法审查处理。"},{"i":2,"n":"第二条","txt":"原告请求惩罚性赔偿的，应当在起诉时明确赔偿数额、计算方式以及所依据的事实和理由。"},{"i":3,"n":"第三条","txt":"对于侵害知识产权的故意的认定，人民法院应当综合考虑被侵害知识产权客体类型、权利状态和相关产品知名度、被告与原告或者利害关系人之间的关系等因素。"},{"i":4,"n":"第四条","txt":"对于侵害知识产权情节严重的认定，人民法院应当综合考虑侵权手段、次数，侵权行为的持续时间、地域范围、规模、后果，侵权人在诉讼中的行为等因素。"},{"i":5,"n":"第五条","txt":"人民法院确定惩罚性赔偿数额时，应当分别依照相关法律，以原告实际损失数额、被告违法所得数额或者因侵权所获得的利益作为计算基数。该基数不包括原告为制止侵权所支付的合理开支；法律另有规定的，依照其规定。"},{"i":6,"n":"第六条","txt":"人民法院依法确定惩罚性赔偿的倍数时，应当综合考虑被告主观过错程度、侵权行为的情节严重程度等因素。"},{"i":7,"n":"第七条","txt":"本解释自2021年3月3日起施行。最高人民法院以前发布的相关司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushenlishejifuqizhaiwujiufeb39c3e":[{"i":1,"n":"第一条","txt":"夫妻双方共同签字或者夫妻一方事后追认等共同意思表示所负的债务，应当认定为夫妻共同债务。"},{"i":2,"n":"第二条","txt":"夫妻一方在婚姻关系存续期间以个人名义为家庭日常生活需要所负的债务，债权人以属于夫妻共同债务为由主张权利的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"夫妻一方在婚姻关系存续期间以个人名义超出家庭日常生活需要所负的债务，债权人以属于夫妻共同债务为由主张权利的，人民法院不予支持，但债权人能够证明该债务用于夫妻共同生活、共同生产经营或者基于夫妻双方共同意思表示的除外。"},{"i":4,"n":"第四条","txt":"本解释自2018年1月18日起施行。"}],"zuigaorenminfayuanguanyushenlishejijinrongzichangu61be09":[{"i":1,"n":"第一条","txt":"金融资产管理公司办事处领取中国人民银行颁发的《金融机构营业许可证》，并向工商行政管理部门依法办理登记的，可以作为诉讼主体参加诉讼。"},{"i":2,"n":"第二条","txt":"金融资产管理公司受让国有银行债权后，人民法院对于债权转让前原债权银行已经提起诉讼尚未审结的案件，可以根据原债权银行或者金融资产管理公司的申请将诉讼主体变更为受让债权的金融资产管理公司。"},{"i":3,"n":"第三条","txt":"金融资产管理公司向债务人提起诉讼的，应当由被告人住所地人民法院管辖。"},{"i":4,"n":"第四条","txt":"人民法院对金融资产管理公司申请支付令的，应当依法受理。债务人提出异议的，依照《中华人民共和国民事诉讼法》第十七章的规定处理。"},{"i":5,"n":"第五条","txt":"人民法院对金融资产管理公司申请财产保全的，如金融资产管理公司与债务人之间债权债务关系明确，根据《中华人民共和国民事诉讼法》第九十二条第二款的规定，可以不要求金融资产管理公司提供担保。"},{"i":6,"n":"第六条","txt":"金融资产管理公司受让国有银行债权后，原债权银行在全国或者省级有影响的报纸上发布债权转让公告或通知的，人民法院可以认定债权人履行了《中华人民共和国合同法》第八十条第一款规定的通知义务。"},{"i":7,"n":"第七条","txt":"债务人逾期归还贷款，原借款合同约定的利息计算方法不违反法律法规规定的，该约定有效。没有约定或者不明的，依照中国人民银行《人民币利率管理规定》计算利息和复息。"},{"i":8,"n":"第八条","txt":"人民法院对最高额抵押所担保的不特定债权特定后，原债权银行转让主债权的，可以认定转让债权的行为有效。"},{"i":9,"n":"第九条","txt":"金融资产管理公司受让有抵押担保的债权后，可以依法取得对债权的抵押权，原抵押权登记继续有效。"},{"i":10,"n":"第十条","txt":"债务人在债权转让协议，债权转让通知上签章或者签收债务催收通知的，诉讼时效中断。原债权银行在全国或者省级有影响的报纸上发布的债权转让公告或通知中，有催收债务内容的，该公告或通知可以作为诉讼时效中断证据。"},{"i":11,"n":"第十一条","txt":"本规定所称金融资产管理公司包括其依法设立在各地的办事处。"},{"i":12,"n":"第十二条","txt":"本规定仅适用于审理涉及金融资产管理公司收购、管理、处置国有银行不良贷款形成的资产的有关案件。"}],"zuigaorenminfayuanguanyushenlitoushuikangshuixingsa753e7":[{"i":1,"n":"第一条","txt":"纳税人实施下列行为之一，不缴或者少缴应纳税款，偷税数额占应纳税额的百分之十以上且偷税数额在一万元以上的，依照刑法第二百零一条第一款的规定定罪处罚："},{"i":2,"n":"第二条","txt":"纳税人伪造、变造、隐匿、擅自销毁用于记账的发票等原始凭证的行为，应当认定为刑法第二百零一条第一款规定的伪造、变造、隐匿、擅自销毁记账凭证的行为。"},{"i":3,"n":"第三条","txt":"偷税数额，是指在确定的纳税期间，不缴或者少缴各税种税款的总额。"},{"i":4,"n":"第四条","txt":"两年内因偷税受过二次行政处罚，又偷税且数额在一万元以上的，应当以偷税罪定罪处罚。"},{"i":5,"n":"第五条","txt":"实施抗税行为具有下列情形之一的，属于刑法第二百零二条规定的“情节严重”："},{"i":6,"n":"第六条","txt":"实施抗税行为致人重伤、死亡，构成故意伤害罪、故意杀人罪的，分别依照刑法第二百三十四条第二款、第二百三十二条的规定定罪处罚。"}],"zuigaorenminfayuanguanyushenlixiqiandengxingshianjd8ab37":[{"i":1,"n":"第一条","txt":"刑法第一百九十一条、第三百一十二条规定的“明知”，应当结合被告人的认知能力，接触他人犯罪所得及其收益的情况，犯罪所得及其收益的种类、数额，犯罪所得及其收益的转换、转移方式以及被告人的供述等主、客观因素进行认定。"},{"i":2,"n":"第二条","txt":"具有下列情形之一的，可以认定为刑法第一百九十一条第一款第（五）项规定的“以其他方法掩饰、隐瞒犯罪所得及其收益的来源和性质”："},{"i":3,"n":"第三条","txt":"明知是犯罪所得及其产生的收益而予以掩饰、隐瞒，构成刑法第三百一十二条规定的犯罪，同时又构成刑法第一百九十一条或者第三百四十九条规定的犯罪的，依照处罚较重的规定定罪处罚。"},{"i":4,"n":"第四条","txt":"刑法第一百九十一条、第三百一十二条、第三百四十九条规定的犯罪，应当以上游犯罪事实成立为认定前提。上游犯罪尚未依法裁判，但查证属实的，不影响刑法第一百九十一条、第三百一十二条、第三百四十九条规定的犯罪的审判。"},{"i":5,"n":"第五条","txt":"刑法第一百二十条之一规定的“资助”，是指为恐怖活动组织或者实施恐怖活动的个人筹集、提供经费、物资或者提供场所以及其他物质便利的行为。"}],"zuigaorenminfayuanguanyushenliyanshiyinmanfanzuisu221e46-2":[{"i":1,"n":"第一条","txt":"明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒，具有下列情形之一的，应当依照刑法第三百一十二条第一款的规定，以掩饰、隐瞒犯罪所得、犯罪所得收益罪定罪处罚："},{"i":2,"n":"第二条","txt":"掩饰、隐瞒犯罪所得及其产生的收益行为符合本解释第一条的规定，认罪、悔罪并退赃、退赔，且具有下列情形之一的，可以认定为犯罪情节轻微，免予刑事处罚："},{"i":3,"n":"第三条","txt":"掩饰、隐瞒犯罪所得及其产生的收益，具有下列情形之一的，应当认定为刑法第三百一十二条第一款规定的“情节严重”："},{"i":4,"n":"第四条","txt":"掩饰、隐瞒犯罪所得及其产生的收益的数额，应当以实施掩饰、隐瞒行为时为准。收购或者代为销售财物的价格高于其实际价值的，以收购或者代为销售的价格计算。"},{"i":5,"n":"第五条","txt":"事前与盗窃、抢劫、诈骗、抢夺等犯罪分子通谋，掩饰、隐瞒犯罪所得及其产生的收益的，以盗窃、抢劫、诈骗、抢夺等犯罪的共犯论处。"},{"i":6,"n":"第六条","txt":"对犯罪所得及其产生的收益实施盗窃、抢劫、诈骗、抢夺等行为，构成犯罪的，分别以盗窃罪、抢劫罪、诈骗罪、抢夺罪等定罪处罚。"},{"i":7,"n":"第七条","txt":"明知是犯罪所得及其产生的收益而予以掩饰、隐瞒，构成刑法第三百一十二条规定的犯罪，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":8,"n":"第八条","txt":"认定掩饰、隐瞒犯罪所得、犯罪所得收益罪，以上游犯罪事实成立为前提。上游犯罪尚未依法裁判，但查证属实的，不影响掩饰、隐瞒犯罪所得、犯罪所得收益罪的认定。"},{"i":9,"n":"第九条","txt":"盗用单位名义实施掩饰、隐瞒犯罪所得及其产生的收益行为，违法所得由行为人私分的，依照刑法和司法解释有关自然人犯罪的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"通过犯罪直接得到的赃款、赃物，应当认定为刑法第三百一十二条规定的“犯罪所得”。上游犯罪的行为人对犯罪所得进行处理后得到的孳息、租金等，应当认定为刑法第三百一十二条规定的“犯罪所得产生的收益”。"},{"i":11,"n":"第十一条","txt":"掩饰、隐瞒犯罪所得、犯罪所得收益罪是选择性罪名，审理此类案件，应当根据具体犯罪行为及其指向的对象，确定适用的罪名。"}],"zuigaorenminfayuanguanyushenliyanshiyinmanfanzuisu221e46":[{"i":1,"n":"第一条","txt":"明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒，具有下列情形之一的，应当依照刑法第三百一十二条第一款的规定，以掩饰、隐瞒犯罪所得、犯罪所得收益罪定罪处罚："},{"i":2,"n":"第二条","txt":"掩饰、隐瞒犯罪所得及其产生的收益行为符合本解释第一条的规定，认罪、悔罪并退赃、退赔，且具有下列情形之一的，可以认定为犯罪情节轻微，免予刑事处罚："},{"i":3,"n":"第三条","txt":"掩饰、隐瞒犯罪所得及其产生的收益，具有下列情形之一的，应当认定为刑法第三百一十二条第一款规定的“情节严重”："},{"i":4,"n":"第四条","txt":"掩饰、隐瞒犯罪所得及其产生的收益的数额，应当以实施掩饰、隐瞒行为时为准。收购或者代为销售财物的价格高于其实际价值的，以收购或者代为销售的价格计算。"},{"i":5,"n":"第五条","txt":"事前与盗窃、抢劫、诈骗、抢夺等犯罪分子通谋，掩饰、隐瞒犯罪所得及其产生的收益的，以盗窃、抢劫、诈骗、抢夺等犯罪的共犯论处。"},{"i":6,"n":"第六条","txt":"对犯罪所得及其产生的收益实施盗窃、抢劫、诈骗、抢夺等行为，构成犯罪的，分别以盗窃罪、抢劫罪、诈骗罪、抢夺罪等定罪处罚。"},{"i":7,"n":"第七条","txt":"明知是犯罪所得及其产生的收益而予以掩饰、隐瞒，构成刑法第三百一十二条规定的犯罪，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":8,"n":"第八条","txt":"认定掩饰、隐瞒犯罪所得、犯罪所得收益罪，以上游犯罪事实成立为前提。上游犯罪尚未依法裁判，但查证属实的，不影响掩饰、隐瞒犯罪所得、犯罪所得收益罪的认定。"},{"i":9,"n":"第九条","txt":"盗用单位名义实施掩饰、隐瞒犯罪所得及其产生的收益行为，违法所得由行为人私分的，依照刑法和司法解释有关自然人犯罪的规定定罪处罚。"},{"i":10,"n":"第十条","txt":"通过犯罪直接得到的赃款、赃物，应当认定为刑法第三百一十二条规定的“犯罪所得”。上游犯罪的行为人对犯罪所得进行处理后得到的孳息、租金等，应当认定为刑法第三百一十二条规定的“犯罪所得产生的收益”。"},{"i":11,"n":"第十一条","txt":"掩饰、隐瞒犯罪所得、犯罪所得收益罪是选择性罪名，审理此类案件，应当根据具体犯罪行为及其指向的对象，确定适用的罪名。"}],"zuigaorenminfayuanguanyushenliyinlongduanxingweiyi757066-2":[{"i":1,"n":"第一条","txt":"本规定所称因垄断行为引发的民事纠纷案件（以下简称垄断民事纠纷案件），是指因垄断行为受到损失以及因合同内容、行业协会的章程等违反反垄断法而发生争议的自然人、法人或者非法人组织，向人民法院提起的民事诉讼案件。"},{"i":2,"n":"第二条","txt":"原告直接向人民法院提起民事诉讼，或者在反垄断执法机构认定构成垄断行为的处理决定发生法律效力后向人民法院提起民事诉讼，并符合法律规定的其他受理条件的，人民法院应当受理。"},{"i":3,"n":"第三条","txt":"第一审垄断民事纠纷案件，由知识产权法院，省、自治区、直辖市人民政府所在地的市、计划单列市中级人民法院以及最高人民法院指定的中级人民法院管辖。"},{"i":4,"n":"第四条","txt":"垄断民事纠纷案件的地域管辖，根据案件具体情况，依照民事诉讼法及相关司法解释有关侵权纠纷、合同纠纷等的管辖规定确定。"},{"i":5,"n":"第五条","txt":"民事纠纷案件立案时的案由并非垄断纠纷，被告以原告实施了垄断行为为由提出抗辩或者反诉且有证据支持，或者案件需要依据反垄断法作出裁判，但受诉人民法院没有垄断民事纠纷案件管辖权的，应当将案件移送有管辖权的人民法院。"},{"i":6,"n":"第六条","txt":"两个或者两个以上原告因同一垄断行为向有管辖权的同一法院分别提起诉讼的，人民法院可以合并审理。"},{"i":7,"n":"第七条","txt":"被诉垄断行为属于反垄断法第十三条第一款第一项至第五项规定的垄断协议的，被告应对该协议不具有排除、限制竞争的效果承担举证责任。"},{"i":8,"n":"第八条","txt":"被诉垄断行为属于反垄断法第十七条第一款规定的滥用市场支配地位的，原告应当对被告在相关市场内具有支配地位和其滥用市场支配地位承担举证责任。"},{"i":9,"n":"第九条","txt":"被诉垄断行为属于公用企业或者其他依法具有独占地位的经营者滥用市场支配地位的，人民法院可以根据市场结构和竞争状况的具体情况，认定被告在相关市场内具有支配地位，但有相反证据足以推翻的除外。"},{"i":10,"n":"第十条","txt":"原告可以以被告对外发布的信息作为证明其具有市场支配地位的证据。被告对外发布的信息能够证明其在相关市场内具有支配地位的，人民法院可以据此作出认定，但有相反证据足以推翻的除外。"},{"i":11,"n":"第十一条","txt":"证据涉及国家秘密、商业秘密、个人隐私或者其他依法应当保密的内容的，人民法院可以依职权或者当事人的申请采取不公开开庭、限制或者禁止复制、仅对代理律师展示、责令签署保密承诺书等保护措施。"},{"i":12,"n":"第十二条","txt":"当事人可以向人民法院申请一至二名具有相应专门知识的人员出庭，就案件的专门性问题进行说明。"},{"i":13,"n":"第十三条","txt":"当事人可以向人民法院申请委托专业机构或者专业人员就案件的专门性问题作出市场调查或者经济分析报告。经人民法院同意，双方当事人可以协商确定专业机构或者专业人员；协商不成的，由人民法院指定。"},{"i":14,"n":"第十四条","txt":"被告实施垄断行为，给原告造成损失的，根据原告的诉讼请求和查明的事实，人民法院可以依法判令被告承担停止侵害、赔偿损失等民事责任。"},{"i":15,"n":"第十五条","txt":"被诉合同内容、行业协会的章程等违反反垄断法或者其他法律、行政法规的强制性规定的，人民法院应当依法认定其无效。但是，该强制性规定不导致该民事法律行为无效的除外。"},{"i":16,"n":"第十六条","txt":"因垄断行为产生的损害赔偿请求权诉讼时效期间，从原告知道或者应当知道权益受到损害以及义务人之日起计算。"}],"zuigaorenminfayuanguanyushenliyinlongduanxingweiyi757066":[{"i":1,"n":"第一条","txt":"本规定所称因垄断行为引发的民事纠纷案件（以下简称垄断民事纠纷案件），是指因垄断行为受到损失以及因合同内容、行业协会的章程等违反反垄断法而发生争议的自然人、法人或者其他组织，向人民法院提起的民事诉讼案件。"},{"i":2,"n":"第二条","txt":"原告直接向人民法院提起民事诉讼，或者在反垄断执法机构认定构成垄断行为的处理决定发生法律效力后向人民法院提起民事诉讼，并符合法律规定的其他受理条件的，人民法院应当受理。"},{"i":3,"n":"第三条","txt":"第一审垄断民事纠纷案件，由省、自治区、直辖市人民政府所在地的市、计划单列市中级人民法院以及最高人民法院指定的中级人民法院管辖。"},{"i":4,"n":"第四条","txt":"垄断民事纠纷案件的地域管辖，根据案件具体情况，依照民事诉讼法及相关司法解释有关侵权纠纷、合同纠纷等的管辖规定确定。"},{"i":5,"n":"第五条","txt":"民事纠纷案件立案时的案由并非垄断纠纷，被告以原告实施了垄断行为为由提出抗辩或者反诉且有证据支持，或者案件需要依据反垄断法作出裁判，但受诉人民法院没有垄断民事纠纷案件管辖权的，应当将案件移送有管辖权的人民法院。"},{"i":6,"n":"第六条","txt":"两个或者两个以上原告因同一垄断行为向有管辖权的同一法院分别提起诉讼的，人民法院可以合并审理。"},{"i":7,"n":"第七条","txt":"被诉垄断行为属于反垄断法第十三条第一款第（一）项至第（五）项规定的垄断协议的，被告应对该协议不具有排除、限制竞争的效果承担举证责任。"},{"i":8,"n":"第八条","txt":"被诉垄断行为属于反垄断法第十七条第一款规定的滥用市场支配地位的，原告应当对被告在相关市场内具有支配地位和其滥用市场支配地位承担举证责任。"},{"i":9,"n":"第九条","txt":"被诉垄断行为属于公用企业或者其他依法具有独占地位的经营者滥用市场支配地位的，人民法院可以根据市场结构和竞争状况的具体情况，认定被告在相关市场内具有支配地位，但有相反证据足以推翻的除外。"},{"i":10,"n":"第十条","txt":"原告可以以被告对外发布的信息作为证明其具有市场支配地位的证据。被告对外发布的信息能够证明其在相关市场内具有支配地位的，人民法院可以据此作出认定，但有相反证据足以推翻的除外。"},{"i":11,"n":"第十一条","txt":"证据涉及国家秘密、商业秘密、个人隐私或者其他依法应当保密的内容的，人民法院可以依职权或者当事人的申请采取不公开开庭、限制或者禁止复制、仅对代理律师展示、责令签署保密承诺书等保护措施。"},{"i":12,"n":"第十二条","txt":"当事人可以向人民法院申请一至二名具有相应专门知识的人员出庭，就案件的专门性问题进行说明。"},{"i":13,"n":"第十三条","txt":"当事人可以向人民法院申请委托专业机构或者专业人员就案件的专门性问题作出市场调查或者经济分析报告。经人民法院同意，双方当事人可以协商确定专业机构或者专业人员；协商不成的，由人民法院指定。"},{"i":14,"n":"第十四条","txt":"被告实施垄断行为，给原告造成损失的，根据原告的诉讼请求和查明的事实，人民法院可以依法判令被告承担停止侵害、赔偿损失等民事责任。"},{"i":15,"n":"第十五条","txt":"被诉合同内容、行业协会的章程等违反反垄断法或者其他法律、行政法规的强制性规定的，人民法院应当依法认定其无效。"},{"i":16,"n":"第十六条","txt":"因垄断行为产生的损害赔偿请求权诉讼时效期间，从原告知道或者应当知道权益受侵害之日起计算。"}],"zuigaorenminfayuanguanyushenlizhengfuxinxigongkaixd575c6":[{"i":1,"n":"第一条","txt":"公民、法人或者其他组织认为下列政府信息公开工作中的具体行政行为侵犯其合法权益，依法提起行政诉讼的，人民法院应当受理："},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织对下列行为不服提起行政诉讼的，人民法院不予受理："},{"i":3,"n":"第三条","txt":"公民、法人或者其他组织认为行政机关不依法履行主动公开政府信息义务，直接向人民法院提起诉讼的，应当告知其先向行政机关申请获取相关政府信息。对行政机关的答复或者逾期不予答复不服的，可以向人民法院提起诉讼。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对国务院部门、地方各级人民政府及县级以上地方人民政府部门依申请公开政府信息行政行为不服提起诉讼的，以作出答复的机关为被告；逾期未作出答复的，以受理申请的机关为被告。"},{"i":5,"n":"第五条","txt":"被告拒绝向原告提供政府信息的，应当对拒绝的根据以及履行法定告知和说明理由义务的情况举证。"},{"i":6,"n":"第六条","txt":"人民法院审理政府信息公开行政案件，应当视情采取适当的审理方式，以避免泄露涉及国家秘密、商业秘密、个人隐私或者法律规定的其他应当保密的政府信息。"},{"i":7,"n":"第七条","txt":"政府信息由被告的档案机构或者档案工作人员保管的，适用《中华人民共和国政府信息公开条例》的规定。"},{"i":8,"n":"第八条","txt":"政府信息涉及国家秘密、商业秘密、个人隐私的，人民法院应当认定属于不予公开范围。"},{"i":9,"n":"第九条","txt":"被告对依法应当公开的政府信息拒绝或者部分拒绝公开的，人民法院应当撤销或者部分撤销被诉不予公开决定，并判决被告在一定期限内公开。尚需被告调查、裁量的，判决其在一定期限内重新答复。"},{"i":10,"n":"第十条","txt":"被告对原告要求公开或者更正政府信息的申请无正当理由逾期不予答复的，人民法院应当判决被告在一定期限内答复。原告一并请求判决被告公开或者更正政府信息且理由成立的，参照第九条的规定处理。"},{"i":11,"n":"第十一条","txt":"被告公开政府信息涉及原告商业秘密、个人隐私且不存在公共利益等法定事由的，人民法院应当判决确认公开政府信息的行为违法，并可以责令被告采取相应的补救措施；造成损害的，根据原告请求依法判决被告承担赔偿责任。政府信息尚未公开的，应当判决行政机关不得公开。"},{"i":12,"n":"第十二条","txt":"有下列情形之一，被告已经履行法定告知或者说明理由义务的，人民法院应当判决驳回原告的诉讼请求："},{"i":13,"n":"第十三条","txt":"最高人民法院以前所作的司法解释及规范性文件，凡与本规定不一致的，按本规定执行。"}],"zuigaorenminfayuanguanyushenlizhengquanshichangyin37052e":[{"i":1,"n":"第一条","txt":"本规定所称证券市场因虚假陈述引发的民事赔偿案件（以下简称虚假陈述证券民事赔偿案件），是指证券市场投资人以信息披露义务人违反法律规定，进行虚假陈述并致使其遭受损失为由，而向人民法院提起诉讼的民事赔偿案件。"},{"i":2,"n":"第二条","txt":"本规定所称投资人，是指在证券市场上从事证券认购和交易的自然人、法人或者其他组织。"},{"i":3,"n":"第三条","txt":"因下列交易发生的民事诉讼，不适用本规定："},{"i":4,"n":"第四条","txt":"人民法院审理虚假陈述证券民事赔偿案件，应当着重调解，鼓励当事人和解。"},{"i":5,"n":"第五条","txt":"投资人对虚假陈述行为人提起民事赔偿的诉讼时效期间，适用民法通则第一百三十五条的规定，根据下列不同情况分别起算："},{"i":6,"n":"第六条","txt":"投资人以自己受到虚假陈述侵害为由，依据有关机关的行政处罚决定或者人民法院的刑事裁判文书，对虚假陈述行为人提起的民事赔偿诉讼，符合民事诉讼法第一百零八条规定的，人民法院应当受理。"},{"i":7,"n":"第七条","txt":"虚假陈述证券民事赔偿案件的被告，应当是虚假陈述行为人，包括："},{"i":8,"n":"第八条","txt":"虚假陈述证券民事赔偿案件，由省、直辖市、自治区人民政府所在的市、计划单列市和经济特区中级人民法院管辖。"},{"i":9,"n":"第九条","txt":"投资人对多个被告提起证券民事赔偿诉讼的，按下列原则确定管辖："},{"i":10,"n":"第十条","txt":"人民法院受理以发行人或者上市公司以外的虚假陈述行为人为被告提起的诉讼后，经当事人申请或者征得所有原告同意后，可以追加发行人或者上市公司为共同被告。人民法院追加后，应当将案件移送发行人或者上市公司所在地有管辖权的中级人民法院管辖。"},{"i":11,"n":"第十一条","txt":"人民法院受理虚假陈述证券民事赔偿案件后，受行政处罚当事人对行政处罚不服申请行政复议或者提起行政诉讼的，可以裁定中止审理。"},{"i":12,"n":"第十二条","txt":"本规定所涉证券民事赔偿案件的原告可以选择单独诉讼或者共同诉讼方式提起诉讼。"},{"i":13,"n":"第十三条","txt":"多个原告因同一虚假陈述事实对相同被告提起的诉讼，既有单独诉讼也有共同诉讼的，人民法院可以通知提起单独诉讼的原告参加共同诉讼。"},{"i":14,"n":"第十四条","txt":"共同诉讼的原告人数应当在开庭审理前确定。原告人数众多的可以推选二至五名诉讼代表人，每名诉讼代表人可以委托一至二名诉讼代理人。"},{"i":15,"n":"第十五条","txt":"诉讼代表人应当经过其所代表的原告特别授权，代表原告参加开庭审理，变更或者放弃诉讼请求、与被告进行和解或者达成调解协议。"},{"i":16,"n":"第十六条","txt":"人民法院判决被告对人数众多的原告承担民事赔偿责任时，可以在判决主文中对赔偿总额作出判决，并将每个原告的姓名、应获得赔偿金额等列表附于民事判决书后。"},{"i":17,"n":"第十七条","txt":"证券市场虚假陈述，是指信息披露义务人违反证券法律规定，在证券发行或者交易过程中，对重大事件作出违背事实真相的虚假记载、误导性陈述，或者在披露信息时发生重大遗漏、不正当披露信息的行为。"},{"i":18,"n":"第十八条","txt":"投资人具有以下情形的，人民法院应当认定虚假陈述与损害结果之间存在因果关系："},{"i":19,"n":"第十九条","txt":"被告举证证明原告具有以下情形的，人民法院应当认定虚假陈述与损害结果之间不存在因果关系："},{"i":20,"n":"第二十条","txt":"本规定所指的虚假陈述实施日，是指作出虚假陈述或者发生虚假陈述之日。"},{"i":21,"n":"第二十一条","txt":"发起人、发行人或者上市公司对其虚假陈述给投资人造成的损失承担民事赔偿责任。"},{"i":22,"n":"第二十二条","txt":"实际控制人操纵发行人或者上市公司违反证券法律规定，以发行人或者上市公司名义虚假陈述并给投资人造成损失的，可以由发行人或者上市公司承担赔偿责任。发行人或者上市公司承担赔偿责任后，可以向实际控制人追偿。"},{"i":23,"n":"第二十三条","txt":"证券承销商、证券上市推荐人对虚假陈述给投资人造成的损失承担赔偿责任。但有证据证明无过错的，应予免责。"},{"i":24,"n":"第二十四条","txt":"专业中介服务机构及其直接责任人违反证券法第一百六十一条和第二百零二条的规定虚假陈述，给投资人造成损失的，就其负有责任的部分承担赔偿责任。但有证据证明无过错的，应予免责。"},{"i":25,"n":"第二十五条","txt":"本规定第七条第（七）项规定的其他作出虚假陈述行为的机构或者自然人，违反证券法第五条、第七十二条、第一百八十八条和第一百八十九条规定，给投资人造成损失的，应当承担赔偿责任。"},{"i":26,"n":"第二十六条","txt":"发起人对发行人信息披露提供担保的，发起人与发行人对投资人的损失承担连带责任。"},{"i":27,"n":"第二十七条","txt":"证券承销商、证券上市推荐人或者专业中介服务机构，知道或者应当知道发行人或者上市公司虚假陈述，而不予纠正或者不出具保留意见的，构成共同侵权，对投资人的损失承担连带责任。"},{"i":28,"n":"第二十八条","txt":"发行人、上市公司、证券承销商、证券上市推荐人负有责任的董事、监事和经理等高级管理人员有下列情形之一的，应当认定为共同虚假陈述，分别与发行人、上市公司、证券承销商、证券上市推荐人对投资人的损失承担连带责任："},{"i":29,"n":"第二十九条","txt":"虚假陈述行为人在证券发行市场虚假陈述，导致投资人损失的，投资人有权要求虚假陈述行为人按本规定第三十条赔偿损失；导致证券被停止发行的，投资人有权要求返还和赔偿所缴股款及银行同期活期存款利率的利息。"},{"i":30,"n":"第三十条","txt":"虚假陈述行为人在证券交易市场承担民事赔偿责任的范围，以投资人因虚假陈述而实际发生的损失为限。投资人实际损失包括："},{"i":31,"n":"第三十一条","txt":"投资人在基准日及以前卖出证券的，其投资差额损失，以买入证券平均价格与实际卖出证券平均价格之差，乘以投资人所持证券数量计算。"},{"i":32,"n":"第三十二条","txt":"投资人在基准日之后卖出或者仍持有证券的，其投资差额损失，以买入证券平均价格与虚假陈述揭露日或者更正日起至基准日期间，每个交易日收盘价的平均价格之差，乘以投资人所持证券数量计算。"},{"i":33,"n":"第三十三条","txt":"投资差额损失计算的基准日，是指虚假陈述揭露或者更正后，为将投资人应获赔偿限定在虚假陈述所造成的损失范围内，确定损失计算的合理期间而规定的截止日期。基准日分别按下列情况确定："},{"i":34,"n":"第三十四条","txt":"投资人持股期间基于股东身份取得的收益，包括红利、红股、公积金转增所得的股份以及投资人持股期间出资购买的配股、增发股和转配股，不得冲抵虚假陈述行为人的赔偿金额。"},{"i":35,"n":"第三十五条","txt":"已经除权的证券，计算投资差额损失时，证券价格和证券数量应当复权计算。"},{"i":36,"n":"第三十六条","txt":"本规定自2003年2月1日起施行。"},{"i":37,"n":"第三十七条","txt":"本院2002年1月15日发布的《关于受理证券市场因虚假陈述引发的民事侵权纠纷案件有关问题的通知》中与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlizhongwaihezijingying54d35c":[],"zuigaorenminfayuanguanyushiyongdanbaofaruoganwentidf8798":[{"i":1,"n":"第一条","txt":"当事人对由民事关系产生的债权，在不违反法律、法规强制性规定的情况下，以担保法规定的方式设定担保的，可以认定为有效。"},{"i":2,"n":"第二条","txt":"反担保人可以是债务人，也可以是债务人之外的其他人。"},{"i":3,"n":"第三条","txt":"国家机关和以公益为目的的事业单位、社会团体违反法律规定提供担保的，担保合同无效。因此给债权人造成损失的，应当根据担保法第五条第二款的规定处理。"},{"i":4,"n":"第四条","txt":"董事、经理违反《中华人民共和国公司法》第六十条的规定，以公司资产为本公司的股东或者其他个人债务提供担保的，担保合同无效。除债权人知道或者应当知道的外，债务人、担保人应当对债权人的损失承担连带赔偿责任。"},{"i":5,"n":"第五条","txt":"以法律、法规禁止流通的财产或者不可转让的财产设定担保的，担保合同无效。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，对外担保合同无效："},{"i":7,"n":"第七条","txt":"主合同有效而担保合同无效，债权人无过错的，担保人与债务人对主合同债权人的经济损失，承担连带赔偿责任；债权人、担保人有过错的，担保人承担民事责任的部分，不应超过债务人不能清偿部分的1/2。"},{"i":8,"n":"第八条","txt":"主合同无效而导致担保合同无效，担保人无过错的，担保人不承担民事责任；担保人有过错的，担保人承担民事责任的部分，不应超过债务人不能清偿部分的1/3。"},{"i":9,"n":"第九条","txt":"担保人因无效担保合同向债权人承担赔偿责任后，可以向债务人追偿，或者在承担赔偿责任的范围内，要求有过错的反担保人承担赔偿责任。"},{"i":10,"n":"第十条","txt":"主合同解除后，担保人对债务人应当承担的民事责任仍应承担担保责任。但是，担保合同另有约定的除外。"},{"i":11,"n":"第十一条","txt":"法人或者其他组织的法定代表人、负责人超越权限订立的担保合同，除相对人知道或者应当知道其超越权限的以外，该代表行为有效。"},{"i":12,"n":"第十二条","txt":"当事人约定的或者登记部门要求登记的担保期间，对担保物权的存续不具有法律约束力。"},{"i":13,"n":"第十三条","txt":"保证合同中约定保证人代为履行非金钱债务的，如果保证人不能实际代为履行，对债权人因此造成的损失，保证人应当承担赔偿责任。"},{"i":14,"n":"第十四条","txt":"不具有完全代偿能力的法人、其他组织或者自然人，以保证人身份订立保证合同后，又以自己没有代偿能力要求免除保证责任的，人民法院不予支持。"},{"i":15,"n":"第十五条","txt":"担保法第七条规定的其他组织主要包括："},{"i":16,"n":"第十六条","txt":"从事经营活动的事业单位、社会团体为保证人的，如无其他导致保证合同无效的情况，其所签订的保证合同应当认定为有效。"},{"i":17,"n":"第十七条","txt":"企业法人的分支机构未经法人书面授权提供保证的，保证合同无效。因此给债权人造成损失的，应当根据担保法第五条第二款的规定处理。"},{"i":18,"n":"第十八条","txt":"企业法人的职能部门提供保证的，保证合同无效。债权人知道或者应当知道保证人为企业法人的职能部门的，因此造成的损失由债权人自行承担。"},{"i":19,"n":"第十九条","txt":"两个以上保证人对同一债务同时或者分别提供保证时，各保证人与债权人没有约定保证份额的，应当认定为连带共同保证。"},{"i":20,"n":"第二十条","txt":"连带共同保证的债务人在主合同规定的债务履行期届满没有履行债务的，债权人可以要求债务人履行债务，也可以要求任何一个保证人承担全部保证责任。"},{"i":21,"n":"第二十一条","txt":"按份共同保证的保证人按照保证合同约定的保证份额承担保证责任后，在其履行保证责任的范围内对债务人行使追偿权。"},{"i":22,"n":"第二十二条","txt":"第三人单方以书面形式向债权人出具担保书，债权人接受且未提出异议的，保证合同成立。"},{"i":23,"n":"第二十三条","txt":"最高额保证合同的不特定债权确定后，保证人应当对在最高债权额限度内就一定期间连续发生的债权余额承担保证责任。"},{"i":24,"n":"第二十四条","txt":"一般保证的保证人在主债权履行期间届满后，向债权人提供了债务人可供执行财产的真实情况的，债权人放弃或者怠于行使权利致使该财产不能被执行，保证人可以请求人民法院在其提供可供执行财产的实际价值范围内免除保证责任。"},{"i":25,"n":"第二十五条","txt":"担保法第十七条第三款第（一）项规定的债权人要求债务人履行债务发生的重大困难情形，包括债务人下落不明、移居境外，且无财产可供执行。"},{"i":26,"n":"第二十六条","txt":"第三人向债权人保证监督支付专款专用的，在履行了监督支付专款专用的义务后，不再承担责任。未尽监督义务造成资金流失的，应当对流失的资金承担补充赔偿责任。"},{"i":27,"n":"第二十七条","txt":"保证人对债务人的注册资金提供保证的，债务人的实际投资与注册资金不符，或者抽逃转移注册资金的，保证人在注册资金不足或者抽逃转移注册资金的范围内承担连带保证责任。"},{"i":28,"n":"第二十八条","txt":"保证期间，债权人依法将主债权转让给第三人的，保证债权同时转让，保证人在原保证担保的范围内对受让人承担保证责任。但是保证人与债权人事先约定仅对特定的债权人承担保证责任或者禁止债权转让的，保证人不再承担保证责任。"},{"i":29,"n":"第二十九条","txt":"保证期间，债权人许可债务人转让部分债务未经保证人书面同意的，保证人对未经其同意转让部分的债务，不再承担保证责任。但是，保证人仍应当对未转让部分的债务承担保证责任。"},{"i":30,"n":"第三十条","txt":"保证期间，债权人与债务人对主合同数量、价款、币种、利率等内容作了变动，未经保证人同意的，如果减轻债务人的债务的，保证人仍应当对变更后的合同承担保证责任；如果加重债务人的债务的，保证人对加重的部分不承担保证责任。"},{"i":31,"n":"第三十一条","txt":"保证期间不因任何事由发生中断、中止、延长的法律后果。"},{"i":32,"n":"第三十二条","txt":"保证合同约定的保证期间早于或者等于主债务履行期限的，视为没有约定，保证期间为主债务履行期届满之日起6个月。"},{"i":33,"n":"第三十三条","txt":"主合同对主债务履行期限没有约定或者约定不明的，保证期间自债权人要求债务人履行义务的宽限期届满之日起计算。"},{"i":34,"n":"第三十四条","txt":"一般保证的债权人在保证期间届满前对债务人提起诉讼或者申请仲裁的，从判决或者仲裁裁决生效之日起，开始计算保证合同的诉讼时效。"},{"i":35,"n":"第三十五条","txt":"保证人对已经超过诉讼时效期间的债务承担保证责任或者提供保证的，又以超过诉讼时效为由抗辩的，人民法院不予支持。"},{"i":36,"n":"第三十六条","txt":"一般保证中，主债务诉讼时效中断，保证债务诉讼时效中断；连带责任保证中，主债务诉讼时效中断，保证债务诉讼时效不中断。"},{"i":37,"n":"第三十七条","txt":"最高额保证合同对保证期间没有约定或者约定不明的，如最高额保证合同约定有保证人清偿债务期限的，保证期间为清偿期限届满之日起6个月。没有约定债务清偿期限的，保证期间自最高额保证终止之日或自债权人收到保证人终止保证合同的书面通知到达之日起6个月。"},{"i":38,"n":"第三十八条","txt":"同一债权既有保证又有第三人提供物的担保的，债权人可以请求保证人或者物的担保人承担担保责任。当事人对保证担保的范围或者物的担保的范围没有约定或者约定不明的，承担了担保责任的担保人，可以向债务人追偿，也可以要求其他担保人清偿其应当分担的份额。"},{"i":39,"n":"第三十九条","txt":"主合同当事人双方协议以新贷偿还旧贷，除保证人知道或者应当知道的外，保证人不承担民事责任。"},{"i":40,"n":"第四十条","txt":"主合同债务人采取欺诈、胁迫等手段，使保证人在违背真实意思的情况下提供保证的，债权人知道或者应当知道欺诈、胁迫事实的，按照担保法第三十条的规定处理。"},{"i":41,"n":"第四十一条","txt":"债务人与保证人共同欺骗债权人，订立主合同和保证合同的，债权人可以请求人民法院予以撤销。因此给债权人造成损失的，由保证人与债务人承担连带赔偿责任。"},{"i":42,"n":"第四十二条","txt":"人民法院判决保证人承担保证责任或者赔偿责任的，应当在判决书主文中明确保证人享有担保法第三十一条规定的权利。判决书中未予明确追偿权的，保证人只能按照承担责任的事实，另行提起诉讼。"},{"i":43,"n":"第四十三条","txt":"保证人自行履行保证责任时，其实际清偿额大于主债权范围的，保证人只能在主债权范围内对债务人行使追偿权。"},{"i":44,"n":"第四十四条","txt":"保证期间，人民法院受理债务人破产案件的，债权人既可以向人民法院申报债权，也可以向保证人主张权利。"},{"i":45,"n":"第四十五条","txt":"债权人知道或者应当知道债务人破产，既未申报债权也未通知保证人，致使保证人不能预先行使追偿权的，保证人在该债权在破产程序中可能受偿的范围内免除保证责任。"},{"i":46,"n":"第四十六条","txt":"人民法院受理债务人破产案件后，债权人未申报债权的，各连带共同保证的保证人应当作为一个主体申报债权，预先行使追偿权。"},{"i":47,"n":"第四十七条","txt":"以依法获准尚未建造的或者正在建造中的房屋或者其他建筑物抵押的，当事人办理了抵押物登记，人民法院可以认定抵押有效。"},{"i":48,"n":"第四十八条","txt":"以法定程序确认为违法、违章的建筑物抵押的，抵押无效。"},{"i":49,"n":"第四十九条","txt":"以尚未办理权属证书的财产抵押的，在第一审法庭辩论终结前能够提供权利证书或者补办登记手续的，可以认定抵押有效。"},{"i":50,"n":"第五十条","txt":"以担保法第三十四条第一款所列财产一并抵押的，抵押财产的范围应当以登记的财产为准。抵押财产的价值在抵押权实现时予以确定。"},{"i":51,"n":"第五十一条","txt":"抵押人所担保的债权超出其抵押物价值的，超出的部分不具有优先受偿的效力。"},{"i":52,"n":"第五十二条","txt":"当事人以农作物和与其尚未分离的土地使用权同时抵押的，土地使用权部分的抵押无效。"},{"i":53,"n":"第五十三条","txt":"学校、幼儿园、医院等以公益为目的的事业单位、社会团体，以其教育设施、医疗卫生设施和其他社会公益设施以外的财产为自身债务设定抵押的，人民法院可以认定抵押有效。"},{"i":54,"n":"第五十四条","txt":"按份共有人以其共有财产中享有的份额设定抵押的，抵押有效。"},{"i":55,"n":"第五十五条","txt":"已经设定抵押的财产被采取查封、扣押等财产保全或者执行措施的，不影响抵押权的效力。"},{"i":56,"n":"第五十六条","txt":"抵押合同对被担保的主债权种类、抵押财产没有约定或者约定不明，根据主合同和抵押合同不能补正或者无法推定的，抵押不成立。"},{"i":57,"n":"第五十七条","txt":"当事人在抵押合同中约定，债务履行期届满抵押权人未受清偿时，抵押物的所有权转移为债权人所有的内容无效。该内容的无效不影响抵押合同其他部分内容的效力。"},{"i":58,"n":"第五十八条","txt":"当事人同一天在不同的法定登记部门办理抵押物登记的，视为顺序相同。"},{"i":59,"n":"第五十九条","txt":"当事人办理抵押物登记手续时，因登记部门的原因致使其无法办理抵押物登记，抵押人向债权人交付权利凭证的，可以认定债权人对该财产有优先受偿权。但是，未办理抵押物登记的，不得对抗第三人。"},{"i":60,"n":"第六十条","txt":"以担保法第四十二条第（二）项规定的不动产抵押的，县级以上地方人民政府对登记部门未作规定，当事人在土地管理部门或者房产管理部门办理了抵押物登记手续，人民法院可以确认其登记的效力。"},{"i":61,"n":"第六十一条","txt":"抵押物登记记载的内容与抵押合同约定的内容不一致的，以登记记载的内容为准。"},{"i":62,"n":"第六十二条","txt":"抵押物因附合、混合或者加工使抵押物的所有权为第三人所有的，抵押权的效力及于补偿金；抵押物所有人为附合物、混合物或者加工物的所有人的，抵押权的效力及于附合物、混合物或者加工物；第三人与抵押物所有人为附合物、混合物或者加工物的共有人的，抵押权的效力及于抵押人对共有物享有的份额。"},{"i":63,"n":"第六十三条","txt":"抵押权设定前为抵押物的从物的，抵押权的效力及于抵押物的从物。但是，抵押物与其从物为两个以上的人分别所有时，抵押权的效力不及于抵押物的从物。"},{"i":64,"n":"第六十四条","txt":"债务履行期届满，债务人不履行债务致使抵押物被人民法院依法扣押的，自扣押之日起抵押权人收取的由抵押物分离的天然孳息和法定孳息，按照下列顺序清偿："},{"i":65,"n":"第六十五条","txt":"抵押人将已出租的财产抵押的，抵押权实现后，租赁合同在有效期内对抵押物的受让人继续有效。"},{"i":66,"n":"第六十六条","txt":"抵押人将已抵押的财产出租的，抵押权实现后，租赁合同对受让人不具有约束力。"},{"i":67,"n":"第六十七条","txt":"抵押权存续期间，抵押人转让抵押物未通知抵押权人或者未告知受让人的，如果抵押物已经登记的，抵押权人仍可以行使抵押权；取得抵押物所有权的受让人，可以代替债务人清偿其全部债务，使抵押权消灭。受让人清偿债务后可以向抵押人追偿。"},{"i":68,"n":"第六十八条","txt":"抵押物依法被继承或者赠与的，抵押权不受影响。"},{"i":69,"n":"第六十九条","txt":"债务人有多个普通债权人的，在清偿债务时，债务人与其中一个债权人恶意串通，将其全部或者部分财产抵押给该债权人，因此丧失了履行其他债务的能力，损害了其他债权人的合法权益，受损害的其他债权人可以请求人民法院撤销该抵押行为。"},{"i":70,"n":"第七十条","txt":"抵押人的行为足以使抵押物价值减少的，抵押权人请求抵押人恢复原状或提供担保遭到拒绝时，抵押权人可以请求债务人履行债务，也可以请求提前行使抵押权。"},{"i":71,"n":"第七十一条","txt":"主债权未受全部清偿的，抵押权人可以就抵押物的全部行使其抵押权。"},{"i":72,"n":"第七十二条","txt":"主债权被分割或者部分转让的，各债权人可以就其享有的债权份额行使抵押权。"},{"i":73,"n":"第七十三条","txt":"抵押物折价或者拍卖、变卖该抵押物的价款低于抵押权设定时约定价值的，应当按照抵押物实现的价值进行清偿。不足清偿的剩余部分，由债务人清偿。"},{"i":74,"n":"第七十四条","txt":"抵押物折价或者拍卖、变卖所得的价款，当事人没有约定的，按下列顺序清偿："},{"i":75,"n":"第七十五条","txt":"同一债权有两个以上抵押人的，债权人放弃债务人提供的抵押担保的，其他抵押人可以请求人民法院减轻或者免除其应当承担的担保责任。"},{"i":76,"n":"第七十六条","txt":"同一动产向两个以上债权人抵押的，当事人未办理抵押物登记，实现抵押权时，各抵押权人按照债权比例受偿。"},{"i":77,"n":"第七十七条","txt":"同一财产向两个以上债权人抵押的，顺序在先的抵押权与该财产的所有权归属一人时，该财产的所有权人可以以其抵押权对抗顺序在后的抵押权。"},{"i":78,"n":"第七十八条","txt":"同一财产向两个以上债权人抵押的，顺序在后的抵押权所担保的债权先到期的，抵押权人只能就抵押物价值超出顺序在先的抵押担保债权的部分受偿。"},{"i":79,"n":"第七十九条","txt":"同一财产法定登记的抵押权与质权并存时，抵押权人优先于质权人受偿。"},{"i":80,"n":"第八十条","txt":"在抵押物灭失、毁损或者被征用的情况下，抵押权人可以就该抵押物的保险金、赔偿金或者补偿金优先受偿。"},{"i":81,"n":"第八十一条","txt":"最高额抵押权所担保的债权范围，不包括抵押物因财产保全或者执行程序被查封后或债务人、抵押人破产后发生的债权。"},{"i":82,"n":"第八十二条","txt":"当事人对最高额抵押合同的最高限额、最高额抵押期间进行变更，以其变更对抗顺序在后的抵押权人的，人民法院不予支持。"},{"i":83,"n":"第八十三条","txt":"最高额抵押权所担保的不特定债权，在特定后，债权已届清偿期的，最高额抵押权人可以根据普通抵押权的规定行使其抵押权。"},{"i":84,"n":"第八十四条","txt":"出质人以其不具有所有权但合法占有的动产出质的，不知出质人无处分权的质权人行使质权后，因此给动产所有人造成损失的，由出质人承担赔偿责任。"},{"i":85,"n":"第八十五条","txt":"债务人或者第三人将其金钱以特户、封金、保证金等形式特定化后，移交债权人占有作为债权的担保，债务人不履行债务时，债权人可以以该金钱优先受偿。"},{"i":86,"n":"第八十六条","txt":"债务人或者第三人未按质押合同约定的时间移交质物的，因此给质权人造成损失的，出质人应当根据其过错承担赔偿责任。"},{"i":87,"n":"第八十七条","txt":"出质人代质权人占有质物的，质押合同不生效；质权人将质物返还于出质人后，以其质权对抗第三人的，人民法院不予支持。"},{"i":88,"n":"第八十八条","txt":"出质人以间接占有的财产出质的，质押合同自书面通知送达占有人时视为移交。占有人收到出质通知后，仍接受出质人的指示处分出质财产的，该行为无效。"},{"i":89,"n":"第八十九条","txt":"质押合同中对质押的财产约定不明，或者约定的出质财产与实际移交的财产不一致的，以实际交付占有的财产为准。"},{"i":90,"n":"第九十条","txt":"质物有隐蔽瑕疵造成质权人其他财产损害的，应由出质人承担赔偿责任。但是，质权人在质物移交时明知质物有瑕疵而予以接受的除外。"},{"i":91,"n":"第九十一条","txt":"动产质权的效力及于质物的从物。但是，从物未随同质物移交质权人占有的，质权的效力不及于从物。"},{"i":92,"n":"第九十二条","txt":"按照担保法第六十九条的规定将质物提存的，质物提存费用由质权人负担；出质人提前清偿债权的，应当扣除未到期部分的利息。"},{"i":93,"n":"第九十三条","txt":"质权人在质权存续期间，未经出质人同意，擅自使用、出租、处分质物，因此给出质人造成损失的，由质权人承担赔偿责任。"},{"i":94,"n":"第九十四条","txt":"质权人在质权存续期间，为担保自己的债务，经出质人同意，以其所占有的质物为第三人设定质权的，应当在原质权所担保的债权范围之内，超过的部分不具有优先受偿的效力。转质权的效力优于原质权。"},{"i":95,"n":"第九十五条","txt":"债务履行期届满质权人未受清偿的，质权人可以继续留置质物，并以质物的全部行使权利。出质人清偿所担保的债权后，质权人应当返还质物。"},{"i":96,"n":"第九十六条","txt":"本解释第五十七条、第六十二条、第六十四条、第七十一条、第七十二条、第七十三条、第七十四条、第八十条之规定，适用于动产质押。"},{"i":97,"n":"第九十七条","txt":"以公路桥梁、公路隧道或者公路渡口等不动产收益权出质的，按照担保法第七十五条第（四）项的规定处理。"},{"i":98,"n":"第九十八条","txt":"以汇票、支票、本票出质，出质人与质权人没有背书记载“质押”字样，以票据出质对抗善意第三人的，人民法院不予支持。"},{"i":99,"n":"第九十九条","txt":"以公司债券出质的，出质人与质权人没有背书记载“质押”字样，以债券出质对抗公司和第三人的，人民法院不予支持。"},{"i":100,"n":"第一百条","txt":"以存款单出质的，签发银行核押后又受理挂失并造成存款流失的，应当承担民事责任。"},{"i":101,"n":"第一百零一条","txt":"以票据、债券、存款单、仓单、提单出质的，质权人再转让或者质押的无效。"},{"i":102,"n":"第一百零二条","txt":"以载明兑现或者提货日期的汇票、支票、本票、债券、存款单、仓单、提单出质的，其兑现或者提货日期后于债务履行期的，质权人只能在兑现或者提货日期届满时兑现款项或者提取货物。"},{"i":103,"n":"第一百零三条","txt":"以股份有限公司的股份出质的，适用《中华人民共和国公司法》有关股份转让的规定。"},{"i":104,"n":"第一百零四条","txt":"以依法可以转让的股份、股票出质的，质权的效力及于股份、股票的法定孳息。"},{"i":105,"n":"第一百零五条","txt":"以依法可以转让的商标专用权，专利权、著作权中的财产权出质的，出质人未经质权人同意而转让或者许可他人使用已出质权利的，应当认定为无效。因此给质权人或者第三人造成损失的，由出质人承担民事责任。"},{"i":106,"n":"第一百零六条","txt":"质权人向出质人、出质债权的债务人行使质权时，出质人、出质债权的债务人拒绝的，质权人可以起诉出质人和出质债权的债务人，也可以单独起诉出质债权的债务人。"},{"i":107,"n":"第一百零七条","txt":"当事人在合同中约定排除留置权，债务履行期届满，债权人行使留置权的，人民法院不予支持。"},{"i":108,"n":"第一百零八条","txt":"债权人合法占有债务人交付的动产时，不知债务人无处分该动产的权利，债权人可以按照担保法第八十二条的规定行使留置权。"},{"i":109,"n":"第一百零九条","txt":"债权人的债权已届清偿期，债权人对动产的占有与其债权的发生有牵连关系，债权人可以留置其所占有的动产。"},{"i":110,"n":"第一百一十条","txt":"留置权人在债权未受全部清偿前，留置物为不可分物的，留置权人可以就其留置物的全部行使留置权。"},{"i":111,"n":"第一百一十一条","txt":"债权人行使留置权与其承担的义务或者合同的特殊约定相抵触的，人民法院不予支持。"},{"i":112,"n":"第一百一十二条","txt":"债权人的债权未届清偿期，其交付占有标的物的义务已届履行期的，不能行使留置权。但是，债权人能够证明债务人无支付能力的除外。"},{"i":113,"n":"第一百一十三条","txt":"债权人未按担保法第八十七条规定的期限通知债务人履行义务，直接变价处分留置物的，应当对此造成的损失承担赔偿责任。债权人与债务人按照担保法第八十七条的规定在合同中约定宽限期的，债权人可以不经通知，直接行使留置权。"},{"i":114,"n":"第一百一十四条","txt":"本解释第六十四条、第八十条、第八十七条、第九十一条、第九十三条的规定，适用于留置。"},{"i":115,"n":"第一百一十五条","txt":"当事人约定以交付定金作为订立主合同担保的，给付定金的一方拒绝订立主合同的，无权要求返还定金；收受定金的一方拒绝订立合同的，应当双倍返还定金。"},{"i":116,"n":"第一百一十六条","txt":"当事人约定以交付定金作为主合同成立或者生效要件的，给付定金的一方未支付定金，但主合同已经履行或者已经履行主要部分的，不影响主合同的成立或者生效。"},{"i":117,"n":"第一百一十七条","txt":"定金交付后，交付定金的一方可以按照合同的约定以丧失定金为代价而解除主合同，收受定金的一方可以双倍返还定金为代价而解除主合同。对解除主合同后责任的处理，适用《中华人民共和国合同法》的规定。"},{"i":118,"n":"第一百一十八条","txt":"当事人交付留置金、担保金、保证金、订约金、押金或者订金等，但没有约定定金性质的，当事人主张定金权利的，人民法院不予支持。"},{"i":119,"n":"第一百一十九条","txt":"实际交付的定金数额多于或者少于约定数额，视为变更定金合同；收受定金一方提出异议并拒绝接受定金的，定金合同不生效。"},{"i":120,"n":"第一百二十条","txt":"因当事人一方迟延履行或者其他违约行为，致使合同目的不能实现，可以适用定金罚则。但法律另有规定或者当事人另有约定的除外。"},{"i":121,"n":"第一百二十一条","txt":"当事人约定的定金数额超过主合同标的额20%的，超过的部分，人民法院不予支持。"},{"i":122,"n":"第一百二十二条","txt":"因不可抗力、意外事件致使主合同不能履行的，不适用定金罚则。因合同关系以外第三人的过错，致使主合同不能履行的，适用定金罚则。受定金处罚的一方当事人，可以依法向第三人追偿。"},{"i":123,"n":"第一百二十三条","txt":"同一债权上数个担保物权并存时，债权人放弃债务人提供的物的担保的，其他担保人在其放弃权利的范围内减轻或者免除担保责任。"},{"i":124,"n":"第一百二十四条","txt":"企业法人的分支机构为他人提供保证的，人民法院在审理保证纠纷案件中可以将该企业法人作为共同被告参加诉讼。但是商业银行、保险公司的分支机构提供保证的除外。"},{"i":125,"n":"第一百二十五条","txt":"一般保证的债权人向债务人和保证人一并提起诉讼的，人民法院可以将债务人和保证人列为共同被告参加诉讼。但是，应当在判决书中明确在对债务人财产依法强制执行后仍不能履行债务时，由保证人承担保证责任。"},{"i":126,"n":"第一百二十六条","txt":"连带责任保证的债权人可以将债务人或者保证人作为被告提起诉讼，也可以将债务人和保证人作为共同被告提起诉讼。"},{"i":127,"n":"第一百二十七条","txt":"债务人对债权人提起诉讼，债权人提起反诉的，保证人可以作为第三人参加诉讼。"},{"i":128,"n":"第一百二十八条","txt":"债权人向人民法院请求行使担保物权时，债务人和担保人应当作为共同被告参加诉讼。"},{"i":129,"n":"第一百二十九条","txt":"主合同和担保合同发生纠纷提起诉讼的，应当根据主合同确定案件管辖。担保人承担连带责任的担保合同发生纠纷，债权人向担保人主张权利的，应当由担保人住所地的法院管辖。"},{"i":130,"n":"第一百三十条","txt":"在主合同纠纷案件中，对担保合同未经审判，人民法院不应当依据对主合同当事人所作出的判决或者裁定，直接执行担保人的财产。"},{"i":131,"n":"第一百三十一条","txt":"本解释所称“不能清偿”指对债务人的存款、现金、有价证券、成品、半成品、原材料、交通工具等可以执行的动产和其他方便执行的财产执行完毕后，债务仍未能得到清偿的状态。"},{"i":132,"n":"第一百三十二条","txt":"在案件审理或者执行程序中，当事人提供财产担保的，人民法院应当对该财产的权属证书予以扣押，同时向有关部门发出协助执行通知书，要求其在规定的时间内不予办理担保财产的转移手续。"},{"i":133,"n":"第一百三十三条","txt":"担保法施行以前发生的担保行为，适用担保行为发生时的法律、法规和有关司法解释。"},{"i":134,"n":"第一百三十四条","txt":"最高人民法院在担保法施行以前作出的有关担保问题的司法解释，与担保法和本解释相抵触的，不再适用。"}],"zuigaorenminfayuanguanyushiyongducuchengxuruoganwea3652d":[{"i":1,"n":"第一条","txt":"基层人民法院受理债权人依法申请支付令的案件，不受争议金额的限制。"},{"i":2,"n":"第二条","txt":"共同债务人住所地、经常居住地不在同一基层人民法院辖区，各有关人民法院都有管辖权的，债权人可以向其中任何一个基层人民法院申请支付令；债权人向两个以上有管辖权的人民法院申请支付令的，由最先立案的人民法院管辖。"},{"i":3,"n":"第三条","txt":"人民法院收到债权人的书面申请后，认为申请书不符合要求的，人民法院可以通知债权人限期补正。补正期间不计入民事诉讼法第一百九十条规定的期限。"},{"i":4,"n":"第四条","txt":"对设有担保的债务案件主债务人发出的支付令，对担保人没有拘束力。债权人就担保关系单独提起诉讼的，支付令自行失效。"},{"i":5,"n":"第五条","txt":"人民法院受理债权人的支付令申请后，经审理，有下列情况之一的，应当裁定驳回申请："},{"i":6,"n":"第六条","txt":"人民法院受理支付令申请后，债权人就同一债权关系又提起诉讼，或者人民法院发出支付令之日起30日内无法送达债务人的，应当裁定终结督促程序。"},{"i":7,"n":"第七条","txt":"债务人对债权债务关系没有异议，但对清偿能力、清偿期限、清偿方式等提出不同意见的，不影响支付令的效力。"},{"i":8,"n":"第八条","txt":"债权人基于同一债权债务关系，向债务人提出多项支付请求，债务人仅就其中一项或几项请求提出异议的，不影响其他各项请求的效力。"},{"i":9,"n":"第九条","txt":"债权人基于同一债权债务关系，就可分之债向多个债务人提出支付请求，多个债务人中的1人或几人提出异议的，不影响其他请求的效力。"},{"i":10,"n":"第十条","txt":"人民法院作出终结督促程序前，债务人请求撤回异议的，应当准许。"},{"i":11,"n":"第十一条","txt":"人民法院院长对本院已发生法律效力的支付令，发现确有错误，认为需要撤销的，应当提交审判委员会讨论决定后，裁定撤销支付令，驳回债权人的申请。"},{"i":12,"n":"第十二条","txt":"最高人民法院有关适用督促程序的其他司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushiyonghetongfaruoganwenti105689":[{"i":1,"n":"第一条","txt":"当事人对合同是否成立存在争议，人民法院能够确定当事人名称或者姓名、标的和数量的，一般应当认定合同成立。但法律另有规定或者当事人另有约定的除外。"},{"i":2,"n":"第二条","txt":"当事人未以书面形式或者口头形式订立合同，但从双方从事的民事行为能够推定双方有订立合同意愿的，人民法院可以认定是以合同法第十条第一款中的“其他形式”订立的合同。但法律另有规定的除外。"},{"i":3,"n":"第三条","txt":"悬赏人以公开方式声明对完成一定行为的人支付报酬，完成特定行为的人请求悬赏人支付报酬的，人民法院依法予以支持。但悬赏有合同法第五十二条规定情形的除外。"},{"i":4,"n":"第四条","txt":"采用书面形式订立合同，合同约定的签订地与实际签字或者盖章地点不符的，人民法院应当认定约定的签订地为合同签订地；合同没有约定签订地，双方当事人签字或者盖章不在同一地点的，人民法院应当认定最后签字或者盖章的地点为合同签订地。"},{"i":5,"n":"第五条","txt":"当事人采用合同书形式订立合同的，应当签字或者盖章。当事人在合同书上摁手印的，人民法院应当认定其具有与签字或者盖章同等的法律效力。"},{"i":6,"n":"第六条","txt":"提供格式条款的一方对格式条款中免除或者限制其责任的内容，在合同订立时采用足以引起对方注意的文字、符号、字体等特别标识，并按照对方的要求对该格式条款予以说明的，人民法院应当认定符合合同法第三十九条所称“采取合理的方式”。"},{"i":7,"n":"第七条","txt":"下列情形，不违反法律、行政法规强制性规定的，人民法院可以认定为合同法所称“交易习惯”："},{"i":8,"n":"第八条","txt":"依照法律、行政法规的规定经批准或者登记才能生效的合同成立后，有义务办理申请批准或者申请登记等手续的一方当事人未按照法律规定或者合同约定办理申请批准或者未申请登记的，属于合同法第四十二条第（三）项规定的“其他违背诚实信用原则的行为”，人民法院可以根据案件的具体情况和相对人的请求，判决相对人自己办理有关手续；对方当事人对由此产生的费用和给相对人造成的实际损失，应当承担损害赔偿责任。"},{"i":9,"n":"第九条","txt":"提供格式条款的一方当事人违反合同法第三十九条第一款关于提示和说明义务的规定，导致对方没有注意免除或者限制其责任的条款，对方当事人申请撤销该格式条款的，人民法院应当支持。"},{"i":10,"n":"第十条","txt":"提供格式条款的一方当事人违反合同法第三十九条第一款的规定，并具有合同法第四十条规定的情形之一的，人民法院应当认定该格式条款无效。"},{"i":11,"n":"第十一条","txt":"根据合同法第四十七条、第四十八条的规定，追认的意思表示自到达相对人时生效，合同自订立时起生效。"},{"i":12,"n":"第十二条","txt":"无权代理人以被代理人的名义订立合同，被代理人已经开始履行合同义务的，视为对合同的追认。"},{"i":13,"n":"第十三条","txt":"被代理人依照合同法第四十九条的规定承担有效代理行为所产生的责任后，可以向无权代理人追偿因代理行为而遭受的损失。"},{"i":14,"n":"第十四条","txt":"合同法第五十二条第（五）项规定的“强制性规定”，是指效力性强制性规定。"},{"i":15,"n":"第十五条","txt":"出卖人就同一标的物订立多重买卖合同，合同均不具有合同法第五十二条规定的无效情形，买受人因不能按照合同约定取得标的物所有权，请求追究出卖人违约责任的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"人民法院根据具体案情可以将合同法第六十四条、第六十五条规定的第三人列为无独立请求权的第三人，但不得依职权将其列为该合同诉讼案件的被告或者有独立请求权的第三人。"},{"i":17,"n":"第十七条","txt":"债权人以境外当事人为被告提起的代位权诉讼，人民法院根据《中华人民共和国民事诉讼法》第二百四十一条的规定确定管辖。"},{"i":18,"n":"第十八条","txt":"债务人放弃其未到期的债权或者放弃债权担保，或者恶意延长到期债权的履行期，对债权人造成损害，债权人依照合同法第七十四条的规定提起撤销权诉讼的，人民法院应当支持。"},{"i":19,"n":"第十九条","txt":"对于合同法第七十四条规定的“明显不合理的低价”，人民法院应当以交易当地一般经营者的判断，并参考交易当时交易地的物价部门指导价或者市场交易价，结合其他相关因素综合考虑予以确认。"},{"i":20,"n":"第二十条","txt":"债务人的给付不足以清偿其对同一债权人所负的数笔相同种类的全部债务，应当优先抵充已到期的债务；几项债务均到期的，优先抵充对债权人缺乏担保或者担保数额最少的债务；担保数额相同的，优先抵充债务负担较重的债务；负担相同的，按照债务到期的先后顺序抵充；到期时间相同的，按比例抵充。但是，债权人与债务人对清偿的债务或者清偿抵充顺序有约定的除外。"},{"i":21,"n":"第二十一条","txt":"债务人除主债务之外还应当支付利息和费用，当其给付不足以清偿全部债务时，并且当事人没有约定的，人民法院应当按照下列顺序抵充："},{"i":22,"n":"第二十二条","txt":"当事人一方违反合同法第九十二条规定的义务，给对方当事人造成损失，对方当事人请求赔偿实际损失的，人民法院应当支持。"},{"i":23,"n":"第二十三条","txt":"对于依照合同法第九十九条的规定可以抵销的到期债权，当事人约定不得抵销的，人民法院可以认定该约定有效。"},{"i":24,"n":"第二十四条","txt":"当事人对合同法第九十六条、第九十九条规定的合同解除或者债务抵销虽有异议，但在约定的异议期限届满后才提出异议并向人民法院起诉的，人民法院不予支持；当事人没有约定异议期间，在解除合同或者债务抵销通知到达之日起三个月以后才向人民法院起诉的，人民法院不予支持。"},{"i":25,"n":"第二十五条","txt":"依照合同法第一百零一条的规定，债务人将合同标的物或者标的物拍卖、变卖所得价款交付提存部门时，人民法院应当认定提存成立。"},{"i":26,"n":"第二十六条","txt":"合同成立以后客观情况发生了当事人在订立合同时无法预见的、非不可抗力造成的不属于商业风险的重大变化，继续履行合同对于一方当事人明显不公平或者不能实现合同目的，当事人请求人民法院变更或者解除合同的，人民法院应当根据公平原则，并结合案件的实际情况确定是否变更或者解除。"},{"i":27,"n":"第二十七条","txt":"当事人通过反诉或者抗辩的方式，请求人民法院依照合同法第一百一十四条第二款的规定调整违约金的，人民法院应予支持。"},{"i":28,"n":"第二十八条","txt":"当事人依照合同法第一百一十四条第二款的规定，请求人民法院增加违约金的，增加后的违约金数额以不超过实际损失额为限。增加违约金以后，当事人又请求对方赔偿损失的，人民法院不予支持。"},{"i":29,"n":"第二十九条","txt":"当事人主张约定的违约金过高请求予以适当减少的，人民法院应当以实际损失为基础，兼顾合同的履行情况、当事人的过错程度以及预期利益等综合因素，根据公平原则和诚实信用原则予以衡量，并作出裁决。"},{"i":30,"n":"第三十条","txt":"合同法施行后成立的合同发生纠纷的案件，本解释施行后尚未终审的，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的，不适用本解释。"}],"zuigaorenminfayuanguanyushiyonghetongfaruoganwenti7ea7cc":[{"i":1,"n":"第一条","txt":"合同法实施以后成立的合同发生纠纷起诉到人民法院的，适用合同法的规定；合同法实施以前成立的合同发生纠纷起诉到人民法院的，除本解释另有规定的以外，适用当时的法律规定，当时没有法律规定的，可以适用合同法的有关规定。"},{"i":2,"n":"第二条","txt":"合同成立于合同法实施之前，但合同约定的履行期限跨越合同法实施之日或者履行期限在合同法实施之后，因履行合同发生的纠纷，适用合同法第四章的有关规定。"},{"i":3,"n":"第三条","txt":"人民法院确认合同效力时，对合同法实施以前成立的合同，适用当时的法律合同无效而适用合同法合同有效的，则适用合同法。"},{"i":4,"n":"第四条","txt":"合同法实施以后，人民法院确认合同无效，应当以全国人大及其常委会制定的法律和国务院制定的行政法规为依据，不得以地方性法规、行政规章为依据。"},{"i":5,"n":"第五条","txt":"人民法院对合同法实施以前已经作出终审裁决的案件进行再审，不适用合同法。"},{"i":6,"n":"第六条","txt":"技术合同争议当事人的权利受到侵害的事实发生在合同法实施之前，自当事人知道或者应当知道其权利受到侵害之日起至合同法实施之日超过1年的，人民法院不予保护；尚未超过1年的，其提起诉讼的时效期间为2年。"},{"i":7,"n":"第七条","txt":"技术进出口合同争议当事人的权利受到侵害的事实发生在合同法实施之前，自当事人知道或者应当知道其权利受到侵害之日起至合同法施行之日超过2年的，人民法院不予保护；尚未超过2年的，其提起诉讼的时效期间为4年。"},{"i":8,"n":"第八条","txt":"合同法第五十五条规定的“1年”、第七十五条和第一百零四条第二款规定的“5年”为不变期间，不适用诉讼时效中止、中断或者延长的规定。"},{"i":9,"n":"第九条","txt":"依照合同法第四十四条第二款的规定，法律、行政法规规定合同应当办理批准手续，或者办理批准、登记等手续才生效，在一审法庭辩论终结前当事人仍未办理批准手续的，或者仍未办理批准、登记等手续的，人民法院应当认定该合同未生效；法律、行政法规规定合同应当办理登记手续，但未规定登记后生效的，当事人未办理登记手续不影响合同的效力，合同标的物所有权及其他物权不能转移。"},{"i":10,"n":"第十条","txt":"当事人超越经营范围订立合同，人民法院不因此认定合同无效。但违反国家限制经营、特许经营以及法律、行政法规禁止经营规定的除外。"},{"i":11,"n":"第十一条","txt":"债权人依照合同法第七十三条的规定提起代位权诉讼，应当符合下列条件："},{"i":12,"n":"第十二条","txt":"合同法第七十三条第一款规定的专属于债务人自身的债权，是指基于扶养关系、抚养关系、赡养关系、继承关系产生的给付请求权和劳动报酬、退休金、养老金、抚恤金、安置费、人寿保险、人身伤害赔偿请求权等权利。"},{"i":13,"n":"第十三条","txt":"合同法第七十三条规定的“债务人怠于行使其到期债权，对债权人造成损害的”，是指债务人不履行其对债权人的到期债务，又不以诉讼方式或者仲裁方式向其债务人主张其享有的具有金钱给付内容的到期债权，致使债权人的到期债权未能实现。"},{"i":14,"n":"第十四条","txt":"债权人依照合同法第七十三条的规定提起代位权诉讼的，由被告住所地人民法院管辖。"},{"i":15,"n":"第十五条","txt":"债权人向人民法院起诉债务人以后，又向同一人民法院对次债务人提起代位权诉讼，符合本解释第十四条的规定和《中华人民共和国民事诉讼法》第一百零八条规定的起诉条件的，应当立案受理；不符合本解释第十四条规定的，告知债权人向次债务人住所地人民法院另行起诉。"},{"i":16,"n":"第十六条","txt":"债权人以次债务人为被告向人民法院提起代位权诉讼，未将债务人列为第三人的，人民法院可以追加债务人为第三人。"},{"i":17,"n":"第十七条","txt":"在代位权诉讼中，债权人请求人民法院对次债务人的财产采取保全措施的，应当提供相应的财产担保。"},{"i":18,"n":"第十八条","txt":"在代位权诉讼中，次债务人对债务人的抗辩，可以向债权人主张。"},{"i":19,"n":"第十九条","txt":"在代位权诉讼中，债权人胜诉的，诉讼费由次债务人负担，从实现的债权中优先支付。"},{"i":20,"n":"第二十条","txt":"债权人向次债务人提起的代位权诉讼经人民法院审理后认定代位权成立的，由次债务人向债权人履行清偿义务，债权人与债务人、债务人与次债务人之间相应的债权债务关系即予消灭。"},{"i":21,"n":"第二十一条","txt":"在代位权诉讼中，债权人行使代位权的请求数额超过债务人所负债务额或者超过次债务人对债务人所负债务额的，对超出部分人民法院不予支持。"},{"i":22,"n":"第二十二条","txt":"债务人在代位权诉讼中，对超过债权人代位请求数额的债权部分起诉次债务人的，人民法院应当告知其向有管辖权的人民法院另行起诉。"},{"i":23,"n":"第二十三条","txt":"债权人依照合同法第七十四条的规定提起撤销权诉讼的，由被告住所地人民法院管辖。"},{"i":24,"n":"第二十四条","txt":"债权人依照合同法第七十四条的规定提起撤销权诉讼时只以债务人为被告，未将受益人或者受让人列为第三人的，人民法院可以追加该受益人或者受让人为第三人。"},{"i":25,"n":"第二十五条","txt":"债权人依照合同法第七十四条的规定提起撤销权诉讼，请求人民法院撤销债务人放弃债权或转让财产的行为，人民法院应当就债权人主张的部分进行审理，依法撤销的，该行为自始无效。"},{"i":26,"n":"第二十六条","txt":"债权人行使撤销权所支付的律师代理费、差旅费等必要费用，由债务人负担；第三人有过错的，应当适当分担。"},{"i":27,"n":"第二十七条","txt":"债权人转让合同权利后，债务人与受让人之间因履行合同发生纠纷诉至人民法院，债务人对债权人的权利提出抗辩的，可以将债权人列为第三人。"},{"i":28,"n":"第二十八条","txt":"经债权人同意，债务人转移合同义务后，受让人与债权人之间因履行合同发生纠纷诉至人民法院，受让人就债务人对债权人的权利提出抗辩的，可以将债务人列为第三人。"},{"i":29,"n":"第二十九条","txt":"合同当事人一方经对方同意将其在合同中的权利义务一并转让给受让人，对方与受让人因履行合同发生纠纷诉至人民法院，对方就合同权利义务提出抗辩的，可以将出让方列为第三人。"},{"i":30,"n":"第三十条","txt":"债权人依照合同法第一百二十二条的规定向人民法院起诉时作出选择后，在一审开庭以前又变更诉讼请求的，人民法院应当准许。对方当事人提出管辖权异议，经审查异议成立的，人民法院应当驳回起诉。"}],"zuigaorenminfayuanguanyushiyonghunyinfaruoganwenti4e1ba7":[{"i":1,"n":"第一条","txt":"当事人以婚姻法第十条规定以外的情形申请宣告婚姻无效的，人民法院应当判决驳回当事人的申请。"},{"i":2,"n":"第二条","txt":"夫妻一方向人民法院起诉请求确认亲子关系不存在，并已提供必要证据予以证明，另一方没有相反证据又拒绝做亲子鉴定的，人民法院可以推定请求确认亲子关系不存在一方的主张成立。"},{"i":3,"n":"第三条","txt":"婚姻关系存续期间，父母双方或者一方拒不履行抚养子女义务，未成年或者不能独立生活的子女请求支付抚养费的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"婚姻关系存续期间，夫妻一方请求分割共同财产的，人民法院不予支持，但有下列重大理由且不损害债权人利益的除外："},{"i":5,"n":"第五条","txt":"夫妻一方个人财产在婚后产生的收益，除孳息和自然增值外，应认定为夫妻共同财产。"},{"i":6,"n":"第六条","txt":"婚前或者婚姻关系存续期间，当事人约定将一方所有的房产赠与另一方，赠与方在赠与房产变更登记之前撤销赠与，另一方请求判令继续履行的，人民法院可以按照合同法第一百八十六条的规定处理。"},{"i":7,"n":"第七条","txt":"婚后由一方父母出资为子女购买的不动产，产权登记在出资人子女名下的，可按照婚姻法第十八条第（三）项的规定，视为只对自己子女一方的赠与，该不动产应认定为夫妻一方的个人财产。"},{"i":8,"n":"第八条","txt":"无民事行为能力人的配偶有虐待、遗弃等严重损害无民事行为能力一方的人身权利或者财产权益行为，其他有监护资格的人可以依照特别程序要求变更监护关系；变更后的监护人代理无民事行为能力一方提起离婚诉讼的，人民法院应予受理。"},{"i":9,"n":"第九条","txt":"夫以妻擅自中止妊娠侵犯其生育权为由请求损害赔偿的，人民法院不予支持；夫妻双方因是否生育发生纠纷，致使感情确已破裂，一方请求离婚的，人民法院经调解无效，应依照婚姻法第三十二条第三款第（五）项的规定处理。"},{"i":10,"n":"第十条","txt":"夫妻一方婚前签订不动产买卖合同，以个人财产支付首付款并在银行贷款，婚后用夫妻共同财产还贷，不动产登记于首付款支付方名下的，离婚时该不动产由双方协议处理。"},{"i":11,"n":"第十一条","txt":"一方未经另一方同意出售夫妻共同共有的房屋，第三人善意购买、支付合理对价并办理产权登记手续，另一方主张追回该房屋的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"婚姻关系存续期间，双方用夫妻共同财产出资购买以一方父母名义参加房改的房屋，产权登记在一方父母名下，离婚时另一方主张按照夫妻共同财产对该房屋进行分割的，人民法院不予支持。购买该房屋时的出资，可以作为债权处理。"},{"i":13,"n":"第十三条","txt":"离婚时夫妻一方尚未退休、不符合领取养老保险金条件，另一方请求按照夫妻共同财产分割养老保险金的，人民法院不予支持；婚后以夫妻共同财产缴付养老保险费，离婚时一方主张将养老金账户中婚姻关系存续期间个人实际缴付部分作为夫妻共同财产分割的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"当事人达成的以登记离婚或者到人民法院协议离婚为条件的财产分割协议，如果双方协议离婚未成，一方在离婚诉讼中反悔的，人民法院应当认定该财产分割协议没有生效，并根据实际情况依法对夫妻共同财产进行分割。"},{"i":15,"n":"第十五条","txt":"婚姻关系存续期间，夫妻一方作为继承人依法可以继承的遗产，在继承人之间尚未实际分割，起诉离婚时另一方请求分割的，人民法院应当告知当事人在继承人之间实际分割遗产后另行起诉。"},{"i":16,"n":"第十六条","txt":"夫妻之间订立借款协议，以夫妻共同财产出借给一方从事个人经营活动或用于其他个人事务的，应视为双方约定处分夫妻共同财产的行为，离婚时可按照借款协议的约定处理。"},{"i":17,"n":"第十七条","txt":"夫妻双方均有婚姻法第四十六条规定的过错情形，一方或者双方向对方提出离婚损害赔偿请求的，人民法院不予支持。"},{"i":18,"n":"第十八条","txt":"离婚后，一方以尚有夫妻共同财产未处理为由向人民法院起诉请求分割的，经审查该财产确属离婚时未涉及的夫妻共同财产，人民法院应当依法予以分割。"},{"i":19,"n":"第十九条","txt":"本解释施行后，最高人民法院此前作出的相关司法解释与本解释相抵触的，以本解释为准。"}],"zuigaorenminfayuanguanyushiyonghunyinfaruoganwenti534b20":[{"i":1,"n":"第一条","txt":"当事人起诉请求解除同居关系的，人民法院不予受理。但当事人请求解除的同居关系，属于婚姻法第三条、第三十二条、第四十六条规定的“有配偶者与他人同居”的，人民法院应当受理并依法予以解除。"},{"i":2,"n":"第二条","txt":"人民法院受理申请宣告婚姻无效案件后，经审查确属无效婚姻的，应当依法作出宣告婚姻无效的判决。原告申请撤诉的，不予准许。"},{"i":3,"n":"第三条","txt":"人民法院受理离婚案件后，经审查确属无效婚姻的，应当将婚姻无效的情形告知当事人，并依法作出宣告婚姻无效的判决。"},{"i":4,"n":"第四条","txt":"人民法院审理无效婚姻案件，涉及财产分割和子女抚养的，应当对婚姻效力的认定和其他纠纷的处理分别制作裁判文书。"},{"i":5,"n":"第五条","txt":"夫妻一方或者双方死亡后一年内，生存一方或者利害关系人依据婚姻法第十条的规定申请宣告婚姻无效的，人民法院应当受理。"},{"i":6,"n":"第六条","txt":"利害关系人依据婚姻法第十条的规定，申请人民法院宣告婚姻无效的，利害关系人为申请人，婚姻关系当事人双方为被申请人。"},{"i":7,"n":"第七条","txt":"人民法院就同一婚姻关系分别受理了离婚和申请宣告婚姻无效案件的，对于离婚案件的审理，应当待申请宣告婚姻无效案件作出判决后进行。"},{"i":8,"n":"第八条","txt":"离婚协议中关于财产分割的条款或者当事人因离婚就财产分割达成的协议，对男女双方具有法律约束力。"},{"i":9,"n":"第九条","txt":"男女双方协议离婚后一年内就财产分割问题反悔，请求变更或者撤销财产分割协议的，人民法院应当受理。"},{"i":10,"n":"第十条","txt":"当事人请求返还按照习俗给付的彩礼的，如果查明属于以下情形，人民法院应当予以支持："},{"i":11,"n":"第十一条","txt":"婚姻关系存续期间，下列财产属于婚姻法第十七条规定的“其他应当归共同所有的财产”："},{"i":12,"n":"第十二条","txt":"婚姻法第十七条第三项规定的“知识产权的收益”，是指婚姻关系存续期间，实际取得或者已经明确可以取得的财产性收益。"},{"i":13,"n":"第十三条","txt":"军人的伤亡保险金、伤残补助金、医药生活补助费属于个人财产。"},{"i":14,"n":"第十四条","txt":"人民法院审理离婚案件，涉及分割发放到军人名下的复员费、自主择业费等一次性费用的，以夫妻婚姻关系存续年限乘以年平均值，所得数额为夫妻共同财产。"},{"i":15,"n":"第十五条","txt":"夫妻双方分割共同财产中的股票、债券、投资基金份额等有价证券以及未上市股份有限公司股份时，协商不成或者按市价分配有困难的，人民法院可以根据数量按比例分配。"},{"i":16,"n":"第十六条","txt":"人民法院审理离婚案件，涉及分割夫妻共同财产中以一方名义在有限责任公司的出资额，另一方不是该公司股东的，按以下情形分别处理："},{"i":17,"n":"第十七条","txt":"人民法院审理离婚案件，涉及分割夫妻共同财产中以一方名义在合伙企业中的出资，另一方不是该企业合伙人的，当夫妻双方协商一致，将其合伙企业中的财产份额全部或者部分转让给对方时，按以下情形分别处理："},{"i":18,"n":"第十八条","txt":"夫妻以一方名义投资设立独资企业的，人民法院分割夫妻在该独资企业中的共同财产时，应当按照以下情形分别处理："},{"i":19,"n":"第十九条","txt":"由一方婚前承租、婚后用共同财产购买的房屋，房屋权属证书登记在一方名下的，应当认定为夫妻共同财产。"},{"i":20,"n":"第二十条","txt":"双方对夫妻共同财产中的房屋价值及归属无法达成协议时，人民法院按以下情形分别处理："},{"i":21,"n":"第二十一条","txt":"离婚时双方对尚未取得所有权或者尚未取得完全所有权的房屋有争议且协商不成的，人民法院不宜判决房屋所有权的归属，应当根据实际情况判决由当事人使用。"},{"i":22,"n":"第二十二条","txt":"当事人结婚前，父母为双方购置房屋出资的，该出资应当认定为对自己子女的个人赠与，但父母明确表示赠与双方的除外。"},{"i":23,"n":"第二十三条","txt":"债权人就一方婚前所负个人债务向债务人的配偶主张权利的，人民法院不予支持。但债权人能够证明所负债务用于婚后家庭共同生活的除外。"},{"i":24,"n":"第二十四条","txt":"债权人就婚姻关系存续期间夫妻一方以个人名义所负债务主张权利的，应当按夫妻共同债务处理。但夫妻一方能够证明债权人与债务人明确约定为个人债务，或者能够证明属于婚姻法第十九条第三款规定情形的除外。"},{"i":25,"n":"第二十五条","txt":"当事人的离婚协议或者人民法院的判决书、裁定书、调解书已经对夫妻财产分割问题作出处理的，债权人仍有权就夫妻共同债务向男女双方主张权利。"},{"i":26,"n":"第二十六条","txt":"夫或妻一方死亡的，生存一方应当对婚姻关系存续期间的共同债务承担连带清偿责任。"},{"i":27,"n":"第二十七条","txt":"当事人在婚姻登记机关办理离婚登记手续后，以婚姻法第四十六条规定为由向人民法院提出损害赔偿请求的，人民法院应当受理。但当事人在协议离婚时已经明确表示放弃该项请求，或者在办理离婚登记手续一年后提出的，不予支持。"},{"i":28,"n":"第二十八条","txt":"夫妻一方申请对配偶的个人财产或者夫妻共同财产采取保全措施的，人民法院可以在采取保全措施可能造成损失的范围内，根据实际情况，确定合理的财产担保数额。"},{"i":29,"n":"第二十九条","txt":"本解释自2004年4月1日起施行。"}],"zuigaorenminfayuanguanyushiyonghunyinfaruoganwentib532d2":[{"i":1,"n":"第一条","txt":"婚姻法第三条、第三十二条、第四十三条、第四十五条、第四十六条所称的“家庭暴力”，是指行为人以殴打、捆绑、残害、强行限制人身自由或者其他手段，给其家庭成员的身体、精神等方面造成一定伤害后果的行为。持续性、经常性的家庭暴力，构成虐待。"},{"i":2,"n":"第二条","txt":"婚姻法第三条、第三十二条、第四十六条规定的“有配偶者与他人同居”的情形，是指有配偶者与婚外异性，不以夫妻名义，持续、稳定地共同居住。"},{"i":3,"n":"第三条","txt":"当事人仅以婚姻法第四条为依据提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":4,"n":"第四条","txt":"男女双方根据婚姻法第八条规定补办结婚登记的，婚姻关系的效力从双方均符合婚姻法所规定的结婚的实质要件时起算。"},{"i":5,"n":"第五条","txt":"未按婚姻法第八条规定办理结婚登记而以夫妻名义共同生活的男女，起诉到人民法院要求离婚的，应当区别对待："},{"i":6,"n":"第六条","txt":"未按婚姻法第八条规定办理结婚登记而以夫妻名义共同生活的男女，一方死亡，另一方以配偶身份主张享有继承权的，按照本解释第五条的原则处理。"},{"i":7,"n":"第七条","txt":"有权依据婚姻法第十条规定向人民法院就已办理结婚登记的婚姻申请宣告婚姻无效的主体，包括婚姻当事人及利害关系人。利害关系人包括："},{"i":8,"n":"第八条","txt":"当事人依据婚姻法第十条规定向人民法院申请宣告婚姻无效的，申请时，法定的无效婚姻情形已经消失的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"人民法院审理宣告婚姻无效案件，对婚姻效力的审理不适用调解，应当依法作出判决；有关婚姻效力的判决一经作出，即发生法律效力。"},{"i":10,"n":"第十条","txt":"婚姻法第十一条所称的“胁迫”，是指行为人以给另一方当事人或者其近亲属的生命、身体健康、名誉、财产等方面造成损害为要挟，迫使另一方当事人违背真实意愿结婚的情况。"},{"i":11,"n":"第十一条","txt":"人民法院审理婚姻当事人因受胁迫而请求撤销婚姻的案件，应当适用简易程序或者普通程序。"},{"i":12,"n":"第十二条","txt":"婚姻法第十一条规定的“1年”，不适用诉讼时效中止、中断或者延长的规定。"},{"i":13,"n":"第十三条","txt":"婚姻法第十二条所规定的自始无效，是指无效或者可撤销婚姻在依法被宣告无效或被撤销时，才确定该婚姻自始不受法律保护。"},{"i":14,"n":"第十四条","txt":"人民法院根据当事人的申请，依法宣告婚姻无效或者撤销婚姻的，应当收缴双方的结婚证书并将生效的判决书寄送当地婚姻登记管理机关。"},{"i":15,"n":"第十五条","txt":"被宣告无效或被撤销的婚姻，当事人同居期间所得的财产，按共同共有处理。但有证据证明为当事人一方所有的除外。"},{"i":16,"n":"第十六条","txt":"人民法院审理重婚导致的无效婚姻案件时，涉及财产处理的，应当准许合法婚姻当事人作为有独立请求权的第三人参加诉讼。"},{"i":17,"n":"第十七条","txt":"婚姻法第十七条关于“夫妻对夫妻共同所有的财产，有平等的处理权”的规定，应当理解为："},{"i":18,"n":"第十八条","txt":"婚姻法第十九条所称“第三人知道该约定的”，夫妻一方对此负有举证责任。"},{"i":19,"n":"第十九条","txt":"婚姻法第十八条规定为夫妻一方所有的财产，不因婚姻关系的延续而转化为夫妻共同财产。但当事人另有约定的除外。"},{"i":20,"n":"第二十条","txt":"婚姻法第二十一条规定的“不能独立生活的子女”，是指尚在校接受高中及其以下学历教育，或者丧失或未完全丧失劳动能力等非因主观原因而无法维持正常生活的成年子女。"},{"i":21,"n":"第二十一条","txt":"婚姻法第二十一条所称“抚养费”，包括子女生活费、教育费、医疗费等费用。"},{"i":22,"n":"第二十二条","txt":"人民法院审理离婚案件，符合第三十二条第三款规定“应准予离婚”情形的，不应当因当事人有过错而判决不准离婚。"},{"i":23,"n":"第二十三条","txt":"婚姻法第三十三条所称的“军人一方有重大过错”，可以依据婚姻法第三十二条第三款前三项规定及军人有其他重大过错导致夫妻感情破裂的情形予以判断。"},{"i":24,"n":"第二十四条","txt":"人民法院作出的生效的离婚判决中未涉及探望权，当事人就探望权问题单独提起诉讼的，人民法院应予受理。"},{"i":25,"n":"第二十五条","txt":"当事人在履行生效判决、裁定或者调解书的过程中，请求中止行使探望权的，人民法院在征询双方当事人意见后，认为需要中止行使探望权的，依法作出裁定。中止探望的情形消失后，人民法院应当根据当事人的申请通知其恢复探望权的行使。"},{"i":26,"n":"第二十六条","txt":"未成年子女、直接抚养子女的父或母及其他对未成年子女负担抚养、教育义务的法定监护人，有权向人民法院提出中止探望权的请求。"},{"i":27,"n":"第二十七条","txt":"婚姻法第四十二条所称“一方生活困难”，是指依靠个人财产和离婚时分得的财产无法维持当地基本生活水平。"},{"i":28,"n":"第二十八条","txt":"婚姻法第四十六条规定的“损害赔偿”，包括物质损害赔偿和精神损害赔偿。涉及精神损害赔偿的，适用最高人民法院《关于确定民事侵权精神损害赔偿责任若干问题的解释》的有关规定。"},{"i":29,"n":"第二十九条","txt":"承担婚姻法第四十六条规定的损害赔偿责任的主体，为离婚诉讼当事人中无过错方的配偶。"},{"i":30,"n":"第三十条","txt":"人民法院受理离婚案件时，应当将婚姻法第四十六条等规定中当事人的有关权利义务，书面告知当事人。在适用婚姻法第四十六条时，应当区分以下不同情况："},{"i":31,"n":"第三十一条","txt":"当事人依据婚姻法第四十七条的规定向人民法院提起诉讼，请求再次分割夫妻共同财产的诉讼时效为两年，从当事人发现之次日起计算。"},{"i":32,"n":"第三十二条","txt":"婚姻法第四十八条关于对拒不执行有关探望子女等判决和裁定的，由人民法院依法强制执行的规定，是指对拒不履行协助另一方行使探望权的有关个人和单位采取拘留、罚款等强制措施，不能对子女的人身、探望行为进行强制执行。"},{"i":33,"n":"第三十三条","txt":"婚姻法修改后正在审理的一、二审婚姻家庭纠纷案件，一律适用修改后的婚姻法。此前最高人民法院作出的相关司法解释如与本解释相抵触，以本解释为准。"},{"i":34,"n":"第三十四条","txt":"本解释自公布之日起施行。"}],"zuigaorenminfayuanguanyushiyonghunyinfaruoganwentif3480e":[{"i":1,"n":"第一条","txt":"当事人起诉请求解除同居关系的，人民法院不予受理。但当事人请求解除的同居关系，属于婚姻法第三条、第三十二条、第四十六条规定的“有配偶者与他人同居”的，人民法院应当受理并依法予以解除。"},{"i":2,"n":"第二条","txt":"人民法院受理申请宣告婚姻无效案件后，经审查确属无效婚姻的，应当依法作出宣告婚姻无效的判决。原告申请撤诉的，不予准许。"},{"i":3,"n":"第三条","txt":"人民法院受理离婚案件后，经审查确属无效婚姻的，应当将婚姻无效的情形告知当事人，并依法作出宣告婚姻无效的判决。"},{"i":4,"n":"第四条","txt":"人民法院审理无效婚姻案件，涉及财产分割和子女抚养的，应当对婚姻效力的认定和其他纠纷的处理分别制作裁判文书。"},{"i":5,"n":"第五条","txt":"夫妻一方或者双方死亡后一年内，生存一方或者利害关系人依据婚姻法第十条的规定申请宣告婚姻无效的，人民法院应当受理。"},{"i":6,"n":"第六条","txt":"利害关系人依据婚姻法第十条的规定，申请人民法院宣告婚姻无效的，利害关系人为申请人，婚姻关系当事人双方为被申请人。"},{"i":7,"n":"第七条","txt":"人民法院就同一婚姻关系分别受理了离婚和申请宣告婚姻无效案件的，对于离婚案件的审理，应当待申请宣告婚姻无效案件作出判决后进行。"},{"i":8,"n":"第八条","txt":"离婚协议中关于财产分割的条款或者当事人因离婚就财产分割达成的协议，对男女双方具有法律约束力。"},{"i":9,"n":"第九条","txt":"男女双方协议离婚后一年内就财产分割问题反悔，请求变更或者撤销财产分割协议的，人民法院应当受理。"},{"i":10,"n":"第十条","txt":"当事人请求返还按照习俗给付的彩礼的，如果查明属于以下情形，人民法院应当予以支持："},{"i":11,"n":"第十一条","txt":"婚姻关系存续期间，下列财产属于婚姻法第十七条规定的“其他应当归共同所有的财产”："},{"i":12,"n":"第十二条","txt":"婚姻法第十七条第三项规定的“知识产权的收益”，是指婚姻关系存续期间，实际取得或者已经明确可以取得的财产性收益。"},{"i":13,"n":"第十三条","txt":"军人的伤亡保险金、伤残补助金、医药生活补助费属于个人财产。"},{"i":14,"n":"第十四条","txt":"人民法院审理离婚案件，涉及分割发放到军人名下的复员费、自主择业费等一次性费用的，以夫妻婚姻关系存续年限乘以年平均值，所得数额为夫妻共同财产。"},{"i":15,"n":"第十五条","txt":"夫妻双方分割共同财产中的股票、债券、投资基金份额等有价证券以及未上市股份有限公司股份时，协商不成或者按市价分配有困难的，人民法院可以根据数量按比例分配。"},{"i":16,"n":"第十六条","txt":"人民法院审理离婚案件，涉及分割夫妻共同财产中以一方名义在有限责任公司的出资额，另一方不是该公司股东的，按以下情形分别处理："},{"i":17,"n":"第十七条","txt":"人民法院审理离婚案件，涉及分割夫妻共同财产中以一方名义在合伙企业中的出资，另一方不是该企业合伙人的，当夫妻双方协商一致，将其合伙企业中的财产份额全部或者部分转让给对方时，按以下情形分别处理："},{"i":18,"n":"第十八条","txt":"夫妻以一方名义投资设立独资企业的，人民法院分割夫妻在该独资企业中的共同财产时，应当按照以下情形分别处理："},{"i":19,"n":"第十九条","txt":"由一方婚前承租、婚后用共同财产购买的房屋，房屋权属证书登记在一方名下的，应当认定为夫妻共同财产。"},{"i":20,"n":"第二十条","txt":"双方对夫妻共同财产中的房屋价值及归属无法达成协议时，人民法院按以下情形分别处理："},{"i":21,"n":"第二十一条","txt":"离婚时双方对尚未取得所有权或者尚未取得完全所有权的房屋有争议且协商不成的，人民法院不宜判决房屋所有权的归属，应当根据实际情况判决由当事人使用。"},{"i":22,"n":"第二十二条","txt":"当事人结婚前，父母为双方购置房屋出资的，该出资应当认定为对自己子女的个人赠与，但父母明确表示赠与双方的除外。"},{"i":23,"n":"第二十三条","txt":"债权人就一方婚前所负个人债务向债务人的配偶主张权利的，人民法院不予支持。但债权人能够证明所负债务用于婚后家庭共同生活的除外。"},{"i":24,"n":"第二十四条","txt":"债权人就婚姻关系存续期间夫妻一方以个人名义所负债务主张权利的，应当按夫妻共同债务处理。但夫妻一方能够证明债权人与债务人明确约定为个人债务，或者能够证明属于婚姻法第十九条第三款规定情形的除外。"},{"i":25,"n":"第二十五条","txt":"当事人的离婚协议或者人民法院的判决书、裁定书、调解书已经对夫妻财产分割问题作出处理的，债权人仍有权就夫妻共同债务向男女双方主张权利。"},{"i":26,"n":"第二十六条","txt":"夫或妻一方死亡的，生存一方应当对婚姻关系存续期间的共同债务承担连带清偿责任。"},{"i":27,"n":"第二十七条","txt":"当事人在婚姻登记机关办理离婚登记手续后，以婚姻法第四十六条规定为由向人民法院提出损害赔偿请求的，人民法院应当受理。但当事人在协议离婚时已经明确表示放弃该项请求，或者在办理离婚登记手续一年后提出的，不予支持。"},{"i":28,"n":"第二十八条","txt":"夫妻一方申请对配偶的个人财产或者夫妻共同财产采取保全措施的，人民法院可以在采取保全措施可能造成损失的范围内，根据实际情况，确定合理的财产担保数额。"},{"i":29,"n":"第二十九条","txt":"本解释自2004年4月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfazongzesusongsh15200c":[{"i":1,"n":"第一条","txt":"民法总则施行后诉讼时效期间开始计算的，应当适用民法总则第一百八十八条关于三年诉讼时效期间的规定。当事人主张适用民法通则关于二年或者一年诉讼时效期间规定的，人民法院不予支持。"},{"i":2,"n":"第二条","txt":"民法总则施行之日，诉讼时效期间尚未满民法通则规定的二年或者一年，当事人主张适用民法总则关于三年诉讼时效期间规定的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"民法总则施行前，民法通则规定的二年或者一年诉讼时效期间已经届满，当事人主张适用民法总则关于三年诉讼时效期间规定的，人民法院不予支持。"},{"i":4,"n":"第四条","txt":"民法总则施行之日，中止时效的原因尚未消除的，应当适用民法总则关于诉讼时效中止的规定。"},{"i":5,"n":"第五条","txt":"本解释自2018年7月23日起施行。"}],"zuigaorenminfayuanguanyushiyongwuquanfaruoganwenti7d3c0c":[{"i":1,"n":"第一条","txt":"因不动产物权的归属，以及作为不动产物权登记基础的买卖、赠与、抵押等产生争议，当事人提起民事诉讼的，应当依法受理。当事人已经在行政诉讼中申请一并解决上述民事争议，且人民法院一并审理的除外。"},{"i":2,"n":"第二条","txt":"当事人有证据证明不动产登记簿的记载与真实权利状态不符、其为该不动产物权的真实权利人，请求确认其享有物权的，应予支持。"},{"i":3,"n":"第三条","txt":"异议登记因物权法第十九条第二款规定的事由失效后，当事人提起民事诉讼，请求确认物权归属的，应当依法受理。异议登记失效不影响人民法院对案件的实体审理。"},{"i":4,"n":"第四条","txt":"未经预告登记的权利人同意，转移不动产所有权，或者设定建设用地使用权、地役权、抵押权等其他物权的，应当依照物权法第二十条第一款的规定，认定其不发生物权效力。"},{"i":5,"n":"第五条","txt":"买卖不动产物权的协议被认定无效、被撤销、被解除，或者预告登记的权利人放弃债权的，应当认定为物权法第二十条第二款所称的“债权消灭”。"},{"i":6,"n":"第六条","txt":"转让人转移船舶、航空器和机动车等所有权，受让人已经支付对价并取得占有，虽未经登记，但转让人的债权人主张其为物权法第二十四条所称的“善意第三人”的，不予支持，法律另有规定的除外。"},{"i":7,"n":"第七条","txt":"人民法院、仲裁委员会在分割共有不动产或者动产等案件中作出并依法生效的改变原有物权关系的判决书、裁决书、调解书，以及人民法院在执行程序中作出的拍卖成交裁定书、以物抵债裁定书，应当认定为物权法第二十八条所称导致物权设立、变更、转让或者消灭的人民法院、仲裁委员会的法律文书。"},{"i":8,"n":"第八条","txt":"依照物权法第二十八条至第三十条规定享有物权，但尚未完成动产交付或者不动产登记的物权人，根据物权法第三十四条至第三十七条的规定，请求保护其物权的，应予支持。"},{"i":9,"n":"第九条","txt":"共有份额的权利主体因继承、遗赠等原因发生变化时，其他按份共有人主张优先购买的，不予支持，但按份共有人之间另有约定的除外。"},{"i":10,"n":"第十条","txt":"物权法第一百零一条所称的“同等条件”，应当综合共有份额的转让价格、价款履行方式及期限等因素确定。"},{"i":11,"n":"第十一条","txt":"优先购买权的行使期间，按份共有人之间有约定的，按照约定处理；没有约定或者约定不明的，按照下列情形确定："},{"i":12,"n":"第十二条","txt":"按份共有人向共有人之外的人转让其份额，其他按份共有人根据法律、司法解释规定，请求按照同等条件购买该共有份额的，应予支持。"},{"i":13,"n":"第十三条","txt":"按份共有人之间转让共有份额，其他按份共有人主张根据物权法第一百零一条规定优先购买的，不予支持，但按份共有人之间另有约定的除外。"},{"i":14,"n":"第十四条","txt":"两个以上按份共有人主张优先购买且协商不成时，请求按照转让时各自份额比例行使优先购买权的，应予支持。"},{"i":15,"n":"第十五条","txt":"受让人受让不动产或者动产时，不知道转让人无处分权，且无重大过失的，应当认定受让人为善意。"},{"i":16,"n":"第十六条","txt":"具有下列情形之一的，应当认定不动产受让人知道转让人无处分权："},{"i":17,"n":"第十七条","txt":"受让人受让动产时，交易的对象、场所或者时机等不符合交易习惯的，应当认定受让人具有重大过失。"},{"i":18,"n":"第十八条","txt":"物权法第一百零六条第一款第一项所称的“受让人受让该不动产或者动产时”，是指依法完成不动产物权转移登记或者动产交付之时。"},{"i":19,"n":"第十九条","txt":"物权法第一百零六条第一款第二项所称“合理的价格”，应当根据转让标的物的性质、数量以及付款方式等具体情况，参考转让时交易地市场价格以及交易习惯等因素综合认定。"},{"i":20,"n":"第二十条","txt":"转让人将物权法第二十四条规定的船舶、航空器和机动车等交付给受让人的，应当认定符合物权法第一百零六条第一款第三项规定的善意取得的条件。"},{"i":21,"n":"第二十一条","txt":"具有下列情形之一，受让人主张根据物权法第一百零六条规定取得所有权的，不予支持："},{"i":22,"n":"第二十二条","txt":"本解释自2016年3月1日起施行。"}],"zuigaorenminfayuanguanyushiyongxingshisusongfadejicaef4d-2":[{"i":1,"n":"第一条","txt":"人民法院直接受理的自诉案件包括："},{"i":2,"n":"第二条","txt":"犯罪地包括犯罪行为发生地和犯罪结果发生地。"},{"i":3,"n":"第三条","txt":"被告人的户籍地为其居住地。经常居住地与户籍地不一致的，经常居住地为其居住地。经常居住地为被告人被追诉前已连续居住一年以上的地方，但住院就医的除外。"},{"i":4,"n":"第四条","txt":"在中华人民共和国领域外的中国船舶内的犯罪，由该船舶最初停泊的中国口岸所在地的人民法院管辖。"},{"i":5,"n":"第五条","txt":"在中华人民共和国领域外的中国航空器内的犯罪，由该航空器在中国最初降落地的人民法院管辖。"},{"i":6,"n":"第六条","txt":"在国际列车上的犯罪，根据我国与相关国家签订的协定确定管辖；没有协定的，由该列车最初停靠的中国车站所在地或者目的地的铁路运输法院管辖。"},{"i":7,"n":"第七条","txt":"中国公民在中国驻外使、领馆内的犯罪，由其主管单位所在地或者原户籍地的人民法院管辖。"},{"i":8,"n":"第八条","txt":"中国公民在中华人民共和国领域外的犯罪，由其入境地或者离境前居住地的人民法院管辖；被害人是中国公民的，也可由被害人离境前居住地的人民法院管辖。"},{"i":9,"n":"第九条","txt":"外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，根据《中华人民共和国刑法》应当受处罚的，由该外国人入境地、入境后居住地或者被害中国公民离境前居住地的人民法院管辖。"},{"i":10,"n":"第十条","txt":"对中华人民共和国缔结或者参加的国际条约所规定的罪行，中华人民共和国在所承担条约义务的范围内，行使刑事管辖权的，由被告人被抓获地的人民法院管辖。"},{"i":11,"n":"第十一条","txt":"正在服刑的罪犯在判决宣告前还有其他罪没有判决的，由原审地人民法院管辖；由罪犯服刑地或者犯罪地的人民法院审判更为适宜的，可以由罪犯服刑地或者犯罪地的人民法院管辖。"},{"i":12,"n":"第十二条","txt":"人民检察院认为可能判处无期徒刑、死刑，向中级人民法院提起公诉的案件，中级人民法院受理后，认为不需要判处无期徒刑、死刑的，应当依法审判，不再交基层人民法院审判。"},{"i":13,"n":"第十三条","txt":"一人犯数罪、共同犯罪和其他需要并案审理的案件，其中一人或者一罪属于上级人民法院管辖的，全案由上级人民法院管辖。"},{"i":14,"n":"第十四条","txt":"上级人民法院决定审判下级人民法院管辖的第一审刑事案件的，应当向下级人民法院下达改变管辖决定书，并书面通知同级人民检察院。"},{"i":15,"n":"第十五条","txt":"基层人民法院对可能判处无期徒刑、死刑的第一审刑事案件，应当移送中级人民法院审判。"},{"i":16,"n":"第十六条","txt":"有管辖权的人民法院因案件涉及本院院长需要回避等原因，不宜行使管辖权的，可以请求移送上一级人民法院管辖。上一级人民法院可以管辖，也可以指定与提出请求的人民法院同级的其他人民法院管辖。"},{"i":17,"n":"第十七条","txt":"两个以上同级人民法院都有管辖权的案件，由最初受理的人民法院审判。必要时，可以移送被告人主要犯罪地的人民法院审判。"},{"i":18,"n":"第十八条","txt":"上级人民法院在必要时，可以指定下级人民法院将其管辖的案件移送其他下级人民法院审判。"},{"i":19,"n":"第十九条","txt":"上级人民法院指定管辖，应当将指定管辖决定书分别送达被指定管辖的人民法院和其他有关的人民法院。"},{"i":20,"n":"第二十条","txt":"原受理案件的人民法院在收到上级人民法院改变管辖决定书、同意移送决定书或者指定其他人民法院管辖决定书后，对公诉案件，应当书面通知同级人民检察院，并将案卷材料退回，同时书面通知当事人；对自诉案件，应当将案卷材料移送被指定管辖的人民法院，并书面通知当事人。"},{"i":21,"n":"第二十一条","txt":"第二审人民法院发回重新审判的案件，人民检察院撤回起诉后，又向原第一审人民法院的下级人民法院重新提起公诉的，下级人民法院应当将有关情况层报原第二审人民法院。原第二审人民法院根据具体情况，可以决定将案件移送原第一审人民法院或者其他人民法院审判。"},{"i":22,"n":"第二十二条","txt":"军队和地方互涉刑事案件，按照有关规定确定管辖。"},{"i":23,"n":"第二十三条","txt":"审判人员具有下列情形之一的，应当自行回避，当事人及其法定代理人有权申请其回避："},{"i":24,"n":"第二十四条","txt":"审判人员违反规定，具有下列情形之一的，当事人及其法定代理人有权申请其回避："},{"i":25,"n":"第二十五条","txt":"参与过本案侦查、审查起诉工作的侦查、检察人员，调至人民法院工作的，不得担任本案的审判人员。"},{"i":26,"n":"第二十六条","txt":"人民法院应当依法告知当事人及其法定代理人有权申请回避，并告知其合议庭组成人员、独任审判员、书记员等人员的名单。"},{"i":27,"n":"第二十七条","txt":"审判人员自行申请回避，或者当事人及其法定代理人申请审判人员回避的，可以口头或者书面提出，并说明理由，由院长决定。"},{"i":28,"n":"第二十八条","txt":"当事人及其法定代理人依照刑事诉讼法第二十九条和本解释第二十四条规定申请回避，应当提供证明材料。"},{"i":29,"n":"第二十九条","txt":"应当回避的审判人员没有自行回避，当事人及其法定代理人也没有申请其回避的，院长或者审判委员会应当决定其回避。"},{"i":30,"n":"第三十条","txt":"对当事人及其法定代理人提出的回避申请，人民法院可以口头或者书面作出决定，并将决定告知申请人。"},{"i":31,"n":"第三十一条","txt":"当事人及其法定代理人申请出庭的检察人员回避的，人民法院应当决定休庭，并通知人民检察院。"},{"i":32,"n":"第三十二条","txt":"本章所称的审判人员，包括人民法院院长、副院长、审判委员会委员、庭长、副庭长、审判员、助理审判员和人民陪审员。"},{"i":33,"n":"第三十三条","txt":"书记员、翻译人员和鉴定人适用审判人员回避的有关规定，其回避问题由院长决定。"},{"i":34,"n":"第三十四条","txt":"辩护人、诉讼代理人可以依照本章的有关规定要求回避、申请复议。"},{"i":35,"n":"第三十五条","txt":"人民法院审判案件，应当充分保障被告人依法享有的辩护权利。"},{"i":36,"n":"第三十六条","txt":"审判人员和人民法院其他工作人员从人民法院离任后二年内，不得以律师身份担任辩护人。"},{"i":37,"n":"第三十七条","txt":"律师，人民团体、被告人所在单位推荐的人，或者被告人的监护人、亲友被委托为辩护人的，人民法院应当核实其身份证明和授权委托书。"},{"i":38,"n":"第三十八条","txt":"一名被告人可以委托一至二人作为辩护人。"},{"i":39,"n":"第三十九条","txt":"被告人没有委托辩护人的，人民法院自受理案件之日起三日内，应当告知其有权委托辩护人；被告人因经济困难或者其他原因没有委托辩护人的，应当告知其可以申请法律援助；被告人属于应当提供法律援助情形的，应当告知其将依法通知法律援助机构指派律师为其提供辩护。"},{"i":40,"n":"第四十条","txt":"审判期间，在押的被告人要求委托辩护人的，人民法院应当在三日内向其监护人、近亲属或者其指定的人员转达要求。被告人应当提供有关人员的联系方式。有关人员无法通知的，应当告知被告人。"},{"i":41,"n":"第四十一条","txt":"人民法院收到在押被告人提出的法律援助申请，应当在二十四小时内转交所在地的法律援助机构。"},{"i":42,"n":"第四十二条","txt":"对下列没有委托辩护人的被告人，人民法院应当通知法律援助机构指派律师为其提供辩护："},{"i":43,"n":"第四十三条","txt":"具有下列情形之一，被告人没有委托辩护人的，人民法院可以通知法律援助机构指派律师为其提供辩护："},{"i":44,"n":"第四十四条","txt":"人民法院通知法律援助机构指派律师提供辩护的，应当将法律援助通知书、起诉书副本或者判决书送达法律援助机构；决定开庭审理的，除适用简易程序审理的以外，应当在开庭十五日前将上述材料送达法律援助机构。"},{"i":45,"n":"第四十五条","txt":"被告人拒绝法律援助机构指派的律师为其辩护，坚持自己行使辩护权的，人民法院应当准许。"},{"i":46,"n":"第四十六条","txt":"审判期间，辩护人接受被告人委托的，应当在接受委托之日起三日内，将委托手续提交人民法院。"},{"i":47,"n":"第四十七条","txt":"辩护律师可以查阅、摘抄、复制案卷材料。其他辩护人经人民法院许可，也可以查阅、摘抄、复制案卷材料。合议庭、审判委员会的讨论记录以及其他依法不公开的材料不得查阅、摘抄、复制。"},{"i":48,"n":"第四十八条","txt":"辩护律师可以同在押的或者被监视居住的被告人会见和通信。其他辩护人经人民法院许可，也可以同在押的或者被监视居住的被告人会见和通信。"},{"i":49,"n":"第四十九条","txt":"辩护人认为在侦查、审查起诉期间公安机关、人民检察院收集的证明被告人无罪或者罪轻的证据材料未随案移送，申请人民法院调取的，应当以书面形式提出，并提供相关线索或者材料。人民法院接受申请后，应当向人民检察院调取。人民检察院移送相关证据材料后，人民法院应当及时通知辩护人。"},{"i":50,"n":"第五十条","txt":"辩护律师申请向被害人及其近亲属、被害人提供的证人收集与本案有关的材料，人民法院认为确有必要的，应当签发准许调查书。"},{"i":51,"n":"第五十一条","txt":"辩护律师向证人或者有关单位、个人收集、调取与本案有关的证据材料，因证人或者有关单位、个人不同意，申请人民法院收集、调取，或者申请通知证人出庭作证，人民法院认为确有必要的，应当同意。"},{"i":52,"n":"第五十二条","txt":"辩护律师直接申请人民法院向证人或者有关单位、个人收集、调取证据材料，人民法院认为确有收集、调取必要，且不宜或者不能由辩护律师收集、调取的，应当同意。人民法院收集、调取证据材料时，辩护律师可以在场。"},{"i":53,"n":"第五十三条","txt":"本解释第五十条至第五十二条规定的申请，应当以书面形式提出，并说明理由，写明需要收集、调取证据材料的内容或者需要调查问题的提纲。"},{"i":54,"n":"第五十四条","txt":"人民法院自受理自诉案件之日起三日内，应当告知自诉人及其法定代理人、附带民事诉讼当事人及其法定代理人，有权委托诉讼代理人，并告知如果经济困难的，可以申请法律援助。"},{"i":55,"n":"第五十五条","txt":"当事人委托诉讼代理人的，参照适用刑事诉讼法第三十二条和本解释的有关规定。"},{"i":56,"n":"第五十六条","txt":"诉讼代理人有权根据事实和法律，维护被害人、自诉人或者附带民事诉讼当事人的诉讼权利和其他合法权益。"},{"i":57,"n":"第五十七条","txt":"经人民法院许可，诉讼代理人可以查阅、摘抄、复制本案的案卷材料。"},{"i":58,"n":"第五十八条","txt":"诉讼代理人接受当事人委托或者法律援助机构指派后，应当在三日内将委托手续或者法律援助手续提交人民法院。"},{"i":59,"n":"第五十九条","txt":"辩护人、诉讼代理人复制案卷材料的，人民法院只收取工本费；法律援助律师复制必要的案卷材料的，应当免收或者减收费用。"},{"i":60,"n":"第六十条","txt":"辩护律师向人民法院告知其委托人或者其他人准备实施、正在实施危害国家安全、公共安全以及严重危害他人人身安全犯罪的，人民法院应当记录在案，立即转告主管机关依法处理，并为反映有关情况的辩护律师保密。"},{"i":61,"n":"第六十一条","txt":"认定案件事实，必须以证据为根据。"},{"i":62,"n":"第六十二条","txt":"审判人员应当依照法定程序收集、审查、核实、认定证据。"},{"i":63,"n":"第六十三条","txt":"证据未经当庭出示、辨认、质证等法庭调查程序查证属实，不得作为定案的根据，但法律和本解释另有规定的除外。"},{"i":64,"n":"第六十四条","txt":"应当运用证据证明的案件事实包括："},{"i":65,"n":"第六十五条","txt":"行政机关在行政执法和查办案件过程中收集的物证、书证、视听资料、电子数据等证据材料，在刑事诉讼中可以作为证据使用；经法庭查证属实，且收集程序符合有关法律、行政法规规定的，可以作为定案的根据。"},{"i":66,"n":"第六十六条","txt":"人民法院依照刑事诉讼法第一百九十一条的规定调查核实证据，必要时，可以通知检察人员、辩护人、自诉人及其法定代理人到场。上述人员未到场的，应当记录在案。"},{"i":67,"n":"第六十七条","txt":"下列人员不得担任刑事诉讼活动的见证人："},{"i":68,"n":"第六十八条","txt":"公开审理案件时，公诉人、诉讼参与人提出涉及国家秘密、商业秘密或者个人隐私的证据的，法庭应当制止。有关证据确与本案有关的，可以根据具体情况，决定将案件转为不公开审理，或者对相关证据的法庭调查不公开进行。"},{"i":69,"n":"第六十九条","txt":"对物证、书证应当着重审查以下内容："},{"i":70,"n":"第七十条","txt":"据以定案的物证应当是原物。原物不便搬运，不易保存，依法应当由有关部门保管、处理，或者依法应当返还的，可以拍摄、制作足以反映原物外形和特征的照片、录像、复制品。"},{"i":71,"n":"第七十一条","txt":"据以定案的书证应当是原件。取得原件确有困难的，可以使用副本、复制件。"},{"i":72,"n":"第七十二条","txt":"对与案件事实可能有关联的血迹、体液、毛发、人体组织、指纹、足迹、字迹等生物样本、痕迹和物品，应当提取而没有提取，应当检验而没有检验，导致案件事实存疑的，人民法院应当向人民检察院说明情况，由人民检察院依法补充收集、调取证据或者作出合理说明。"},{"i":73,"n":"第七十三条","txt":"在勘验、检查、搜查过程中提取、扣押的物证、书证，未附笔录或者清单，不能证明物证、书证来源的，不得作为定案的根据。"},{"i":74,"n":"第七十四条","txt":"对证人证言应当着重审查以下内容："},{"i":75,"n":"第七十五条","txt":"处于明显醉酒、中毒或者麻醉等状态，不能正常感知或者正确表达的证人所提供的证言，不得作为证据使用。"},{"i":76,"n":"第七十六条","txt":"证人证言具有下列情形之一的，不得作为定案的根据："},{"i":77,"n":"第七十七条","txt":"证人证言的收集程序、方式有下列瑕疵，经补正或者作出合理解释的，可以采用；不能补正或者作出合理解释的，不得作为定案的根据："},{"i":78,"n":"第七十八条","txt":"证人当庭作出的证言，经控辩双方质证、法庭查证属实的，应当作为定案的根据。"},{"i":79,"n":"第七十九条","txt":"对被害人陈述的审查与认定，参照适用本节的有关规定。"},{"i":80,"n":"第八十条","txt":"对被告人供述和辩解应当着重审查以下内容："},{"i":81,"n":"第八十一条","txt":"被告人供述具有下列情形之一的，不得作为定案的根据："},{"i":82,"n":"第八十二条","txt":"讯问笔录有下列瑕疵，经补正或者作出合理解释的，可以采用；不能补正或者作出合理解释的，不得作为定案的根据："},{"i":83,"n":"第八十三条","txt":"审查被告人供述和辩解，应当结合控辩双方提供的所有证据以及被告人的全部供述和辩解进行。"},{"i":84,"n":"第八十四条","txt":"对鉴定意见应当着重审查以下内容："},{"i":85,"n":"第八十五条","txt":"鉴定意见具有下列情形之一的，不得作为定案的根据："},{"i":86,"n":"第八十六条","txt":"经人民法院通知，鉴定人拒不出庭作证的，鉴定意见不得作为定案的根据。"},{"i":87,"n":"第八十七条","txt":"对案件中的专门性问题需要鉴定，但没有法定司法鉴定机构，或者法律、司法解释规定可以进行检验的，可以指派、聘请有专门知识的人进行检验，检验报告可以作为定罪量刑的参考。"},{"i":88,"n":"第八十八条","txt":"对勘验、检查笔录应当着重审查以下内容："},{"i":89,"n":"第八十九条","txt":"勘验、检查笔录存在明显不符合法律、有关规定的情形，不能作出合理解释或者说明的，不得作为定案的根据。"},{"i":90,"n":"第九十条","txt":"对辨认笔录应当着重审查辨认的过程、方法，以及辨认笔录的制作是否符合有关规定。"},{"i":91,"n":"第九十一条","txt":"对侦查实验笔录应当着重审查实验的过程、方法，以及笔录的制作是否符合有关规定。"},{"i":92,"n":"第九十二条","txt":"对视听资料应当着重审查以下内容："},{"i":93,"n":"第九十三条","txt":"对电子邮件、电子数据交换、网上聊天记录、博客、微博客、手机短信、电子签名、域名等电子数据，应当着重审查以下内容："},{"i":94,"n":"第九十四条","txt":"视听资料、电子数据具有下列情形之一的，不得作为定案的根据："},{"i":95,"n":"第九十五条","txt":"使用肉刑或者变相肉刑，或者采用其他使被告人在肉体上或者精神上遭受剧烈疼痛或者痛苦的方法，迫使被告人违背意愿供述的，应当认定为刑事诉讼法第五十四条规定的“刑讯逼供等非法方法”。"},{"i":96,"n":"第九十六条","txt":"当事人及其辩护人、诉讼代理人申请人民法院排除以非法方法收集的证据的，应当提供涉嫌非法取证的人员、时间、地点、方式、内容等相关线索或者材料。"},{"i":97,"n":"第九十七条","txt":"人民法院向被告人及其辩护人送达起诉书副本时，应当告知其申请排除非法证据的，应当在开庭审理前提出，但在庭审期间才发现相关线索或者材料的除外。"},{"i":98,"n":"第九十八条","txt":"开庭审理前，当事人及其辩护人、诉讼代理人申请人民法院排除非法证据的，人民法院应当在开庭前及时将申请书或者申请笔录及相关线索、材料的复制件送交人民检察院。"},{"i":99,"n":"第九十九条","txt":"开庭审理前，当事人及其辩护人、诉讼代理人申请排除非法证据，人民法院经审查，对证据收集的合法性有疑问的，应当依照刑事诉讼法第一百八十二条第二款的规定召开庭前会议，就非法证据排除等问题了解情况，听取意见。人民检察院可以通过出示有关证据材料等方式，对证据收集的合法性加以说明。"},{"i":100,"n":"第一百条","txt":"法庭审理过程中，当事人及其辩护人、诉讼代理人申请排除非法证据的，法庭应当进行审查。经审查，对证据收集的合法性有疑问的，应当进行调查；没有疑问的，应当当庭说明情况和理由，继续法庭审理。当事人及其辩护人、诉讼代理人以相同理由再次申请排除非法证据的，法庭不再进行审查。"},{"i":101,"n":"第一百零一条","txt":"法庭决定对证据收集的合法性进行调查的，可以由公诉人通过出示、宣读讯问笔录或者其他证据，有针对性地播放讯问过程的录音录像，提请法庭通知有关侦查人员或者其他人员出庭说明情况等方式，证明证据收集的合法性。"},{"i":102,"n":"第一百零二条","txt":"经审理，确认或者不能排除存在刑事诉讼法第五十四条规定的以非法方法收集证据情形的，对有关证据应当排除。"},{"i":103,"n":"第一百零三条","txt":"具有下列情形之一的，第二审人民法院应当对证据收集的合法性进行审查，并根据刑事诉讼法和本解释的有关规定作出处理："},{"i":104,"n":"第一百零四条","txt":"对证据的真实性，应当综合全案证据进行审查。"},{"i":105,"n":"第一百零五条","txt":"没有直接证据，但间接证据同时符合下列条件的，可以认定被告人有罪："},{"i":106,"n":"第一百零六条","txt":"根据被告人的供述、指认提取到了隐蔽性很强的物证、书证，且被告人的供述与其他证明犯罪事实发生的证据相互印证，并排除串供、逼供、诱供等可能性的，可以认定被告人有罪。"},{"i":107,"n":"第一百零七条","txt":"采取技术侦查措施收集的证据材料，经当庭出示、辨认、质证等法庭调查程序查证属实的，可以作为定案的根据。"},{"i":108,"n":"第一百零八条","txt":"对侦查机关出具的被告人到案经过、抓获经过等材料，应当审查是否有出具该说明材料的办案人、办案机关的签名、盖章。"},{"i":109,"n":"第一百零九条","txt":"下列证据应当慎重使用，有其他证据印证的，可以采信："},{"i":110,"n":"第一百一十条","txt":"证明被告人自首、坦白、立功的证据材料，没有加盖接受被告人投案、坦白、检举揭发等的单位的印章，或者接受人员没有签名的，不得作为定案的根据。"},{"i":111,"n":"第一百一十一条","txt":"证明被告人构成累犯、毒品再犯的证据材料，应当包括前罪的裁判文书、释放证明等材料；材料不全的，应当要求有关机关提供。"},{"i":112,"n":"第一百一十二条","txt":"审查被告人实施被指控的犯罪时或者审判时是否达到相应法定责任年龄，应当根据户籍证明、出生证明文件、学籍卡、人口普查登记、无利害关系人的证言等证据综合判断。"},{"i":113,"n":"第一百一十三条","txt":"人民法院审判案件，根据情况，对被告人可以决定拘传、取保候审、监视居住或者逮捕。"},{"i":114,"n":"第一百一十四条","txt":"对经依法传唤拒不到庭的被告人，或者根据案件情况有必要拘传的被告人，可以拘传。"},{"i":115,"n":"第一百一十五条","txt":"拘传被告人，持续的时间不得超过十二小时；案情特别重大、复杂，需要采取逮捕措施的，持续的时间不得超过二十四小时。不得以连续拘传的形式变相拘禁被告人。应当保证被拘传人的饮食和必要的休息时间。"},{"i":116,"n":"第一百一十六条","txt":"被告人具有刑事诉讼法第六十五条第一款规定情形之一的，人民法院可以决定取保候审。"},{"i":117,"n":"第一百一十七条","txt":"对下列被告人决定取保候审的，可以责令其提出一至二名保证人："},{"i":118,"n":"第一百一十八条","txt":"人民法院应当审查保证人是否符合法定条件。符合条件的，应当告知其必须履行的义务，并由其出具保证书。"},{"i":119,"n":"第一百一十九条","txt":"对决定取保候审的被告人使用保证金保证的，应当依照刑事诉讼法第七十条第一款的规定确定保证金的具体数额，并责令被告人或者为其提供保证金的单位、个人将保证金一次性存入公安机关指定银行的专门账户。"},{"i":120,"n":"第一百二十条","txt":"人民法院向被告人宣布取保候审决定后，应当将取保候审决定书等相关材料送交当地同级公安机关执行；被告人不在本地居住的，送交其居住地公安机关执行。"},{"i":121,"n":"第一百二十一条","txt":"被告人被取保候审期间，保证人不愿继续履行保证义务或者丧失履行保证义务能力的，人民法院应当在收到保证人的申请或者公安机关的书面通知后三日内，责令被告人重新提出保证人或者交纳保证金，或者变更强制措施，并通知公安机关。"},{"i":122,"n":"第一百二十二条","txt":"根据案件事实和法律规定，认为已经构成犯罪的被告人在取保候审期间逃匿的，如果系保证人协助被告人逃匿，或者保证人明知被告人藏匿地点但拒绝向司法机关提供，对保证人应当依法追究刑事责任。"},{"i":123,"n":"第一百二十三条","txt":"人民法院发现使用保证金保证的被取保候审人违反刑事诉讼法第六十九条第一款、第二款规定的，应当提出没收部分或者全部保证金的书面意见，连同有关材料一并送交负责执行的公安机关处理。"},{"i":124,"n":"第一百二十四条","txt":"对被取保候审的被告人的判决、裁定生效后，应当解除取保候审、退还保证金的，如果保证金属于其个人财产，人民法院可以书面通知公安机关将保证金移交人民法院，用以退赔被害人、履行附带民事赔偿义务或者执行财产刑，剩余部分应当退还被告人。"},{"i":125,"n":"第一百二十五条","txt":"对具有刑事诉讼法第七十二条第一款、第二款规定情形的被告人，人民法院可以决定监视居住。"},{"i":126,"n":"第一百二十六条","txt":"人民法院向被告人宣布监视居住决定后，应当将监视居住决定书等相关材料送交被告人住处或者指定居所所在地的同级公安机关执行。"},{"i":127,"n":"第一百二十七条","txt":"人民检察院、公安机关已经对犯罪嫌疑人取保候审、监视居住，案件起诉至人民法院后，需要继续取保候审、监视居住或者变更强制措施的，人民法院应当在七日内作出决定，并通知人民检察院、公安机关。"},{"i":128,"n":"第一百二十八条","txt":"对具有刑事诉讼法第七十九条第一款、第二款规定情形的被告人，人民法院应当决定逮捕。"},{"i":129,"n":"第一百二十九条","txt":"被取保候审的被告人具有下列情形之一的，人民法院应当决定逮捕："},{"i":130,"n":"第一百三十条","txt":"被监视居住的被告人具有下列情形之一的，人民法院应当决定逮捕："},{"i":131,"n":"第一百三十一条","txt":"人民法院作出逮捕决定后，应当将逮捕决定书等相关材料送交同级公安机关执行，并将逮捕决定书抄送人民检察院。逮捕被告人后，人民法院应当将逮捕的原因和羁押的处所，在二十四小时内通知其家属；确实无法通知的，应当记录在案。"},{"i":132,"n":"第一百三十二条","txt":"人民法院对决定逮捕的被告人，应当在逮捕后二十四小时内讯问。发现不应当逮捕的，应当变更强制措施或者立即释放。"},{"i":133,"n":"第一百三十三条","txt":"被逮捕的被告人具有下列情形之一的，人民法院可以变更强制措施："},{"i":134,"n":"第一百三十四条","txt":"第一审人民法院判决被告人无罪、不负刑事责任或者免除刑事处罚，被告人在押的，应当在宣判后立即释放。"},{"i":135,"n":"第一百三十五条","txt":"人民法院决定变更强制措施或者释放被告人的，应当立即将变更强制措施决定书或者释放通知书送交公安机关执行。"},{"i":136,"n":"第一百三十六条","txt":"对人民法院决定逮捕的被告人，人民检察院建议释放或者变更强制措施的，人民法院应当在收到建议后十日内将处理情况通知人民检察院。"},{"i":137,"n":"第一百三十七条","txt":"被告人及其法定代理人、近亲属或者辩护人申请变更强制措施的，应当说明理由。人民法院收到申请后，应当在三日内作出决定。同意变更强制措施的，应当依照本解释规定处理；不同意的，应当告知申请人，并说明理由。"},{"i":138,"n":"第一百三十八条","txt":"被害人因人身权利受到犯罪侵犯或者财物被犯罪分子毁坏而遭受物质损失的，有权在刑事诉讼过程中提起附带民事诉讼；被害人死亡或者丧失行为能力的，其法定代理人、近亲属有权提起附带民事诉讼。"},{"i":139,"n":"第一百三十九条","txt":"被告人非法占有、处置被害人财产的，应当依法予以追缴或者责令退赔。被害人提起附带民事诉讼的，人民法院不予受理。追缴、退赔的情况，可以作为量刑情节考虑。"},{"i":140,"n":"第一百四十条","txt":"国家机关工作人员在行使职权时，侵犯他人人身、财产权利构成犯罪，被害人或者其法定代理人、近亲属提起附带民事诉讼的，人民法院不予受理，但应当告知其可以依法申请国家赔偿。"},{"i":141,"n":"第一百四十一条","txt":"人民法院受理刑事案件后，对符合刑事诉讼法第九十九条和本解释第一百三十八条第一款规定的，可以告知被害人或者其法定代理人、近亲属有权提起附带民事诉讼。"},{"i":142,"n":"第一百四十二条","txt":"国家财产、集体财产遭受损失，受损失的单位未提起附带民事诉讼，人民检察院在提起公诉时提起附带民事诉讼的，人民法院应当受理。"},{"i":143,"n":"第一百四十三条","txt":"附带民事诉讼中依法负有赔偿责任的人包括："},{"i":144,"n":"第一百四十四条","txt":"被害人或者其法定代理人、近亲属仅对部分共同侵害人提起附带民事诉讼的，人民法院应当告知其可以对其他共同侵害人，包括没有被追究刑事责任的共同侵害人，一并提起附带民事诉讼，但共同犯罪案件中同案犯在逃的除外。"},{"i":145,"n":"第一百四十五条","txt":"附带民事诉讼的起诉条件是："},{"i":146,"n":"第一百四十六条","txt":"共同犯罪案件，同案犯在逃的，不应列为附带民事诉讼被告人。逃跑的同案犯到案后，被害人或者其法定代理人、近亲属可以对其提起附带民事诉讼，但已经从其他共同犯罪人处获得足额赔偿的除外。"},{"i":147,"n":"第一百四十七条","txt":"附带民事诉讼应当在刑事案件立案后及时提起。"},{"i":148,"n":"第一百四十八条","txt":"侦查、审查起诉期间，有权提起附带民事诉讼的人提出赔偿要求，经公安机关、人民检察院调解，当事人双方已经达成协议并全部履行，被害人或者其法定代理人、近亲属又提起附带民事诉讼的，人民法院不予受理，但有证据证明调解违反自愿、合法原则的除外。"},{"i":149,"n":"第一百四十九条","txt":"被害人或者其法定代理人、近亲属提起附带民事诉讼的，人民法院应当在七日内决定是否立案。符合刑事诉讼法第九十九条以及本解释有关规定的，应当受理；不符合的，裁定不予受理。"},{"i":150,"n":"第一百五十条","txt":"人民法院受理附带民事诉讼后，应当在五日内将附带民事起诉状副本送达附带民事诉讼被告人及其法定代理人，或者将口头起诉的内容及时通知附带民事诉讼被告人及其法定代理人，并制作笔录。"},{"i":151,"n":"第一百五十一条","txt":"附带民事诉讼当事人对自己提出的主张，有责任提供证据。"},{"i":152,"n":"第一百五十二条","txt":"人民法院对可能因被告人的行为或者其他原因，使附带民事判决难以执行的案件，根据附带民事诉讼原告人的申请，可以裁定采取保全措施，查封、扣押或者冻结被告人的财产；附带民事诉讼原告人未提出申请的，必要时，人民法院也可以采取保全措施。"},{"i":153,"n":"第一百五十三条","txt":"人民法院审理附带民事诉讼案件，可以根据自愿、合法的原则进行调解。经调解达成协议的，应当制作调解书。调解书经双方当事人签收后，即具有法律效力。"},{"i":154,"n":"第一百五十四条","txt":"调解未达成协议或者调解书签收前当事人反悔的，附带民事诉讼应当同刑事诉讼一并判决。"},{"i":155,"n":"第一百五十五条","txt":"对附带民事诉讼作出判决，应当根据犯罪行为造成的物质损失，结合案件具体情况，确定被告人应当赔偿的数额。"},{"i":156,"n":"第一百五十六条","txt":"人民检察院提起附带民事诉讼的，人民法院经审理，认为附带民事诉讼被告人依法应当承担赔偿责任的，应当判令附带民事诉讼被告人直接向遭受损失的单位作出赔偿；遭受损失的单位已经终止，有权利义务继受人的，应当判令其向继受人作出赔偿；没有权利义务继受人的，应当判令其向人民检察院交付赔偿款，由人民检察院上缴国库。"},{"i":157,"n":"第一百五十七条","txt":"审理刑事附带民事诉讼案件，人民法院应当结合被告人赔偿被害人物质损失的情况认定其悔罪表现，并在量刑时予以考虑。"},{"i":158,"n":"第一百五十八条","txt":"附带民事诉讼原告人经传唤，无正当理由拒不到庭，或者未经法庭许可中途退庭的，应当按撤诉处理。"},{"i":159,"n":"第一百五十九条","txt":"附带民事诉讼应当同刑事案件一并审判，只有为了防止刑事案件审判的过分迟延，才可以在刑事案件审判后，由同一审判组织继续审理附带民事诉讼；同一审判组织的成员确实不能继续参与审判的，可以更换。"},{"i":160,"n":"第一百六十条","txt":"人民法院认定公诉案件被告人的行为不构成犯罪，对已经提起的附带民事诉讼，经调解不能达成协议的，应当一并作出刑事附带民事判决。"},{"i":161,"n":"第一百六十一条","txt":"第一审期间未提起附带民事诉讼，在第二审期间提起的，第二审人民法院可以依法进行调解；调解不成的，告知当事人可以在刑事判决、裁定生效后另行提起民事诉讼。"},{"i":162,"n":"第一百六十二条","txt":"人民法院审理附带民事诉讼案件，不收取诉讼费。"},{"i":163,"n":"第一百六十三条","txt":"人民法院审理附带民事诉讼案件，除刑法、刑事诉讼法以及刑事司法解释已有规定的以外，适用民事法律的有关规定。"},{"i":164,"n":"第一百六十四条","txt":"被害人或者其法定代理人、近亲属在刑事诉讼过程中未提起附带民事诉讼，另行提起民事诉讼的，人民法院可以进行调解，或者根据物质损失情况作出判决。"},{"i":165,"n":"第一百六十五条","txt":"以月计算的期限，自本月某日至下月同日为一个月。期限起算日为本月最后一日的，至下月最后一日为一个月。下月同日不存在的，自本月某日至下月最后一日为一个月。半个月一律按十五日计算。"},{"i":166,"n":"第一百六十六条","txt":"当事人由于不能抗拒的原因或者有其他正当理由而耽误期限，依法申请继续进行应当在期满前完成的诉讼活动的，人民法院查证属实后，应当裁定准许。"},{"i":167,"n":"第一百六十七条","txt":"送达诉讼文书，应当由收件人签收。收件人不在的，可以由其成年家属或者所在单位负责收件的人员代收。"},{"i":168,"n":"第一百六十八条","txt":"直接送达诉讼文书有困难的，可以委托收件人所在地的人民法院代为送达，或者邮寄送达。"},{"i":169,"n":"第一百六十九条","txt":"委托送达的，应当将委托函、委托送达的诉讼文书及送达回证寄送受托法院。受托法院收到后，应当登记，在十日内送达收件人，并将送达回证寄送委托法院；无法送达的，应当告知委托法院，并将诉讼文书及送达回证退回。"},{"i":170,"n":"第一百七十条","txt":"邮寄送达的，应当将诉讼文书、送达回证挂号邮寄给收件人。挂号回执上注明的日期为送达日期。"},{"i":171,"n":"第一百七十一条","txt":"诉讼文书的收件人是军人的，可以通过其所在部队团级以上单位的政治部门转交。"},{"i":172,"n":"第一百七十二条","txt":"指定管辖案件的审理期限，自被指定管辖的人民法院收到指定管辖决定书和有关案卷、证据材料之日起计算。"},{"i":173,"n":"第一百七十三条","txt":"申请上级人民法院批准延长审理期限，应当在期限届满十五日前层报。有权决定的人民法院不同意延长的，应当在审理期限届满五日前作出决定。"},{"i":174,"n":"第一百七十四条","txt":"审判期间，对被告人作精神病鉴定的时间不计入审理期限。"},{"i":175,"n":"第一百七十五条","txt":"审判长由审判员担任。助理审判员由本院院长提出，经审判委员会通过，可以临时代行审判员职务，并可以担任审判长。"},{"i":176,"n":"第一百七十六条","txt":"开庭审理和评议案件，应当由同一合议庭进行。合议庭成员在评议案件时，应当独立表达意见并说明理由。意见分歧的，应当按多数意见作出决定，但少数意见应当记入笔录。评议笔录由合议庭的组成人员在审阅确认无误后签名。评议情况应当保密。"},{"i":177,"n":"第一百七十七条","txt":"审判员依法独任审判时，行使与审判长相同的职权。"},{"i":178,"n":"第一百七十八条","txt":"合议庭审理、评议后，应当及时作出判决、裁定。"},{"i":179,"n":"第一百七十九条","txt":"审判委员会的决定，合议庭、独任审判员应当执行；有不同意见的，可以建议院长提交审判委员会复议。"},{"i":180,"n":"第一百八十条","txt":"对提起公诉的案件，人民法院应当在收到起诉书（一式八份，每增加一名被告人，增加起诉书五份）和案卷、证据后，指定审判人员审查以下内容："},{"i":181,"n":"第一百八十一条","txt":"人民法院对提起公诉的案件审查后，应当按照下列情形分别处理："},{"i":182,"n":"第一百八十二条","txt":"开庭审理前，人民法院应当进行下列工作："},{"i":183,"n":"第一百八十三条","txt":"案件具有下列情形之一的，审判人员可以召开庭前会议："},{"i":184,"n":"第一百八十四条","txt":"召开庭前会议，审判人员可以就下列问题向控辩双方了解情况，听取意见："},{"i":185,"n":"第一百八十五条","txt":"开庭审理前，合议庭可以拟出法庭审理提纲，提纲一般包括下列内容："},{"i":186,"n":"第一百八十六条","txt":"审判案件应当公开进行。"},{"i":187,"n":"第一百八十七条","txt":"精神病人、醉酒的人、未经人民法院批准的未成年人以及其他不宜旁听的人不得旁听案件审理。"},{"i":188,"n":"第一百八十八条","txt":"被害人、诉讼代理人经传唤或者通知未到庭，不影响开庭审理的，人民法院可以开庭审理。"},{"i":189,"n":"第一百八十九条","txt":"开庭审理前，书记员应当依次进行下列工作："},{"i":190,"n":"第一百九十条","txt":"审判长宣布开庭，传被告人到庭后，应当查明被告人的下列情况："},{"i":191,"n":"第一百九十一条","txt":"审判长宣布案件的来源、起诉的案由、附带民事诉讼当事人的姓名及是否公开审理；不公开审理的，应当宣布理由。"},{"i":192,"n":"第一百九十二条","txt":"审判长宣布合议庭组成人员、书记员、公诉人名单及辩护人、鉴定人、翻译人员等诉讼参与人的名单。"},{"i":193,"n":"第一百九十三条","txt":"审判长应当告知当事人及其法定代理人、辩护人、诉讼代理人在法庭审理过程中依法享有下列诉讼权利："},{"i":194,"n":"第一百九十四条","txt":"审判长应当询问当事人及其法定代理人、辩护人、诉讼代理人是否申请回避、申请何人回避和申请回避的理由。"},{"i":195,"n":"第一百九十五条","txt":"审判长宣布法庭调查开始后，应当先由公诉人宣读起诉书；有附带民事诉讼的，再由附带民事诉讼原告人或者其法定代理人、诉讼代理人宣读附带民事起诉状。"},{"i":196,"n":"第一百九十六条","txt":"起诉书指控的被告人的犯罪事实为两起以上的，法庭调查一般应当分别进行。"},{"i":197,"n":"第一百九十七条","txt":"在审判长主持下，被告人、被害人可以就起诉书指控的犯罪事实分别陈述。"},{"i":198,"n":"第一百九十八条","txt":"在审判长主持下，公诉人可以就起诉书指控的犯罪事实讯问被告人。"},{"i":199,"n":"第一百九十九条","txt":"讯问同案审理的被告人，应当分别进行。必要时，可以传唤同案被告人等到庭对质。"},{"i":200,"n":"第二百条","txt":"经审判长准许，控辩双方可以向被害人、附带民事诉讼原告人发问。"},{"i":201,"n":"第二百零一条","txt":"审判人员可以讯问被告人。必要时，可以向被害人、附带民事诉讼当事人发问。"},{"i":202,"n":"第二百零二条","txt":"公诉人可以提请审判长通知证人、鉴定人出庭作证，或者出示证据。被害人及其法定代理人、诉讼代理人，附带民事诉讼原告人及其诉讼代理人也可以提出申请。"},{"i":203,"n":"第二百零三条","txt":"控辩双方申请证人出庭作证，出示证据，应当说明证据的名称、来源和拟证明的事实。法庭认为有必要的，应当准许；对方提出异议，认为有关证据与案件无关或者明显重复、不必要，法庭经审查异议成立的，可以不予准许。"},{"i":204,"n":"第二百零四条","txt":"已经移送人民法院的证据，控辩双方需要出示的，可以向法庭提出申请。法庭同意的，应当指令值庭法警出示、播放；需要宣读的，由值庭法警交由申请人宣读。"},{"i":205,"n":"第二百零五条","txt":"公诉人、当事人或者辩护人、诉讼代理人对证人证言有异议，且该证人证言对定罪量刑有重大影响，或者对鉴定意见有异议，申请法庭通知证人、鉴定人出庭作证，人民法院认为有必要的，应当通知证人、鉴定人出庭；无法通知或者证人、鉴定人拒绝出庭的，应当及时告知申请人。"},{"i":206,"n":"第二百零六条","txt":"证人具有下列情形之一，无法出庭作证的，人民法院可以准许其不出庭："},{"i":207,"n":"第二百零七条","txt":"证人出庭作证所支出的交通、住宿、就餐等费用，人民法院应当给予补助。"},{"i":208,"n":"第二百零八条","txt":"强制证人出庭的，应当由院长签发强制证人出庭令。"},{"i":209,"n":"第二百零九条","txt":"审判危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、毒品犯罪等案件，证人、鉴定人、被害人因出庭作证，本人或者其近亲属的人身安全面临危险的，人民法院应当采取不公开其真实姓名、住址和工作单位等个人信息，或者不暴露其外貌、真实声音等保护措施。"},{"i":210,"n":"第二百一十条","txt":"决定对出庭作证的证人、鉴定人、被害人采取不公开个人信息的保护措施的，审判人员应当在开庭前核实其身份，对证人、鉴定人如实作证的保证书不得公开，在判决书、裁定书等法律文书中可以使用化名等代替其个人信息。"},{"i":211,"n":"第二百一十一条","txt":"证人、鉴定人到庭后，审判人员应当核实其身份、与当事人以及本案的关系，并告知其有关作证的权利义务和法律责任。"},{"i":212,"n":"第二百一十二条","txt":"向证人、鉴定人发问，应当先由提请通知的一方进行；发问完毕后，经审判长准许，对方也可以发问。"},{"i":213,"n":"第二百一十三条","txt":"向证人发问应当遵循以下规则："},{"i":214,"n":"第二百一十四条","txt":"控辩双方的讯问、发问方式不当或者内容与本案无关的，对方可以提出异议，申请审判长制止，审判长应当判明情况予以支持或者驳回；对方未提出异议的，审判长也可以根据情况予以制止。"},{"i":215,"n":"第二百一十五条","txt":"审判人员认为必要时，可以询问证人、鉴定人、有专门知识的人。"},{"i":216,"n":"第二百一十六条","txt":"向证人、鉴定人、有专门知识的人发问应当分别进行。证人、鉴定人、有专门知识的人经控辩双方发问或者审判人员询问后，审判长应当告知其退庭。"},{"i":217,"n":"第二百一十七条","txt":"公诉人、当事人及其辩护人、诉讼代理人申请法庭通知有专门知识的人出庭，就鉴定意见提出意见的，应当说明理由。法庭认为有必要的，应当通知有专门知识的人出庭。"},{"i":218,"n":"第二百一十八条","txt":"举证方当庭出示证据后，由对方进行辨认并发表意见。控辩双方可以互相质问、辩论。"},{"i":219,"n":"第二百一十九条","txt":"当庭出示的证据，尚未移送人民法院的，应当在质证后移交法庭。"},{"i":220,"n":"第二百二十条","txt":"法庭对证据有疑问的，可以告知公诉人、当事人及其法定代理人、辩护人、诉讼代理人补充证据或者作出说明；必要时，可以宣布休庭，对证据进行调查核实。"},{"i":221,"n":"第二百二十一条","txt":"公诉人申请出示开庭前未移送人民法院的证据，辩护方提出异议的，审判长应当要求公诉人说明理由；理由成立并确有出示必要的，应当准许。"},{"i":222,"n":"第二百二十二条","txt":"法庭审理过程中，当事人及其辩护人、诉讼代理人申请通知新的证人到庭，调取新的证据，申请重新鉴定或者勘验的，应当提供证人的姓名、证据的存放地点，说明拟证明的案件事实，要求重新鉴定或者勘验的理由。法庭认为有必要的，应当同意，并宣布延期审理；不同意的，应当说明理由并继续审理。"},{"i":223,"n":"第二百二十三条","txt":"审判期间，公诉人发现案件需要补充侦查，建议延期审理的，合议庭应当同意，但建议延期审理不得超过两次。"},{"i":224,"n":"第二百二十四条","txt":"人民法院向人民检察院调取需要调查核实的证据材料，或者根据被告人、辩护人的申请，向人民检察院调取在侦查、审查起诉期间收集的有关被告人无罪或者罪轻的证据材料，应当通知人民检察院在收到调取证据材料决定书后三日内移交。"},{"i":225,"n":"第二百二十五条","txt":"法庭审理过程中，对与量刑有关的事实、证据，应当进行调查。"},{"i":226,"n":"第二百二十六条","txt":"审判期间，合议庭发现被告人可能有自首、坦白、立功等法定量刑情节，而人民检察院移送的案卷中没有相关证据材料的，应当通知人民检察院移送。"},{"i":227,"n":"第二百二十七条","txt":"对被告人认罪的案件，在确认被告人了解起诉书指控的犯罪事实和罪名，自愿认罪且知悉认罪的法律后果后，法庭调查可以主要围绕量刑和其他有争议的问题进行。"},{"i":228,"n":"第二百二十八条","txt":"合议庭认为案件事实已经调查清楚的，应当由审判长宣布法庭调查结束，开始就定罪、量刑的事实、证据和适用法律等问题进行法庭辩论。"},{"i":229,"n":"第二百二十九条","txt":"法庭辩论应当在审判长的主持下，按照下列顺序进行："},{"i":230,"n":"第二百三十条","txt":"人民检察院可以提出量刑建议并说明理由，量刑建议一般应当具有一定的幅度。当事人及其辩护人、诉讼代理人可以对量刑提出意见并说明理由。"},{"i":231,"n":"第二百三十一条","txt":"对被告人认罪的案件，法庭辩论时，可以引导控辩双方主要围绕量刑和其他有争议的问题进行。"},{"i":232,"n":"第二百三十二条","txt":"附带民事部分的辩论应当在刑事部分的辩论结束后进行，先由附带民事诉讼原告人及其诉讼代理人发言，后由附带民事诉讼被告人及其诉讼代理人答辩。"},{"i":233,"n":"第二百三十三条","txt":"法庭辩论过程中，审判长应当充分听取控辩双方的意见，对控辩双方与案件无关、重复或者指责对方的发言应当提醒、制止。"},{"i":234,"n":"第二百三十四条","txt":"法庭辩论过程中，合议庭发现与定罪、量刑有关的新的事实，有必要调查的，审判长可以宣布暂停辩论，恢复法庭调查，在对新的事实调查后，继续法庭辩论。"},{"i":235,"n":"第二百三十五条","txt":"审判长宣布法庭辩论终结后，合议庭应当保证被告人充分行使最后陈述的权利。被告人在最后陈述中多次重复自己的意见的，审判长可以制止。陈述内容蔑视法庭、公诉人，损害他人及社会公共利益，或者与本案无关的，应当制止。"},{"i":236,"n":"第二百三十六条","txt":"被告人在最后陈述中提出新的事实、证据，合议庭认为可能影响正确裁判的，应当恢复法庭调查；被告人提出新的辩解理由，合议庭认为可能影响正确裁判的，应当恢复法庭辩论。"},{"i":237,"n":"第二百三十七条","txt":"被告人最后陈述后，审判长应当宣布休庭，由合议庭进行评议。"},{"i":238,"n":"第二百三十八条","txt":"开庭审理的全部活动，应当由书记员制作笔录；笔录经审判长审阅后，分别由审判长和书记员签名。"},{"i":239,"n":"第二百三十九条","txt":"法庭笔录应当在庭审后交由当事人、法定代理人、辩护人、诉讼代理人阅读或者向其宣读。"},{"i":240,"n":"第二百四十条","txt":"合议庭评议案件，应当根据已经查明的事实、证据和有关法律规定，在充分考虑控辩双方意见的基础上，确定被告人是否有罪、构成何罪，有无从重、从轻、减轻或者免除处罚情节，应否处以刑罚、判处何种刑罚，附带民事诉讼如何解决，查封、扣押、冻结的财物及其孳息如何处理等，并依法作出判决、裁定。"},{"i":241,"n":"第二百四十一条","txt":"对第一审公诉案件，人民法院审理后，应当按照下列情形分别作出判决、裁定："},{"i":242,"n":"第二百四十二条","txt":"宣告判决前，人民检察院要求撤回起诉的，人民法院应当审查撤回起诉的理由，作出是否准许的裁定。"},{"i":243,"n":"第二百四十三条","txt":"审判期间，人民法院发现新的事实，可能影响定罪的，可以建议人民检察院补充或者变更起诉；人民检察院不同意或者在七日内未回复意见的，人民法院应当就起诉指控的犯罪事实，依照本解释第二百四十一条的规定作出判决、裁定。"},{"i":244,"n":"第二百四十四条","txt":"对依照本解释第一百八十一条第一款第四项规定受理的案件，人民法院应当在判决中写明被告人曾被人民检察院提起公诉，因证据不足，指控的犯罪不能成立，被人民法院依法判决宣告无罪的情况；前案依照刑事诉讼法第一百九十五条第三项规定作出的判决不予撤销。"},{"i":245,"n":"第二百四十五条","txt":"合议庭成员应当在评议笔录上签名，在判决书、裁定书等法律文书上署名。"},{"i":246,"n":"第二百四十六条","txt":"裁判文书应当写明裁判依据，阐释裁判理由，反映控辩双方的意见并说明采纳或者不予采纳的理由。"},{"i":247,"n":"第二百四十七条","txt":"当庭宣告判决的，应当在五日内送达判决书。定期宣告判决的，应当在宣判前，先期公告宣判的时间和地点，传唤当事人并通知公诉人、法定代理人、辩护人和诉讼代理人；判决宣告后，应当立即送达判决书。"},{"i":248,"n":"第二百四十八条","txt":"宣告判决，一律公开进行。公诉人、辩护人、诉讼代理人、被害人、自诉人或者附民事诉讼原告人未到庭的，不影响宣判的进行。"},{"i":249,"n":"第二百四十九条","txt":"法庭审理过程中，诉讼参与人、旁听人员应当遵守以下纪律："},{"i":250,"n":"第二百五十条","txt":"法庭审理过程中，诉讼参与人或者旁听人员扰乱法庭秩序的，审判长应当按照下列情形分别处理："},{"i":251,"n":"第二百五十一条","txt":"担任辩护人、诉讼代理人的律师严重扰乱法庭秩序，被强行带出法庭或者被处以罚款、拘留的，人民法院应当通报司法行政机关，并可以建议依法给予相应处罚。"},{"i":252,"n":"第二百五十二条","txt":"聚众哄闹、冲击法庭或者侮辱、诽谤、威胁、殴打司法工作人员或者诉讼参与人，严重扰乱法庭秩序，构成犯罪的，应当依法追究刑事责任。"},{"i":253,"n":"第二百五十三条","txt":"辩护人严重扰乱法庭秩序，被强行带出法庭或者被处以罚款、拘留，被告人自行辩护的，庭审继续进行；被告人要求另行委托辩护人，或者被告人属于应当提供法律援助情形的，应当宣布休庭。"},{"i":254,"n":"第二百五十四条","txt":"被告人当庭拒绝辩护人辩护，要求另行委托辩护人或者指派律师的，合议庭应当准许。被告人拒绝辩护人辩护后，没有辩护人的，应当宣布休庭；仍有辩护人的，庭审可以继续进行。"},{"i":255,"n":"第二百五十五条","txt":"法庭审理过程中，辩护人拒绝为被告人辩护的，应当准许；是否继续庭审，参照适用前条的规定。"},{"i":256,"n":"第二百五十六条","txt":"依照前两条规定另行委托辩护人或者指派律师的，自案件宣布休庭之日起至第十五日止，由辩护人准备辩护，但被告人及其辩护人自愿缩短时间的除外。"},{"i":257,"n":"第二百五十七条","txt":"有多名被告人的案件，部分被告人具有刑事诉讼法第二百条第一款规定情形的，人民法院可以对全案中止审理；根据案件情况，也可以对该部分被告人中止审理，对其他被告人继续审理。"},{"i":258,"n":"第二百五十八条","txt":"人民检察院认为人民法院审理案件违反法定程序，在庭审后提出书面纠正意见，人民法院认为正确的，应当采纳。"},{"i":259,"n":"第二百五十九条","txt":"人民法院受理自诉案件必须符合下列条件："},{"i":260,"n":"第二百六十条","txt":"本解释第一条规定的案件，如果被害人死亡、丧失行为能力或者因受强制、威吓等无法告诉，或者是限制行为能力人以及因年老、患病、盲、聋、哑等不能亲自告诉，其法定代理人、近亲属告诉或者代为告诉的，人民法院应当依法受理。"},{"i":261,"n":"第二百六十一条","txt":"提起自诉应当提交刑事自诉状；同时提起附带民事诉讼的，应当提交刑事附带民事自诉状。"},{"i":262,"n":"第二百六十二条","txt":"自诉状应当包括以下内容："},{"i":263,"n":"第二百六十三条","txt":"对自诉案件，人民法院应当在十五日内审查完毕。经审查，符合受理条件的，应当决定立案，并书面通知自诉人或者代为告诉人。"},{"i":264,"n":"第二百六十四条","txt":"对已经立案，经审查缺乏罪证的自诉案件，自诉人提不出补充证据的，人民法院应当说服其撤回起诉或者裁定驳回起诉；自诉人撤回起诉或者被驳回起诉后，又提出了新的足以证明被告人有罪的证据，再次提起自诉的，人民法院应当受理。"},{"i":265,"n":"第二百六十五条","txt":"自诉人对不予受理或者驳回起诉的裁定不服的，可以提起上诉。"},{"i":266,"n":"第二百六十六条","txt":"自诉人明知有其他共同侵害人，但只对部分侵害人提起自诉的，人民法院应当受理，并告知其放弃告诉的法律后果；自诉人放弃告诉，判决宣告后又对其他共同侵害人就同一事实提起自诉的，人民法院不予受理。"},{"i":267,"n":"第二百六十七条","txt":"被告人实施两个以上犯罪行为，分别属于公诉案件和自诉案件，人民法院可以一并审理。对自诉部分的审理，适用本章的规定。"},{"i":268,"n":"第二百六十八条","txt":"自诉案件当事人因客观原因不能取得的证据，申请人民法院调取的，应当说明理由，并提供相关线索或者材料。人民法院认为有必要的，应当及时调取。"},{"i":269,"n":"第二百六十九条","txt":"对犯罪事实清楚，有足够证据的自诉案件，应当开庭审理。"},{"i":270,"n":"第二百七十条","txt":"自诉案件，符合简易程序适用条件的，可以适用简易程序审理。"},{"i":271,"n":"第二百七十一条","txt":"人民法院审理自诉案件，可以在查明事实、分清是非的基础上，根据自愿、合法的原则进行调解。调解达成协议的，应当制作刑事调解书，由审判人员和书记员署名，并加盖人民法院印章。调解书经双方当事人签收后，即具有法律效力。调解没有达成协议，或者调解书签收前当事人反悔的，应当及时作出判决。"},{"i":272,"n":"第二百七十二条","txt":"判决宣告前，自诉案件的当事人可以自行和解，自诉人可以撤回自诉。"},{"i":273,"n":"第二百七十三条","txt":"裁定准许撤诉或者当事人自行和解的自诉案件，被告人被采取强制措施的，人民法院应当立即解除。"},{"i":274,"n":"第二百七十四条","txt":"自诉人经两次传唤，无正当理由拒不到庭，或者未经法庭准许中途退庭的，人民法院应当裁定按撤诉处理。"},{"i":275,"n":"第二百七十五条","txt":"被告人在自诉案件审判期间下落不明的，人民法院应当裁定中止审理。被告人到案后，应当恢复审理，必要时应当对被告人依法采取强制措施。"},{"i":276,"n":"第二百七十六条","txt":"对自诉案件，应当参照刑事诉讼法第一百九十五条和本解释第二百四十一条的有关规定作出判决；对依法宣告无罪的案件，其附带民事部分应当依法进行调解或者一并作出判决。"},{"i":277,"n":"第二百七十七条","txt":"告诉才处理和被害人有证据证明的轻微刑事案件的被告人或者其法定代理人在诉讼过程中，可以对自诉人提起反诉。反诉必须符合下列条件："},{"i":278,"n":"第二百七十八条","txt":"人民法院受理单位犯罪案件，除依照本解释第一百八十条的有关规定进行审查外，还应当审查起诉书是否列明被告单位的名称、住所地、联系方式，法定代表人、主要负责人以及代表被告单位出庭的诉讼代表人的姓名、职务、联系方式。需要人民检察院补充材料的，应当通知人民检察院在三日内补送。"},{"i":279,"n":"第二百七十九条","txt":"被告单位的诉讼代表人，应当是法定代表人或者主要负责人；法定代表人或者主要负责人被指控为单位犯罪直接负责的主管人员或者因客观原因无法出庭的，应当由被告单位委托其他负责人或者职工作为诉讼代表人。但是，有关人员被指控为单位犯罪的其他直接责任人员或者知道案件情况、负有作证义务的除外。"},{"i":280,"n":"第二百八十条","txt":"开庭审理单位犯罪案件，应当通知被告单位的诉讼代表人出庭；没有诉讼代表人参与诉讼的，应当要求人民检察院确定。"},{"i":281,"n":"第二百八十一条","txt":"被告单位的诉讼代表人享有刑事诉讼法规定的有关被告人的诉讼权利。开庭时，诉讼代表人席位置于审判台前左侧，与辩护人席并列。"},{"i":282,"n":"第二百八十二条","txt":"被告单位委托辩护人，参照适用本解释的有关规定。"},{"i":283,"n":"第二百八十三条","txt":"对应当认定为单位犯罪的案件，人民检察院只作为自然人犯罪起诉的，人民法院应当建议人民检察院对犯罪单位补充起诉。人民检察院仍以自然人犯罪起诉的，人民法院应当依法审理，按照单位犯罪中的直接负责的主管人员或者其他直接责任人员追究刑事责任，并援引刑法分则关于追究单位犯罪中直接负责的主管人员和其他直接责任人员刑事责任的条款。"},{"i":284,"n":"第二百八十四条","txt":"被告单位的违法所得及其孳息，尚未被依法追缴或者查封、扣押、冻结的，人民法院应当决定追缴或者查封、扣押、冻结。"},{"i":285,"n":"第二百八十五条","txt":"为保证判决的执行，人民法院可以先行查封、扣押、冻结被告单位的财产，或者由被告单位提出担保。"},{"i":286,"n":"第二百八十六条","txt":"审判期间，被告单位被撤销、注销、吊销营业执照或者宣告破产的，对单位犯罪直接负责的主管人员和其他直接责任人员应当继续审理。"},{"i":287,"n":"第二百八十七条","txt":"审判期间，被告单位合并、分立的，应当将原单位列为被告单位，并注明合并、分立情况。对被告单位所判处的罚金以其在新单位的财产及收益为限。"},{"i":288,"n":"第二百八十八条","txt":"审理单位犯罪案件，本章没有规定的，参照适用本解释的有关规定。"},{"i":289,"n":"第二百八十九条","txt":"基层人民法院受理公诉案件后，经审查认为案件事实清楚、证据充分的，在将起诉书副本送达被告人时，应当询问被告人对指控的犯罪事实的意见，告知其适用简易程序的法律规定。被告人对指控的犯罪事实没有异议并同意适用简易程序的，可以决定适用简易程序，并在开庭前通知人民检察院和辩护人。"},{"i":290,"n":"第二百九十条","txt":"具有下列情形之一的，不适用简易程序："},{"i":291,"n":"第二百九十一条","txt":"适用简易程序审理的案件，符合刑事诉讼法第三十四条第一款规定的，人民法院应当告知被告人及其近亲属可以申请法律援助。"},{"i":292,"n":"第二百九十二条","txt":"适用简易程序审理案件，人民法院应当在开庭三日前，将开庭的时间、地点通知人民检察院、自诉人、被告人、辩护人，也可以通知其他诉讼参与人。"},{"i":293,"n":"第二百九十三条","txt":"适用简易程序审理案件，被告人有辩护人的，应当通知其出庭。"},{"i":294,"n":"第二百九十四条","txt":"适用简易程序审理案件，审判长或者独任审判员应当当庭询问被告人对指控的犯罪事实的意见，告知被告人适用简易程序审理的法律规定，确认被告人是否同意适用简易程序。"},{"i":295,"n":"第二百九十五条","txt":"适用简易程序审理案件，可以对庭审作如下简化："},{"i":296,"n":"第二百九十六条","txt":"适用简易程序独任审判过程中，发现对被告人可能判处的有期徒刑超过三年的，应当转由合议庭审理。"},{"i":297,"n":"第二百九十七条","txt":"适用简易程序审理案件，一般应当当庭宣判。"},{"i":298,"n":"第二百九十八条","txt":"适用简易程序审理案件，在法庭审理过程中，有下列情形之一的，应当转为普通程序审理："},{"i":299,"n":"第二百九十九条","txt":"地方各级人民法院在宣告第一审判决、裁定时，应当告知被告人、自诉人及其法定代理人不服判决、裁定的，有权在法定期限内以书面或者口头形式，通过本院或者直接向上一级人民法院提出上诉；被告人的辩护人、近亲属经被告人同意，也可以提出上诉；附带民事诉讼当事人及其法定代理人，可以对判决、裁定中的附带民事部分提出上诉。"},{"i":300,"n":"第三百条","txt":"人民法院受理的上诉案件，一般应当有上诉状正本及副本。"},{"i":301,"n":"第三百零一条","txt":"上诉、抗诉必须在法定期限内提出。不服判决的上诉、抗诉的期限为十日；不服裁定的上诉、抗诉的期限为五日。上诉、抗诉的期限，从接到判决书、裁定书的第二日起计算。"},{"i":302,"n":"第三百零二条","txt":"上诉人通过第一审人民法院提出上诉的，第一审人民法院应当审查。上诉符合法律规定的，应当在上诉期满后三日内将上诉状连同案卷、证据移送上一级人民法院，并将上诉状副本送交同级人民检察院和对方当事人。"},{"i":303,"n":"第三百零三条","txt":"上诉人直接向第二审人民法院提出上诉的，第二审人民法院应当在收到上诉状后三日内将上诉状交第一审人民法院。第一审人民法院应当审查上诉是否符合法律规定。符合法律规定的，应当在接到上诉状后三日内将上诉状连同案卷、证据移送上一级人民法院，并将上诉状副本送交同级人民检察院和对方当事人。"},{"i":304,"n":"第三百零四条","txt":"上诉人在上诉期限内要求撤回上诉的，人民法院应当准许。"},{"i":305,"n":"第三百零五条","txt":"上诉人在上诉期满后要求撤回上诉的，第二审人民法院应当审查。经审查，认为原判认定事实和适用法律正确，量刑适当的，应当裁定准许撤回上诉；认为原判事实不清、证据不足或者将无罪判为有罪、轻罪重判等的，应当不予准许，继续按照上诉案件审理。"},{"i":306,"n":"第三百零六条","txt":"地方各级人民检察院对同级人民法院第一审判决、裁定的抗诉，应当通过第一审人民法院提交抗诉书。第一审人民法院应当在抗诉期满后三日内将抗诉书连同案卷、证据移送上一级人民法院，并将抗诉书副本送交当事人。"},{"i":307,"n":"第三百零七条","txt":"人民检察院在抗诉期限内撤回抗诉的，第一审人民法院不再向上一级人民法院移送案件；在抗诉期满后第二审人民法院宣告裁判前撤回抗诉的，第二审人民法院可以裁定准许，并通知第一审人民法院和当事人。"},{"i":308,"n":"第三百零八条","txt":"在上诉、抗诉期满前撤回上诉、抗诉的，第一审判决、裁定在上诉、抗诉期满之日起生效。在上诉、抗诉期满后要求撤回上诉、抗诉，第二审人民法院裁定准许的，第一审判决、裁定应当自第二审裁定书送达上诉人或者抗诉机关之日起生效。"},{"i":309,"n":"第三百零九条","txt":"第二审人民法院对第一审人民法院移送的上诉、抗诉案卷、证据，应当审查是否包括下列内容："},{"i":310,"n":"第三百一十条","txt":"第二审人民法院审理上诉、抗诉案件，应当就第一审判决、裁定认定的事实和适用法律进行全面审查，不受上诉、抗诉范围的限制。"},{"i":311,"n":"第三百一十一条","txt":"共同犯罪案件，只有部分被告人提出上诉，或者自诉人只对部分被告人的判决提出上诉，或者人民检察院只对部分被告人的判决提出抗诉的，第二审人民法院应当对全案进行审查，一并处理。"},{"i":312,"n":"第三百一十二条","txt":"共同犯罪案件，上诉的被告人死亡，其他被告人未上诉的，第二审人民法院仍应对全案进行审查。经审查，死亡的被告人不构成犯罪的，应当宣告无罪；构成犯罪的，应当终止审理。对其他同案被告人仍应作出判决、裁定。"},{"i":313,"n":"第三百一十三条","txt":"刑事附带民事诉讼案件，只有附带民事诉讼当事人及其法定代理人上诉的，第二审人民法院应当对全案进行审查。经审查，第一审判决的刑事部分并无不当的，第二审人民法院只需就附带民事部分作出处理；第一审判决的附带民事部分事实清楚，适用法律正确的，应当以刑事附带民事裁定维持原判，驳回上诉。"},{"i":314,"n":"第三百一十四条","txt":"刑事附带民事诉讼案件，只有附带民事诉讼当事人及其法定代理人上诉的，第一审刑事部分的判决在上诉期满后即发生法律效力。"},{"i":315,"n":"第三百一十五条","txt":"对上诉、抗诉案件，应当着重审查下列内容："},{"i":316,"n":"第三百一十六条","txt":"第二审期间，被告人除自行辩护外，还可以继续委托第一审辩护人或者另行委托辩护人辩护。"},{"i":317,"n":"第三百一十七条","txt":"下列案件，根据刑事诉讼法第二百二十三条第一款的规定，应当开庭审理："},{"i":318,"n":"第三百一十八条","txt":"对上诉、抗诉案件，第二审人民法院经审查，认为原判事实不清、证据不足，或者具有刑事诉讼法第二百二十七条规定的违反法定诉讼程序情形，需要发回重新审判的，可以不开庭审理。"},{"i":319,"n":"第三百一十九条","txt":"第二审期间，人民检察院或者被告人及其辩护人提交新证据的，人民法院应当及时通知对方查阅、摘抄或者复制。"},{"i":320,"n":"第三百二十条","txt":"开庭审理第二审公诉案件，应当在决定开庭审理后及时通知人民检察院查阅案卷。自通知后的第二日起，人民检察院查阅案卷的时间不计入审理期限。"},{"i":321,"n":"第三百二十一条","txt":"开庭审理上诉、抗诉的公诉案件，应当通知同级人民检察院派员出庭。"},{"i":322,"n":"第三百二十二条","txt":"开庭审理上诉、抗诉案件，除参照适用第一审程序的有关规定外，应当按照下列规定进行："},{"i":323,"n":"第三百二十三条","txt":"开庭审理上诉、抗诉案件，可以重点围绕对第一审判决、裁定有争议的问题或者有疑问的部分进行。根据案件情况，可以按照下列方式审理："},{"i":324,"n":"第三百二十四条","txt":"第二审案件依法不开庭审理的，应当讯问被告人，听取其他当事人、辩护人、诉讼代理人的意见。合议庭全体成员应当阅卷，必要时应当提交书面阅卷意见。"},{"i":325,"n":"第三百二十五条","txt":"审理被告人或者其法定代理人、辩护人、近亲属提出上诉的案件，不得加重被告人的刑罚，并应当执行下列规定："},{"i":326,"n":"第三百二十六条","txt":"人民检察院只对部分被告人的判决提出抗诉，或者自诉人只对部分被告人的判决提出上诉的，第二审人民法院不得对其他同案被告人加重刑罚。"},{"i":327,"n":"第三百二十七条","txt":"被告人或者其法定代理人、辩护人、近亲属提出上诉的案件，第二审人民法院发回重新审判后，除有新的犯罪事实，人民检察院补充起诉的以外，原审人民法院不得加重被告人的刑罚。"},{"i":328,"n":"第三百二十八条","txt":"原判事实不清、证据不足，第二审人民法院发回重新审判的案件，原审人民法院重新作出判决后，被告人上诉或者人民检察院抗诉的，第二审人民法院应当依法作出判决、裁定，不得再发回重新审判。"},{"i":329,"n":"第三百二十九条","txt":"第二审人民法院发现原审人民法院在重新审判过程中，有刑事诉讼法第二百二十七条规定的情形之一，或者违反第二百二十八条规定的，应当裁定撤销原判，发回重新审判。"},{"i":330,"n":"第三百三十条","txt":"第二审人民法院审理对刑事部分提出上诉、抗诉，附带民事部分已经发生法律效力的案件，发现第一审判决、裁定中的附带民事部分确有错误的，应当依照审判监督程序对附带民事部分予以纠正。"},{"i":331,"n":"第三百三十一条","txt":"第二审人民法院审理对附带民事部分提出上诉，刑事部分已经发生法律效力的案件，发现第一审判决、裁定中的刑事部分确有错误的，应当依照审判监督程序对刑事部分进行再审，并将附带民事部分与刑事部分一并审理。"},{"i":332,"n":"第三百三十二条","txt":"第二审期间，第一审附带民事诉讼原告人增加独立的诉讼请求或者第一审附带民事诉讼被告人提出反诉的，第二审人民法院可以根据自愿、合法的原则进行调解；调解不成的，告知当事人另行起诉。"},{"i":333,"n":"第三百三十三条","txt":"对第二审自诉案件，必要时可以调解，当事人也可以自行和解。调解结案的，应当制作调解书，第一审判决、裁定视为自动撤销；当事人自行和解的，应当裁定准许撤回自诉，并撤销第一审判决、裁定。"},{"i":334,"n":"第三百三十四条","txt":"第二审期间，自诉案件的当事人提出反诉的，应当告知其另行起诉。"},{"i":335,"n":"第三百三十五条","txt":"第二审人民法院可以委托第一审人民法院代为宣判，并向当事人送达第二审判决书、裁定书。第一审人民法院应当在代为宣判后五日内将宣判笔录送交第二审人民法院，并在送达完毕后及时将送达回证送交第二审人民法院。"},{"i":336,"n":"第三百三十六条","txt":"报请最高人民法院核准在法定刑以下判处刑罚的案件，应当按照下列情形分别处理："},{"i":337,"n":"第三百三十七条","txt":"报请最高人民法院核准在法定刑以下判处刑罚的案件，应当报送判决书、报请核准的报告各五份，以及全部案卷、证据。"},{"i":338,"n":"第三百三十八条","txt":"对在法定刑以下判处刑罚的案件，最高人民法院予以核准的，应当作出核准裁定书；不予核准的，应当作出不核准裁定书，并撤销原判决、裁定，发回原审人民法院重新审判或者指定其他下级人民法院重新审判。"},{"i":339,"n":"第三百三十九条","txt":"依照本解释第三百三十六条、第三百三十八条规定发回第二审人民法院重新审判的案件，第二审人民法院可以直接改判；必须通过开庭查清事实、核实证据或者纠正原审程序违法的，应当开庭审理。"},{"i":340,"n":"第三百四十条","txt":"最高人民法院和上级人民法院复核在法定刑以下判处刑罚案件的审理期限，参照适用刑事诉讼法第二百三十二条的规定。"},{"i":341,"n":"第三百四十一条","txt":"报请最高人民法院核准因罪犯具有特殊情况，不受执行刑期限制的假释案件，应当按照下列情形分别处理："},{"i":342,"n":"第三百四十二条","txt":"报请最高人民法院核准因罪犯具有特殊情况，不受执行刑期限制的假释案件，应当报送报请核准的报告、罪犯具有特殊情况的报告、假释裁定书各五份，以及全部案卷。"},{"i":343,"n":"第三百四十三条","txt":"对因罪犯具有特殊情况，不受执行刑期限制的假释案件，最高人民法院予以核准的，应当作出核准裁定书；不予核准的，应当作出不核准裁定书，并撤销原裁定。"},{"i":344,"n":"第三百四十四条","txt":"报请最高人民法院核准死刑案件，应当按照下列情形分别处理："},{"i":345,"n":"第三百四十五条","txt":"中级人民法院判处死刑缓期执行的第一审案件，被告人未上诉、人民检察院未抗诉的，应当报请高级人民法院核准。"},{"i":346,"n":"第三百四十六条","txt":"报请复核的死刑、死刑缓期执行案件，应当一案一报。报送的材料包括报请复核的报告，第一、二审裁判文书，死刑案件综合报告各五份以及全部案卷、证据。死刑案件综合报告，第一、二审裁判文书和审理报告应当附送电子文本。"},{"i":347,"n":"第三百四十七条","txt":"报请复核的报告，应当写明案由、简要案情、审理过程和判决结果。"},{"i":348,"n":"第三百四十八条","txt":"复核死刑、死刑缓期执行案件，应当全面审查以下内容："},{"i":349,"n":"第三百四十九条","txt":"高级人民法院复核死刑缓期执行案件，应当按照下列情形分别处理："},{"i":350,"n":"第三百五十条","txt":"最高人民法院复核死刑案件，应当按照下列情形分别处理："},{"i":351,"n":"第三百五十一条","txt":"对一人有两罪以上被判处死刑的数罪并罚案件，最高人民法院复核后，认为其中部分犯罪的死刑判决、裁定事实不清、证据不足的，应当对全案裁定不予核准，并撤销原判，发回重新审判；认为其中部分犯罪的死刑判决、裁定认定事实正确，但依法不应当判处死刑的，可以改判，并对其他应当判处死刑的犯罪作出核准死刑的判决。"},{"i":352,"n":"第三百五十二条","txt":"对有两名以上被告人被判处死刑的案件，最高人民法院复核后，认为其中部分被告人的死刑判决、裁定事实不清、证据不足的，应当对全案裁定不予核准，并撤销原判，发回重新审判；认为其中部分被告人的死刑判决、裁定认定事实正确，但依法不应当判处死刑的，可以改判，并对其他应当判处死刑的被告人作出核准死刑的判决。"},{"i":353,"n":"第三百五十三条","txt":"最高人民法院裁定不予核准死刑的，根据案件情况，可以发回第二审人民法院或者第一审人民法院重新审判。"},{"i":354,"n":"第三百五十四条","txt":"高级人民法院依照复核程序审理后报请最高人民法院核准死刑，最高人民法院裁定不予核准，发回高级人民法院重新审判的，高级人民法院可以依照第二审程序提审或者发回重新审判。"},{"i":355,"n":"第三百五十五条","txt":"最高人民法院裁定不予核准死刑，发回重新审判的案件，原审人民法院应当另行组成合议庭审理，但本解释第三百五十条第四项、第五项规定的案件除外。"},{"i":356,"n":"第三百五十六条","txt":"死刑复核期间，辩护律师要求当面反映意见的，最高人民法院有关合议庭应当在办公场所听取其意见，并制作笔录；辩护律师提出书面意见的，应当附卷。"},{"i":357,"n":"第三百五十七条","txt":"死刑复核期间，最高人民检察院提出意见的，最高人民法院应当审查，并将采纳情况及理由反馈最高人民检察院。"},{"i":358,"n":"第三百五十八条","txt":"最高人民法院应当根据有关规定向最高人民检察院通报死刑案件复核结果。"},{"i":359,"n":"第三百五十九条","txt":"人民法院对查封、扣押、冻结的被告人财物及其孳息，应当妥善保管，并制作清单，附卷备查；对人民检察院随案移送的被告人财物及其孳息，应当根据清单核查后妥善保管。任何单位和个人不得挪用或者自行处理。"},{"i":360,"n":"第三百六十条","txt":"对被害人的合法财产，权属明确的，应当依法及时返还，但须经拍照、鉴定、估价，并在案卷中注明返还的理由，将原物照片、清单和被害人的领取手续附卷备查；权属不明的，应当在人民法院判决、裁定生效后，按比例返还被害人，但已获退赔的部分应予扣除。"},{"i":361,"n":"第三百六十一条","txt":"审判期间，权利人申请出卖被扣押、冻结的债券、股票、基金份额等财产，人民法院经审查，认为不损害国家利益、被害人利益，不影响诉讼正常进行的，以及扣押、冻结的汇票、本票、支票有效期即将届满的，可以在判决、裁定生效前依法出卖，所得价款由人民法院保管，并及时告知当事人或者其近亲属。"},{"i":362,"n":"第三百六十二条","txt":"对作为证据使用的实物，包括作为物证的货币、有价证券等，应当随案移送。第一审判决、裁定宣告后，被告人上诉或者人民检察院抗诉的，第一审人民法院应当将上述证据移送第二审人民法院。"},{"i":363,"n":"第三百六十三条","txt":"对不宜移送的实物，应当根据情况，分别审查以下内容："},{"i":364,"n":"第三百六十四条","txt":"法庭审理过程中，对查封、扣押、冻结的财物及其孳息，应当调查其权属情况，是否属于违法所得或者依法应当追缴的其他涉案财物。"},{"i":365,"n":"第三百六十五条","txt":"对查封、扣押、冻结的财物及其孳息，应当在判决书中写明名称、金额、数量、存放地点及其处理方式等。涉案财物较多，不宜在判决主文中详细列明的，可以附清单。"},{"i":366,"n":"第三百六十六条","txt":"查封、扣押、冻结的财物及其孳息，经审查，确属违法所得或者依法应当追缴的其他涉案财物的，应当判决返还被害人，或者没收上缴国库，但法律另有规定的除外。"},{"i":367,"n":"第三百六十七条","txt":"随案移送的或者人民法院查封、扣押的财物及其孳息，由第一审人民法院在判决生效后负责处理。"},{"i":368,"n":"第三百六十八条","txt":"对冻结的存款、汇款、债券、股票、基金份额等财产判决没收的，第一审人民法院应当在判决生效后，将判决书、裁定书送达相关金融机构和财政部门，通知相关金融机构依法上缴国库并在接到执行通知书后十五日内，将上缴国库的凭证、执行回单送回。"},{"i":369,"n":"第三百六十九条","txt":"查封、扣押、冻结的财物与本案无关但已列入清单的，应当由查封、扣押、冻结机关依法处理。"},{"i":370,"n":"第三百七十条","txt":"查封、扣押、冻结财物及其处理，本解释没有规定的，参照适用法律、其他司法解释的有关规定。"},{"i":371,"n":"第三百七十一条","txt":"当事人及其法定代理人、近亲属对已经发生法律效力的判决、裁定提出申诉的，人民法院应当审查处理。"},{"i":372,"n":"第三百七十二条","txt":"向人民法院申诉，应当提交以下材料："},{"i":373,"n":"第三百七十三条","txt":"申诉由终审人民法院审查处理。但是，第二审人民法院裁定准许撤回上诉的案件，申诉人对第一审判决提出申诉的，可以由第一审人民法院审查处理。"},{"i":374,"n":"第三百七十四条","txt":"对死刑案件的申诉，可以由原核准的人民法院直接审查处理，也可以交由原审人民法院审查。原审人民法院应当写出审查报告，提出处理意见，层报原核准的人民法院审查处理。"},{"i":375,"n":"第三百七十五条","txt":"对立案审查的申诉案件，应当在三个月内作出决定，至迟不得超过六个月。"},{"i":376,"n":"第三百七十六条","txt":"具有下列情形之一，可能改变原判决、裁定据以定罪量刑的事实的证据，应当认定为刑事诉讼法第二百四十二条第一项规定的“新的证据”："},{"i":377,"n":"第三百七十七条","txt":"申诉人对驳回申诉不服的，可以向上一级人民法院申诉。上一级人民法院经审查认为申诉不符合刑事诉讼法第二百四十二条和本解释第三百七十五条第二款规定的，应当说服申诉人撤回申诉；对仍然坚持申诉的，应当驳回或者通知不予重新审判。"},{"i":378,"n":"第三百七十八条","txt":"各级人民法院院长发现本院已经发生法律效力的判决、裁定确有错误的，应当提交审判委员会讨论决定是否再审。"},{"i":379,"n":"第三百七十九条","txt":"上级人民法院发现下级人民法院已经发生法律效力的判决、裁定确有错误的，可以指令下级人民法院再审；原判决、裁定认定事实正确但适用法律错误，或者案件疑难、复杂、重大，或者有不宜由原审人民法院审理情形的，也可以提审。"},{"i":380,"n":"第三百八十条","txt":"对人民检察院依照审判监督程序提出抗诉的案件，人民法院应当在收到抗诉书后一个月内立案。但是，有下列情形之一的，应当区别情况予以处理："},{"i":381,"n":"第三百八十一条","txt":"对人民检察院依照审判监督程序提出抗诉的案件，接受抗诉的人民法院应当组成合议庭审理。对原判事实不清、证据不足，包括有新的证据证明原判可能有错误，需要指令下级人民法院再审的，应当在立案之日起一个月内作出决定，并将指令再审决定书送达抗诉的人民检察院。"},{"i":382,"n":"第三百八十二条","txt":"对决定依照审判监督程序重新审判的案件，除人民检察院抗诉的以外，人民法院应当制作再审决定书。再审期间不停止原判决、裁定的执行，但被告人可能经再审改判无罪，或者可能经再审减轻原判刑罚而致刑期届满的，可以决定中止原判决、裁定的执行，必要时，可以对被告人采取取保候审、监视居住措施。"},{"i":383,"n":"第三百八十三条","txt":"依照审判监督程序重新审判的案件，人民法院应当重点针对申诉、抗诉和决定再审的理由进行审理。必要时，应当对原判决、裁定认定的事实、证据和适用法律进行全面审查。"},{"i":384,"n":"第三百八十四条","txt":"原审人民法院审理依照审判监督程序重新审判的案件，应当另行组成合议庭。"},{"i":385,"n":"第三百八十五条","txt":"开庭审理的再审案件，再审决定书或者抗诉书只针对部分原审被告人，其他同案原审被告人不出庭不影响审理的，可以不出庭参加诉讼。"},{"i":386,"n":"第三百八十六条","txt":"除人民检察院抗诉的以外，再审一般不得加重原审被告人的刑罚。再审决定书或者抗诉书只针对部分原审被告人的，不得加重其他同案原审被告人的刑罚。"},{"i":387,"n":"第三百八十七条","txt":"人民法院审理人民检察院抗诉的再审案件，人民检察院在开庭审理前撤回抗诉的，应当裁定准许；人民检察院接到出庭通知后不派员出庭，且未说明原因的，可以裁定按撤回抗诉处理，并通知诉讼参与人。"},{"i":388,"n":"第三百八十八条","txt":"开庭审理的再审案件，系人民法院决定再审的，由合议庭组成人员宣读再审决定书；系人民检察院抗诉的，由检察人员宣读抗诉书；系申诉人申诉的，由申诉人或者其辩护人、诉讼代理人陈述申诉理由。"},{"i":389,"n":"第三百八十九条","txt":"再审案件经过重新审理后，应当按照下列情形分别处理："},{"i":390,"n":"第三百九十条","txt":"原判决、裁定认定被告人姓名等身份信息有误，但认定事实和适用法律正确、量刑适当的，作出生效判决、裁定的人民法院可以通过裁定对有关信息予以更正。"},{"i":391,"n":"第三百九十一条","txt":"对再审改判宣告无罪并依法享有申请国家赔偿权利的当事人，人民法院宣判时，应当告知其在判决发生法律效力后可以依法申请国家赔偿。"},{"i":392,"n":"第三百九十二条","txt":"本解释所称的涉外刑事案件是指："},{"i":393,"n":"第三百九十三条","txt":"第一审涉外刑事案件，除刑事诉讼法第二十条至第二十二条规定的以外，由基层人民法院管辖。必要时，中级人民法院可以指定辖区内若干基层人民法院集中管辖第一审涉外刑事案件，也可以依照刑事诉讼法第二十三条的规定，审理基层人民法院管辖的第一审涉外刑事案件。"},{"i":394,"n":"第三百九十四条","txt":"外国人的国籍，根据其入境时的有效证件确认；国籍不明的，根据公安机关或者有关国家驻华使、领馆出具的证明确认。"},{"i":395,"n":"第三百九十五条","txt":"在刑事诉讼中，外国籍当事人享有我国法律规定的诉讼权利并承担相应义务。"},{"i":396,"n":"第三百九十六条","txt":"涉外刑事案件审判期间，人民法院应当将下列事项及时通报同级人民政府外事主管部门，并通知有关国家驻华使、领馆："},{"i":397,"n":"第三百九十七条","txt":"需要向有关国家驻华使、领馆通知有关事项的，应当层报高级人民法院，由高级人民法院按照下列规定通知："},{"i":398,"n":"第三百九十八条","txt":"人民法院受理涉外刑事案件后，应当告知在押的外国籍被告人享有与其国籍国驻华使、领馆联系，与其监护人、近亲属会见、通信，以及请求人民法院提供翻译的权利。"},{"i":399,"n":"第三百九十九条","txt":"涉外刑事案件审判期间，外国籍被告人在押，其国籍国驻华使、领馆官员要求探视的，可以向受理案件的人民法院所在地的高级人民法院提出。人民法院应当根据我国与被告人国籍国签订的双边领事条约规定的时限予以安排；没有条约规定的，应当尽快安排。必要时，可以请人民政府外事主管部门协助。"},{"i":400,"n":"第四百条","txt":"人民法院审理涉外刑事案件，应当公开进行，但依法不应公开审理的除外。"},{"i":401,"n":"第四百零一条","txt":"人民法院审判涉外刑事案件，使用中华人民共和国通用的语言、文字，应当为外国籍当事人提供翻译。"},{"i":402,"n":"第四百零二条","txt":"外国籍被告人委托律师辩护，或者外国籍附带民事诉讼原告人、自诉人委托律师代理诉讼的，应当委托具有中华人民共和国律师资格并依法取得执业证书的律师。"},{"i":403,"n":"第四百零三条","txt":"外国籍当事人从中华人民共和国领域外寄交或者托交给中国律师或者中国公民的委托书，以及外国籍当事人的监护人、近亲属提供的与当事人关系的证明，必须经所在国公证机关证明，所在国中央外交主管机关或者其授权机关认证，并经我国驻该国使、领馆认证，但我国与该国之间有互免认证协定的除外。"},{"i":404,"n":"第四百零四条","txt":"对涉外刑事案件的被告人，可以决定限制出境；对开庭审理案件时必须到庭的证人，可以要求暂缓出境。作出限制出境的决定，应当通报同级公安机关或者国家安全机关；限制外国人出境的，应当同时通报同级人民政府外事主管部门和当事人国籍国驻华使、领馆。"},{"i":405,"n":"第四百零五条","txt":"对来自境外的证据材料，人民法院应当对材料来源、提供人、提供时间以及提取人、提取时间等进行审查。经审查，能够证明案件事实且符合刑事诉讼法规定的，可以作为证据使用，但提供人或者我国与有关国家签订的双边条约对材料的使用范围有明确限制的除外；材料来源不明或者其真实性无法确认的，不得作为定案的根据。"},{"i":406,"n":"第四百零六条","txt":"涉外刑事案件，符合刑事诉讼法第二百零二条第一款、第二百三十二条规定的，经有关人民法院批准或者决定，可以延长审理期限。"},{"i":407,"n":"第四百零七条","txt":"涉外刑事案件宣判后，外国籍当事人国籍国驻华使、领馆要求提供裁判文书的，可以向受理案件的人民法院所在地的高级人民法院提出，人民法院可以提供。"},{"i":408,"n":"第四百零八条","txt":"根据中华人民共和国缔结或者参加的国际条约，或者按照互惠原则，人民法院和外国法院可以相互请求刑事司法协助。"},{"i":409,"n":"第四百零九条","txt":"请求和提供司法协助，应当依照中华人民共和国缔结或者参加的国际条约规定的途径进行；没有条约关系的，通过外交途径进行。"},{"i":410,"n":"第四百一十条","txt":"人民法院请求外国提供司法协助的，应当经高级人民法院审查后报最高人民法院审核同意。"},{"i":411,"n":"第四百一十一条","txt":"人民法院请求外国提供司法协助的请求书及其所附文件，应当附有该国文字译本或者国际条约规定的其他文字文本。"},{"i":412,"n":"第四百一十二条","txt":"人民法院向在中华人民共和国领域外居住的当事人送达刑事诉讼文书，可以采用下列方式："},{"i":413,"n":"第四百一十三条","txt":"人民法院通过外交途径向在中华人民共和国领域外居住的受送达人送达刑事诉讼文书的，所送达的文书应当经高级人民法院审查后报最高人民法院审核。最高人民法院认为可以发出的，由最高人民法院交外交部主管部门转递。"},{"i":414,"n":"第四百一十四条","txt":"涉外刑事案件审理过程中的其他事宜，依照法律、司法解释和其他有关规定办理。"},{"i":415,"n":"第四百一十五条","txt":"被判处死刑缓期执行的罪犯，在死刑缓期执行期间故意犯罪的，应当由罪犯服刑地的中级人民法院依法审判，所作的判决可以上诉、抗诉。"},{"i":416,"n":"第四百一十六条","txt":"死刑缓期执行的期间，从判决或者裁定核准死刑缓期执行的法律文书宣告或者送达之日起计算。"},{"i":417,"n":"第四百一十七条","txt":"最高人民法院的执行死刑命令，由高级人民法院交付第一审人民法院执行。第一审人民法院接到执行死刑命令后，应当在七日内执行。"},{"i":418,"n":"第四百一十八条","txt":"第一审人民法院在接到执行死刑命令后、执行前，发现有下列情形之一的，应当暂停执行，并立即将请求停止执行死刑的报告和相关材料层报最高人民法院："},{"i":419,"n":"第四百一十九条","txt":"最高人民法院在执行死刑命令签发后、执行前，发现有前条第一款规定情形的，应当立即裁定停止执行死刑，并将有关材料移交下级人民法院。"},{"i":420,"n":"第四百二十条","txt":"下级人民法院接到最高人民法院停止执行死刑的裁定后，应当会同有关部门调查核实停止执行死刑的事由，并及时将调查结果和意见层报最高人民法院审核。"},{"i":421,"n":"第四百二十一条","txt":"对下级人民法院报送的停止执行死刑的调查结果和意见，由最高人民法院原作出核准死刑判决、裁定的合议庭负责审查，必要时，另行组成合议庭进行审查。"},{"i":422,"n":"第四百二十二条","txt":"最高人民法院对停止执行死刑的案件，应当按照下列情形分别处理："},{"i":423,"n":"第四百二十三条","txt":"第一审人民法院在执行死刑前，应当告知罪犯有权会见其近亲属。罪犯申请会见并提供具体联系方式的，人民法院应当通知其近亲属。罪犯近亲属申请会见的，人民法院应当准许，并及时安排会见。"},{"i":424,"n":"第四百二十四条","txt":"第一审人民法院在执行死刑三日前，应当通知同级人民检察院派员临场监督。"},{"i":425,"n":"第四百二十五条","txt":"死刑采用枪决或者注射等方法执行。"},{"i":426,"n":"第四百二十六条","txt":"执行死刑前，指挥执行的审判人员对罪犯应当验明正身，讯问有无遗言、信札，并制作笔录，再交执行人员执行死刑。"},{"i":427,"n":"第四百二十七条","txt":"执行死刑后，应当由法医验明罪犯确实死亡，在场书记员制作笔录。负责执行的人民法院应当在执行死刑后十五日内将执行情况，包括罪犯被执行死刑前后的照片，上报最高人民法院。"},{"i":428,"n":"第四百二十八条","txt":"执行死刑后，负责执行的人民法院应当办理以下事项："},{"i":429,"n":"第四百二十九条","txt":"被判处死刑缓期执行、无期徒刑、有期徒刑、拘役的罪犯，交付执行时在押的，第一审人民法院应当在判决、裁定生效后十日内，将判决书、裁定书、起诉书副本、自诉状复印件、执行通知书、结案登记表送达看守所，由公安机关将罪犯交付执行。"},{"i":430,"n":"第四百三十条","txt":"同案审理的案件中，部分被告人被判处死刑，对未被判处死刑的同案被告人需要羁押执行刑罚的，应当在其判决、裁定生效后十日内交付执行。但是，该同案被告人参与实施有关死刑之罪的，应当在最高人民法院复核讯问被判处死刑的被告人后交付执行。"},{"i":431,"n":"第四百三十一条","txt":"执行通知书回执经看守所盖章后，应当附卷备查。"},{"i":432,"n":"第四百三十二条","txt":"被判处无期徒刑、有期徒刑或者拘役的罪犯，符合刑事诉讼法第二百五十四条第一款、第二款的规定，人民法院决定暂予监外执行的，应当制作暂予监外执行决定书，写明罪犯基本情况、判决确定的罪名和刑罚、决定暂予监外执行的原因、依据等，通知罪犯居住地的县级司法行政机关派员办理交接手续，并将暂予监外执行决定书抄送罪犯居住地的县级人民检察院和公安机关。"},{"i":433,"n":"第四百三十三条","txt":"暂予监外执行的罪犯具有下列情形之一的，原作出暂予监外执行决定的人民法院，应当在收到执行机关的收监执行建议书后十五日内，作出收监执行的决定："},{"i":434,"n":"第四百三十四条","txt":"人民法院应当将收监执行决定书送交罪犯居住地的县级司法行政机关，由其根据有关规定将罪犯交付执行。收监执行决定书应当同时抄送罪犯居住地的同级人民检察院和公安机关。"},{"i":435,"n":"第四百三十五条","txt":"被收监执行的罪犯有不计入执行刑期情形的，人民法院应当在作出收监决定时，确定不计入执行刑期的具体时间。"},{"i":436,"n":"第四百三十六条","txt":"对被判处管制、宣告缓刑的罪犯，人民法院应当核实其居住地。宣判时，应当书面告知罪犯到居住地县级司法行政机关报到的期限和不按期报到的后果。判决、裁定生效后十日内，应当将判决书、裁定书、执行通知书等法律文书送达罪犯居住地的县级司法行政机关，同时抄送罪犯居住地的县级人民检察院。"},{"i":437,"n":"第四百三十七条","txt":"对单处剥夺政治权利的罪犯，人民法院应当在判决、裁定生效后十日内，将判决书、裁定书、执行通知书等法律文书送达罪犯居住地的县级公安机关，并抄送罪犯居住地的县级人民检察院。"},{"i":438,"n":"第四百三十八条","txt":"财产刑和附带民事裁判由第一审人民法院负责裁判执行的机构执行。"},{"i":439,"n":"第四百三十九条","txt":"罚金在判决规定的期限内一次或者分期缴纳。期满无故不缴纳或者未足额缴纳的，人民法院应当强制缴纳。经强制缴纳仍不能全部缴纳的，在任何时候，包括主刑执行完毕后，发现被执行人有可供执行的财产的，应当追缴。"},{"i":440,"n":"第四百四十条","txt":"执行财产刑和附带民事裁判过程中，案外人对被执行财产提出权属异议的，人民法院应当参照民事诉讼有关执行异议的规定进行审查并作出处理。"},{"i":441,"n":"第四百四十一条","txt":"被判处财产刑，同时又承担附带民事赔偿责任的被执行人，应当先履行民事赔偿责任。"},{"i":442,"n":"第四百四十二条","txt":"被执行人或者被执行财产在外地的，可以委托当地人民法院执行。"},{"i":443,"n":"第四百四十三条","txt":"执行财产刑过程中，具有下列情形之一的，人民法院应当裁定中止执行："},{"i":444,"n":"第四百四十四条","txt":"执行财产刑过程中，具有下列情形之一的，人民法院应当裁定终结执行："},{"i":445,"n":"第四百四十五条","txt":"财产刑全部或者部分被撤销的，已经执行的财产应当全部或者部分返还被执行人；无法返还的，应当依法赔偿。"},{"i":446,"n":"第四百四十六条","txt":"因遭遇不能抗拒的灾祸缴纳罚金确有困难，被执行人申请减少或者免除罚金的，应当提交相关证明材料。人民法院应当在收到申请后一个月内作出裁定。符合法定减免条件的，应当准许；不符合条件的，驳回申请。"},{"i":447,"n":"第四百四十七条","txt":"财产刑和附带民事裁判的执行，本解释没有规定的，参照适用民事执行的有关规定。"},{"i":448,"n":"第四百四十八条","txt":"被判处死刑缓期执行的罪犯，在死刑缓期执行期间，没有故意犯罪的，死刑缓期执行期满后，应当裁定减刑；死刑缓期执行期满后，尚未裁定减刑前又犯罪的，应当依法减刑后对其所犯新罪另行审判。"},{"i":449,"n":"第四百四十九条","txt":"对减刑、假释案件，应当按照下列情形分别处理："},{"i":450,"n":"第四百五十条","txt":"受理减刑、假释案件，应当审查执行机关移送的材料是否包括下列内容："},{"i":451,"n":"第四百五十一条","txt":"审理减刑、假释案件，应当审查财产刑和附带民事裁判的执行情况，以及罪犯退赃、退赔情况。罪犯积极履行判决确定的义务的，可以认定有悔改表现，在减刑、假释时从宽掌握；确有履行能力而不履行的，在减刑、假释时从严掌握。"},{"i":452,"n":"第四百五十二条","txt":"审理减刑、假释案件，应当对以下内容予以公示："},{"i":453,"n":"第四百五十三条","txt":"审理减刑、假释案件，应当组成合议庭，可以采用书面审理的方式，但下列案件应当开庭审理："},{"i":454,"n":"第四百五十四条","txt":"人民法院作出减刑、假释裁定后，应当在七日内送达提请减刑、假释的执行机关、同级人民检察院以及罪犯本人。人民检察院认为减刑、假释裁定不当，在法定期限内提出书面纠正意见的，人民法院应当在收到意见后另行组成合议庭审理，并在一个月内作出裁定。"},{"i":455,"n":"第四百五十五条","txt":"减刑、假释裁定作出前，执行机关书面提请撤回减刑、假释建议的，是否准许，由人民法院决定。"},{"i":456,"n":"第四百五十六条","txt":"人民法院发现本院已经生效的减刑、假释裁定确有错误的，应当另行组成合议庭审理；发现下级人民法院已经生效的减刑、假释裁定确有错误的，可以指令下级人民法院另行组成合议庭审理。"},{"i":457,"n":"第四百五十七条","txt":"罪犯在缓刑、假释考验期限内犯新罪或者被发现在判决宣告前还有其他罪没有判决，应当撤销缓刑、假释的，由审判新罪的人民法院撤销原判决、裁定宣告的缓刑、假释，并书面通知原审人民法院和执行机关。"},{"i":458,"n":"第四百五十八条","txt":"罪犯在缓刑、假释考验期限内，有下列情形之一的，原作出缓刑、假释判决、裁定的人民法院应当在收到执行机关的撤销缓刑、假释建议书后一个月内，作出撤销缓刑、假释的裁定："},{"i":459,"n":"第四百五十九条","txt":"人民法院审理未成年人刑事案件，应当贯彻教育、感化、挽救的方针，坚持教育为主、惩罚为辅的原则，加强对未成年人的特殊保护。"},{"i":460,"n":"第四百六十条","txt":"人民法院应当加强同政府有关部门以及共青团、妇联、工会、未成年人保护组织等团体的联系，推动未成年人刑事案件人民陪审、情况调查、安置帮教等工作的开展，充分保障未成年人的合法权益，积极参与社会管理综合治理。"},{"i":461,"n":"第四百六十一条","txt":"审理未成年人刑事案件，应当由熟悉未成年人身心特点、善于做未成年人思想教育工作的审判人员进行，并应当保持有关审判人员工作的相对稳定性。"},{"i":462,"n":"第四百六十二条","txt":"中级人民法院和基层人民法院可以设立独立建制的未成年人案件审判庭。尚不具备条件的，应当在刑事审判庭内设立未成年人刑事案件合议庭，或者由专人负责审理未成年人刑事案件。"},{"i":463,"n":"第四百六十三条","txt":"下列案件由少年法庭审理："},{"i":464,"n":"第四百六十四条","txt":"对分案起诉至同一人民法院的未成年人与成年人共同犯罪案件，可以由同一个审判组织审理；不宜由同一个审判组织审理的，可以分别由少年法庭、刑事审判庭审理。"},{"i":465,"n":"第四百六十五条","txt":"对未成年人刑事案件，必要时，上级人民法院可以根据刑事诉讼法第二十六条的规定，指定下级人民法院将案件移送其他人民法院审判。"},{"i":466,"n":"第四百六十六条","txt":"人民法院审理未成年人刑事案件，在讯问和开庭时，应当通知未成年被告人的法定代理人到场。法定代理人无法通知、不能到场或者是共犯的，也可以通知未成年被告人的其他成年亲属，所在学校、单位、居住地的基层组织或者未成年人保护组织的代表到场，并将有关情况记录在案。"},{"i":467,"n":"第四百六十七条","txt":"开庭审理时被告人不满十八周岁的案件，一律不公开审理。经未成年被告人及其法定代理人同意，未成年被告人所在学校和未成年人保护组织可以派代表到场。到场代表的人数和范围，由法庭决定。到场代表经法庭同意，可以参与对未成年被告人的法庭教育工作。"},{"i":468,"n":"第四百六十八条","txt":"确有必要通知未成年被害人、证人出庭作证的，人民法院应当根据案件情况采取相应的保护措施。有条件的，可以采取视频等方式对其陈述、证言进行质证。"},{"i":469,"n":"第四百六十九条","txt":"审理未成年人刑事案件，不得向外界披露该未成年人的姓名、住所、照片以及可能推断出该未成年人身份的其他资料。"},{"i":470,"n":"第四百七十条","txt":"审理未成年人刑事案件，本章没有规定的，适用本解释的有关规定。"},{"i":471,"n":"第四百七十一条","txt":"人民法院向未成年被告人送达起诉书副本时，应当向其讲明被指控的罪行和有关法律规定，并告知其审判程序和诉讼权利、义务。"},{"i":472,"n":"第四百七十二条","txt":"审判时不满十八周岁的未成年被告人没有委托辩护人的，人民法院应当通知法律援助机构指派律师为其提供辩护。"},{"i":473,"n":"第四百七十三条","txt":"未成年被害人及其法定代理人因经济困难或者其他原因没有委托诉讼代理人的，人民法院应当帮助其申请法律援助。"},{"i":474,"n":"第四百七十四条","txt":"对未成年人刑事案件，人民法院决定适用简易程序审理的，应当征求未成年被告人及其法定代理人、辩护人的意见。上述人员提出异议的，不适用简易程序。"},{"i":475,"n":"第四百七十五条","txt":"被告人实施被指控的犯罪时不满十八周岁，开庭时已满十八周岁、不满二十周岁的，人民法院开庭时，一般应当通知其近亲属到庭。经法庭同意，近亲属可以发表意见。近亲属无法通知、不能到场或者是共犯的，应当记录在案。"},{"i":476,"n":"第四百七十六条","txt":"对人民检察院移送的关于未成年被告人性格特点、家庭情况、社会交往、成长经历、犯罪原因、犯罪前后的表现、监护教育等情况的调查报告，以及辩护人提交的反映未成年被告人上述情况的书面材料，法庭应当接受。"},{"i":477,"n":"第四百七十七条","txt":"对未成年人刑事案件，人民法院根据情况，可以对未成年被告人进行心理疏导；经未成年被告人及其法定代理人同意，也可以对未成年被告人进行心理测评。"},{"i":478,"n":"第四百七十八条","txt":"开庭前和休庭时，法庭根据情况，可以安排未成年被告人与其法定代理人或者刑事诉讼法第二百七十条第一款规定的其他成年亲属、代表会见。"},{"i":479,"n":"第四百七十九条","txt":"人民法院应当在辩护台靠近旁听区一侧为未成年被告人的法定代理人或者刑事诉讼法第二百七十条第一款规定的其他成年亲属、代表设置席位。"},{"i":480,"n":"第四百八十条","txt":"在法庭上不得对未成年被告人使用戒具，但被告人人身危险性大，可能妨碍庭审活动的除外。必须使用戒具的，在现实危险消除后，应当立即停止使用。"},{"i":481,"n":"第四百八十一条","txt":"未成年被告人或者其法定代理人当庭拒绝辩护人辩护的，适用本解释第二百五十四条第一款、第二款的规定。"},{"i":482,"n":"第四百八十二条","txt":"法庭审理过程中，审判人员应当根据未成年被告人的智力发育程度和心理状态，使用适合未成年人的语言表达方式。"},{"i":483,"n":"第四百八十三条","txt":"控辩双方提出对未成年被告人判处管制、宣告缓刑等量刑建议的，应当向法庭提供有关未成年被告人能够获得监护、帮教以及对所居住社区无重大不良影响的书面材料。"},{"i":484,"n":"第四百八十四条","txt":"对未成年被告人情况的调查报告，以及辩护人提交的有关未成年被告人情况的书面材料，法庭应当审查并听取控辩双方意见。上述报告和材料可以作为法庭教育和量刑的参考。"},{"i":485,"n":"第四百八十五条","txt":"法庭辩论结束后，法庭可以根据案件情况，对未成年被告人进行教育；判决未成年被告人有罪的，宣判后，应当对未成年被告人进行教育。"},{"i":486,"n":"第四百八十六条","txt":"未成年被告人最后陈述后，法庭应当询问其法定代理人是否补充陈述。"},{"i":487,"n":"第四百八十七条","txt":"对未成年人刑事案件宣告判决应当公开进行，但不得采取召开大会等形式。"},{"i":488,"n":"第四百八十八条","txt":"定期宣告判决的未成年人刑事案件，未成年被告人的法定代理人无法通知、不能到庭或者是共犯的，法庭可以通知刑事诉讼法第二百七十条第一款规定的其他成年亲属、代表到庭，并在宣判后向未成年被告人的成年亲属送达判决书。"},{"i":489,"n":"第四百八十九条","txt":"将未成年罪犯送监执行刑罚或者送交社区矫正时，人民法院应当将有关未成年罪犯的调查报告及其在案件审理中的表现材料，连同有关法律文书，一并送达执行机关。"},{"i":490,"n":"第四百九十条","txt":"犯罪时不满十八周岁，被判处五年有期徒刑以下刑罚以及免除刑事处罚的未成年人的犯罪记录，应当封存。"},{"i":491,"n":"第四百九十一条","txt":"人民法院可以与未成年罪犯管教所等服刑场所建立联系，了解未成年罪犯的改造情况，协助做好帮教、改造工作，并可以对正在服刑的未成年罪犯进行回访考察。"},{"i":492,"n":"第四百九十二条","txt":"人民法院认为必要时，可以督促被收监服刑的未成年罪犯的父母或者其他监护人及时探视。"},{"i":493,"n":"第四百九十三条","txt":"对被判处管制、宣告缓刑、裁定假释、决定暂予监外执行的未成年罪犯，人民法院可以协助社区矫正机构制定帮教措施。"},{"i":494,"n":"第四百九十四条","txt":"人民法院可以适时走访被判处管制、宣告缓刑、免除刑事处罚、裁定假释、决定暂予监外执行等的未成年罪犯及其家庭，了解未成年罪犯的管理和教育情况，引导未成年罪犯的家庭承担管教责任，为未成年罪犯改过自新创造良好环境。"},{"i":495,"n":"第四百九十五条","txt":"被判处管制、宣告缓刑、免除刑事处罚、裁定假释、决定暂予监外执行等的未成年罪犯，具备就学、就业条件的，人民法院可以就其安置问题向有关部门提出司法建议，并附送必要的材料。"},{"i":496,"n":"第四百九十六条","txt":"对符合刑事诉讼法第二百七十七条规定的公诉案件，事实清楚、证据充分的，人民法院应当告知当事人可以自行和解；当事人提出申请的，人民法院可以主持双方当事人协商以达成和解。"},{"i":497,"n":"第四百九十七条","txt":"符合刑事诉讼法第二百七十七条规定的公诉案件，被害人死亡的，其近亲属可以与被告人和解。近亲属有多人的，达成和解协议，应当经处于同一继承顺序的所有近亲属同意。"},{"i":498,"n":"第四百九十八条","txt":"被告人的近亲属经被告人同意，可以代为和解。"},{"i":499,"n":"第四百九十九条","txt":"对公安机关、人民检察院主持制作的和解协议书，当事人提出异议的，人民法院应当审查。经审查，和解自愿、合法的，予以确认，无需重新制作和解协议书；和解不具有自愿性、合法性的，应当认定无效。和解协议被认定无效后，双方当事人重新达成和解的，人民法院应当主持制作新的和解协议书。"},{"i":500,"n":"第五百条","txt":"审判期间，双方当事人和解的，人民法院应当听取当事人及其法定代理人等有关人员的意见。双方当事人在庭外达成和解的，人民法院应当通知人民检察院，并听取其意见。经审查，和解自愿、合法的，应当主持制作和解协议书。"},{"i":501,"n":"第五百零一条","txt":"和解协议书应当包括以下内容："},{"i":502,"n":"第五百零二条","txt":"和解协议约定的赔偿损失内容，被告人应当在协议签署后即时履行。"},{"i":503,"n":"第五百零三条","txt":"双方当事人在侦查、审查起诉期间已经达成和解协议并全部履行，被害人或者其法定代理人、近亲属又提起附带民事诉讼的，人民法院不予受理，但有证据证明和解违反自愿、合法原则的除外。"},{"i":504,"n":"第五百零四条","txt":"被害人或者其法定代理人、近亲属提起附带民事诉讼后，双方愿意和解，但被告人不能即时履行全部赔偿义务的，人民法院应当制作附带民事调解书。"},{"i":505,"n":"第五百零五条","txt":"对达成和解协议的案件，人民法院应当对被告人从轻处罚；符合非监禁刑适用条件的，应当适用非监禁刑；判处法定最低刑仍然过重的，可以减轻处罚；综合全案认为犯罪情节轻微不需要判处刑罚的，可以免除刑事处罚。"},{"i":506,"n":"第五百零六条","txt":"达成和解协议的，裁判文书应当作出叙述，并援引刑事诉讼法的相关条文。"},{"i":507,"n":"第五百零七条","txt":"依照刑法规定应当追缴违法所得及其他涉案财产，且符合下列情形之一的，人民检察院可以向人民法院提出没收违法所得的申请："},{"i":508,"n":"第五百零八条","txt":"具有下列情形之一的，应当认定为刑事诉讼法第二百八十条第一款规定的“重大犯罪案件”："},{"i":509,"n":"第五百零九条","txt":"实施犯罪行为所取得的财物及其孳息，以及被告人非法持有的违禁品、供犯罪所用的本人财物，应当认定为刑事诉讼法第二百八十条第一款规定的“违法所得及其他涉案财产”。"},{"i":510,"n":"第五百一十条","txt":"对人民检察院提出的没收违法所得申请，人民法院应当审查以下内容："},{"i":511,"n":"第五百一十一条","txt":"对没收违法所得的申请，人民法院应当在七日内审查完毕，并按照下列情形分别处理："},{"i":512,"n":"第五百一十二条","txt":"人民法院决定受理没收违法所得的申请后，应当在十五日内发出公告，公告期为六个月。公告应当写明以下内容："},{"i":513,"n":"第五百一十三条","txt":"对申请没收的财产主张所有权的人，应当认定为刑事诉讼法第二百八十一条第二款规定的“其他利害关系人”。"},{"i":514,"n":"第五百一十四条","txt":"公告期满后，人民法院应当组成合议庭对申请没收违法所得的案件进行审理。"},{"i":515,"n":"第五百一十五条","txt":"开庭审理申请没收违法所得的案件，按照下列程序进行："},{"i":516,"n":"第五百一十六条","txt":"对申请没收违法所得的案件，人民法院审理后，应当按照下列情形分别处理："},{"i":517,"n":"第五百一十七条","txt":"对没收违法所得或者驳回申请的裁定，犯罪嫌疑人、被告人的近亲属和其他利害关系人或者人民检察院可以在五日内提出上诉、抗诉。"},{"i":518,"n":"第五百一十八条","txt":"对不服第一审没收违法所得或者驳回申请裁定的上诉、抗诉案件，第二审人民法院经审理，应当按照下列情形分别作出裁定："},{"i":519,"n":"第五百一十九条","txt":"在审理申请没收违法所得的案件过程中，在逃的犯罪嫌疑人、被告人到案的，人民法院应当裁定终止审理。人民检察院向原受理申请的人民法院提起公诉的，可以由同一审判组织审理。"},{"i":520,"n":"第五百二十条","txt":"在审理案件过程中，被告人死亡或者脱逃，符合刑事诉讼法第二百八十条第一款规定的，人民检察院可以向人民法院提出没收违法所得的申请。"},{"i":521,"n":"第五百二十一条","txt":"审理申请没收违法所得案件的期限，参照公诉案件第一审普通程序和第二审程序的审理期限执行。"},{"i":522,"n":"第五百二十二条","txt":"没收违法所得裁定生效后，犯罪嫌疑人、被告人到案并对没收裁定提出异议，人民检察院向原作出裁定的人民法院提起公诉的，可以由同一审判组织审理。"},{"i":523,"n":"第五百二十三条","txt":"人民法院审理申请没收违法所得的案件，本章没有规定的，参照适用本解释的有关规定。"},{"i":524,"n":"第五百二十四条","txt":"实施暴力行为，危害公共安全或者严重危害公民人身安全，社会危害性已经达到犯罪程度，但经法定程序鉴定依法不负刑事责任的精神病人，有继续危害社会可能的，可以予以强制医疗。"},{"i":525,"n":"第五百二十五条","txt":"人民检察院申请对依法不负刑事责任的精神病人强制医疗的案件，由被申请人实施暴力行为所在地的基层人民法院管辖；由被申请人居住地的人民法院审判更为适宜的，可以由被申请人居住地的基层人民法院管辖。"},{"i":526,"n":"第五百二十六条","txt":"对人民检察院提出的强制医疗申请，人民法院应当审查以下内容："},{"i":527,"n":"第五百二十七条","txt":"对人民检察院提出的强制医疗申请，人民法院应当在七日内审查完毕，并按照下列情形分别处理："},{"i":528,"n":"第五百二十八条","txt":"审理强制医疗案件，应当通知被申请人或者被告人的法定代理人到场。被申请人或者被告人没有委托诉讼代理人的，应当通知法律援助机构指派律师担任其诉讼代理人，为其提供法律帮助。"},{"i":529,"n":"第五百二十九条","txt":"审理强制医疗案件，应当组成合议庭，开庭审理。但是，被申请人、被告人的法定代理人请求不开庭审理，并经人民法院审查同意的除外。"},{"i":530,"n":"第五百三十条","txt":"开庭审理申请强制医疗的案件，按照下列程序进行："},{"i":531,"n":"第五百三十一条","txt":"对申请强制医疗的案件，人民法院审理后，应当按照下列情形分别处理："},{"i":532,"n":"第五百三十二条","txt":"第一审人民法院在审理案件过程中发现被告人可能符合强制医疗条件的，应当依照法定程序对被告人进行法医精神病鉴定。经鉴定，被告人属于依法不负刑事责任的精神病人的，应当适用强制医疗程序，对案件进行审理。"},{"i":533,"n":"第五百三十三条","txt":"对前条规定的案件，人民法院审理后，应当按照下列情形分别处理："},{"i":534,"n":"第五百三十四条","txt":"人民法院在审理第二审刑事案件过程中，发现被告人可能符合强制医疗条件的，可以依照强制医疗程序对案件作出处理，也可以裁定发回原审人民法院重新审判。"},{"i":535,"n":"第五百三十五条","txt":"人民法院决定强制医疗的，应当在作出决定后五日内，向公安机关送达强制医疗决定书和强制医疗执行通知书，由公安机关将被决定强制医疗的人送交强制医疗。"},{"i":536,"n":"第五百三十六条","txt":"被决定强制医疗的人、被害人及其法定代理人、近亲属对强制医疗决定不服的，可以自收到决定书之日起五日内向上一级人民法院申请复议。复议期间不停止执行强制医疗的决定。"},{"i":537,"n":"第五百三十七条","txt":"对不服强制医疗决定的复议申请，上一级人民法院应当组成合议庭审理，并在一个月内，按照下列情形分别作出复议决定："},{"i":538,"n":"第五百三十八条","txt":"对本解释第五百三十三条第一项规定的判决、决定，人民检察院提出抗诉，同时被决定强制医疗的人、被害人及其法定代理人、近亲属申请复议的，上一级人民法院应当依照第二审程序一并处理。"},{"i":539,"n":"第五百三十九条","txt":"审理强制医疗案件，本章没有规定的，参照适用公诉案件第一审普通程序和第二审程序的有关规定。"},{"i":540,"n":"第五百四十条","txt":"被强制医疗的人及其近亲属申请解除强制医疗的，应当向决定强制医疗的人民法院提出。"},{"i":541,"n":"第五百四十一条","txt":"强制医疗机构提出解除强制医疗意见，或者被强制医疗的人及其近亲属申请解除强制医疗的，人民法院应当审查是否附有对被强制医疗的人的诊断评估报告。"},{"i":542,"n":"第五百四十二条","txt":"强制医疗机构提出解除强制医疗意见，或者被强制医疗的人及其近亲属申请解除强制医疗的，人民法院应当组成合议庭进行审查，并在一个月内，按照下列情形分别处理："},{"i":543,"n":"第五百四十三条","txt":"人民检察院认为强制医疗决定或者解除强制医疗决定不当，在收到决定书后二十日内提出书面纠正意见的，人民法院应当另行组成合议庭审理，并在一个月内作出决定。"},{"i":544,"n":"第五百四十四条","txt":"人民法院讯问被告人，宣告判决，审理减刑、假释案件，根据案件情况，可以采取视频方式进行。"},{"i":545,"n":"第五百四十五条","txt":"向人民法院提出自诉、上诉、申诉、申请等的，应当以书面形式提出。书写有困难的，除另有规定的以外，可以口头提出，由人民法院工作人员制作笔录或者记录在案，并向口述人宣读或者交其阅读。"},{"i":546,"n":"第五百四十六条","txt":"诉讼期间制作、形成的工作记录、告知笔录等材料，应当由制作人员和其他有关人员签名、盖章。宣告或者送达判决书、裁定书、决定书、通知书等诉讼文书的，应当由接受宣告或者送达的人在诉讼文书、送达回证上签名、盖章。"},{"i":547,"n":"第五百四十七条","txt":"本解释的有关规定适用于军事法院、铁路运输法院等专门人民法院。"},{"i":548,"n":"第五百四十八条","txt":"本解释自2013年1月1日起施行，最高人民法院1998年9月2日公布的《关于执行〈中华人民共和国刑事诉讼法〉若干问题的解释》同时废止；最高人民法院以前发布的司法解释和规范性文件，与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushiyongxingzhengsusongfarudb70eb":[{"i":1,"n":"第一条","txt":"人民法院对符合起诉条件的案件应当立案，依法保障当事人行使诉讼权利。"},{"i":2,"n":"第二条","txt":"行政诉讼法第四十九条第三项规定的“有具体的诉讼请求”是指："},{"i":3,"n":"第三条","txt":"有下列情形之一，已经立案的，应当裁定驳回起诉："},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织依照行政诉讼法第四十七条第一款的规定，对行政机关不履行法定职责提起诉讼的，应当在行政机关履行法定职责期限届满之日起六个月内提出。"},{"i":5,"n":"第五条","txt":"行政诉讼法第三条第三款规定的“行政机关负责人”，包括行政机关的正职和副职负责人。行政机关负责人出庭应诉的，可以另行委托一至二名诉讼代理人。"},{"i":6,"n":"第六条","txt":"行政诉讼法第二十六条第二款规定的“复议机关决定维持原行政行为”，包括复议机关驳回复议申请或者复议请求的情形，但以复议申请不符合受理条件为由驳回的除外。"},{"i":7,"n":"第七条","txt":"复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是共同被告。原告只起诉作出原行政行为的行政机关或者复议机关的，人民法院应当告知原告追加被告。原告不同意追加的，人民法院应当将另一机关列为共同被告。"},{"i":8,"n":"第八条","txt":"作出原行政行为的行政机关和复议机关为共同被告的，以作出原行政行为的行政机关确定案件的级别管辖。"},{"i":9,"n":"第九条","txt":"复议机关决定维持原行政行为的，人民法院应当在审查原行政行为合法性的同时，一并审查复议程序的合法性。"},{"i":10,"n":"第十条","txt":"人民法院对原行政行为作出判决的同时，应当对复议决定一并作出相应判决。"},{"i":11,"n":"第十一条","txt":"行政机关为实现公共利益或者行政管理目标，在法定职责范围内，与公民、法人或者其他组织协商订立的具有行政法上权利义务内容的协议，属于行政诉讼法第十二条第一款第十一项规定的行政协议。"},{"i":12,"n":"第十二条","txt":"公民、法人或者其他组织对行政机关不依法履行、未按照约定履行协议提起诉讼的，参照民事法律规范关于诉讼时效的规定；对行政机关单方变更、解除协议等行为提起诉讼的，适用行政诉讼法及其司法解释关于起诉期限的规定。"},{"i":13,"n":"第十三条","txt":"对行政协议提起诉讼的案件，适用行政诉讼法及其司法解释的规定确定管辖法院。"},{"i":14,"n":"第十四条","txt":"人民法院审查行政机关是否依法履行、按照约定履行协议或者单方变更、解除协议是否合法，在适用行政法律规范的同时，可以适用不违反行政法和行政诉讼法强制性规定的民事法律规范。"},{"i":15,"n":"第十五条","txt":"原告主张被告不依法履行、未按照约定履行协议或者单方变更、解除协议违法，理由成立的，人民法院可以根据原告的诉讼请求判决确认协议有效、判决被告继续履行协议，并明确继续履行的具体内容；被告无法继续履行或者继续履行已无实际意义的，判决被告采取相应的补救措施；给原告造成损失的，判决被告予以赔偿。"},{"i":16,"n":"第十六条","txt":"对行政机关不依法履行、未按照约定履行协议提起诉讼的，诉讼费用准用民事案件交纳标准；对行政机关单方变更、解除协议等行为提起诉讼的，诉讼费用适用行政案件交纳标准。"},{"i":17,"n":"第十七条","txt":"公民、法人或者其他组织请求一并审理行政诉讼法第六十一条规定的相关民事争议，应当在第一审开庭审理前提出；有正当理由的，也可以在法庭调查中提出。"},{"i":18,"n":"第十八条","txt":"人民法院在行政诉讼中一并审理相关民事争议的，民事争议应当单独立案，由同一审判组织审理。"},{"i":19,"n":"第十九条","txt":"人民法院一并审理相关民事争议，适用民事法律规范的相关规定，法律另有规定的除外。"},{"i":20,"n":"第二十条","txt":"公民、法人或者其他组织请求人民法院一并审查行政诉讼法第五十三条规定的规范性文件，应当在第一审开庭审理前提出；有正当理由的，也可以在法庭调查中提出。"},{"i":21,"n":"第二十一条","txt":"规范性文件不合法的，人民法院不作为认定行政行为合法的依据，并在裁判理由中予以阐明。作出生效裁判的人民法院应当向规范性文件的制定机关提出处理建议，并可以抄送制定机关的同级人民政府或者上一级行政机关。"},{"i":22,"n":"第二十二条","txt":"原告请求被告履行法定职责的理由成立，被告违法拒绝履行或者无正当理由逾期不予答复的，人民法院可以根据行政诉讼法第七十二条的规定，判决被告在一定期限内依法履行原告请求的法定职责；尚需被告调查或者裁量的，应当判决被告针对原告的请求重新作出处理。"},{"i":23,"n":"第二十三条","txt":"原告申请被告依法履行支付抚恤金、最低生活保障待遇或者社会保险待遇等给付义务的理由成立，被告依法负有给付义务而拒绝或者拖延履行义务且无正当理由的，人民法院可以根据行政诉讼法第七十三条的规定，判决被告在一定期限内履行相应的给付义务。"},{"i":24,"n":"第二十四条","txt":"当事人向上一级人民法院申请再审，应当在判决、裁定或者调解书发生法律效力后六个月内提出。有下列情形之一的，自知道或者应当知道之日起六个月内提出："},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，当事人可以向人民检察院申请抗诉或者检察建议："},{"i":26,"n":"第二十六条","txt":"2015年5月1日前起诉期限尚未届满的，适用修改后的行政诉讼法关于起诉期限的规定。"},{"i":27,"n":"第二十七条","txt":"最高人民法院以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanguanyushizhengfujingjijishuxiezu1bd20b":[],"zuigaorenminfayuanguanyushuiwujiguanshifouyouyiwux281416":[],"zuigaorenminfayuanguanyusifanggaizaozhongdiandangs13cb6c":[],"zuigaorenminfayuanguanyusuqiantingzhiqinfanzhucesh0213ba":[{"i":1,"n":"第一条","txt":"根据商标法第五十七条、第五十八条的规定，商标注册人或者利害关系人可以向人民法院提出诉前责令停止侵犯注册商标专用权行为或者保全证据的申请。"},{"i":2,"n":"第二条","txt":"诉前责令停止侵犯注册商标专用权行为或者保全证据的申请，应当向侵权行为地或者被申请人住所地对商标案件有管辖权的人民法院提出。"},{"i":3,"n":"第三条","txt":"商标注册人或者利害关系人向人民法院提出诉前停止侵犯注册商标专用权行为的申请，应当递交书面申请状。申请状应当载明："},{"i":4,"n":"第四条","txt":"申请人提出诉前停止侵犯注册商标专用权行为的申请时，应当提交下列证据："},{"i":5,"n":"第五条","txt":"人民法院作出诉前停止侵犯注册商标专用权行为或者保全证据的裁定事项，应当限于商标注册人或者利害关系人申请的范围。"},{"i":6,"n":"第六条","txt":"申请人提出诉前停止侵犯注册商标专用权行为的申请时应当提供担保。"},{"i":7,"n":"第七条","txt":"在执行停止有关行为裁定过程中，被申请人可能因采取该项措施造成更大损失的，人民法院可以责令申请人追加相应的担保。申请人不追加担保的，可以解除有关停止措施。"},{"i":8,"n":"第八条","txt":"停止侵犯注册商标专用权行为裁定所采取的措施，不因被申请人提供担保而解除，但申请人同意的除外。"},{"i":9,"n":"第九条","txt":"人民法院接受商标注册人或者利害关系人提出责令停止侵犯注册商标专用权行为的申请后，经审查符合本规定第四条的，应当在48小时内作出书面裁定；裁定责令被申请人停止侵犯注册商标专用权行为的，应当立即开始执行。"},{"i":10,"n":"第十条","txt":"当事人对诉前责令停止侵犯注册商标专用权行为裁定不服的，可以在收到裁定之日起10日内申请复议一次。复议期间不停止裁定的执行。"},{"i":11,"n":"第十一条","txt":"人民法院对当事人提出的复议申请应当从以下方面进行审查："},{"i":12,"n":"第十二条","txt":"商标注册人或者利害关系人在人民法院采取停止有关行为或者保全证据的措施后15日内不起诉的，人民法院应当解除裁定采取的措施。"},{"i":13,"n":"第十三条","txt":"申请人不起诉或者申请错误造成被申请人损失的，被申请人可以向有管辖权的人民法院起诉请求申请人赔偿，也可以在商标注册人或者利害关系人提起的侵犯注册商标专用权的诉讼中提出损害赔偿请求，人民法院可以一并处理。"},{"i":14,"n":"第十四条","txt":"停止侵犯注册商标专用权行为裁定的效力，一般应维持到终审法律文书生效时止。"},{"i":15,"n":"第十五条","txt":"被申请人违反人民法院责令停止侵犯注册商标专用权行为或者保全证据裁定的，依照民事诉讼法第一百零二条规定处理。"},{"i":16,"n":"第十六条","txt":"商标注册人或者利害关系人向人民法院提起商标侵权诉讼时或者诉讼中，提出先行停止侵犯注册商标专用权请求的，人民法院可以先行作出裁定。前款规定涉及的有关申请、证据提交、担保的确定、裁定的执行和复议等事项，参照本司法解释有关规定办理。"},{"i":17,"n":"第十七条","txt":"诉前停止侵犯注册商标专用权行为和保全证据的案件，申请人应当按照《人民法院诉讼收费办法》及其补充规定缴纳费用。"}],"zuigaorenminfayuanguanyutiaozhengsifajieshidengwen0e101d":[],"zuigaorenminfayuanguanyutuoyunrenzhuzhanghuosunhuo782965":[],"zuigaorenminfayuanguanyuweifanjihuashengyuzhengced5227a0":[],"zuigaorenminfayuanguanyuxiangwaiguogongsisongdasiffe2f93":[],"zuigaorenminfayuanguanyuxiangzhengfuyuqitadanweiqic5a669":[],"zuigaorenminfayuanguanyuxingzhengjiguanduitudizhen9782d4":[],"zuigaorenminfayuanguanyuxinyongsheweifanguidingsho0b1bb3":[],"zuigaorenminfayuanguanyuxiugaizuigaorenminfayuangu0901aa":[],"zuigaorenminfayuanguanyuxuexixuanchuanguancheweich7d5b3d":[],"zuigaorenminfayuanguanyuyanzidanweiduiduogeanjianz3fdcdf":[],"zuigaorenminfayuanguanyuyichengdanbaozhengzerendebc65688":[],"zuigaorenminfayuanguanyuyinfafaguankaopingweiyuanh97bf4a":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国法官法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"法官考评委员会是人民法院依法设置的指导对法官的培训、考核、评议工作的机构。"},{"i":3,"n":"第三条","txt":"最高人民法院、地方各级人民法院和军事法院等专门人民法院分别设立法官考评委员会。"},{"i":4,"n":"第四条","txt":"法官考评委员会履行以下职责："},{"i":5,"n":"第五条","txt":"法官考评委员会由本院院长、副院长以及有关部门的主要负责人组成。"},{"i":6,"n":"第六条","txt":"法官考评委员会设主任一人、副主任一至三人。主任由本院院长担任；副主任由主任提名，法官考评委员会通过。"},{"i":7,"n":"第七条","txt":"各级人民法院法官考评委员会组成人数为五人、七人或九人。"},{"i":8,"n":"第八条","txt":"法官考评委员会实行民主集中制。根据需要，适时召开会议。"},{"i":9,"n":"第九条","txt":"法官考评委员会由主任或受委托的副主任主持。决定事项须经全体委员的半数以上同意。"},{"i":10,"n":"第十条","txt":"法官考评委员会的办事机构为本院人事管理部门。"},{"i":11,"n":"第十一条","txt":"各级人民法院法官考评委员会在初任审判员、助理审判员全国统一考核期间设考试办公室。"},{"i":12,"n":"第十二条","txt":"本办法由最高人民法院负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自颁布之日起施行。"},{"i":14,"n":"第一条","txt":"为了公正地选择德才兼备的优秀人才，建设一支政治坚定、清正廉明、精通法律、秉公执法的法官队伍，根据《中华人民共和国法官法》，制定本办法。"},{"i":15,"n":"第二条","txt":"初任审判员、助理审判员必须经过全国统一考试。"},{"i":16,"n":"第三条","txt":"最高人民法院法官考评委员会是初任审判员、助理审判员全国统一考试的主管机构，负责制定考试方案及实施细则并组织全国统一考试工作。"},{"i":17,"n":"第四条","txt":"地方各级人民法院、专门人民法院法官考评委员会负责其管辖范围内的考试组织工作，承办上级人民法院法官考评委员会委托的有关考试工作。"},{"i":18,"n":"第五条","txt":"各级人民法院法官考评委员会在初任审判员、助理审判员全国统一考试期间设考试办公室，挂靠本院人事管理部门，具体负责考试的组织实施工作。"},{"i":19,"n":"第六条","txt":"报名参加考试的人员，必须具备下列条件："},{"i":20,"n":"第七条","txt":"各级人民法院法官考评委员会按规定对本地区的报考人员进行资格审查，由高级人民法院法官考评委员会统一发给准考证。"},{"i":21,"n":"第八条","txt":"考试试题及评分标准由最高人民法院法官考评委员会制定。"},{"i":22,"n":"第九条","txt":"考试的主要内容包括马列主义基础理论知识、法律专业知识和分析、判断能力，文字、语言能力等。"},{"i":23,"n":"第十条","txt":"考试采取闭卷笔试和面试两种形式。笔试成绩合格者，方可参加面试。"},{"i":24,"n":"第十一条","txt":"评卷工作在最高人民法院法官考评委员会统一领导下，由高级人民法院法官考评委员会组织实施。"},{"i":25,"n":"第十二条","txt":"最高人民法院、地方各级人民法院、专门人民法院参加考试合格者，由最高人民法院法官考评委员会或委托高级人民法院法官考评委员会颁发《初任审判员、助理审判员考试合格证书》。"},{"i":26,"n":"第十三条","txt":"《初任审判员、助理审判员考试合格证书》有效期为三年。在有效期内根据工作需要，经考核可以被任命为审判员或助理审判员。"},{"i":27,"n":"第十四条","txt":"《初任审判员、助理审判员考试合格证书》由最高人民法院统一制作。"},{"i":28,"n":"第十五条","txt":"考场规则、监考守则、试卷保密规定等考试纪律，由最高人民法院法官考评委员会制定。"},{"i":29,"n":"第十六条","txt":"违反考试纪律者，视情节轻重，依照有关规定予以处理。"},{"i":30,"n":"第十七条","txt":"因作弊取得《初任审判员、助理审判员考试合格证书》的，由最高人民法院法官考评委员会或委托高级人民法院法官考评委员会宣布其无效，并收回证书。"},{"i":31,"n":"第十八条","txt":"考试经费列入法院机关业务费范围，专款专用。各级人民法院按规定收取的报考费，应当全部用于考试支出。"},{"i":32,"n":"第十九条","txt":"本办法由最高人民法院负责解释。"},{"i":33,"n":"第二十条","txt":"本办法自颁布之日起施行。"}],"zuigaorenminfayuanguanyuyinfaguanyushenlilianyingh205048":[],"zuigaorenminfayuanguanyuyinfaguojiatongjijuguanyudd14e7d":[],"zuigaorenminfayuanguanyuyinfamayuanfuyuanzhangzaiqd0ba40":[],"zuigaorenminfayuanguanyuyinfayuancuopandaozhizhaiq2b13f4":[],"zuigaorenminfayuanguanyuyinhanggongzuorenyuanweian3fcb5f":[],"zuigaorenminfayuanguanyuyinhangxinyongshekouhuayuf9ba4e9":[],"zuigaorenminfayuanguanyuyinhangyizhejiaoheduifangfa3a484":[],"zuigaorenminfayuanguanyuzailinmucaifaxukezhengguidc7e85d":[],"zuigaorenminfayuanguanyuzaizhuanliqinquansusongzho7cc2b6":[],"zuigaorenminfayuanguanyuzhenglibenyuqingdaoshijianc82536":[],"zuigaorenminfayuanguanyuzhixingminshizhengcefalvru1ab625":[],"zuigaorenminfayuanguanyuzhongjirenminfayuannengfou26f930":[],"zuigaorenminfayuanguanyuzuoweibaozhengrendehehuozucf6583":[],"zuigaorenminfayuanjingjishenpantingguanyudailifaxib7c29b":[],"zuigaorenminfayuanjingjishenpantingguanyugouxiaohe042bec":[],"zuigaorenminfayuanjingjishenpantingguanyuxinyongheefb000":[],"zuigaorenminfayuanyinfachulishetaixingshishensumin4895da":[],"zuigaorenminfayuanyinfaguanyuguanchezhixingminfato1c85f4":[],"zuigaorenminfayuanyinfaguanyushenlilihunanjianzhon4f5be6":[],"zuigaorenminfayuanyinfaguanyushenlixingzhengpeichaa80215":[{"i":1,"n":"第一条","txt":"《中华人民共和国国家赔偿法》第三条、第四条规定的其他违法行为，包括具体行政行为和与行政机关及其工作人员行使行政职权有关的，给公民、法人或者其他组织造成损害的，违反行政职责的行为。"},{"i":2,"n":"第二条","txt":"赔偿请求人对行政机关确认具体行政行为违法但又决定不予赔偿，或者对确定的赔偿数额有异议提起行政赔偿诉讼的，人民法院应予受理。"},{"i":3,"n":"第三条","txt":"赔偿请求人认为行政机关及其工作人员实施了国家赔偿法第三条第（三）、（四）、（五）项和第四条第（四）项规定的非具体行政行为的行为侵犯其人身权、财产权并造成损失，赔偿义务机关拒不确认致害行为违法，赔偿请求人可直接向人民法院提起行政赔偿诉讼。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织在提起行政诉讼的同时一并提出行政赔偿请求的，人民法院应一并受理。"},{"i":5,"n":"第五条","txt":"法律规定由行政机关最终裁决的具体行政行为，被作出最终裁决的行政机关确认违法，赔偿请求人以赔偿义务机关应当赔偿而不予赔偿或逾期不予赔偿或者对赔偿数额有异议提起行政赔偿诉讼，人民法院应依法受理。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织以国防、外交等国家行为或者行政机关制定发布行政法规、规章或者具有普遍约束力的决定、命令侵犯其合法权益造成损害为由，向人民法院提起行政赔偿诉讼的，人民法院不予受理。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织在提起行政诉讼的同时一并提出行政赔偿请求的，人民法院依照行政诉讼法第十七条、第十八条、第二十条的规定管辖。"},{"i":8,"n":"第八条","txt":"赔偿请求人提起行政赔偿诉讼的请求涉及不动产的，由不动产所在地的人民法院管辖。"},{"i":9,"n":"第九条","txt":"单独提起的行政赔偿诉讼案件由被告住所地的基层人民法院管辖。"},{"i":10,"n":"第十条","txt":"赔偿请求人因同一事实对两个以上行政机关提起行政赔偿诉讼的，可以向其中任何一个行政机关住所地的人民法院提起。赔偿请求人向两个以上有管辖权的人民法院提起行政赔偿诉讼的，由最先收到起诉状的人民法院管辖。"},{"i":11,"n":"第十一条","txt":"公民对限制人身自由的行政强制措施不服，或者对行政机关基于同一事实对同一当事人作出限制人身自由和对财产采取强制措施的具体行政行为不服，在提起行政诉讼的同时一并提出行政赔偿请求的，由受理该行政案件的人民法院管辖；单独提起行政赔偿诉讼的，由被告住所地或原告住所地或不动产所在地的人民法院管辖。"},{"i":12,"n":"第十二条","txt":"人民法院发现受理的案件不属于自己管辖，应当移送有管辖权的人民法院；受移送的人民法院不得再行移送。"},{"i":13,"n":"第十三条","txt":"人民法院对管辖权发生争议的，由争议双方协商解决，协商不成的，报请他们的共同上级人民法院指定管辖。如双方为跨省、自治区、直辖市的人民法院，高级人民法院协商不成的，由最高人民法院及时指定管辖。"},{"i":14,"n":"第十四条","txt":"与行政赔偿案件处理结果有法律上的利害关系的其他公民、法人或者其他组织有权作为第三人参加行政赔偿诉讼。"},{"i":15,"n":"第十五条","txt":"受害的公民死亡，其继承人和其他有抚养关系的亲属以及死者生前抚养的无劳动能力的人有权提起行政赔偿诉讼。"},{"i":16,"n":"第十六条","txt":"企业法人或者其他组织被行政机关撤销、变更、兼并、注销，认为经营自主权受到侵害，依法提起行政赔偿诉讼，原企业法人或其他组织，或者对其享有权利的法人或其他组织均具有原告资格。"},{"i":17,"n":"第十七条","txt":"两个以上行政机关共同侵权，赔偿请求人对其中一个或者数个侵权机关提起行政赔偿诉讼，若诉讼请求系可分之诉，被诉的一个或者数个侵权机关为被告；若诉讼请求系不可分之诉，由人民法院依法追加其他侵权机关为共同被告。"},{"i":18,"n":"第十八条","txt":"复议机关的复议决定加重损害的，赔偿请求人只对作出原决定的行政机关提起行政赔偿诉讼，作出原决定的行政机关为被告；赔偿请求人只对复议机关提起行政赔偿诉讼的，复议机关为被告。"},{"i":19,"n":"第十九条","txt":"行政机关依据行政诉讼法第六十六条的规定申请人民法院强制执行具体行政行为，由于据以强制执行的根据错误而发生行政赔偿诉讼的，申请强制执行的行政机关为被告。"},{"i":20,"n":"第二十条","txt":"人民法院审理行政赔偿案件，需要变更被告而原告不同意变更的，裁定驳回起诉。"},{"i":21,"n":"第二十一条","txt":"赔偿请求人单独提起行政赔偿诉讼，应当符合下列条件："},{"i":22,"n":"第二十二条","txt":"赔偿请求人单独提起行政赔偿诉讼，可以在向赔偿义务机关递交赔偿申请后的2个月届满之日起3个月内提出。"},{"i":23,"n":"第二十三条","txt":"公民、法人或者其他组织在提起行政诉讼的同时一并提出行政赔偿请求的，其起诉期限按照行政诉讼起诉期限的规定执行。"},{"i":24,"n":"第二十四条","txt":"赔偿义务机关作出赔偿决定时，未告知赔偿请求人的诉权或者起诉期限，致使赔偿请求人逾期向人民法院起诉的，其起诉期限从赔偿请求人实际知道诉权或者起诉期限时计算，但逾期的期间自赔偿请求人收到赔偿决定之日起不得超过1年。"},{"i":25,"n":"第二十五条","txt":"受害的公民死亡，其继承人和有抚养关系的人提起行政赔偿诉讼，应当提供该公民死亡的证明及赔偿请求人与死亡公民之间的关系证明。"},{"i":26,"n":"第二十六条","txt":"当事人先后被采取限制人身自由的行政强制措施和刑事拘留等强制措施，因强制措施被确认为违法而请求赔偿的，人民法院按其行为性质分别适用行政赔偿程序和刑事赔偿程序立案受理。"},{"i":27,"n":"第二十七条","txt":"人民法院接到原告单独提起的行政赔偿起诉状，应当进行审查，并在7日内立案或者作出不予受理的裁定。"},{"i":28,"n":"第二十八条","txt":"当事人在提起行政诉讼的同时一并提出行政赔偿请求，或者因具体行政行为和与行使行政职权有关的其他行为侵权造成损害一并提出行政赔偿请求的，人民法院应当分别立案，根据具体情况可以合并审理，也可以单独审理。"},{"i":29,"n":"第二十九条","txt":"人民法院审理行政赔偿案件，就当事人之间的行政赔偿争议进行审理与裁判。"},{"i":30,"n":"第三十条","txt":"人民法院审理行政赔偿案件在坚持合法、自愿的前提下，可以就赔偿范围、赔偿方式和赔偿数额进行调解。调解成立的，应当制作行政赔偿调解书。"},{"i":31,"n":"第三十一条","txt":"被告在一审判决前同原告达成赔偿协议，原告申请撤诉的，人民法院应当依法予以审查并裁定是否准许。"},{"i":32,"n":"第三十二条","txt":"原告在行政赔偿诉讼中对自己的主张承担举证责任。被告有权提供不予赔偿或者减少赔偿数额方面的证据。"},{"i":33,"n":"第三十三条","txt":"被告的具体行政行为违法但尚未对原告合法权益造成损害的，或者原告的请求没有事实根据或法律根据的，人民法院应当判决驳回原告的赔偿请求。"},{"i":34,"n":"第三十四条","txt":"人民法院对赔偿请求人未经确认程序而直接提起行政赔偿诉讼的案件，在判决时应当对赔偿义务机关致害行为是否违法予以确认。"},{"i":35,"n":"第三十五条","txt":"人民法院对单独提起行政赔偿案件作出判决的法律文书的名称为行政赔偿判决书、行政赔偿裁定书或者行政赔偿调解书。"},{"i":36,"n":"第三十六条","txt":"发生法律效力的行政赔偿判决、裁定或调解协议，当事人必须履行。一方拒绝履行的，对方当事人可以向第一审人民法院申请执行。"},{"i":37,"n":"第三十七条","txt":"单独受理的第一审行政赔偿案件的审理期限为3个月，第二审为2个月；一并受理行政赔偿请求案件的审理期限与该行政案件的审理期限相同。如因特殊情况不能按期结案，需要延长审限的，应按照行政诉讼法的有关规定报请批准。"},{"i":38,"n":"第三十八条","txt":"人民法院审理行政赔偿案件，除依照国家赔偿法行政赔偿程序的规定外，对本规定没有规定的，在不与国家赔偿法相抵触的情况下，可以适用行政诉讼的有关规定。"},{"i":39,"n":"第三十九条","txt":"赔偿请求人要求人民法院确认致害行为违法涉及的鉴定、勘验、审计等费用，由申请人预付，最后由败诉方承担。"},{"i":40,"n":"第四十条","txt":"最高人民法院以前所作的有关司法解释与本规定不一致的，按本规定执行。"}],"zuigaorenminfayuanyinfaguanyushiyongquanguorenmind4f23c1":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban1d5539-2":[{"i":1,"n":"第一条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“足以造成严重食物中毒事故或者其他严重食源性疾病”："},{"i":2,"n":"第二条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“对人体健康造成严重危害”："},{"i":3,"n":"第三条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“其他严重情节”："},{"i":4,"n":"第四条","txt":"生产、销售不符合食品安全标准的食品，具有下列情形之一的，应当认定为刑法第一百四十三条规定的“后果特别严重”："},{"i":5,"n":"第五条","txt":"生产、销售有毒、有害食品，具有本解释第二条规定情形之一的，应当认定为刑法第一百四十四条规定的“对人体健康造成严重危害”。"},{"i":6,"n":"第六条","txt":"生产、销售有毒、有害食品，具有下列情形之一的，应当认定为刑法第一百四十四条规定的“其他严重情节”："},{"i":7,"n":"第七条","txt":"生产、销售有毒、有害食品，生产、销售金额五十万元以上，或者具有本解释第四条规定的情形之一的，应当认定为刑法第一百四十四条规定的“致人死亡或者有其他特别严重情节”。"},{"i":8,"n":"第八条","txt":"在食品加工、销售、运输、贮存等过程中，违反食品安全标准，超限量或者超范围滥用食品添加剂，足以造成严重食物中毒事故或者其他严重食源性疾病的，依照刑法第一百四十三条的规定以生产、销售不符合安全标准的食品罪定罪处罚。"},{"i":9,"n":"第九条","txt":"在食品加工、销售、运输、贮存等过程中，掺入有毒、有害的非食品原料，或者使用有毒、有害的非食品原料加工食品的，依照刑法第一百四十四条的规定以生产、销售有毒、有害食品罪定罪处罚。"},{"i":10,"n":"第十条","txt":"生产、销售不符合食品安全标准的食品添加剂，用于食品的包装材料、容器、洗涤剂、消毒剂，或者用于食品生产经营的工具、设备等，构成犯罪的，依照刑法第一百四十条的规定以生产、销售伪劣产品罪定罪处罚。"},{"i":11,"n":"第十一条","txt":"以提供给他人生产、销售食品为目的，违反国家规定，生产、销售国家禁止用于食品生产、销售的非食品原料，情节严重的，依照刑法第二百二十五条的规定以非法经营罪定罪处罚。"},{"i":12,"n":"第十二条","txt":"违反国家规定，私设生猪屠宰厂（场），从事生猪屠宰、销售等经营活动，情节严重的，依照刑法第二百二十五条的规定以非法经营罪定罪处罚。"},{"i":13,"n":"第十三条","txt":"生产、销售不符合食品安全标准的食品，有毒、有害食品，符合刑法第一百四十三条、第一百四十四条规定的，以生产、销售不符合安全标准的食品罪或者生产、销售有毒、有害食品罪定罪处罚。同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"},{"i":14,"n":"第十四条","txt":"明知他人生产、销售不符合食品安全标准的食品，有毒、有害食品，具有下列情形之一的，以生产、销售不符合安全标准的食品罪或者生产、销售有毒、有害食品罪的共犯论处："},{"i":15,"n":"第十五条","txt":"广告主、广告经营者、广告发布者违反国家规定，利用广告对保健食品或者其他食品作虚假宣传，情节严重的，依照刑法第二百二十二条的规定以虚假广告罪定罪处罚。"},{"i":16,"n":"第十六条","txt":"负有食品安全监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，导致发生重大食品安全事故或者造成其他严重后果，同时构成食品监管渎职罪和徇私舞弊不移交刑事案件罪、商检徇私舞弊罪、动植物检疫徇私舞弊罪、放纵制售伪劣商品犯罪行为罪等其他渎职犯罪的，依照处罚较重的规定定罪处罚。"},{"i":17,"n":"第十七条","txt":"犯生产、销售不符合安全标准的食品罪，生产、销售有毒、有害食品罪，一般应当依法判处生产、销售金额二倍以上的罚金。"},{"i":18,"n":"第十八条","txt":"对实施本解释规定之犯罪的犯罪分子，应当依照刑法规定的条件严格适用缓刑、免予刑事处罚。根据犯罪事实、情节和悔罪表现，对于符合刑法规定的缓刑适用条件的犯罪分子，可以适用缓刑，但是应当同时宣告禁止令，禁止其在缓刑考验期限内从事食品生产、销售及相关活动。"},{"i":19,"n":"第十九条","txt":"单位实施本解释规定的犯罪的，依照本解释规定的定罪量刑标准处罚。"},{"i":20,"n":"第二十条","txt":"下列物质应当认定为“有毒、有害的非食品原料”："},{"i":21,"n":"第二十一条","txt":"“足以造成严重食物中毒事故或者其他严重食源性疾病”“有毒、有害非食品原料”难以确定的，司法机关可以根据检验报告并结合专家意见等相关材料进行认定。必要时，人民法院可以依法通知有关专家出庭作出说明。"},{"i":22,"n":"第二十二条","txt":"最高人民法院、最高人民检察院此前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban2bc3ed":[{"i":1,"n":"第一条","txt":"具有下列情形之一的，可以认定为刑法第二百一十三条规定的“与其注册商标相同的商标”："},{"i":2,"n":"第二条","txt":"在刑法第二百一十七条规定的作品、录音制品上以通常方式署名的自然人、法人或者非法人组织，应当推定为著作权人或者录音制作者，且该作品、录音制品上存在着相应权利，但有相反证明的除外。"},{"i":3,"n":"第三条","txt":"采取非法复制、未经授权或者超越授权使用计算机信息系统等方式窃取商业秘密的，应当认定为刑法第二百一十九条第一款第一项规定的“盗窃”。"},{"i":4,"n":"第四条","txt":"实施刑法第二百一十九条规定的行为，具有下列情形之一的，应当认定为“给商业秘密的权利人造成重大损失”："},{"i":5,"n":"第五条","txt":"实施刑法第二百一十九条规定的行为造成的损失数额或者违法所得数额，可以按照下列方式认定："},{"i":6,"n":"第六条","txt":"在刑事诉讼程序中，当事人、辩护人、诉讼代理人或者案外人书面申请对有关商业秘密或者其他需要保密的商业信息的证据、材料采取保密措施的，应当根据案件情况采取组织诉讼参与人签署保密承诺书等必要的保密措施。"},{"i":7,"n":"第七条","txt":"除特殊情况外，假冒注册商标的商品、非法制造的注册商标标识、侵犯著作权的复制品、主要用于制造假冒注册商标的商品、注册商标标识或者侵权复制品的材料和工具，应当依法予以没收和销毁。"},{"i":8,"n":"第八条","txt":"具有下列情形之一的，可以酌情从重处罚，一般不适用缓刑："},{"i":9,"n":"第九条","txt":"具有下列情形之一的，可以酌情从轻处罚："},{"i":10,"n":"第十条","txt":"对于侵犯知识产权犯罪的，应当综合考虑犯罪违法所得数额、非法经营数额、给权利人造成的损失数额、侵权假冒物品数量及社会危害性等情节，依法判处罚金。"},{"i":11,"n":"第十一条","txt":"本解释发布施行后，之前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"},{"i":12,"n":"第十二条","txt":"本解释自2020年9月14日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban3e0509":[{"i":1,"n":"第一条","txt":"未经注册商标所有人许可，在同一种商品上使用与其注册商标相同的商标，具有下列情形之一的，属于刑法第二百一十三条规定的“情节严重”，应当以假冒注册商标罪判处三年以下有期徒刑或者拘役，并处或者单处罚金："},{"i":2,"n":"第二条","txt":"销售明知是假冒注册商标的商品，销售金额在五万元以上的，属于刑法第二百一十四条规定的“数额较大”，应当以销售假冒注册商标的商品罪判处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":3,"n":"第三条","txt":"伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识，具有下列情形之一的，属于刑法第二百一十五条规定的“情节严重”，应当以非法制造、销售非法制造的注册商标标识罪判处三年以下有期徒刑、拘役或者管制，并处或者单处罚金："},{"i":4,"n":"第四条","txt":"假冒他人专利，具有下列情形之一的，属于刑法第二百一十六条规定的“情节严重”，应当以假冒专利罪判处三年以下有期徒刑或者拘役，并处或者单处罚金："},{"i":5,"n":"第五条","txt":"以营利为目的，实施刑法第二百一十七条所列侵犯著作权行为之一，违法所得数额在三万元以上的，属于“违法所得数额较大”；具有下列情形之一的，属于“有其他严重情节”，应当以侵犯著作权罪判处三年以下有期徒刑或者拘役，并处或者单处罚金："},{"i":6,"n":"第六条","txt":"以营利为目的，实施刑法第二百一十八条规定的行为，违法所得数额在十万元以上的，属于“违法所得数额巨大”，应当以销售侵权复制品罪判处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":7,"n":"第七条","txt":"实施刑法第二百一十九条规定的行为之一，给商业秘密的权利人造成损失数额在五十万元以上的，属于“给商业秘密的权利人造成重大损失”，应当以侵犯商业秘密罪判处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"i":8,"n":"第八条","txt":"刑法第二百一十三条规定的“相同的商标”，是指与被假冒的注册商标完全相同，或者与被假冒的注册商标在视觉上基本无差别、足以对公众产生误导的商标。"},{"i":9,"n":"第九条","txt":"刑法第二百一十四条规定的“销售金额”，是指销售假冒注册商标的商品后所得和应得的全部违法收入。"},{"i":10,"n":"第十条","txt":"实施下列行为之一的，属于刑法第二百一十六条规定的“假冒他人专利”的行为："},{"i":11,"n":"第十一条","txt":"以刊登收费广告等方式直接或者间接收取费用的情形，属于刑法第二百一十七条规定的“以营利为目的”。"},{"i":12,"n":"第十二条","txt":"本解释所称“非法经营数额”，是指行为人在实施侵犯知识产权行为过程中，制造、储存、运输、销售侵权产品的价值。已销售的侵权产品的价值，按照实际销售的价格计算。制造、储存、运输和未销售的侵权产品的价值，按照标价或者已经查清的侵权产品的实际销售平均价格计算。侵权产品没有标价或者无法查清其实际销售价格的，按照被侵权产品的市场中间价格计算。"},{"i":13,"n":"第十三条","txt":"实施刑法第二百一十三条规定的假冒注册商标犯罪，又销售该假冒注册商标的商品，构成犯罪的，应当依照刑法第二百一十三条的规定，以假冒注册商标罪定罪处罚。"},{"i":14,"n":"第十四条","txt":"实施刑法第二百一十七条规定的侵犯著作权犯罪，又销售该侵权复制品，构成犯罪的，应当依照刑法第二百一十七条的规定，以侵犯著作权罪定罪处罚。"},{"i":15,"n":"第十五条","txt":"单位实施刑法第二百一十三条至第二百一十九条规定的行为，按照本解释规定的相应个人犯罪的定罪量刑标准的三倍定罪量刑。"},{"i":16,"n":"第十六条","txt":"明知他人实施侵犯知识产权犯罪，而为其提供贷款、资金、账号、发票、证明、许可证件，或者提供生产、经营场所或者运输、储存、代理进出口等便利条件、帮助的，以侵犯知识产权犯罪的共犯论处。"},{"i":17,"n":"第十七条","txt":"以前发布的有关侵犯知识产权犯罪的司法解释，与本解释相抵触的，自本解释施行后不再适用。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban8d88e7-2":[{"i":1,"n":"第一条","txt":"实施刑法第三百三十八条规定的行为，具有下列情形之一的，应当认定为“严重污染环境”："},{"i":2,"n":"第二条","txt":"实施刑法第三百三十九条、第四百零八条规定的行为，致使公私财产损失三十万元以上，或者具有本解释第一条第十项至第十七项规定情形之一的，应当认定为“致使公私财产遭受重大损失或者严重危害人体健康”或者“致使公私财产遭受重大损失或者造成人身伤亡的严重后果”。"},{"i":3,"n":"第三条","txt":"实施刑法第三百三十八条、第三百三十九条规定的行为，具有下列情形之一的，应当认定为“后果特别严重”："},{"i":4,"n":"第四条","txt":"实施刑法第三百三十八条、第三百三十九条规定的犯罪行为，具有下列情形之一的，应当从重处罚："},{"i":5,"n":"第五条","txt":"实施刑法第三百三十八条、第三百三十九条规定的行为，刚达到应当追究刑事责任的标准，但行为人及时采取措施，防止损失扩大、消除污染，全部赔偿损失，积极修复生态环境，且系初犯，确有悔罪表现的，可以认定为情节轻微，不起诉或者免予刑事处罚；确有必要判处刑罚的，应当从宽处罚。"},{"i":6,"n":"第六条","txt":"无危险废物经营许可证从事收集、贮存、利用、处置危险废物经营活动，严重污染环境的，按照污染环境罪定罪处罚；同时构成非法经营罪的，依照处罚较重的规定定罪处罚。"},{"i":7,"n":"第七条","txt":"明知他人无危险废物经营许可证，向其提供或者委托其收集、贮存、利用、处置危险废物，严重污染环境的，以共同犯罪论处。"},{"i":8,"n":"第八条","txt":"违反国家规定，排放、倾倒、处置含有毒害性、放射性、传染病病原体等物质的污染物，同时构成污染环境罪、非法处置进口的固体废物罪、投放危险物质罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":9,"n":"第九条","txt":"环境影响评价机构或其人员，故意提供虚假环境影响评价文件，情节严重的，或者严重不负责任，出具的环境影响评价文件存在重大失实，造成严重后果的，应当依照刑法第二百二十九条、第二百三十一条的规定，以提供虚假证明文件罪或者出具证明文件重大失实罪定罪处罚。"},{"i":10,"n":"第十条","txt":"违反国家规定，针对环境质量监测系统实施下列行为，或者强令、指使、授意他人实施下列行为的，应当依照刑法第二百八十六条的规定，以破坏计算机信息系统罪论处："},{"i":11,"n":"第十一条","txt":"单位实施本解释规定的犯罪的，依照本解释规定的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":12,"n":"第十二条","txt":"环境保护主管部门及其所属监测机构在行政执法过程中收集的监测数据，在刑事诉讼中可以作为证据使用。"},{"i":13,"n":"第十三条","txt":"对国家危险废物名录所列的废物，可以依据涉案物质的来源、产生过程、被告人供述、证人证言以及经批准或者备案的环境影响评价文件等证据，结合环境保护主管部门、公安机关等出具的书面意见作出认定。"},{"i":14,"n":"第十四条","txt":"对案件所涉的环境污染专门性问题难以确定的，依据司法鉴定机构出具的鉴定意见，或者国务院环境保护主管部门、公安部门指定的机构出具的报告，结合其他证据作出认定。"},{"i":15,"n":"第十五条","txt":"下列物质应当认定为刑法第三百三十八条规定的“有毒物质”："},{"i":16,"n":"第十六条","txt":"无危险废物经营许可证，以营利为目的，从危险废物中提取物质作为原材料或者燃料，并具有超标排放污染物、非法倾倒污染物或者其他违法造成环境污染的情形的行为，应当认定为“非法处置危险废物”。"},{"i":17,"n":"第十七条","txt":"本解释所称“二年内”，以第一次违法行为受到行政处罚的生效之日与又实施相应行为之日的时间间隔计算确定。"},{"i":18,"n":"第十八条","txt":"本解释自2017年1月1日起施行。本解释施行后，最高人民法院、最高人民检察院《关于办理环境污染刑事案件适用法律若干问题的解释》（法释〔2013〕15号）同时废止；之前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubana39bf5":[{"i":1,"n":"第一条","txt":"以营利为目的，未经著作权人许可，复制发行其文字作品、音乐、电影、电视、录像作品、计算机软件及其他作品，复制品数量合计在五百张（份）以上的，属于刑法第二百一十七条规定的“有其他严重情节”；复制品数量在二千五百张（份）以上的，属于刑法第二百一十七条规定的“有其他特别严重情节”。"},{"i":2,"n":"第二条","txt":"刑法第二百一十七条侵犯著作权罪中的“复制发行”，包括复制、发行或者既复制又发行的行为。"},{"i":3,"n":"第三条","txt":"侵犯知识产权犯罪，符合刑法规定的缓刑条件的，依法适用缓刑。有下列情形之一的，一般不适用缓刑："},{"i":4,"n":"第四条","txt":"对于侵犯知识产权犯罪的，人民法院应当综合考虑犯罪的违法所得、非法经营数额、给权利人造成的损失、社会危害性等情节，依法判处罚金。罚金数额一般在违法所得的一倍以上五倍以下，或者按照非法经营数额的50%以上一倍以下确定。"},{"i":5,"n":"第五条","txt":"被害人有证据证明的侵犯知识产权刑事案件，直接向人民法院起诉的，人民法院应当依法受理；严重危害社会秩序和国家利益的侵犯知识产权刑事案件，由人民检察院依法提起公诉。"},{"i":6,"n":"第六条","txt":"单位实施刑法第二百一十三条至第二百一十九条规定的行为，按照《最高人民法院、最高人民检察院关于办理侵犯知识产权刑事案件具体应用法律若干问题的解释》和本解释规定的相应个人犯罪的定罪量刑标准定罪处罚。"},{"i":7,"n":"第七条","txt":"以前发布的司法解释与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubana5e406":[{"i":1,"n":"第一条","txt":"药物非临床研究机构、药物临床试验机构、合同研究组织的工作人员，故意提供虚假的药物非临床研究报告、药物临床试验报告及相关材料的，应当认定为刑法第二百二十九条规定的“故意提供虚假证明文件”。"},{"i":2,"n":"第二条","txt":"实施本解释第一条规定的行为，索取或者非法收受他人财物的，应当依照刑法第二百二十九条第二款规定，以提供虚假证明文件罪处五年以上十年以下有期徒刑，并处罚金；同时构成提供虚假证明文件罪和受贿罪、非国家工作人员受贿罪的，依照处罚较重的规定定罪处罚。"},{"i":3,"n":"第三条","txt":"药品注册申请单位的工作人员，故意使用符合本解释第一条第二款规定的虚假药物非临床研究报告、药物临床试验报告及相关材料，骗取药品批准证明文件生产、销售药品的，应当依照刑法第一百四十一条规定，以生产、销售假药罪定罪处罚。"},{"i":4,"n":"第四条","txt":"药品注册申请单位的工作人员指使药物非临床研究机构、药物临床试验机构、合同研究组织的工作人员提供本解释第一条第二款规定的虚假药物非临床研究报告、药物临床试验报告及相关材料的，以提供虚假证明文件罪的共同犯罪论处。"},{"i":5,"n":"第五条","txt":"在医疗器械注册申请中，故意提供、使用虚假的医疗器械临床试验报告及相关材料的，参照适用本解释第一条至第四条规定。"},{"i":6,"n":"第六条","txt":"单位犯本解释第一条至第五条规定之罪的，对单位判处罚金，并依照本解释规定的相应自然人犯罪的定罪量刑标准对直接负责的主管人员和其他直接责任人员定罪处罚。"},{"i":7,"n":"第七条","txt":"对药品、医疗器械注册申请负有核查职责的国家机关工作人员，滥用职权或者玩忽职守，导致使用虚假证明材料的药品、医疗器械获得注册，致使公共财产、国家和人民利益遭受重大损失的，应当依照刑法第三百九十七条规定，以滥用职权罪或者玩忽职守罪追究刑事责任。"},{"i":8,"n":"第八条","txt":"对是否属于虚假的药物非临床研究报告、药物或者医疗器械临床试验报告及相关材料，是否影响药品或者医疗器械安全性、有效性评价结果，以及是否属于严重不良事件等专门性问题难以确定的，可以根据国家药品监督管理部门设置或者指定的药品、医疗器械审评等机构出具的意见，结合其他证据作出认定。"},{"i":9,"n":"第九条","txt":"本解释所称“合同研究组织”，是指受药品或者医疗器械注册申请单位、药物非临床研究机构、药物或者医疗器械临床试验机构的委托，从事试验方案设计、数据统计、分析测试、监查稽查等与非临床研究或者临床试验相关活动的单位。"},{"i":10,"n":"第十条","txt":"本解释自2017年9月1日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubana72741-2":[{"i":1,"n":"第一条","txt":"生产、销售假药，具有下列情形之一的，应当酌情从重处罚："},{"i":2,"n":"第二条","txt":"生产、销售假药，具有下列情形之一的，应当认定为刑法第一百四十一条规定的“对人体健康造成严重危害”："},{"i":3,"n":"第三条","txt":"生产、销售假药，具有下列情形之一的，应当认定为刑法第一百四十一条规定的“其他严重情节”："},{"i":4,"n":"第四条","txt":"生产、销售假药，具有下列情形之一的，应当认定为刑法第一百四十一条规定的“其他特别严重情节”："},{"i":5,"n":"第五条","txt":"生产、销售劣药，具有本解释第二条规定情形之一的，应当认定为刑法第一百四十二条规定的“对人体健康造成严重危害”。"},{"i":6,"n":"第六条","txt":"以生产、销售假药、劣药为目的，实施下列行为之一的，应当认定为刑法第一百四十一条、第一百四十二条规定的“生产”："},{"i":7,"n":"第七条","txt":"违反国家药品管理法律法规，未取得或者使用伪造、变造的药品经营许可证，非法经营药品，情节严重的，依照刑法第二百二十五条的规定以非法经营罪定罪处罚。"},{"i":8,"n":"第八条","txt":"明知他人生产、销售假药、劣药，而有下列情形之一的，以共同犯罪论处："},{"i":9,"n":"第九条","txt":"广告主、广告经营者、广告发布者违反国家规定，利用广告对药品作虚假宣传，情节严重的，依照刑法第二百二十二条的规定以虚假广告罪定罪处罚。"},{"i":10,"n":"第十条","txt":"实施生产、销售假药、劣药犯罪，同时构成生产、销售伪劣产品、侵犯知识产权、非法经营、非法行医、非法采供血等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":11,"n":"第十一条","txt":"对实施本解释规定之犯罪的犯罪分子，应当依照刑法规定的条件，严格缓刑、免予刑事处罚的适用。对于适用缓刑的，应当同时宣告禁止令，禁止犯罪分子在缓刑考验期内从事药品生产、销售及相关活动。"},{"i":12,"n":"第十二条","txt":"犯生产、销售假药罪的，一般应当依法判处生产、销售金额二倍以上的罚金。共同犯罪的，对各共同犯罪人合计判处的罚金应当在生产、销售金额的二倍以上。"},{"i":13,"n":"第十三条","txt":"单位犯本解释规定之罪的，对单位判处罚金，并对直接负责的主管人员和其他直接责任人员，依照本解释规定的自然人犯罪的定罪量刑标准处罚。"},{"i":14,"n":"第十四条","txt":"是否属于刑法第一百四十一条、第一百四十二条规定的“假药”、“劣药”难以确定的，司法机关可以根据地市级以上药品监督管理部门出具的认定意见等相关材料进行认定。必要时，可以委托省级以上药品监督管理部门设置或者确定的药品检验机构进行检验。"},{"i":15,"n":"第十五条","txt":"本解释所称“生产、销售金额”，是指生产、销售假药、劣药所得和可得的全部违法收入。"},{"i":16,"n":"第十六条","txt":"本解释规定的“轻伤”、“重伤”按照《人体损伤程度鉴定标准》进行鉴定。"},{"i":17,"n":"第十七条","txt":"本解释发布施行后，最高人民法院、最高人民检察院《关于办理生产、销售假药、劣药刑事案件具体应用法律若干问题的解释》（法释〔2009〕9号）同时废止；之前发布的司法解释和规范性文件与本解释不一致的，以本解释为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubane05ad5":[],"zuigaorenminjianchayuanguanyubanlifeifajingyingshi3102c8":[{"i":1,"n":"第一条","txt":"违反国家有关盐业管理规定，非法生产、储运、销售食盐，扰乱市场秩序，情节严重的，应当依照刑法第二百二十五条的规定，以非法经营罪追究刑事责任。"},{"i":2,"n":"第二条","txt":"非法经营食盐，具有下列情形之一的，应当依法追究刑事责任："},{"i":3,"n":"第三条","txt":"非法经营食盐行为未经处理的，其非法经营的数量累计计算；行为人非法经营行为是否盈利，不影响犯罪的构成。"},{"i":4,"n":"第四条","txt":"以非碘盐充当碘盐或者以工业用盐等非食盐充当食盐进行非法经营，同时构成非法经营罪和生产、销售伪劣产品罪、生产、销售不符合卫生标准的食品罪、生产、销售有毒、有害食品罪等其他犯罪的，依照处罚较重的规定追究刑事责任。"},{"i":5,"n":"第五条","txt":"以暴力、威胁方法阻碍行政执法人员依法行使盐业管理职务的，依照刑法第二百七十七条的规定，以妨害公务罪追究刑事责任；其非法经营行为已构成犯罪的，依照数罪并罚的规定追究刑事责任。"}],"zuigaorenminjianchayuanguanyuxiajirenminjianchayuadcae2a":[]};
